/* -- css/animations.css -- */
/* Animaciones reutilizables */
@keyframes pulse {
            0%, 100% { opacity: 1; transform: translateY(0); }
            50% { opacity: 0.6; transform: translateY(3px); }
        }

@keyframes bounce-focus {
            0%, 100% { transform: translateX(-50%) translateY(0); }
            50% { transform: translateX(-50%) translateY(-10px); }
        }

@keyframes glow {
            0%, 100% { filter: brightness(1.1) drop-shadow(0 0 20px rgba(201, 168, 108, 0.3)); }
            50% { filter: brightness(1.3) drop-shadow(0 0 30px rgba(201, 168, 108, 0.6)); }
        }

@keyframes flower-pulse {
            0%, 100% { transform: scale(1); filter: drop-shadow(0 0 5px currentColor); }
            50% { transform: scale(1.05); filter: drop-shadow(0 0 15px currentColor); }
        }

@keyframes firefly {
            0%, 100% { opacity: 0; transform: translate(0, 0) scale(0.5); }
            50% { opacity: 1; transform: translate(var(--move-x), var(--move-y)) scale(1); }
        }

@keyframes leaf-fall {
            0% { transform: translateY(-10vh) rotate(0deg) translateX(0); opacity: 0; }
            10% { opacity: 1; }
            90% { opacity: 1; }
            100% { transform: translateY(110vh) rotate(360deg) translateX(100px); opacity: 0; }
        }

@keyframes profile-particle-float {
            0% { transform: translateY(0) translateX(0) scale(0.9); opacity: 0; }
            20% { opacity: 0.45; }
            80% { opacity: 0.25; }
            100% { transform: translateY(-130px) translateX(var(--float-x, 30px)) scale(1.2); opacity: 0; }
        }

@keyframes add-profile-pulse {
            0%, 100% {
                transform: scale(1);
                box-shadow: 0 0 0 0 rgba(201, 168, 108, 0.35);
            }
            50% {
                transform: scale(1.08);
                box-shadow: 0 0 0 16px rgba(201, 168, 108, 0);
            }
        }

@keyframes rain-fall {
            0% { transform: translateY(-100vh) rotate(15deg); opacity: 0; }
            10% { opacity: 0.6; }
            90% { opacity: 0.6; }
            100% { transform: translateY(100vh) rotate(15deg); opacity: 0; }
        }

@keyframes fog-move {
            0% { transform: translateX(-50%); }
            100% { transform: translateX(0%); }
        }

@keyframes emote-appear {
            0% { transform: scale(0) rotate(-20deg); opacity: 0; }
            50% { transform: scale(1.3) rotate(5deg); }
            100% { transform: scale(1.2) rotate(0deg); opacity: 1; }
        }

@keyframes emote-disappear {
            0% { transform: scale(1.2); opacity: 1; }
            100% { transform: scale(0.6) translateY(-20px); opacity: 0; }
        }

@keyframes emote-angry-anim {
            0%, 100% { transform: scale(1.2); }
            50% { transform: scale(1.3) rotate(-5deg); }
        }

@keyframes emote-happy-anim {
            0%, 100% { transform: scale(1.2); filter: brightness(1) drop-shadow(0 0 5px gold); }
            50% { transform: scale(1.3); filter: brightness(1.3) drop-shadow(0 0 15px gold); }
        }

@keyframes emote-shock-anim {
            0%, 100% { transform: scale(1.2) translateY(0); }
            25% { transform: scale(1.25) translateY(-5px); }
            50% { transform: scale(1.2) translateY(0); }
            75% { transform: scale(1.25) translateY(-3px); }
        }

@keyframes emote-sad-anim {
            0%, 100% { transform: scale(1.2) translateY(0); opacity: 1; }
            50% { transform: scale(1.2) translateY(10px); opacity: 0.7; }
        }

@keyframes emote-think-anim {
            0%, 100% { opacity: 1; }
            50% { opacity: 0.5; }
        }

@keyframes emote-love-anim {
            0%, 100% { transform: scale(1.2); }
            50% { transform: scale(1.4); }
        }

@keyframes emote-annoyed-anim {
            0%, 100% { transform: scale(1.2) translateX(0); }
            25% { transform: scale(1.2) translateX(-3px); }
            75% { transform: scale(1.2) translateX(3px); }
        }

@keyframes emote-embarrassed-anim {
            0%, 100% { opacity: 1; filter: brightness(1); }
            50% { opacity: 0.6; filter: brightness(1.2); }
        }

@keyframes emote-idea-anim {
            0%, 100% { transform: scale(1.2); filter: brightness(1) drop-shadow(0 0 5px yellow); }
            50% { transform: scale(1.3); filter: brightness(1.5) drop-shadow(0 0 20px yellow); }
        }

@keyframes emote-sleep-anim {
            0% { transform: scale(1.2) translateY(0); opacity: 1; }
            100% { transform: scale(1.2) translateY(-30px); opacity: 0; }
        }

@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

@keyframes fadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

@keyframes topicModalFloat {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-4px); }
        }

@keyframes titleStarBlink {
            0%, 100% { opacity: 0.45; transform: scale(0.95); }
            50% { opacity: 1; transform: scale(1.15); }
        }

@keyframes pulse-diamond {
            0%, 100% { opacity: 0.3; transform: rotate(45deg) scale(1); }
            50% { opacity: 1; transform: rotate(45deg) scale(1.2); }
        }


@keyframes firefly-pulse {
            0%, 100% { opacity: 0.42; transform: scale(0.82); }
            50% { opacity: 1; transform: scale(1.14); }
        }

@keyframes sprite-breathing {
            0%, 100% { transform: translateY(0) scaleY(1) rotate(-0.2deg); }
            35% { transform: translateY(-1px) scaleY(1.013) rotate(0.25deg); }
            68% { transform: translateY(1px) scaleY(0.992) rotate(-0.2deg); }
        }

@keyframes avatar-rune-pulse {
            0%, 100% { filter: drop-shadow(0 0 6px rgba(201,168,108,0.4)); opacity: 0.85; }
            50% { filter: drop-shadow(0 0 16px rgba(201,168,108,0.95)); opacity: 1; }
        }

@keyframes wax-stamp-pop {
            0% { transform: scale(0.6) rotate(-14deg); opacity: 0.5; }
            60% { transform: scale(1.18) rotate(5deg); opacity: 1; }
            100% { transform: scale(1) rotate(0deg); }
        }

@keyframes vn-scene-cinematic {
            0%   { opacity: 0; backdrop-filter: blur(0px);  }
            35%  { opacity: 1; backdrop-filter: blur(8px);  }
            65%  { opacity: 1; backdrop-filter: blur(8px);  }
            100% { opacity: 0; backdrop-filter: blur(0px);  }
        }

/* ============================================
   MEJORA 9: OVERLAY DE TRANSICIÓN DE SECCIÓN
   ============================================ */
#sectionTransitionOverlay {
    position: fixed;
    inset: 0;
    background: rgba(10, 8, 5, 0.55);
    z-index: var(--z-i-9999);
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.18s ease;
}
#sectionTransitionOverlay.fade-out {
    opacity: 1;
}

/* ── Transiciones tipo VN: estado activo común ──────────────────────────── */
#sectionTransitionOverlay.eth-t-active {
    background: rgb(10, 8, 5);
    opacity: 1;
    pointer-events: auto;
    transition: none;
}

/* ── Iris (círculo que crece / encoge) ──────────────────────────────────── */
@keyframes eth-iris-close {
    from { clip-path: circle(0%   at 50% 50%); }
    to   { clip-path: circle(150% at 50% 50%); }
}
@keyframes eth-iris-open {
    from { clip-path: circle(150% at 50% 50%); }
    to   { clip-path: circle(0%   at 50% 50%); }
}
#sectionTransitionOverlay.eth-t-iris-close {
    animation: eth-iris-close 380ms cubic-bezier(0.4, 0, 0.2, 1) both;
}
#sectionTransitionOverlay.eth-t-iris-open {
    animation: eth-iris-open 320ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

/* ── Diagonal (cortinilla de derecha a izquierda) ───────────────────────── */
@keyframes eth-diag-close {
    from { clip-path: polygon(140% 0%, 180% 0%, 160% 100%, 120% 100%); }
    to   { clip-path: polygon(-20% 0%, 180% 0%, 160% 100%, -60% 100%); }
}
@keyframes eth-diag-open {
    from { clip-path: polygon(-20% 0%, 180% 0%, 160% 100%, -60% 100%); }
    to   { clip-path: polygon(-180% 0%, -140% 0%, -160% 100%, -200% 100%); }
}
#sectionTransitionOverlay.eth-t-diagonal-close {
    animation: eth-diag-close 340ms cubic-bezier(0.4, 0, 0.2, 1) both;
}
#sectionTransitionOverlay.eth-t-diagonal-open {
    animation: eth-diag-open 300ms cubic-bezier(0.4, 0, 0.2, 1) both;
}

/* ============================================
   MEJORA 11: LOGO ANIMADO ETHERIA
   ============================================ */
.menu-title-animated {
    display: inline-block;
    position: relative;
}
.menu-title-animated .title-letter {
    display: inline-block;
    /* Sin animación en reposo — solo brilla al hacer hover en el sidebar */
    text-shadow:
        0 0 12px rgba(201, 168, 108, 0.35),
        0 0 28px rgba(201, 168, 108, 0.15);
    transition: text-shadow 0.4s ease, transform 0.4s ease;
}
.menu-sidebar:hover .menu-title-animated .title-letter {
    text-shadow:
        0 0 20px rgba(201, 168, 108, 0.6),
        0 0 40px rgba(201, 168, 108, 0.3);
}
.menu-title-animated .title-letter:nth-child(1) { animation-delay: 0s; }

@keyframes titleFloat {
    0%, 100% {
        transform: translateY(0) scale(1);
        text-shadow: 0 0 20px rgba(201, 168, 108, 0.6), 0 0 40px rgba(201, 168, 108, 0.3);
        color: inherit;
    }
    30% {
        transform: translateY(-5px) scale(1.05);
        text-shadow: 0 0 30px rgba(201, 168, 108, 0.9), 0 0 60px rgba(255, 220, 130, 0.5);
        color: #ffecc8;
    }
    60% {
        transform: translateY(-2px) scale(1.02);
    }
}

/* ============================================
   MEJORA 12: EFECTO SUSPENSE EN OPCIONES
   ============================================ */
.vn-section.suspense-mode .vn-sprite-container,
.vn-section.suspense-mode > .weather-container {
    filter: blur(4px);
    transform: scale(0.97);
    transition: filter 0.5s ease, transform 0.5s ease;
}
.vn-section.suspense-mode::after {
    content: '';
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.35);
    pointer-events: none;
    z-index: var(--z-i-155);
    animation: suspenseFadeIn 0.5s ease forwards;
}
@keyframes suspenseFadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

/* ============================================
   MEJORA 7: DADO DND
   ============================================ */
.dice-toggle-btn {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: rgba(107, 80, 155, 0.2);
    border: 1.5px solid rgba(150, 120, 200, 0.5);
    color: rgba(200, 175, 240, 0.9);
    border-radius: 8px;
    padding: 0.5rem 0.9rem;
    cursor: pointer;
    font-family: 'Inter', sans-serif;
    font-size: 0.85rem;
    transition: all 0.2s;
    white-space: nowrap;
}
.dice-toggle-btn:hover, .dice-toggle-btn.active {
    background: rgba(107, 80, 155, 0.4);
    border-color: rgba(180, 150, 230, 0.8);
    color: #d8c8ff;
}

.dice-result-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.7);
    z-index: var(--z-i-5000);
    display: flex;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(6px);
    animation: fadeIn 0.3s ease;
}
.dice-result-box {
    background: linear-gradient(135deg, rgba(30, 20, 50, 0.97), rgba(15, 10, 30, 0.99));
    border: 2px solid rgba(180, 150, 230, 0.6);
    border-radius: 20px;
    padding: 2.5rem 3rem;
    text-align: center;
    box-shadow: 0 0 60px rgba(150, 100, 255, 0.3), 0 0 120px rgba(80, 50, 180, 0.15);
    min-width: 260px;
    animation: diceReveal 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes diceReveal {
    from { transform: scale(0.5) rotate(-10deg); opacity: 0; }
    to { transform: scale(1) rotate(0deg); opacity: 1; }
}
.dice-number {
    font-family: 'Cinzel', serif;
    font-size: 5rem;
    font-weight: 700;
    line-height: 1;
    margin-bottom: 0.5rem;
}
.dice-result-label {
    font-family: 'Cinzel', serif;
    font-size: 1.5rem;
    letter-spacing: 0.1em;
    margin-bottom: 0.4rem;
}
.dice-result-success { color: #5ec98a; text-shadow: 0 0 20px rgba(94, 201, 138, 0.7); }
.dice-result-fail { color: #e07070; text-shadow: 0 0 20px rgba(224, 112, 112, 0.7); }
.dice-result-critical { color: #f1c40f; text-shadow: 0 0 30px rgba(241, 196, 15, 0.9); }
.dice-result-fumble { color: #ff4444; text-shadow: 0 0 30px rgba(255, 68, 68, 0.9); }
.dice-close-hint {
    color: rgba(200, 185, 160, 0.5);
    font-size: 0.8rem;
    font-family: 'Inter', sans-serif;
    margin-top: 1.2rem;
}

@keyframes diceRoll {
    0% { transform: rotate(0deg) scale(1); }
    25% { transform: rotate(180deg) scale(1.3); }
    50% { transform: rotate(360deg) scale(0.8); }
    75% { transform: rotate(540deg) scale(1.2); }
    100% { transform: rotate(720deg) scale(1); }
}
.dice-rolling {
    animation: diceRoll 0.6s ease-in-out;
}

/* ============================================
   MEJORA 7 REVISADA: DADO — BADGE EN CAJA DE DIÁLOGO
   ============================================ */

/* Wrapper contador + badge */
.vn-counter-dice-wrap {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.25rem;
}

/* Badge del resultado del dado — compacto, debajo del contador */
.vn-dice-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-family: 'Cinzel', serif;
    font-size: 0.72rem;
    letter-spacing: 0.04em;
    padding: 0.3rem 0.7rem;
    border-radius: 8px;
    border: 1px solid currentColor;
    border-left-width: 3px;
    opacity: 0.9;
    user-select: none;
    max-width: 100%;
    flex-wrap: wrap;
    animation: diceBadgePop 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes diceBadgePop {
    from { transform: scale(0.7); opacity: 0; }
    to   { transform: scale(1);   opacity: 0.85; }
}

/* Colores por resultado */
.vn-dice-badge.badge-critical {
    color: #f1c40f;
    border-color: rgba(241, 196, 15, 0.45);
    background: rgba(241, 196, 15, 0.08);
    text-shadow: 0 0 8px rgba(241, 196, 15, 0.5);
}
.vn-dice-badge.badge-fumble {
    color: #ff5555;
    border-color: rgba(255, 85, 85, 0.45);
    background: rgba(255, 85, 85, 0.08);
}
.vn-dice-badge.badge-success {
    color: #5ec98a;
    border-color: rgba(94, 201, 138, 0.5);
    background: rgba(94, 201, 138, 0.1);
}
.vn-dice-badge.badge-fail {
    color: #e07070;
    border-color: rgba(224, 112, 112, 0.5);
    background: rgba(224, 112, 112, 0.1);
}

/* Preview del dado en el panel de respuesta */
.dice-preview-badge {
    font-family: 'Cinzel', serif;
    font-size: 0.78rem;
    letter-spacing: 0.05em;
    padding: 0.2rem 0.6rem;
    border-radius: 6px;
    border: 1px solid currentColor;
    opacity: 0.9;
}
.dice-preview-badge.badge-critical { color: #f1c40f; border-color: rgba(241,196,15,0.5); background: rgba(241,196,15,0.1); }
.dice-preview-badge.badge-fumble   { color: #ff5555; border-color: rgba(255,85,85,0.5);  background: rgba(255,85,85,0.1); }
.dice-preview-badge.badge-success  { color: #6bdd9a; border-color: rgba(107,221,154,0.5); background: rgba(107,221,154,0.1); }
.dice-preview-badge.badge-fail     { color: #dd6b6b; border-color: rgba(221,107,107,0.5); background: rgba(221,107,107,0.1); }

/* Botón quitar tirada */
.dice-clear-btn {
    background: none;
    border: 1px solid rgba(200,180,160,0.25);
    color: rgba(200,180,160,0.5);
    border-radius: 5px;
    padding: 0.18rem 0.45rem;
    font-size: 0.72rem;
    cursor: pointer;
    font-family: 'Inter', sans-serif;
    transition: all 0.15s;
}
.dice-clear-btn:hover {
    border-color: rgba(200,180,160,0.6);
    color: rgba(200,180,160,0.9);
}

/* Botón dado — desactivado cuando no hay texto */
.dice-toggle-btn:disabled,
.dice-toggle-btn.no-text {
    opacity: 0.35;
    cursor: not-allowed;
    pointer-events: none;
}
.dice-toggle-btn.rolled {
    border-color: rgba(107, 221, 154, 0.6);
    color: rgba(107, 221, 154, 0.9);
    background: rgba(107, 221, 154, 0.08);
}

/* ── TYPEWRITER DRAMÁTICO ────────────────────────────────── */
.tw-char {
    display: inline;
    opacity: 0;
    filter: blur(4px);
    transform: translateY(6px);
    transition: none;
}
.tw-char--in {
    animation: tw-char-appear 0.22s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes tw-char-appear {
    0%   { opacity: 0; filter: blur(5px); transform: translateY(5px); }
    60%  { opacity: 1; filter: blur(0px); transform: translateY(-1px); }
    100% { opacity: 1; filter: blur(0px); transform: translateY(0);   }
}

/* ── Respiración de la sombra (espejo del sprite-breathing) ── */
@keyframes shadow-breathe {
    0%,  100% { transform: scaleY(1)     scaleX(1)     translateY(0);   opacity: 0.95; }
    35%       { transform: scaleY(1.014) scaleX(0.996) translateY(-1px); opacity: 1;    }
    68%       { transform: scaleY(0.991) scaleX(1.003) translateY(1px);  opacity: 0.93; }
}

/* ── Animaciones de entrada para cards y listas ── */
@keyframes cardReveal {
    from {
        opacity: 0;
        transform: translateY(14px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideInLeft {
    from {
        opacity: 0;
        transform: translateX(-16px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}


/* -- css/mobile-perf.css -- */
/* ================================================================
   ETHERIA — MOBILE PERFORMANCE OPTIMIZATIONS
   css/mobile-perf.css
   ================================================================
   Cargado DESPUÉS de components.css (ver main.css).
   Estrategia:
     1. @media (max-width: 767px) — reduce intensidad sin eliminar.
     2. @media (prefers-reduced-motion: reduce) — pausa todo lo no esencial.
     3. body.is-mobile — clase JS para control fino (partículas, typewriter).
     4. body.low-spec — clase JS para gama baja adicional.

   REGLA: nada aquí afecta a min-width: 1024px.
         Los efectos originales permanecen intactos en desktop.
   ================================================================ */


/* ================================================================
   A. PARTÍCULAS Y WEATHER EFFECTS
   profile-particle, rain-drop, fog-layer, firefly, leaf
   ================================================================ */

/* --- A1. Profile particles: más lentas en mobile --- */
@media (max-width: 767px) {
    .profile-particle {
        /* Duraciones más largas = menos frames por segundo */
        animation-duration: calc(var(--particle-duration, 8s) * 1.8) !important;
    }
}

/* --- A2. Lluvia: menos gotas (JS) + animación más lenta --- */
@media (max-width: 767px) {
    .rain-drop {
        /* Aumentar duración base: la generación JS ya limita la cantidad */
        animation-duration: calc(var(--rain-duration, 0.7s) * 1.6) !important;
        opacity: 0.4; /* ligeramente más sutil */
    }
}

/* --- A3. Niebla: blur reducido + transición más lenta --- */
@media (max-width: 767px) {
    .fog-layer {
        filter: blur(10px); /* 20px → 10px: la mitad de GPU */
        opacity: 0.25;      /* 0.4 → 0.25 */
    }
    .fog-layer:nth-child(1) { animation-duration: 50s; }  /* 30s → 50s */
    .fog-layer:nth-child(2) { animation-duration: 40s; }  /* 25s → 40s */
    .fog-layer:nth-child(3) { animation-duration: 56s; }  /* 35s → 56s */
}

/* --- A4. Fireflies / Petals: Canvas system — pool size controlled in JS --- */
/* .firefly y .leaf ya no existen en el DOM, el canvas se gestiona en generateParticles() */

/* --- A5. Canvas partículas: ocultar en low-spec vía JS (isLowSpec check) --- */



/* ================================================================
   B. SUSPENSE MODE (blur + overlay)
   ================================================================ */

@media (max-width: 767px) {
    /* B1. Blur suavizado: 4px → 2px */
    .vn-section.suspense-mode .vn-sprite-container,
    .vn-section.suspense-mode > .weather-container {
        filter: blur(2px);          /* 4px → 2px */
        transform: scale(0.985);    /* 0.97 → 0.985 — menos GPU */
        transition: filter 0.3s ease, transform 0.3s ease; /* 0.5s → 0.3s */
    }

    /* B2. Overlay más ligero */
    .vn-section.suspense-mode::after {
        background: rgba(0, 0, 0, 0.22); /* 0.35 → 0.22 */
        animation: suspenseFadeIn 0.3s ease forwards; /* 0.5s → 0.3s */
    }
}

body.low-spec .vn-section.suspense-mode .vn-sprite-container,
body.low-spec .vn-section.suspense-mode > .weather-container {
    filter: none; /* Sin blur en gama baja */
    transform: scale(0.99);
}


/* ================================================================
   C. TYPEWRITER — la clase JS body.is-mobile ajusta la velocidad
      en JS directamente. El CSS sólo acorta la animación del span.
   ================================================================ */

@media (max-width: 767px) {
    .tw-char--in {
        /* 0.22s → 0.13s: el fade por carácter es menos pesado */
        animation-duration: 0.13s;
    }

    /* En mobile el blur inicial también consume GPU — lo reducimos */
    .tw-char {
        filter: blur(2px);          /* 4px → 2px */
        transform: translateY(4px); /* 6px → 4px */
    }
}

body.low-spec .tw-char--in {
    /* Gama baja: sin animación per-char, solo aparece */
    animation-duration: 0.04s;
}
body.low-spec .tw-char {
    filter: none;
    transform: none;
}


/* ================================================================
   D. EMOTES MANGA
   ================================================================ */

@media (max-width: 767px) {
    /* D1. Animación de aparición más rápida (0.3s → 0.2s) */
    .manga-emote {
        animation-duration: 0.2s !important; /* emote-appear */
        /* Eliminar drop-shadow en mobile — es caro en compositing */
        filter: none;
    }

    /* D2. Loops más lentos: 2s → 2.8s, 1.5s → 2.2s, 0.5s → 0.9s */
    .emote-angry     { animation-duration: 2.8s !important; }
    .emote-happy     { animation-duration: 2.8s !important; }
    .emote-shock     { animation-duration: 2.8s !important; }
    .emote-sad       { animation-duration: 2.8s !important; }
    .emote-think     { animation-duration: 2.8s !important; }
    .emote-love      { animation-duration: 2.2s !important; }
    .emote-annoyed   { animation-duration: 0.9s !important; } /* Era 0.5s — muy rápido */
    .emote-embarrassed { animation-duration: 2.8s !important; }
    .emote-idea      { animation-duration: 2.8s !important; }
    .emote-sleep     { animation-duration: 4s   !important; }  /* 3s → 4s */
}

body.low-spec .manga-emote {
    /* Gama baja: sin bucle, solo la aparición */
    animation-iteration-count: 1 !important;
}


/* ================================================================
   E. SPRITE BREATHING + SHADOW BREATHE
   ================================================================ */

@media (max-width: 767px) {
    /* E1. Breathing muy suave: duplicar duración */
    .vn-sprite.active img {
        animation-duration: 8s !important;  /* 4s → 8s */
    }

    /* E2. shadow-breathe */
    .vn-sprite.active .shadow-silhouette {
        animation-duration: 8s !important;  /* 4.8s → 8s */
    }

    /* E3. sprite-breathing del keyframe estático (línea 3583 components.css) */
    .vn-sprite.active .vn-sprite-img,
    .vn-sprite.active > img {
        animation-duration: 8s !important;
    }

    /* E4. Reducir blur de sombras inactivas — son costosas */
    .vn-sprite.inactive .shadow-silhouette {
        filter: blur(3px);          /* 5px → 3px */
    }
    .shadow-silhouette {
        filter: blur(1px);          /* 1.5px → 1px */
        transition: filter 0.35s ease, transform 0.35s ease, opacity 0.35s ease; /* 0.6s → 0.35s */
    }
    .shadow-silhouette.shadow-masc { filter: blur(0.6px); } /* sin cambio */
    .shadow-silhouette.shadow-fem  { filter: blur(1.2px); } /* 1.8px → 1.2px */
}

body.low-spec .vn-sprite.active img,
body.low-spec .vn-sprite.active .shadow-silhouette {
    /* Gama baja: sin respiración */
    animation: none !important;
}
body.low-spec .shadow-silhouette {
    filter: none !important;
    transition: none !important;
}


/* ================================================================
   F. DICE ANIMATIONS
   ================================================================ */

@media (max-width: 767px) {
    /* F1. Overlay de resultado: sin backdrop-filter (MUY caro) */
    .dice-result-overlay {
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        background: rgba(0, 0, 0, 0.82); /* Compensa visualmente */
    }

    /* F2. Animación de reveal: 0.5s → 0.3s + scale más corto */
    .dice-result-box {
        animation-duration: 0.3s;
        /* Eliminar box-shadow doble — una capa es suficiente */
        box-shadow: 0 0 40px rgba(150, 100, 255, 0.25);
    }

    /* F3. diceRoll: 0.6s → 0.4s + menos scale */
    .dice-rolling {
        animation-duration: 0.4s !important;
    }

    /* F4. Número del dado: sin text-shadow pesado */
    .dice-result-critical { text-shadow: 0 0 12px rgba(241, 196, 15, 0.7); }
    .dice-result-fumble   { text-shadow: 0 0 12px rgba(255, 68, 68, 0.7);  }
    .dice-result-success  { text-shadow: none; }
    .dice-result-fail     { text-shadow: none; }
}


/* ================================================================
   G. ANIMACIONES GENERALES: backdrop-filter y blurs pesados
   ================================================================ */

@media (max-width: 767px) {
    /* G1. Menu sidebar: backdrop-filter 20px → 8px */
    .menu-sidebar {
        backdrop-filter: blur(8px);
        -webkit-backdrop-filter: blur(8px);
    }

    /* G2. Modal overlays: backdrop-filter reducido */
    .modal-overlay {
        backdrop-filter: blur(4px);
        -webkit-backdrop-filter: blur(4px);
    }

    /* G3. Settings panel */
    .settings-panel {
        backdrop-filter: blur(6px);
        -webkit-backdrop-filter: blur(6px);
    }

    /* G4. Collab typing indicator */
    .collab-typing-indicator {
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
        background: rgba(20, 16, 12, 0.88);
    }

    /* G5. vn-scene-cinematic: sin backdrop-filter animado */
    @keyframes vn-scene-cinematic-mobile {
        0%   { opacity: 0; }
        35%  { opacity: 1; }
        65%  { opacity: 1; }
        100% { opacity: 0; }
    }
    .vn-scene-transition.active {
        animation-name: vn-scene-cinematic-mobile;
        animation-duration: 600ms; /* 750ms → 600ms */
    }

    /* G6. Section transition overlay: más rápido */
    #sectionTransitionOverlay {
        transition: opacity 0.12s ease; /* 0.18s → 0.12s */
    }

    /* G7. Glow de sprites: versión ligera */
    .vn-sprite.active.sprite-blink img {
        filter: brightness(1.1) saturate(1.04)
                drop-shadow(0 18px 24px rgba(0,0,0,0.4)); /* Reduce 2 capas a 1 */
    }

    /* G8. shadow-silhouette-img: menos capas de drop-shadow */
    .shadow-silhouette-img {
        filter:
            drop-shadow(0 8px 16px rgba(0, 0, 0, 0.5));  /* 2 drop-shadow → 1 */
    }
    .vn-sprite.active .shadow-silhouette-img {
        filter:
            drop-shadow(0 10px 20px rgba(0, 0, 0, 0.55));
    }
    .vn-sprite.inactive .shadow-silhouette-img {
        filter:
            blur(1.5px)
            drop-shadow(0 6px 10px rgba(0, 0, 0, 0.35));
    }

    /* G9. btn-pulse-soft: más lento */
    .add-profile-btn {
        animation-duration: 4s; /* 2.8s → 4s */
    }

    /* G10. Autosave icon wax-stamp */
    .autosave-indicator.visible .autosave-icon {
        animation-duration: 0.25s; /* 0.38s → 0.25s */
    }

    /* G11. story-dot-pulse */
    .story-active-dot {
        animation-duration: 3s; /* 2s → 3s */
    }

    /* G12. titleFloat — desactivado en mobile (solo hover en desktop) */
    .menu-title-animated .title-letter {
        /* La animación titleFloat no está activa en reposo, pero
           por si acaso se activa programáticamente: */
        animation: none !important;
    }

    /* G13. bgParallaxIn: sin filter brightness animado */
    @keyframes bgParallaxIn-mobile {
        from { transform: scale(1.03) translateY(4px); }
        to   { transform: scale(1)    translateY(0);   }
    }
    .vn-section-bg-enter {
        animation-name: bgParallaxIn-mobile;
        animation-duration: 0.5s;
    }

    /* G14. Shadow glow: transición más corta */
    .shadow-glow {
        transition: opacity 0.35s ease; /* 0.6s → 0.35s */
    }
}


/* ================================================================
   H. SPRITE SHIMMER LOADING
   ================================================================ */
@media (max-width: 767px) {
    /* H1. Shimmer de carga: animación más lenta */
    .vn-sprite img.is-loading {
        animation-duration: 2.4s !important; /* 1.8s → 2.4s */
    }
}


/* ================================================================
   I. COLLAB TYPING DOTS
   ================================================================ */
@media (max-width: 767px) {
    .collab-typing-indicator::after {
        animation-duration: 1.8s; /* 1.4s → 1.8s */
    }
}


/* ================================================================
   J. GALLERY lazy-load transition
   ================================================================ */
@media (max-width: 767px) {
    .gallery-img-loading {
        /* En mobile, el blur-up de 8px es caro */
        filter: blur(4px) brightness(0.75);
        transition: filter 0.25s ease, transform 0.25s ease;
    }
    .gallery-img-loaded {
        transition: filter 0.25s ease, transform 0.25s ease;
    }
}


/* ================================================================
   K. PREFERS-REDUCED-MOTION — extiende el bloque ya existente
      en components.css. Añade lo que faltaba cubrir.
   ================================================================ */

@media (prefers-reduced-motion: reduce) {
    /* K1. Efectos de clima — parar por completo */
    .rain-drop,
    .fog-layer,
    .leaf,
    .profile-particle {
        animation: none !important;
        transition: none !important;
    }

    /* K2. Fireflies — parar rAF es responsabilidad del JS (ver characters.js).
           El CSS elimina la animación CSS de parpadeo si la hubiera */
    .firefly {
        animation: none !important;
        opacity: 0.5;
    }

    /* K3. Suspense mode — sin blur ni scale */
    .vn-section.suspense-mode .vn-sprite-container,
    .vn-section.suspense-mode > .weather-container {
        filter: none !important;
        transform: none !important;
        transition: none !important;
    }
    .vn-section.suspense-mode::after {
        animation: none !important;
        opacity: 0.3;
    }

    /* K4. Typewriter — sin animación por carácter */
    .tw-char--in {
        animation: none !important;
        opacity: 1 !important;
        filter: none !important;
        transform: none !important;
    }
    .tw-char {
        opacity: 0; /* El JS los muestra uno a uno, esto es solo estado inicial */
        filter: none;
        transform: none;
    }

    /* K5. Emotes — solo aparición, sin loop */
    .manga-emote {
        animation: none !important;
        filter: none !important;
        opacity: 1;
        transform: scale(1.2);
    }

    /* K6. Sprite breathing — parar */
    .vn-sprite.active img,
    .vn-sprite.active .shadow-silhouette {
        animation: none !important;
    }

    /* K7. Sprite shimmer */
    .vn-sprite img.is-loading {
        animation: none !important;
        filter: brightness(0.7);
    }

    /* K8. Dice */
    .dice-result-box {
        animation: none !important;
    }
    .dice-rolling {
        animation: none !important;
    }

    /* K9. Shadow glow transition */
    .shadow-glow {
        transition: none !important;
    }

    /* K10. Section transition overlay */
    #sectionTransitionOverlay {
        transition: none !important;
    }

    /* K10b. VN-style transitions (iris, diagonal) */
    #sectionTransitionOverlay.eth-t-iris-close,
    #sectionTransitionOverlay.eth-t-iris-open,
    #sectionTransitionOverlay.eth-t-diagonal-close,
    #sectionTransitionOverlay.eth-t-diagonal-open {
        animation: none !important;
        clip-path: none !important;
    }

    /* K11. Story dot pulse */
    .story-active-dot {
        animation: none !important;
    }

    /* K12. btn-pulse-soft */
    .add-profile-btn {
        animation: none !important;
    }

    /* K13. collab typing dots */
    .collab-typing-indicator::after {
        animation: none !important;
    }

    /* K14. Gallery transitions */
    .gallery-img-loading,
    .gallery-img-loaded {
        filter: none !important;
        transform: none !important;
        transition: none !important;
    }

    /* K15. Autosave indicator */
    .autosave-indicator.visible .autosave-icon {
        animation: none !important;
    }

    /* K16. bgParallaxIn — sin transform animado */
    .vn-section-bg-enter {
        animation: none !important;
    }
}


/* ================================================================
   L. PWA STANDALONE — body.is-pwa
   Solo se aplica cuando la app está instalada y corre sin chrome
   del navegador. No afecta en absoluto a la versión de escritorio
   o navegador normal.
   ================================================================ */

/* ── L1. Eliminar rubber-band / overscroll ──────────────────────
   El rebote elástico al hacer scroll más allá del límite es la
   señal más clara de "esto es una web". Con none desaparece en
   Android. En iOS afecta al body pero no al scroll interno. */
body.is-pwa {
    overscroll-behavior: none;
}

/* ── L2. Evitar selección de texto accidental ───────────────────
   En la pantalla principal, menú y VN un tap largo no debería
   seleccionar texto. Sí la dejamos activa en inputs, textareas
   y zonas de contenido de usuario (mensajes). */
body.is-pwa .main-menu,
body.is-pwa .user-select-screen,
body.is-pwa .menu-sidebar,
body.is-pwa .vn-section .vn-dialogue-box,
body.is-pwa .vn-section .vn-controls,
body.is-pwa .vn-section .vn-weather-controls,
body.is-pwa .section-header-bar,
body.is-pwa .topics-list .topic-header-row,
body.is-pwa .auth-screen .auth-card {
    user-select: none;
    -webkit-user-select: none;
}
/* Restablecer en zonas donde sí queremos selección */
body.is-pwa input,
body.is-pwa textarea,
body.is-pwa [contenteditable],
body.is-pwa .vn-message-text,
body.is-pwa .vn-dialogue-text {
    user-select: text;
    -webkit-user-select: text;
}

/* ── L3. Safe areas completas ───────────────────────────────────
   Gestionadas por pwa.css a nivel de elemento individual
   (auth-screen, main-menu, #vnSection, game-sections…).
   NO ponemos padding en body.is-pwa porque .game-section no es
   position:fixed y el body padding causaría un gap arriba +
   recorte abajo (height:100vh se calcula desde la posición
   desplazada, no desde el borde del viewport). */

/* Los elementos fixed necesitan safe area propia — heredarla del
   body no funciona porque están fuera del flujo normal. */
body.is-pwa .autosave-indicator {
    bottom: calc(env(safe-area-inset-bottom, 0px) + 0.7rem);
}
body.is-pwa #cloudSyncIndicator {
    bottom: calc(env(safe-area-inset-bottom, 0px) + 1rem);
}
body.is-pwa .ethy-container {
    bottom: calc(env(safe-area-inset-bottom, 0px) + 20px);
    right:  calc(env(safe-area-inset-right,  0px) + 20px);
}
body.is-pwa .settings-panel {
    padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 1rem);
}
/* Reply modal: el footer con "Publicar" no debe quedar bajo la home bar */
body.is-pwa .vrp-footer {
    padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 0.55rem);
}
/* Menu sidebar */
body.is-pwa .menu-sidebar {
    padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 1rem);
}

/* ── L4. Ajustes de layout exclusivos de standalone ────────────
   Pequeños retoques que solo tienen sentido cuando no hay barra
   del navegador y la app ocupa toda la pantalla. */
body.is-pwa .auth-screen {
    /* En standalone la pantalla de auth puede quedar cortada en
       algunos Android por la barra de sistema. Compensamos. */
    min-height: 100dvh;
}
/* Ocultar el banner de "instala la app" si algún día se añade,
   ya que en standalone no tiene sentido mostrarlo. */
body.is-pwa .pwa-install-banner {
    display: none !important;
}

/* ── L5. Tap highlight — eliminar el flash gris en Android ─────
   El highlight azul/gris que aparece al tocar elementos en
   Android Chrome es un indicador visual de "web". */
body.is-pwa * {
    -webkit-tap-highlight-color: transparent;
}
/* Restablecer para inputs para que tengan feedback visual */
body.is-pwa input,
body.is-pwa textarea,
body.is-pwa select {
    -webkit-tap-highlight-color: rgba(201, 168, 108, 0.15);
}


/* ================================================================
   M. PWA LANDSCAPE — Layout horizontal tipo videojuego
   Solo activo en: body.is-pwa + orientation:landscape + min-width
   ================================================================
   
   Objetivo: cuando la app está instalada y se usa en apaisado,
   cada pantalla aprovecha el ancho extra de forma inteligente
   en vez de simplemente mostrar el layout vertical estirado.
   ================================================================ */

@media (orientation: landscape) and (min-width: 600px) {

    /* ── M1. Selector de perfiles ─────────────────────────────────
       En portrait: tarjetas en grid centrado verticalmente.
       En landscape: mismo grid pero con más columnas y altura
       reducida para que quepan sin scroll. */
    body.is-pwa .user-select-screen {
        flex-direction: row;
        justify-content: center;
        align-items: center;
        gap: 0;
        padding: 0;
    }

    /* Cabecera lateral izquierda */
    body.is-pwa .user-select-screen > *:not(.profile-particles):not(.user-cards):not(.profile-theme-btn) {
        /* El título ETHERIA y subtítulo van en un panel lateral */
        writing-mode: initial;
    }

    /* Zona central: scroll horizontal compacto en landscape */
    body.is-pwa .user-cards {
        max-width: min(96vw, 900px);
        width: max-content;
        gap: 0.75rem;
    }

    /* Tarjetas más compactas en landscape */
    body.is-pwa .user-card,
    body.is-pwa .add-profile-card {
        flex: 0 0 172px;
        width: 172px;
    }
    body.is-pwa .user-card:hover {
        transform: translateY(-4px) scale(1.01);
    }

    /* ── M2. Menú principal ───────────────────────────────────────
       El sidebar ya es lateral — solo ajustamos proporciones
       para que no ocupe demasiado ancho del viewport. */
    body.is-pwa .menu-sidebar {
        width: clamp(240px, 30vw, 340px);
        padding: 1.75rem 1.5rem;
        overflow-y: auto;
    }
    body.is-pwa .menu-brand {
        margin-bottom: 1.5rem;
    }
    body.is-pwa .menu-title {
        font-size: clamp(1.8rem, 3.5vw, 2.4rem);
    }
    body.is-pwa .menu-subtitle {
        font-size: 0.85rem;
    }
    body.is-pwa .menu-container {
        gap: 0.55rem;
    }
    body.is-pwa .menu-button {
        padding: 0.7rem 1.1rem;
        font-size: 0.9rem;
    }

    /* Info del usuario en el menú: más compacta */
    body.is-pwa .menu-user-info {
        margin-top: 1rem;
        padding-top: 0.75rem;
    }

    /* ── M3. Secciones internas (Galería, Topics, Options) ────────
       La barra de encabezado y el contenido se pueden permitir
       más ancho, así que limitamos el max-width. */
    body.is-pwa .game-section:not(#vnSection) .section-content {
        max-width: 100%;
    }

    /* ── M4. VN section — landscape ──────────────────────────────
       El VN ya funciona bien en landscape, solo ajustamos el
       diálogo para que sea más compacto y deje más espacio al fondo. */
    body.is-pwa .vn-dialogue-box {
        max-width: min(75vw, 820px);
        margin: 0 auto;
    }

    /* Info card del personaje: sidebar vertical compacto */
    body.is-pwa .vn-info-card {
        max-width: 200px;
        font-size: 0.78rem;
    }

    /* Controles VN: barra horizontal compacta arriba */
    body.is-pwa .vn-controls {
        gap: 0.3rem;
    }

    /* ── M5. Secciones con header-bar ─────────────────────────────
       En landscape el header puede ser más bajo ya que no hay
       barra de navegador ocupando espacio vertical. */
    body.is-pwa .section-header-bar {
        padding: 0.75rem 1.5rem;
    }

    /* ── M6. Topics list — dos columnas en landscape ──────────────*/
    body.is-pwa .topics-list-container,
    body.is-pwa #topicsList {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0.75rem;
        align-items: start;
    }
    /* Revertir para el header que está dentro */
    body.is-pwa .topics-list-container > .topic-header-row,
    body.is-pwa #topicsList > .topic-group-header,
    body.is-pwa #topicsList > .topics-empty {
        grid-column: 1 / -1;
    }

    /* ── M7. Galería — más columnas en landscape ──────────────────*/
    body.is-pwa .characters-grid,
    body.is-pwa .gallery-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    }
}

/* ── Landscape en pantallas pequeñas (móvil apaisado) ─────────────
   Ajustes más agresivos para teléfonos girados donde la altura
   es muy reducida (max-height: 500px). */
@media (orientation: landscape) and (min-width: 600px) and (max-height: 500px) {

    body.is-pwa .user-cards {
        max-width: 90dvw;
    }
    body.is-pwa .user-card,
    body.is-pwa .add-profile-card {
        flex: 0 0 150px;
        width: 150px;
    }
    body.is-pwa .user-card-footer { padding: 0.4rem 0.6rem; }

    body.is-pwa .menu-sidebar {
        padding: 1rem 1.1rem;
        width: clamp(200px, 28vw, 280px);
    }
    body.is-pwa .menu-brand { margin-bottom: 0.75rem; }
    body.is-pwa .menu-button { padding: 0.55rem 0.9rem; font-size: 0.82rem; }

    body.is-pwa .section-header-bar { padding: 0.5rem 1rem; }

    /* VN: barra de diálogo más pequeña para no tapar el fondo */
    body.is-pwa .vn-dialogue-box {
        max-width: 68vw;
        font-size: 0.9em;
    }
}


/* ================================================================
   N. PWA LANDSCAPE — ajustes de auth screen en landscape compacto
   ================================================================
   La rotación CSS de todo el body (portrait → landscape forzado)
   fue eliminada: causaba que los eventos táctiles no coincidieran
   con el layout visual, rompiendo el formulario de login.
   La orientación la gestiona screen.orientation.lock('landscape')
   desde app.js + manifest "orientation":"landscape".
   ================================================================ */

/* Auth screen en landscape móvil muy compacto (keyboard visible) */
@media (orientation: landscape) and (max-height: 500px) {
    .auth-screen {
        align-items: flex-start;
        overflow-y: auto;
        padding: 0.5rem;
    }
    .auth-container {
        width: min(420px, 94vw);
        padding: 1.25rem 1.5rem;
        margin: auto;
    }
    .auth-header { margin-bottom: 1rem; }
    .auth-logo   { font-size: 2rem; }
    .auth-title  { font-size: 1.6rem; }
}


/* ── Botón Salir del menú principal ──────────────────────────────────────
   Visible solo en PWA (body.is-pwa). En navegador se oculta porque
   window.close() no funciona en pestañas abiertas por el usuario. */

.menu-exit-btn {
    display: none; /* oculto por defecto */
}

body.is-pwa .menu-exit-btn {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    margin-top: 0.75rem;
    padding: 0.55rem 1rem;
    background: rgba(180, 60, 40, 0.07);
    border: 1px solid rgba(180, 60, 40, 0.2);
    border-radius: 8px;
    color: rgba(220, 120, 100, 0.65);
    font-family: 'Cinzel', serif;
    font-size: 0.82rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    cursor: pointer;
    transition: background 0.2s, border-color 0.2s, color 0.2s;
}
body.is-pwa .menu-exit-btn:hover,
body.is-pwa .menu-exit-btn:active {
    background: rgba(180, 60, 40, 0.15);
    border-color: rgba(200, 80, 60, 0.45);
    color: rgba(230, 140, 110, 0.9);
}
.menu-exit-icon {
    font-size: 1rem;
    line-height: 1;
}

/* ═══════════════════════════════════════════════════════════════
   LANDSCAPE COMPACTO — móvil apaisado (viewport bajo)
   El selector de perfiles usa el layout de escritorio; en ~360-520px
   de alto el título desborda, las cards se estiran a toda altura y
   los widgets flotantes pisan los botones. Capa aditiva de compactado.
   ═══════════════════════════════════════════════════════════════ */
@media (orientation: landscape) and (max-height: 640px) and (any-pointer: coarse) {

    .user-select-screen {
        padding: 6px 14px calc(6px + env(safe-area-inset-bottom, 0px)) !important;
        justify-content: flex-start !important;
    }

    /* Título y subtítulo: discretos, arriba, sin recortes */
    .game-title {
        font-size: clamp(1.3rem, 6vh, 1.9rem) !important;
        letter-spacing: 0.32em !important;
        margin: 0 !important;
        line-height: 1.1 !important;
    }
    .save-screen-rule { display: none !important; }
    .game-subtitle {
        font-size: 0.66rem !important;
        margin: 2px 0 8px !important;
        letter-spacing: 0.12em !important;
    }

    /* Fila de cards: ocupa el resto de la altura, con su scroll-x */
    .user-cards {
        max-width: 96vw !important;
        gap: 0.7rem !important;
        padding: 0.2rem 0.4rem 0.5rem !important;
        align-items: stretch !important;
    }

    /* Card compacta: cabe entera en el alto disponible; si su contenido
       no cabe, scrollea por dentro en vez de estirar el layout */
    .user-card {
        min-width: 170px !important;
        max-width: 200px !important;
        max-height: calc(100dvh - 96px - env(safe-area-inset-bottom, 0px)) !important;
        overflow-y: auto !important;
        padding: 10px 12px !important;
    }
    .user-avatar-wrap {
        width: 52px !important;
        height: 52px !important;
        margin: 0 auto 4px !important;
    }
    .user-name { font-size: 0.95rem !important; margin: 2px 0 !important; }
    .user-gender-badge { font-size: 0.6rem !important; padding: 1px 8px !important; }
    .user-card-stats { gap: 4px !important; margin: 6px 0 !important; }
    .user-card-stats > * { padding: 4px 6px !important; font-size: 0.62rem !important; }
    .user-card-divider { margin: 4px 0 !important; }
    .user-last-session, .user-last-topic { font-size: 0.6rem !important; }
    .user-continue-btn { padding: 6px 10px !important; font-size: 0.7rem !important; }
    .user-directory-badge { font-size: 0.58rem !important; }

    /* Widgets flotantes: fuera del camino de los botones de las cards */
    #ethyContainer { display: none !important; }
    .profile-theme-btn {
        top: auto !important;
        bottom: calc(8px + env(safe-area-inset-bottom, 0px)) !important;
        left: 10px !important;
        right: auto !important;
        transform: scale(0.85);
    }
}

/* ═══════════════════════════════════════════════════════════════
   LANDSCAPE COMPACTO II — hub (#mainMenu) y escena VN (#vnSection)
   Mismo rango que el selector: móvil apaisado de viewport bajo.
   ═══════════════════════════════════════════════════════════════ */
@media (orientation: landscape) and (max-height: 640px) and (any-pointer: coarse) {

    /* ── Selector: refuerzo (garantizar columna y anclaje arriba) ── */
    .user-select-screen {
        flex-direction: column !important;
        align-items: center !important;
    }
    .game-title, .game-subtitle { text-align: center !important; }

    /* ── HUB · barra superior compacta ── */
    #mainMenu .cel-topbar { top: 8px !important; left: 12px !important; right: 12px !important; }
    #mainMenu .menu-profile-btn { padding: 4px 12px 4px 4px !important; gap: 8px !important; }
    #mainMenu .menu-profile-avatar { width: 36px !important; height: 36px !important; font-size: 15px !important; }
    #mainMenu .menu-profile-name { font-size: 14px !important; }
    #mainMenu .menu-profile-hint { display: none !important; }

    /* Acciones (buzón/backup/tema): compactas y SIN pisar las cards */
    #mainMenu .menu-top-actions { gap: 6px !important; }
    #mainMenu .cel-round-btn {
        width: 34px !important;
        height: 34px !important;
        transform: none !important;
    }

    /* Marca y cita: contenidas a la mitad izquierda */
    #mainMenu .menu-brand { max-width: 46vw !important; }
    #mainMenu .menu-brand h1, #mainMenu .brand-title {
        font-size: clamp(2rem, 14vh, 3.2rem) !important;
        line-height: 1 !important;
    }

    /* Columna de cards: empieza bajo la topbar, contenida.
       hub-luna fija top:50% + translateY(-50%) con !important y
       especificidad id+2clases (#mainMenu.cel-hub .menu-container) —
       ese transform expulsaba "Continuar" por encima del viewport.
       Ganamos con id+3clases (.menu-container doblada). */
    #mainMenu.cel-hub .menu-container.menu-container,
    #mainMenu .menu-container.menu-container {
        top: 68px !important;
        right: 14px !important;
        width: min(360px, 44vw) !important;
        bottom: 8px !important;
        transform: none !important;
        z-index: 5 !important;
        max-height: none !important;
        overflow-y: auto !important;
        padding-bottom: 8px !important;
        gap: 8px !important;
    }

    /* Cards compactas (idea de Irune: en pantalla pequeña, ornamentos
       pequeños): sin subtítulo, icono-rombo reducido, sello decorativo
       de 118px fuera, padding contenido. Misma especificidad ganadora. */
    #mainMenu .hub-item-sub { display: none !important; }
    #mainMenu.cel-hub .hub-menu-item.hub-menu-item,
    #mainMenu .hub-menu-item.hub-menu-item {
        padding: 8px 12px !important;
        gap: 10px !important;
    }
    #mainMenu.cel-hub .hub-item-icon.hub-item-icon,
    #mainMenu .hub-item-icon.hub-item-icon {
        width: 30px !important;
        height: 30px !important;
    }
    #mainMenu .hub-item-icon svg { width: 13px !important; height: 13px !important; }
    #mainMenu .hub-menu-item .seal { display: none !important; }
    #mainMenu .hub-item-arcana { font-size: 0.58rem !important; }
    #mainMenu .menu-label { font-size: 1rem !important; }
    #mainMenu .menu-container .menu-card,
    #mainMenu .menu-container .menu-item { padding: 10px 14px !important; }

    /* Estado, Ethy y ruido inferior: fuera; Salir compacto en su esquina */
    #mainMenu .cel-status { display: none !important; }
    #mainMenu .cel-ethy { display: none !important; }
    #mainMenu .menu-exit-btn {
        right: 10px !important;
        bottom: calc(6px + env(safe-area-inset-bottom, 0px)) !important;
        left: auto !important;
        width: auto !important;
        padding: 6px 12px !important;
        font-size: 9.5px !important;
    }

    /* ── ESCENA VN · caja y satélites contenidos ── */
    /* Placa del hablante: pegada a la esquina del box, sin flotar */
    #vnSection .vn-speaker-plate {
        top: -12px !important;
        left: 14px !important;
        transform: none !important;
        font-size: 0.8rem !important;
        padding: 4px 14px !important;
    }

    /* Avatar del hablante: de gigante a discreto */
    #vnSection .vn-speaker-avatar-wrap,
    #vnSection .vn-speaker-avatar {
        width: 64px !important;
        height: 64px !important;
    }

    /* La caja aprovecha el ancho; menos aire interno */
    #vnSection .vn-dialogue-box { padding: 16px 18px 12px !important; }

    /* FAB de navegación: dentro del viewport, sobre la safe-area */
    #vnSection .vn-mobile-fab-nav,
    .vn-mobile-fab-nav {
        bottom: calc(4px + env(safe-area-inset-bottom, 0px)) !important;
    }
    .vn-mobile-fab-btn { width: 40px !important; height: 40px !important; }
    .vn-mobile-fab-btn.main { width: 46px !important; height: 46px !important; }

    /* Toolbar lateral derecha: compacta y pegada al borde */
    #vnSection .vn-toolbar {
        right: 2px !important;
        transform: scale(0.82) !important;
        transform-origin: right center !important;
    }

    /* ── VN · descompresión (feedback Irune) ── */
    /* Los FAB inferiores son redundantes (la caja tiene sus flechas ‹ ›
       y el botón Responder) y taparían los sprites: fuera en apaisado */
    #vnSection .vn-mobile-fab-nav,
    .vn-mobile-fab-nav { display: none !important; }

    /* Caja más contenida: aire para los sprites por encima */
    #vnSection .vn-dialogue-box {
        max-height: 46vh !important;
        margin-bottom: calc(6px + env(safe-area-inset-bottom, 0px)) !important;
    }
    #vnSection .vn-dialogue-text {
        font-size: 0.95rem !important;
        line-height: 1.5 !important;
    }
    #vnSection .vn-dialogue-actions button {
        padding: 4px 12px !important;
        font-size: 0.68rem !important;
    }
    #vnSection .vn-dialogue-footer { padding-top: 4px !important; }

    /* ── TEMAS · scroll solo en la lista, no en toda la pantalla ──
       CRÍTICO: scoped a .active — sin esto, id+!important gana siempre
       a la base ".game-section{display:none}" y fuerza la sección
       visible para siempre tras visitarla, bloqueando el resto del
       hub (mismo bug real que #gallerySection, detectado en vivo). */
    #topicsSection.active {
        height: 100dvh !important;
        overflow: hidden !important;
        display: flex !important;
        flex-direction: column !important;
    }
    #topicsSection .section-content {
        flex: 1 1 auto !important;
        min-height: 0 !important;
        overflow: hidden !important;
        display: flex !important;
    }
    #topicsSection .topics-layout {
        flex: 1 1 auto !important;
        min-height: 0 !important;
        overflow: hidden !important;
    }
    #topicsSection .topics-main {
        display: flex !important;
        flex-direction: column !important;
        min-height: 0 !important;
        height: 100% !important;
    }
    #topicsSection .topics-panel-title { flex-shrink: 0; margin: 4px 0 !important; }
    #topicsSection .topics-command-bar { flex-shrink: 0; padding: 4px 0 !important; }
    #topicsSection .topics-grid-wrap {
        flex: 1 1 auto !important;
        min-height: 0 !important;
        overflow-y: auto !important;
        padding-bottom: calc(8px + env(safe-area-inset-bottom, 0px)) !important;
    }
    /* El panel lateral de estadísticas cede el sitio en apaisado corto */
    #topicsSection .topics-sidebar,
    #topicsSection .topics-side-panel { display: none !important; }
}

/* ═══════════════════════════════════════════════════════════════
   APTITUD MÓVIL (vertical, ≤767px) — legibilidad, tacto y modales
   Pase genérico: tipografía de lectura más cómoda, objetivos
   táctiles ≥40px y modales como hoja amplia en vez de ventanita.
   ═══════════════════════════════════════════════════════════════ */
@media (max-width: 767px) and (orientation: portrait) {

    /* ── Lectura: el texto del relato es el protagonista ── */
    #vnSection .vn-dialogue-text {
        font-size: 1.05rem !important;
        line-height: 1.68 !important;
    }
    #vnSection .vn-options-subtitle { font-size: 0.76rem !important; }
    body.theme-classic #vnSection .vn-opt-text { font-size: 1rem !important; }

    /* ── Modales: hoja casi completa, con aire y safe-areas ── */
    .modal, .character-modal {
        width: 96vw !important;
        max-width: 96vw !important;
        max-height: calc(92dvh - env(safe-area-inset-top, 0px)) !important;
        border-radius: 18px !important;
    }

    /* ── Objetivos táctiles ≥40px en los controles que se tocan mucho ── */
    .vcb-chip,
    .vcb-action-btn {
        min-height: 40px !important;
        padding-top: 8px !important;
        padding-bottom: 8px !important;
    }
    .vcb-format-btn { width: 38px !important; height: 36px !important; }
    body.theme-classic #vnSection .vn-option-btn { min-height: 48px !important; }
    #vnSection .vn-dialogue-actions button { min-height: 38px !important; }

    /* ── El pie del diálogo respira sobre el gesto de home ── */
    #vnSection .vn-dialogue-footer {
        padding-bottom: max(6px, env(safe-area-inset-bottom, 0px)) !important;
    }
}


/* -- css/auth.css -- */
/* ============================================
   AUTH SCREEN - Pantalla de autenticación
   ============================================ */

.auth-screen {
    position: fixed;
    inset: 0;
    z-index: var(--z-loading);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    background: linear-gradient(135deg, #080618 0%, #0e0c1c 50%, #080618 100%);
    overflow: hidden;
}

/* Fondo animado */
.auth-background {
    position: absolute;
    inset: 0;
    overflow: hidden;
    pointer-events: none;
}

.auth-background::before {
    content: '';
    position: absolute;
    inset: -50%;
    background: 
        radial-gradient(ellipse at 20% 20%, rgba(160,128,220, 0.08) 0%, transparent 50%),
        radial-gradient(ellipse at 80% 80%, rgba(160,128,220, 0.05) 0%, transparent 50%),
        radial-gradient(ellipse at 50% 50%, rgba(139, 115, 71, 0.03) 0%, transparent 70%);
    animation: authBackgroundPulse 8s ease-in-out infinite;
}

@keyframes authBackgroundPulse {
    0%, 100% { transform: scale(1) rotate(0deg); opacity: 1; }
    50% { transform: scale(1.1) rotate(2deg); opacity: 0.8; }
}

/* Partículas flotantes */
.auth-particles {
    position: absolute;
    inset: 0;
}

.auth-particles::before,
.auth-particles::after {
    content: '✦';
    position: absolute;
    color: rgba(160,128,220, 0.3);
    font-size: 1.5rem;
    animation: authParticleFloat 6s ease-in-out infinite;
}

.auth-particles::before {
    top: 20%;
    left: 15%;
    animation-delay: 0s;
}

.auth-particles::after {
    bottom: 25%;
    right: 20%;
    animation-delay: 3s;
}

@keyframes authParticleFloat {
    0%, 100% { transform: translateY(0) rotate(0deg); opacity: 0.3; }
    50% { transform: translateY(-20px) rotate(180deg); opacity: 0.6; }
}

/* Contenedor principal */
.auth-container {
    position: relative;
    width: min(420px, 95vw);
    background: linear-gradient(145deg, rgba(42, 37, 32, 0.95) 0%, rgba(26, 24, 21, 0.98) 100%);
    border: 1px solid rgba(160,128,220, 0.3);
    border-radius: 24px;
    padding: 2.5rem 2rem;
    box-shadow: 
        0 25px 80px rgba(0, 0, 0, 0.6),
        0 0 60px rgba(160,128,220, 0.1),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    backdrop-filter: blur(20px);
}

/* Header */
.auth-header {
    text-align: center;
    margin-bottom: 2rem;
}

.auth-logo {
    font-size: 4rem;
    margin-bottom: 0.5rem;
    animation: authLogoGlow 3s ease-in-out infinite;
    filter: drop-shadow(0 0 20px rgba(160,128,220, 0.5));
}

@keyframes authLogoGlow {
    0%, 100% { transform: scale(1); filter: drop-shadow(0 0 20px rgba(160,128,220, 0.5)); }
    50% { transform: scale(1.05); filter: drop-shadow(0 0 30px rgba(160,128,220, 0.8)); }
}

.auth-title {
    font-family: 'Cinzel', serif;
    font-size: 2.5rem;
    font-weight: 700;
    color: #a080e0;
    margin: 0;
    letter-spacing: 0.15em;
    text-shadow: 0 2px 20px rgba(160,128,220, 0.3);
}

.auth-subtitle {
    font-family: 'Cinzel', serif;
    font-size: 0.95rem;
    color: rgba(232, 213, 163, 0.6);
    margin: 0.5rem 0 0;
    font-style: italic;
}

/* Vistas */
.auth-view {
    display: none;
    animation: authViewIn 0.4s ease;
}

.auth-view.active {
    display: block;
}

@keyframes authViewIn {
    from { opacity: 0; transform: translateY(20px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Opciones principales */
.auth-options {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

/* Botones */
.auth-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.75rem;
    padding: 1rem 1.5rem;
    border: none;
    border-radius: 12px;
    font-family: 'Cinzel', serif;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55);
    position: relative;
    overflow: hidden;
}

.auth-btn::before {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
    transform: translateX(-100%);
    transition: transform 0.5s ease;
}

.auth-btn:hover::before {
    transform: translateX(100%);
}

.auth-btn-icon {
    font-size: 1.2rem;
}

.auth-btn-text {
    font-weight: 600;
}

.auth-btn-primary {
    background: linear-gradient(145deg, #a080e0 0%, #a88b52 100%);
    color: #1a1815;
    box-shadow: 0 4px 15px rgba(160,128,220, 0.3);
}

.auth-btn-primary:hover {
    transform: translateY(-2px) scale(1.02);
    box-shadow: 0 8px 25px rgba(160,128,220, 0.5);
}

.auth-btn-secondary {
    background: transparent;
    color: #a080e0;
    border: 2px solid #a080e0;
}

.auth-btn-secondary:hover {
    background: rgba(160,128,220, 0.1);
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(160,128,220, 0.2);
}

.auth-btn-guest {
    background: rgba(255, 255, 255, 0.05);
    color: rgba(232, 213, 163, 0.8);
    border: 1px solid rgba(255, 255, 255, 0.1);
}

.auth-btn-guest:hover {
    background: rgba(255, 255, 255, 0.1);
    color: #e8d5a3;
}

.auth-btn-full {
    width: 100%;
}

/* Divider */
.auth-divider {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin: 0.5rem 0;
    color: rgba(232, 213, 163, 0.4);
    font-size: 0.9rem;
}

.auth-divider::before,
.auth-divider::after {
    content: '';
    flex: 1;
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(160,128,220, 0.3), transparent);
}

/* Hint */
.auth-hint {
    text-align: center;
    font-size: 0.85rem;
    color: rgba(232, 213, 163, 0.5);
    margin-top: 1.5rem;
    font-style: italic;
}

/* Botón volver */
.auth-back {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: none;
    border: none;
    color: rgba(232, 213, 163, 0.6);
    font-family: 'Cinzel', serif;
    font-size: 0.9rem;
    cursor: pointer;
    padding: 0;
    margin-bottom: 1.5rem;
    transition: color 0.2s ease;
}

.auth-back:hover {
    color: #a080e0;
}

/* Título de vista */
.auth-view-title {
    font-family: 'Cinzel', serif;
    font-size: 1.5rem;
    color: #a080e0;
    margin: 0 0 1.5rem;
    text-align: center;
}

/* Formulario */
.auth-form {
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
}

.auth-input-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.auth-input-group label {
    font-size: 0.85rem;
    color: rgba(232, 213, 163, 0.7);
    font-weight: 500;
}

.auth-input-group input {
    padding: 0.875rem 1rem;
    border: 1px solid rgba(160,128,220, 0.2);
    border-radius: 10px;
    background: rgba(0, 0, 0, 0.2);
    color: #e8d5a3;
    font-family: inherit;
    font-size: 1rem;
    transition: all 0.2s ease;
}

.auth-input-group input:focus {
    outline: none;
    border-color: #a080e0;
    box-shadow: 0 0 0 3px rgba(160,128,220, 0.1);
}

.auth-input-group input::placeholder {
    color: rgba(232, 213, 163, 0.3);
}

/* Estado */
.auth-status {
    text-align: center;
    font-size: 0.9rem;
    margin-top: 1rem;
    min-height: 1.5em;
}

.auth-status.error {
    color: #e74c3c;
}

.auth-status.success {
    color: #27ae60;
}

.auth-status.info {
    color: #3498db;
}

/* Responsive */
@media (max-width: 480px) {
    .auth-container {
        padding: 2rem 1.5rem;
    }
    
    .auth-title {
        font-size: 2rem;
    }
    
    .auth-logo {
        font-size: 3rem;
    }
    
    .auth-btn {
        padding: 0.875rem 1.25rem;
    }
}

/* Ocultar pantalla de auth */
.auth-screen.hidden {
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.5s ease;
}


/* ============================================================
   BUZÓN FLOTANTE — Botón sutil fijo en esquina superior izquierda
   ============================================================ */

.menu-inbox-float {
    position: absolute;
    /* Junto al botón de tema (top-right), a su izquierda */
    top: 1.2rem;
    right: 4.4rem;   /* botón tema ocupa ~42px + 1.4rem ≈ 4.4rem desde la derecha */
    z-index: 50;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    background: rgba(0, 0, 0, 0.35);
    border: 1.5px solid rgba(255, 255, 255, 0.18);
    border-radius: 50%;
    color: rgba(160,128,220, 0.55);
    cursor: pointer;
    transition: background 0.3s, border-color 0.3s, color 0.3s, transform 0.2s;
    backdrop-filter: blur(8px);
}

.menu-inbox-float:hover {
    background: rgba(255, 255, 255, 0.12);
    border-color: rgba(255, 255, 255, 0.35);
    color: rgba(160,128,220, 0.95);
    transform: scale(1.1);
}

.menu-inbox-float.has-unread {
    border-color: rgba(200, 110, 78, 0.6);
    color: rgba(200, 110, 78, 0.9);
    background: rgba(40, 24, 18, 0.75);
    animation: inboxFloatGlow 2.5s ease-in-out infinite;
}

@keyframes inboxFloatGlow {
    0%, 100% { box-shadow: 0 0 0 0 rgba(200, 110, 78, 0); }
    50%       { box-shadow: 0 0 10px 2px rgba(200, 110, 78, 0.25); }
}

.menu-inbox-badge {
    position: absolute;
    top: -5px;
    right: -5px;
    min-width: 17px;
    height: 17px;
    padding: 0 4px;
    background: #c86e4e;
    color: #fff;
    font-family: 'Inter', system-ui, sans-serif;
    font-size: 10px;
    font-weight: 700;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    border: 1.5px solid #1a1815;
    pointer-events: none;
}

@keyframes inboxBadgePulse {
    0%   { transform: scale(1); }
    40%  { transform: scale(1.5); }
    100% { transform: scale(1); }
}
.inbox-badge-pulse {
    animation: inboxBadgePulse 0.5s cubic-bezier(0.36, 0.07, 0.19, 0.97);
}

/* ── Modal del buzón ── */
.modal-overlay {
    position: fixed;
    inset: 0;
    z-index: var(--z-modals);
    background: rgba(10, 9, 8, 0.75);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 1rem;
    backdrop-filter: blur(4px);
}

.inbox-modal {
    width: min(480px, 95vw);
    max-height: 70vh;
    background: linear-gradient(145deg, #2a2520 0%, #1e1c19 100%);
    border: 1px solid rgba(160,128,220, 0.25);
    border-radius: 16px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    box-shadow: 0 20px 60px rgba(0,0,0,0.6), 0 0 40px rgba(160,128,220,0.08);
}

.inbox-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 1.25rem 1.5rem;
    border-bottom: 1px solid rgba(160,128,220, 0.15);
    background: rgba(0,0,0,0.2);
}

.inbox-title {
    font-family: 'Cinzel', serif;
    font-size: 1.1rem;
    font-weight: 600;
    color: #a080e0;
    letter-spacing: 2px;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin: 0;
}

.inbox-close {
    background: none;
    border: none;
    color: rgba(232, 213, 163, 0.5);
    font-size: 1.1rem;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
    border-radius: 6px;
    transition: color 0.2s, background 0.2s;
}
.inbox-close:hover { color: #a080e0; background: rgba(160,128,220,0.1); }

.inbox-list {
    overflow-y: auto;
    flex: 1;
    padding: 0.5rem 0;
}

.inbox-empty {
    text-align: center;
    color: rgba(232, 213, 163, 0.4);
    font-style: italic;
    padding: 2.5rem 1rem;
    font-size: 0.95rem;
}

.inbox-item {
    display: flex;
    gap: 1rem;
    padding: 0.9rem 1.5rem;
    cursor: pointer;
    transition: background 0.15s;
    border-bottom: 1px solid rgba(160,128,220, 0.06);
}
.inbox-item:hover { background: rgba(160,128,220,0.06); }

.inbox-item--unread { background: rgba(160,128,220, 0.05); }
.inbox-item--unread .inbox-item-title { color: #e8d5a3; }

.inbox-item-icon { font-size: 1.3rem; flex-shrink: 0; margin-top: 2px; }

.inbox-item-body { flex: 1; min-width: 0; }

.inbox-item-title {
    font-family: 'Cinzel', serif;
    font-size: 0.85rem;
    color: rgba(232,213,163,0.75);
    font-weight: 600;
    margin-bottom: 0.2rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.inbox-item-text {
    font-size: 0.88rem;
    color: rgba(232,213,163,0.5);
    line-height: 1.4;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.inbox-item-date {
    font-size: 0.75rem;
    color: rgba(232,213,163,0.3);
    margin-top: 0.3rem;
    font-style: italic;
}

/* ============================================================
   PRESENCIA EN EL VN — Panel de participantes online
   ============================================================ */

.vn-presence-panel {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    z-index: var(--z-hud);
    pointer-events: none;
}

.vn-presence-list {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    align-items: flex-end;
}

.vn-presence-user {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    background: rgba(26, 24, 21, 0.82);
    border: 1px solid rgba(160,128,220, 0.2);
    border-radius: 20px;
    padding: 0.3rem 0.7rem 0.3rem 0.3rem;
    backdrop-filter: blur(6px);
}

.vn-presence-avatar {
    position: relative;
    width: 28px;
    height: 28px;
    flex-shrink: 0;
}

.vn-presence-avatar-img {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    object-fit: cover;
}

.vn-presence-avatar-initials {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: rgba(160,128,220,0.2);
    border: 1px solid rgba(160,128,220,0.3);
    display: flex;
    align-items: center;
    justify-content: center;
    font-family: 'Cinzel', serif;
    font-size: 0.7rem;
    color: #a080e0;
    font-weight: 600;
}

.vn-presence-dot {
    position: absolute;
    bottom: 0;
    right: 0;
    width: 8px;
    height: 8px;
    background: #4caf7d;
    border-radius: 50%;
    border: 1.5px solid #1a1815;
    box-shadow: 0 0 6px rgba(76, 175, 125, 0.7);
}

.vn-presence-name {
    font-family: 'Cinzel', serif;
    font-size: 0.72rem;
    color: rgba(232, 213, 163, 0.8);
    letter-spacing: 0.5px;
    white-space: nowrap;
}

/* ============================================================
   TYPING INDICATOR — "Nombre está escribiendo..."
   ============================================================ */

.collab-typing-indicator {
    position: absolute;
    bottom: 5.5rem;
    left: 1rem;
    right: 1rem;
    z-index: var(--z-hud);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    font-family: 'Crimson Text', Georgia, serif;
    font-size: 0.9rem;
    color: rgba(232, 213, 163, 0.6);
    font-style: italic;
    opacity: 0;
    transform: translateY(6px);
    transition: opacity 0.3s ease, transform 0.3s ease;
    pointer-events: none;
}

.collab-typing-indicator.visible {
    opacity: 1;
    transform: translateY(0);
}

.typing-name {
    color: rgba(160,128,220, 0.85);
    font-style: normal;
}

.typing-dots {
    display: inline-flex;
    gap: 3px;
    align-items: center;
    margin-left: 2px;
}

.typing-dots span {
    width: 4px;
    height: 4px;
    background: rgba(160,128,220, 0.6);
    border-radius: 50%;
    animation: typingBounce 1.2s ease-in-out infinite;
}
.typing-dots span:nth-child(2) { animation-delay: 0.2s; }
.typing-dots span:nth-child(3) { animation-delay: 0.4s; }

@keyframes typingBounce {
    0%, 60%, 100% { transform: translateY(0);    opacity: 0.4; }
    30%            { transform: translateY(-4px); opacity: 1;   }
}

/* ── Seguridad en panel de opciones ── */
.opt-security-status {
    font-size: 0.82rem;
    margin-top: 0.4rem;
    min-height: 1.2em;
    font-style: italic;
    color: var(--text-muted);
}
.opt-security-status.error   { color: #e74c3c; }
.opt-security-status.success { color: #6b8e7d; }
.opt-security-status.info    { color: rgba(160,128,220, 0.7); }

/* ── Enlace "¿Olvidaste tu contraseña?" ── */
.auth-forgot-link {
    background: none;
    border: none;
    color: rgba(160,128,220, 0.55);
    font-family: 'Cinzel', serif;
    font-size: 0.8rem;
    cursor: pointer;
    text-align: center;
    width: 100%;
    margin-top: 0.25rem;
    padding: 0.25rem 0;
    transition: color 0.2s ease;
    text-decoration: underline;
    text-underline-offset: 3px;
}
.auth-forgot-link:hover { color: #a080e0; }

@media (max-width: 480px) {
    .vn-presence-panel { top: 0.5rem; right: 0.5rem; }
    .vn-presence-name  { display: none; }
    .inbox-modal       { max-height: 85vh; }
    .menu-inbox-float  { top: 0.75rem; right: 3.8rem; width: 36px; height: 36px; }
}


