        }

        

        /* EMOTES MANGA */
        .manga-emote {
            position: absolute;
            top: 8%;
            right: 4%;
            font-size: clamp(2rem, 5vw, 3.5rem);
            z-index: var(--z-i-300);
            pointer-events: none;
            filter: drop-shadow(0 2px 8px rgba(0,0,0,0.6));
            transform-origin: center center;
            animation: emote-appear 0.3s ease-out forwards;
        }

        

        /* Animaciones específicas por emote */
        .emote-angry { animation: emote-angry-anim 2s ease-in-out infinite; }
        

        .emote-happy { animation: emote-happy-anim 2s ease-in-out infinite; }
        

