        .emote-idea { animation: emote-idea-anim 2s ease-in-out infinite; }
        

        .emote-sleep { animation: emote-sleep-anim 3s ease-in-out infinite; }
        

        /* Selector de emotes */
        .emote-picker {
            position: fixed;
            bottom: 180px;
            right: 20px;
            background: var(--glass-bg);
            border: 2px solid var(--accent-gold);
            border-radius: 16px;
            padding: 1rem;
            display: none;
            flex-wrap: wrap;
            gap: 0.5rem;
            max-width: 300px;
            z-index: var(--z-i-300);
            backdrop-filter: blur(10px);
        }

        .emote-picker.active { display: flex; }

        .emote-btn {
            width: 50px;
            height: 50px;
            border: 2px solid var(--border-color);
            background: rgba(255,255,255,0.1);
            border-radius: 10px;
            cursor: pointer;
            font-size: 1.5rem;
            transition: all 0.3s;
        }

        .emote-btn:hover {
            transform: scale(1.1);
            border-color: var(--accent-gold);
            background: rgba(160,128,220, 0.2);
        }

        [data-tooltip] {
            position: relative;
        }

        .smart-tooltip {
            position: fixed;
            background: var(--glass-bg);
            color: var(--accent-gold);
            padding: 0.45rem 0.8rem;
            border-radius: 8px;
            font-size: 0.8rem;
            font-family: 'Inter', sans-serif;
            white-space: nowrap;
            pointer-events: none;
            border: 1px solid var(--accent-gold);
            z-index: var(--z-i-10000);
            opacity: 0;
            transform: translateY(0);
            transition: opacity 0.18s ease, transform 0.18s ease;
        }

        .smart-tooltip.visible {
            opacity: 1;
        }

        .smart-tooltip[data-placement="top"] {
            transform: translateY(-4px);
        }

        .smart-tooltip[data-placement="bottom"] {
            transform: translateY(4px);
        }


        /* Mejora 5: Indicador cloud — esquina inferior izquierda, temporal */
        .cloud-sync-indicator {
            position: fixed;
            bottom: 20px;
            left: 20px;
            display: flex;
            align-items: center;
            gap: 0.4rem;
            padding: 0.35rem 0.65rem;
            border-radius: 999px;
            border: 1px solid var(--border-color);
            background: rgba(14, 16, 24, 0.82);
            color: #f2f2f2;
            font-size: 0.72rem;
            z-index: var(--z-modals, 500);
            backdrop-filter: blur(4px);
            opacity: 0;
            transform: translateY(6px);
            transition: opacity 0.5s ease, transform 0.5s ease;
            pointer-events: none;
        }
        /* Solo mostrar si tiene la clase 'visible' o si no es online */
        .cloud-sync-indicator.visible,
        .cloud-sync-indicator.degraded,
        .cloud-sync-indicator.offline {
            opacity: 1;
            transform: translateY(0);
            pointer-events: auto;
        }
        /* Online se muestra brevemente al conectar y se oculta */
        .cloud-sync-indicator.online {
            color: #8ff7b4;
            border-color: rgba(143, 247, 180, 0.6);
            opacity: 0;
            pointer-events: none;
        }
        .cloud-sync-indicator.degraded { color: #ffd08a; border-color: rgba(255, 208, 138, 0.7); }
        .cloud-sync-indicator.offline { color: #ff9b9b; border-color: rgba(255, 155, 155, 0.7); }
        .cloud-sync-icon { font-size: 0.85rem; }


        .sync-btn.is-synced { border-color: rgba(180,180,180,0.5); color: #d8d8d8; }
        .sync-btn.is-syncing { border-color: #79b9ff; color: #b8deff; }
        .sync-btn.is-syncing .vn-control-icon { animation: sync-spin 1s linear infinite; }
        .sync-btn.is-upload-pending { border-color: #76dd95; color: #bbf7cc; }
        .sync-btn.is-download-pending { border-color: #f1b266; color: #ffd8a8; }
        .sync-btn.is-error { border-color: #ff8f8f; color: #ffb9b9; }
        @keyframes sync-spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

        /* ── NOTIFICACIÓN DE MENSAJES NUEVOS — estilo VN ── */
        .sync-toast {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -40%) scale(0.92);
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.9rem;
            background: linear-gradient(160deg, rgba(28, 20, 12, 0.97) 0%, rgba(18, 13, 8, 0.99) 100%);
            border: 1px solid rgba(160,128,220, 0.35);
            border-radius: 8px;
            padding: 2rem 2.8rem 1.6rem;
            z-index: var(--z-overlays, 700);
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
            box-shadow:
                0 0 0 1px rgba(160,128,220, 0.08),
                0 30px 80px rgba(0, 0, 0, 0.75),
                0 0 40px rgba(160,128,220, 0.06);
            min-width: 320px;
            text-align: center;
        }
        /* Línea dorada superior */
        .sync-toast::before {
            content: '';
            position: absolute;
            top: 0; left: 15%; right: 15%;
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(160,128,220,0.6), transparent);
        }
        /* Icono decorativo */
        .sync-toast::after {
            content: '✦';
            position: absolute;
            top: -0.65rem;
            left: 50%;
            transform: translateX(-50%);
            font-size: 0.8rem;
            color: rgba(160,128,220,0.8);
            background: rgba(18,13,8,1);
            padding: 0 0.5rem;
            line-height: 1;
        }
        .sync-toast.visible {
            opacity: 1;
            pointer-events: auto;
            transform: translate(-50%, -50%) scale(1);
        }
        .sync-toast-text {
            font-family: 'Cinzel', serif;
            font-size: 0.82rem;
            letter-spacing: 0.15em;
            text-transform: uppercase;
            color: rgba(232, 216, 180, 0.9);
        }
        .sync-toast-buttons {
            display: flex;
            gap: 0.75rem;
        }
        .sync-toast-action, .sync-toast-dismiss {
            border: none;
            border-radius: 3px;
            padding: 0.45rem 1.2rem;
            cursor: pointer;
            font-family: 'Cinzel', serif;
            font-size: 0.65rem;
            letter-spacing: 0.12em;
            text-transform: uppercase;
            transition: all 0.15s;
        }
        .sync-toast-action {
            background: rgba(160,128,220, 0.15);
            color: rgba(160,128,220, 0.95);
            border: 1px solid rgba(160,128,220, 0.4);
        }
        .sync-toast-action:hover {
            background: rgba(160,128,220, 0.25);
            border-color: rgba(160,128,220, 0.7);
        }
        .sync-toast-dismiss {
            background: transparent;
            color: rgba(180, 160, 130, 0.45);
            border: 1px solid rgba(180, 160, 130, 0.15);
        }
        .sync-toast-dismiss:hover {
            color: rgba(180, 160, 130, 0.7);
            border-color: rgba(180, 160, 130, 0.3);
        }
        /* Overlay de fondo semitransparente cuando aparece el toast */
        .sync-toast-backdrop {
            position: fixed;
            inset: 0;
            background: rgba(0, 0, 0, 0.45);
            z-index: var(--z-overlays, 700);
            opacity: 0;
            pointer-events: none;
            transition: opacity 0.35s ease;
        }
        .sync-toast-backdrop.visible {
            opacity: 1;
            pointer-events: auto;
        }

        .autosave-indicator {
            position: fixed;
            top: 20px;
            right: 20px;
            display: flex;
            align-items: center;
            gap: 0.55rem;
            padding: 0.7rem 1.1rem;
            background: radial-gradient(circle at 30% 30%, rgba(255, 245, 225, 0.25), rgba(59, 25, 15, 0.88));
            border: 2px solid #9f6b3c;
            border-radius: 999px;
            color: #f6deba;
            font-family: 'Cinzel', serif;
            font-size: 0.82rem;
            letter-spacing: 0.25px;
            z-index: var(--z-modals, 500);
            opacity: 0;
            transform: translateY(-22px) scale(0.92);
            transform-origin: top right;
            transition: opacity 0.25s ease, transform 0.25s ease;
            pointer-events: none;
            backdrop-filter: blur(6px);
            box-shadow: 0 8px 26px rgba(0,0,0,0.35), inset 0 -4px 12px rgba(0,0,0,0.28);
        }
        .autosave-indicator::before {
            content: '';
            position: absolute;
            inset: -3px;
            border-radius: inherit;
            border: 1px solid rgba(255, 219, 170, 0.28);
            pointer-events: none;
        }
        .autosave-indicator.visible { opacity: 1; transform: translateY(0) scale(1); }
        .autosave-indicator.saved { border-color: #dbb868; color: #ffecc8; }
        .autosave-indicator.error { border-color: #a6423f; color: #ffd8d6; }
        .autosave-indicator.info { border-color: #4a8d55; color: #dbffe3; }
        .autosave-icon {
            font-size: 1.06rem;
            filter: drop-shadow(0 0 5px currentColor);
        }
        .autosave-indicator.visible .autosave-icon { animation: wax-stamp-pop 0.38s ease-out; }
        



/* -- css/components/02-user-selection.css -- */
/* ═══════════════════════════════════════════════════════════════
