            --ps-card-border: rgba(200, 155, 230, 0.50);
            --ps-gold:        #ddb8f5;
            --ps-gold-dim:    rgba(200, 155, 230, 0.55);
            --ps-gold-faint:  rgba(200, 155, 230, 0.14);
            --ps-text:        #f8eeff;
            --ps-text-soft:   rgba(240, 220, 255, 0.90);
            --ps-text-muted:  rgba(215, 185, 245, 0.65);
            --ps-shadow:      rgba(50, 15, 80, 0.55);
            --ps-vignette:    rgba(40, 15, 80, 0.18);
            --ps-scan:        rgba(80, 50, 140, 0.02);
        }
        [data-theme="dark"] .user-select-screen {
            --ps-bg-from:     #08071c;
            --ps-bg-to:       #100d28;
            --ps-card-bg:     rgba(8, 4, 22, 0.62);
            --ps-card-border: rgba(180, 120, 255, 0.35);
            --ps-gold:        #c090ff;
            --ps-gold-dim:    rgba(180, 128, 255, 0.50);
            --ps-gold-faint:  rgba(180, 128, 255, 0.10);
            --ps-text:        #ebe6f8;
            --ps-text-soft:   #c0b8e0;
            --ps-text-muted:  rgba(180, 155, 230, 0.55);
            --ps-shadow:      rgba(0, 0, 0, 0.55);
            --ps-vignette:    rgba(0, 0, 20, 0.70);
            --ps-scan:        rgba(100, 80, 160, 0.05);
        }

        .user-select-screen {
            position: fixed; top: 0; left: 0; width: 100%; height: 100%;
            display: flex; flex-direction: column;
            justify-content: center; align-items: center;
            z-index: var(--z-i-2000); overflow: hidden;
            transition: background 0.4s ease;
            /* Base — sobreescrito por cada tema */
            background: linear-gradient(170deg, var(--ps-bg-from) 0%, var(--ps-bg-to) 100%);
        }

        /* ── LIGHT MODE — sensación mágica, rosa/lila ── */
        [data-theme="light"] .user-select-screen {
            background:
                /* Bruma superior — lila pálido */
                radial-gradient(ellipse 90% 55% at 50%  -5%,  rgba(190, 150, 240, 0.42) 0%, rgba(170, 120, 225, 0.18) 50%, transparent 75%),
                /* Bruma izquierda — morado suave */
                radial-gradient(ellipse 65% 90% at -5%  50%,  rgba(175, 120, 230, 0.40) 0%, rgba(150, 100, 215, 0.16) 50%, transparent 75%),
                /* Bruma derecha — lila-violeta */
                radial-gradient(ellipse 62% 85% at 105% 50%,  rgba(180, 115, 235, 0.38) 0%, rgba(155, 95,  220, 0.15) 50%, transparent 75%),
                /* Bruma inferior — lila muy tenue */
                radial-gradient(ellipse 85% 50% at 50%  105%, rgba(185, 135, 230, 0.34) 0%, rgba(160, 110, 218, 0.12) 50%, transparent 75%),
                /* Fulgor central muy sutil */
                radial-gradient(ellipse 70% 50% at 50%  50%,  rgba(200, 160, 240, 0.10) 0%, transparent 65%),
                linear-gradient(170deg, rgba(50, 8, 90, 0.15) 0%, rgba(25, 4, 60, 0.10) 100%),
                url('./assets/backgrounds/profile_selector_bg.png');
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
        }

        /* ── DARK MODE — noche siniestra, fría y misteriosa ── */
        [data-theme="dark"] .user-select-screen {
            background:
                /* Orbe superior — cian helado, luna fría */
                radial-gradient(ellipse 88% 52% at 50%  -5%,  rgba(60,  200, 240, 0.55) 0%, rgba(30,  140, 220, 0.22) 50%, transparent 75%),
                /* Orbe izquierdo — verde-azul fantasmal */
                radial-gradient(ellipse 62% 88% at -5%  50%,  rgba(30,  170, 200, 0.50) 0%, rgba(15,  110, 180, 0.18) 50%, transparent 75%),
                /* Orbe derecho — índigo frío */
                radial-gradient(ellipse 60% 82% at 105% 50%,  rgba(50,   90, 220, 0.46) 0%, rgba(25,   55, 180, 0.16) 50%, transparent 75%),
                /* Oscuridad densa desde el suelo */
                radial-gradient(ellipse 100% 45% at 50% 110%, rgba(2,    6,  25,  0.80) 0%, rgba(3,    8,  30,  0.40) 55%, transparent 78%),
                /* Velo de medianoche */
                linear-gradient(180deg, rgba(2, 4, 24, 0.22) 0%, rgba(4, 12, 40, 0.32) 60%, rgba(1, 3, 16, 0.52) 100%),
                url('./assets/backgrounds/profile_selector_bg.png');
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
        }

        .user-select-screen.hidden { display: none; }

        /* Textura de papel fina — más visible en light */
        .user-select-screen::before {
            content: '';
            position: absolute; inset: 0;
            background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.72' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.45'/%3E%3C/svg%3E");
            opacity: 0.06;
            mix-blend-mode: overlay;
            pointer-events: none; z-index: var(--z-i-0);
        }
        [data-theme="light"] .user-select-screen::before { opacity: 0.10; }

        /* Viñeta más pronunciada en las esquinas */
        .user-select-screen::after {
            content: '';
            position: absolute; inset: 0;
            background:
                radial-gradient(ellipse 100% 100% at 50% 50%, transparent 42%, var(--ps-vignette) 100%);
            pointer-events: none; z-index: var(--z-i-0);
        }

        .profile-particles { position: absolute; inset: 0; pointer-events: none; z-index: var(--z-i-0); }
        .profile-particle {
            position: absolute;
            width: 6px; height: 6px;
            border-radius: 50%;
            /* Dark mode — chispas de hielo azul-cian, aspecto siniestro/noche */
            background: rgba(160, 235, 255, 0.92);
            box-shadow:
                0 0 5px 2px  rgba(100, 210, 255, 0.75),
                0 0 12px 4px rgba(60,  180, 255, 0.40);
            animation: profile-particle-float linear infinite;
        }
        [data-theme="light"] .profile-particle {
            /* Light mode — chispas blancas con halo rosa, aspecto mágico */
            background: rgba(255, 255, 255, 0.98);
            box-shadow:
                0 0 5px 2px  rgba(255, 180, 240, 0.85),
                0 0 12px 4px rgba(220, 100, 220, 0.45);
        }
        .user-select-screen > *:not(.profile-particles) { position: relative; z-index: var(--z-i-1); }

        /* ── CABECERA ── */
        .game-title {
            font-family: 'Cinzel', serif;
            font-size: clamp(2.4rem, 5vw, 3.8rem);
            font-weight: 700;
            letter-spacing: 0.28em;
            color: transparent;
            background: linear-gradient(155deg,
                rgba(255, 255, 255, 0.95) 0%,
                var(--ps-gold) 35%,
                rgba(255, 255, 255, 0.90) 50%,
                var(--ps-gold) 65%,
                rgba(255, 255, 255, 0.95) 100%);
            -webkit-background-clip: text;
            background-clip: text;
            margin: 0 0 0.4rem;
            line-height: 1;
            text-shadow: none;
            filter:
                drop-shadow(0 0 12px rgba(255, 255, 255, 0.55))
                drop-shadow(0 0 30px var(--ps-gold))
                drop-shadow(0 2px 4px rgba(0, 0, 0, 0.60));
        }
        [data-theme="dark"] .game-title {
            filter:
                drop-shadow(0 0 10px rgba(200, 160, 255, 0.70))
                drop-shadow(0 0 28px rgba(140, 90, 220, 0.50))
                drop-shadow(0 2px 4px rgba(0, 0, 0, 0.80));
        }
        .save-screen-rule {
            width: 240px; height: 1px;
            background: linear-gradient(90deg, transparent, var(--ps-gold-dim) 30%, var(--ps-gold) 50%, var(--ps-gold-dim) 70%, transparent);
            margin: 0 auto 0.55rem;
            opacity: 0.85;
            filter: drop-shadow(0 0 4px var(--ps-gold));
        }
        .game-subtitle {
            font-family: 'Cinzel', serif;
            font-size: 0.72rem; letter-spacing: 0.22em;
            color: rgba(255, 255, 255, 0.88);
            text-transform: none; font-style: italic;
            margin: 0 0 2.2rem;
            text-shadow:
                0 0 12px rgba(200, 160, 255, 0.60),
                0 1px 3px rgba(0, 0, 0, 0.70);
        }
        [data-theme="light"] .game-subtitle {
            color: rgba(255, 240, 255, 0.92);
            text-shadow:
                0 0 14px rgba(180, 100, 220, 0.65),
                0 1px 3px rgba(40, 0, 80, 0.55);
        }

        /* Botón tema en la pantalla de perfiles */
        .profile-theme-btn {
            position: fixed;
            bottom: 2rem; right: 2rem;
            width: 48px; height: 48px;
            border-radius: 50%;
            background: var(--ps-card-bg);
            border: 1px solid var(--ps-gold-dim);
            font-size: 1.4rem;
            line-height: 1;
            display: flex; align-items: center; justify-content: center;
            cursor: pointer;
            transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
            z-index: var(--z-i-2010);
            backdrop-filter: blur(10px);
            box-shadow: 0 4px 16px var(--ps-shadow);
            padding: 0;
        }
        .profile-theme-btn:hover {
            transform: scale(1.12) rotate(15deg);
            box-shadow: 0 6px 24px var(--ps-shadow), 0 0 16px var(--ps-gold-faint);
            border-color: var(--ps-gold);
        }


        /* ── FILA DE TARJETAS — scroll horizontal snap ── */
        .user-cards {
            display: flex;
            flex-direction: row;
            align-items: stretch;
            gap: 1rem;
            width: max-content;
            max-width: min(960px, 90vw);
            overflow-x: auto;
            overflow-y: hidden;
            padding: 0.5rem 0.6rem 0.9rem;
            scroll-snap-type: x mandatory;
            -webkit-overflow-scrolling: touch;
            scrollbar-width: thin;
            scrollbar-color: var(--ps-gold-dim) transparent;
        }
        .user-cards::-webkit-scrollbar { height: 4px; }
        .user-cards::-webkit-scrollbar-track { background: transparent; }
        .user-cards::-webkit-scrollbar-thumb {
            background: var(--ps-gold-dim);
            border-radius: 2px;
        }

        /* ── TARJETA ── */
        .user-card {
            flex: 0 0 200px;
            width: 200px;
            display: flex;
            flex-direction: column;
            align-items: center;
            /* Gradiente de fondo: suave de arriba (levemente púrpura) hacia abajo (blanco/oscuro) */
            background-color: var(--ps-card-bg);
            background-image:
                /* Puntos ornamentales — esquina sup-derecha omitida porque está cortada */
                radial-gradient(circle at 11px 11px, var(--ps-gold-dim) 2.5px, transparent 2.5px),
                radial-gradient(circle at 11px calc(100% - 11px), var(--ps-gold-dim) 2.5px, transparent 2.5px),
                radial-gradient(circle at calc(100% - 11px) calc(100% - 11px), var(--ps-gold-dim) 2.5px, transparent 2.5px),
                /* Gradiente sutil de cuerpo */
                linear-gradient(175deg, rgba(155, 120, 235, 0.07) 0%, transparent 40%);
            border: 1px solid var(--ps-card-border);
            /* Sin border-radius — la forma la da clip-path */
            padding: 0;
            overflow: hidden;
            cursor: pointer;
            scroll-snap-align: start;
            /* Corte diagonal en esquina superior-derecha (estilo carta de tarot) */
            clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 0 100%);
            transition: transform 0.22s ease, filter 0.22s ease, border-color 0.22s ease;
            /* drop-shadow sigue la forma del clip-path; box-shadow quedaría recortado */
            filter: drop-shadow(0 4px 18px var(--ps-shadow));
            position: relative;
            color: var(--ps-text);
            backdrop-filter: blur(10px);
            -webkit-backdrop-filter: blur(10px);
        }
        [data-theme="dark"] .user-card {
            filter: drop-shadow(0 4px 20px var(--ps-shadow)) drop-shadow(0 0 10px rgba(100,70,180,0.15));
        }
        /* Borde superior ornamental */
        .user-card::before {
            content: '';
            position: absolute; top: 0; left: 0; right: 0;
            height: 2px;
            background: linear-gradient(90deg,
                transparent 0%,
                var(--ps-gold-faint) 15%,
                var(--ps-gold-dim) 40%,
                var(--ps-gold) 50%,
                var(--ps-gold-dim) 60%,
                var(--ps-gold-faint) 85%,
                transparent 100%);
            opacity: 0.35;
            transition: opacity 0.3s, box-shadow 0.3s;
        }
        .user-card:hover::before {
            opacity: 0.85;
            box-shadow: 0 0 8px 1px var(--ps-gold-faint);
        }
        .user-card.active::before {
            opacity: 1;
            box-shadow: 0 0 12px 2px rgba(150,110,230,0.25);
        }

        /* Shimmer de luz al hacer hover */
        .user-card::after {
            content: '';
            position: absolute;
            top: 0; left: -90%;
            width: 55%; height: 100%;
            background: linear-gradient(
                108deg,
                transparent 0%,
                rgba(230, 210, 255, 0.06) 40%,
                rgba(240, 220, 255, 0.11) 50%,
                rgba(230, 210, 255, 0.06) 60%,
                transparent 100%
            );
            transform: skewX(-14deg);
            transition: left 0.70s ease;
            pointer-events: none;
            z-index: 1;
        }
        .user-card:hover::after { left: 145%; }

        .user-card:hover {
            transform: translateY(-6px) scale(1.018);
            filter: drop-shadow(0 14px 32px var(--ps-shadow)) drop-shadow(0 0 20px rgba(140,100,220,0.30));
            border-color: rgba(160, 120, 240, 0.65);
        }
        [data-theme="dark"] .user-card:hover {
            filter: drop-shadow(0 14px 32px var(--ps-shadow)) drop-shadow(0 0 24px rgba(140,100,220,0.40));
        }
        .user-card.active {
            border-color: rgba(160, 120, 240, 0.70);
            filter: drop-shadow(0 8px 24px var(--ps-shadow)) drop-shadow(0 0 30px rgba(150,110,230,0.35));
        }
        /* Pulso suave solo en la tarjeta activa — guiding the eye */
        .user-card.active .save-slot-number {
            color: rgba(160,128,220,0.75);
        }
        .user-card.active .user-card-footer {
            background:
                linear-gradient(var(--ps-card-bg), var(--ps-card-bg)) padding-box,
                linear-gradient(90deg, transparent 5%, rgba(160,128,220,0.35) 50%, transparent 95%) border-box;
        }
        .user-card.active .user-continue-btn {
            animation: btn-pulse-soft 2.8s ease-in-out infinite;
        }
        @keyframes btn-pulse-soft {
            0%, 100% { box-shadow: none; border-color: rgba(160,128,220,0.35); }
            50%       { box-shadow: 0 0 10px rgba(160,128,220,0.35); border-color: rgba(160,128,220,0.7); }
        }

        /* Cabecera de slot — banda de color visible */
        .save-slot-number {
            width: 100%;
            text-align: center;
            font-family: 'Cinzel', serif;
            font-size: 0.55rem;
            letter-spacing: 0.22em;
            color: var(--ps-gold);
            background: linear-gradient(135deg, rgba(145, 105, 230, 0.16) 0%, rgba(120, 85, 220, 0.22) 100%);
            padding: 0.46rem 0 0.36rem;
            border-bottom: 1px solid rgba(145, 105, 225, 0.22);
            text-transform: uppercase;
        }
        [data-theme="light"] .save-slot-number {
            color: rgba(100, 65, 180, 0.85);
            background: linear-gradient(135deg, rgba(145, 105, 230, 0.12) 0%, rgba(120, 85, 215, 0.18) 100%);
        }
        .save-slot-dot {
            opacity: 0.6;
            margin: 0 0.15em;
        }


        .rpg-stats-modal {
            background: rgba(16, 11, 8, 0.97);
            border: 1.5px solid rgba(160,128,220, 0.45);
            border-radius: 14px;
            width: min(340px, 92vw);
            box-shadow: 0 16px 48px rgba(0,0,0,0.7);
            padding: 0.75rem 0.85rem;
        }
        .rpg-stats-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 0.6rem;
            margin-bottom: 0.6rem;
        }
        .rpg-stats-title {
            font-family: 'Cinzel', serif;
            font-size: 1rem;
            color: var(--accent-gold);
            font-weight: 700;
        }
        .rpg-stats-body {
            display: grid;
            gap: 0.45rem;
        }
        .rpg-stats-progress-row {
            display: grid;
            grid-template-columns: 28px 1fr auto;
            align-items: center;
            gap: 0.4rem;
        }
        .rpg-stats-progress-label {
            color: var(--accent-gold);
            font-size: 0.72rem;
            font-weight: 700;
        }
        .rpg-stats-progress-value {
            font-size: 0.7rem;
            color: var(--text-secondary);
            min-width: 38px;
            text-align: right;
        }
        /* Grid 2x2 compacto — stat en fila con +/- */
        .rpg-stats-grid {
            margin-top: 0.15rem;
            display: grid;
            grid-template-columns: repeat(2, minmax(0, 1fr));
            gap: 0.35rem;
        }
        .rpg-stats-card {
            border: 1px solid var(--border-light);
            border-radius: 8px;
            padding: 0.3rem 0.4rem;
            background: rgba(255,255,255,0.02);
            display: grid;
            grid-template-columns: auto minmax(0, 1fr) auto auto;
            align-items: center;
            gap: 0.3rem;
            text-align: left;
        }
        .rpg-stats-card-key {
            font-size: 0.72rem;
            font-weight: 700;
            color: var(--accent-gold);
            min-width: 26px;
        }
        .rpg-stats-card-desc {
            font-size: 0.65rem;
            color: var(--text-secondary);
        }
        .rpg-stats-card-value {
            font-size: 0.95rem;
            font-weight: 700;
            color: var(--text-primary);
            min-width: 22px;
            text-align: center;
        }
        /* Botones +/- para distribuir puntos */
        .rpg-stat-btn-group {
            display: inline-flex;
            align-items: center;
            gap: 0.18rem;
            grid-column: 4;
            grid-row: 1 / span 2;
            padding: 0.06rem;
            border-radius: 6px;
            border: 1px solid rgba(160,128,220,0.2);
            background: rgba(160,128,220,0.06);
        }
        .rpg-stat-btn {
            width: 18px; height: 18px;
            border-radius: 4px;
            border: 1px solid rgba(160,128,220,0.35);
            background: rgba(160,128,220,0.08);
            color: rgba(160,128,220,0.85);
            font-size: 0.75rem;
            line-height: 1;
            cursor: pointer;
            display: flex; align-items: center; justify-content: center;
            padding: 0;
            transition: all 0.12s;
            flex-shrink: 0;
        }
        .rpg-stat-btn:hover:not(:disabled) {
            background: rgba(160,128,220,0.25);
            border-color: rgba(160,128,220,0.7);
        }
        .rpg-stat-btn:disabled {
            opacity: 0.3;
            cursor: not-allowed;
        }
        .rpg-stats-points {
            margin-top: 0.3rem;
            color: var(--accent-gold);
            font-size: 0.78rem;
            text-align: center;
        }
        .rpg-stats-note {
            color: var(--text-secondary);
            font-size: 0.68rem;
            line-height: 1.4;
            text-align: center;
        }
        #rpgStatsModal[data-flow="creation"] .rpg-stats-modal {
            width: min(440px, 94vw);
            padding: 1rem 1rem 0.85rem;
            border-color: rgba(160,128,220, 0.6);
            background:
                radial-gradient(120% 100% at 0% 0%, rgba(160,128,220,0.12), transparent 55%),
                linear-gradient(180deg, rgba(18, 12, 8, 0.98), rgba(9, 7, 5, 0.98));
            box-shadow: 0 24px 65px rgba(0,0,0,0.72), inset 0 1px 0 rgba(255, 226, 164, 0.14);
        }
        .rpg-forge-intro {
            border: 1px solid rgba(160,128,220,0.22);
            border-radius: 10px;
            padding: 0.6rem 0.7rem;
            background: linear-gradient(180deg, rgba(160,128,220,0.08), rgba(160,128,220,0.02));
            margin-bottom: 0.25rem;
        }
        .rpg-forge-kicker {
            font-size: 0.58rem;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            color: rgba(230,205,155,0.7);
            margin-bottom: 0.18rem;
        }
        .rpg-forge-title {
            margin: 0;
            font-family: 'Cinzel', serif;
            font-size: 0.95rem;
            color: rgba(245,220,160,0.95);
        }
        .rpg-forge-copy {
            margin: 0.28rem 0 0;
            color: rgba(210,190,150,0.75);
            font-size: 0.67rem;
            line-height: 1.35;
        }
        .rpg-stats-card-cost {
            grid-column: 2 / span 2;
            font-size: 0.53rem;
            letter-spacing: 0.03em;
            color: rgba(160,128,220,0.62);
            margin-top: -0.08rem;
        }

        /* Halo de luz debajo del avatar (efecto "resplandor") */
        .user-avatar-wrap {
            position: relative;
        }
        .user-avatar-wrap::after {
            content: '';
            position: absolute;
            bottom: -6px; left: 50%;
            transform: translateX(-50%);
            width: 60%; height: 8px;
            background: radial-gradient(ellipse at 50% 0%, var(--ps-gold-dim) 0%, transparent 80%);
            opacity: 0;
            transition: opacity 0.3s;
            pointer-events: none;
        }
        .user-card:hover .user-avatar-wrap::after,
        .user-card.active .user-avatar-wrap::after { opacity: 0.7; }

        /* Nombre */
        .user-name {
            font-family: 'Cinzel', serif;
            font-size: 0.92rem;
            font-weight: 700;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            color: var(--ps-text);
            text-align: center;
            padding: 0 1rem;
            margin-bottom: 0.85rem;
        }

        /* Divisor ornamental */
        .user-card-divider {
            position: relative;
            width: 65%;
            height: 1px;
            background: linear-gradient(90deg, transparent, var(--ps-gold-dim) 35%, var(--ps-gold) 50%, var(--ps-gold-dim) 65%, transparent);
            margin: 0 auto 0.75rem;
            opacity: 0.9;
        }
        .user-card-divider::before {
            content: '✦';
            position: absolute;
            left: 50%; top: 50%;
            transform: translate(-50%, -50%);
            font-size: 0.55rem;
            color: var(--ps-gold);
            line-height: 1;
            background: var(--ps-card-bg);
            padding: 0 0.3rem;
            opacity: 1;
        }

        /* Stats — pills flexibles */
        .user-card-stats {
            display: flex;
            flex-wrap: wrap;
            gap: 0.35rem;
            justify-content: center;
            width: 100%;
            padding: 0 0.7rem 0.75rem;
        }
        .user-stat {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.08rem;
            background: var(--ps-gold-faint);
            border: 1px solid var(--ps-card-border);
            border-radius: 9px;
            padding: 0.28rem 0.55rem;
        }
        .user-stat-sep { display: none; }
        .user-stat-val {
            font-family: 'Cinzel', serif;
            font-size: 0.9rem;
            color: var(--ps-gold);
            line-height: 1;
        }
        .user-stat-lbl {
            font-size: 0.5rem;
            color: var(--ps-text-muted);
            text-transform: uppercase;
            letter-spacing: 0.07em;
            text-align: center;
        }

        /* Footer de la tarjeta */
        .user-card-footer {
            position: relative;
            width: 100%;
            margin-top: auto;
            padding: 0.55rem 1rem 0.9rem;
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 0.4rem;
            border-top: 1px solid transparent;
            background:
                linear-gradient(var(--ps-card-bg), var(--ps-card-bg)) padding-box,
                linear-gradient(90deg, transparent 10%, var(--ps-gold-faint) 50%, transparent 90%) border-box;
        }
        .user-last-session {
            font-size: 0.62rem;
            color: var(--ps-text-muted);
            text-transform: uppercase;
            letter-spacing: 0.1em;
            font-family: 'Cinzel', serif;
        }
        .user-last-topic {
            font-size: 0.7rem;
            color: var(--ps-gold);
            opacity: 0.65;
            font-style: italic;
            font-family: 'Crimson Text', serif;
            text-align: center;
            max-width: 155px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .user-continue-btn {
            width: 100%;
            background: linear-gradient(135deg, rgba(140, 100, 220, 0.22), rgba(100, 70, 180, 0.12));
            border: 1px solid var(--ps-gold-dim);
            color: var(--ps-gold);
            border-radius: 8px;
            padding: 0.42rem 0.5rem;
            font-size: 0.62rem;
            cursor: pointer;
            font-family: 'Cinzel', serif;
            letter-spacing: 0.1em;
            text-transform: uppercase;
            transition: all 0.18s;
        }
        .user-continue-btn:hover {
            background: linear-gradient(135deg, rgba(150, 110, 230, 0.38), rgba(110, 80, 190, 0.22));
            border-color: var(--ps-gold);
            box-shadow: 0 0 12px rgba(150, 110, 220, 0.22);
        }
        .user-hint { display: none; }

        /* ── PERFIL PROPIO — resalta sobre los demás ── */
        .user-card.profile-mine {
            border-color: var(--ps-gold);
            border-width: 1.5px;
            animation: profile-mine-glow 3.2s ease-in-out infinite;
        }
        .user-card.profile-mine::after { display: none; } /* sin shimmer */

        @keyframes profile-mine-glow {
            0%, 100% {
                filter: drop-shadow(0 4px 20px var(--ps-shadow))
                        drop-shadow(0 0 14px rgba(175, 125, 255, 0.40));
                border-color: rgba(170, 118, 255, 0.55);
                transform: translateY(0px) scale(1);
            }
            50% {
                filter: drop-shadow(0 10px 30px var(--ps-shadow))
                        drop-shadow(0 0 42px rgba(195, 140, 255, 0.90))
                        drop-shadow(0 0 85px rgba(160, 105, 245, 0.50));
                border-color: var(--ps-gold);
                transform: translateY(-5px) scale(1.028);
            }
        }

        /* Hover: congela el glow en máximo y lo refuerza más */
        .user-card.profile-mine:hover {
            animation: none;
            transform: translateY(-7px) scale(1.032);
            filter: drop-shadow(0 14px 36px var(--ps-shadow))
                    drop-shadow(0 0 52px rgba(200, 145, 255, 0.95))
                    drop-shadow(0 0 100px rgba(165, 110, 250, 0.60));
            border-color: var(--ps-gold);
        }

        /* ── PERFILES AJENOS (reclamados por otra cuenta) — atenuados e inaccesibles ── */
        .user-card.profile-foreign {
            opacity: 0.42;
            filter: saturate(0.18) brightness(0.80) drop-shadow(0 2px 8px var(--ps-shadow));
            cursor: not-allowed;
            pointer-events: none; /* el click no llega ni al JS */
        }
        /* El hover no llega porque pointer-events: none — estas reglas son fallback para
           navegadores que ignoran pointer-events en elementos no SVG */
        .user-card.profile-foreign:hover {
            transform: none;
            opacity: 0.42;
            filter: saturate(0.18) brightness(0.80) drop-shadow(0 2px 8px var(--ps-shadow));
            border-color: var(--ps-card-border);
        }
        .user-card.profile-foreign::after { display: none; } /* sin shimmer */

        /* ── SLOT "NUEVO ARCHIVO" ── */
        .add-profile-card {
            flex: 0 0 200px;
            width: 200px;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            gap: 0.75rem;
            background: var(--ps-card-bg);
            opacity: 0.55;
            border: 2px dashed var(--ps-gold-dim);
            /* Sin border-radius — forma definida por clip-path */
            padding: 2rem 1rem;
            cursor: pointer;
            scroll-snap-align: start;
            clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 0 100%);
            transition: opacity 0.22s ease, transform 0.22s ease, filter 0.22s ease, border-color 0.22s ease, color 0.22s ease;
            color: var(--ps-text-muted);
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
            animation: add-profile-pulse 2.8s ease-in-out infinite;
        }
        .add-profile-card:hover {
            border-color: var(--ps-gold);
            opacity: 0.85;
            color: var(--ps-gold);
            transform: translateY(-4px);
            filter: drop-shadow(0 8px 24px var(--ps-shadow));
            animation: none;
        }
        .add-profile-card.highlight {
            border-color: var(--ps-gold);
        }
        @keyframes add-profile-pulse {
            0%, 100% {
                border-color: var(--ps-gold-dim);
                filter: drop-shadow(0 0 0px transparent);
            }
            50% {
                border-color: var(--ps-gold);
                filter: drop-shadow(0 0 18px rgba(200,145,255,0.35));
            }
        }
        .add-profile-icon {
            width: 54px; height: 54px;
            border-radius: 50%;
            background: var(--ps-gold-faint);
            border: 1.5px solid var(--ps-gold-dim);
            display: flex; align-items: center; justify-content: center;
            font-size: 1.8rem; line-height: 1; font-weight: 200;
            transition: background 0.22s, border-color 0.22s;
        }
        .add-profile-card:hover .add-profile-icon {
            background: rgba(150, 110, 220, 0.18);
            border-color: var(--ps-gold);
        }
        .add-profile-text {
            font-family: 'Cinzel', serif;
            font-size: 0.78rem;
            letter-spacing: 0.15em;
            text-transform: uppercase;
        }

        /* ── WELCOME OVERLAY ── */
        .welcome-overlay {
            position: fixed; inset: 0;
            background: rgba(0,0,0,0.5);
            backdrop-filter: blur(3px);
            display: none; align-items: center; justify-content: center;
            z-index: var(--z-i-2100); pointer-events: none;
        }
        .welcome-overlay.active { display: flex; }
        .welcome-message {
            background: var(--ps-card-bg);
            border: 1px solid var(--ps-gold-dim);
            border-radius: 6px;
            padding: 1.6rem 2.8rem;
            font-family: 'Cinzel', serif;
            font-size: 0.88rem;
            letter-spacing: 0.1em;
            color: var(--ps-gold);
            text-transform: uppercase;
            text-align: center;
            box-shadow: 0 0 40px var(--ps-shadow);
        }


        /* MENÚ PRINCIPAL */
        .main-menu {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-image: var(--asset-bg-menu);
            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            z-index: var(--z-i-1000);
        }

        [data-theme="dark"] .main-menu::before {
            content: '';
            position: absolute;
            top: 0; left: 0; width: 100%; height: 100%;
            background:
                radial-gradient(circle at 50% -20%, rgba(122, 146, 207, 0.3) 0%, rgba(14, 22, 43, 0.05) 55%),
                linear-gradient(180deg, rgba(8, 14, 31, 0.92) 0%, rgba(8, 16, 36, 0.86) 48%, rgba(6, 12, 24, 0.95) 100%);
            backdrop-filter: blur(1.4px);
            z-index: var(--z-i-0);
        }

        [data-theme="dark"] .main-menu::after {
            content: '';
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 18% 22%, rgba(255, 245, 200, 0.2) 0 1px, transparent 2px),
                radial-gradient(circle at 74% 18%, rgba(203, 221, 255, 0.16) 0 1px, transparent 2px),
                radial-gradient(circle at 46% 16%, rgba(255, 255, 255, 0.14) 0 1px, transparent 2px),
                radial-gradient(ellipse at 50% 82%, rgba(25, 34, 55, 0.5) 0%, rgba(3, 5, 10, 0.78) 72%);
            background-size: 220px 220px, 180px 180px, 240px 240px, 100% 100%;
            mix-blend-mode: screen;
            opacity: 0.95;
            z-index: var(--z-i-0);
            pointer-events: none;
        }

        [data-theme="light"] .main-menu::before {
            content: '';
            position: absolute;
            top: 0; left: 0; width: 100%; height: 100%;
            background: rgba(245, 241, 232, 0.85);
            backdrop-filter: blur(1px);
            z-index: var(--z-i-0);
        }

        .main-menu.hidden { display: none; }

        /* ══════════════════════════════════════════════════════════════
           PARALLAX DE MENÚ — 4 capas con profundidad, CSS-puro para
           estrellas/luna/niebla. Sin imágenes externas duplicadas.
           ══════════════════════════════════════════════════════════════ */

        .menu-parallax {
            position: absolute;
            inset: 0;
            overflow: hidden;
            pointer-events: none;
            z-index: var(--z-i-1);
            /* URL del fondo — definida en :root al inicio del archivo */
        }

        /* ── Capas de parallax — estilos base (menu.css sobreescribe) ── */
        .parallax-layer {
            position: absolute;
            top: -5%;
            left: -5%;
            width: 110%;
            height: 110%;
            will-change: transform;
            background-size: cover;
            background-repeat: no-repeat;
            background-position: center center;
        }

        /* ── Capa niebla CSS-puro: ribbons de gradiente ── */
        .layer-fog {
            --depth: 0.15;
            background: none;
            filter: none;
            mask-image: none;
            -webkit-mask-image: none;
            z-index: var(--z-i-4);
            pointer-events: none;
        }

        .fog-ribbon {
            position: absolute;
            left: -20%;
            width: 140%;
            height: 120px;
            border-radius: 50%;
            opacity: 0;
            will-change: transform, opacity;
        }

        .fog-ribbon--1 {
            bottom: 18%;
            background: radial-gradient(ellipse at 50% 100%,
                rgba(180, 200, 220, 0.10) 0%,
                rgba(140, 160, 190, 0.06) 40%,
                transparent 72%);
            animation: fog-drift-1 28s ease-in-out infinite;
        }
        .fog-ribbon--2 {
            bottom: 10%;
            background: radial-gradient(ellipse at 50% 100%,
                rgba(160, 185, 210, 0.13) 0%,
                rgba(120, 145, 175, 0.07) 45%,
                transparent 72%);
            animation: fog-drift-2 36s ease-in-out infinite;
            animation-delay: -12s;
        }
        .fog-ribbon--3 {
            bottom: 2%;
            background: radial-gradient(ellipse at 50% 100%,
                rgba(200, 215, 230, 0.09) 0%,
                rgba(160, 180, 205, 0.05) 40%,
                transparent 68%);
            animation: fog-drift-3 44s ease-in-out infinite;
            animation-delay: -22s;
        }

        @keyframes fog-drift-1 {
            0%   { opacity: 0;    transform: translateX(0)   scaleY(0.85); }
            15%  { opacity: 1; }
            50%  { opacity: 0.8;  transform: translateX(4%)  scaleY(1.05); }
            85%  { opacity: 1; }
            100% { opacity: 0;    transform: translateX(0)   scaleY(0.85); }
        }
        @keyframes fog-drift-2 {
            0%   { opacity: 0;    transform: translateX(0)   scaleY(0.9); }
            20%  { opacity: 0.85; }
            55%  { opacity: 0.7;  transform: translateX(-3%) scaleY(1.1); }
            80%  { opacity: 0.85; }
            100% { opacity: 0;    transform: translateX(0)   scaleY(0.9); }
        }
        @keyframes fog-drift-3 {
            0%   { opacity: 0;    transform: translateX(0)   scaleY(0.95); }
            25%  { opacity: 0.75; }
            60%  { opacity: 0.6;  transform: translateX(2%)  scaleY(1.08); }
            75%  { opacity: 0.75; }
            100% { opacity: 0;    transform: translateX(0)   scaleY(0.95); }
        }

        /* ══════════════════════════════════════════════════════════════
           CAMPO DE ESTRELLAS — CSS-puro, 3 profundidades, solo dark mode
           ══════════════════════════════════════════════════════════════ */

        .menu-stars {
            position: absolute;
            inset: 0;
            pointer-events: none;
            opacity: 0;  /* Oculto en light mode; JS/CSS activa en dark */
            transition: opacity 1.2s ease;
        }
        [data-theme="dark"] .menu-stars { opacity: 1; }

        .star-field {
            position: absolute;
            inset: 0;
            background-repeat: repeat;
        }

        /* Far stars: pequeñas y densas */
        .star-field--far {
            background-image:
                radial-gradient(circle, rgba(255,255,255,0.85) 1px, transparent 1px),
                radial-gradient(circle, rgba(200,220,255,0.6)  1px, transparent 1px),
                radial-gradient(circle, rgba(255,255,255,0.7)  1px, transparent 1px);
            background-size: 180px 180px, 220px 220px, 260px 260px;
            background-position: 14px 22px, 88px 55px, 44px 130px;
            opacity: 0.55;
            animation: stars-twinkle-far 8s ease-in-out infinite alternate;
        }

        /* Mid stars: medianas */
        .star-field--mid {
            background-image:
                radial-gradient(circle, rgba(255,250,220,0.9)  1.5px, transparent 1.5px),
                radial-gradient(circle, rgba(220,235,255,0.75) 1.2px, transparent 1.2px),
                radial-gradient(circle, rgba(255,255,255,0.8)  1px,   transparent 1px);
            background-size: 340px 340px, 280px 280px, 380px 380px;
            background-position: 60px 40px, 170px 120px, 22px 200px;
            opacity: 0.65;
            animation: stars-twinkle-mid 11s ease-in-out infinite alternate;
            animation-delay: -3s;
        }

        /* Near stars: pocas, grandes, brillantes — el parallax las mueve más */
        .star-field--near {
            background-image:
                radial-gradient(circle, rgba(255,255,240,1)   2px,   transparent 2px),
                radial-gradient(circle, rgba(200,220,255,0.9) 1.8px, transparent 1.8px),
                radial-gradient(circle, rgba(255,245,200,0.95) 1.5px, transparent 1.5px);
            background-size: 520px 520px, 440px 440px, 600px 600px;
            background-position: 80px 60px, 250px 180px, 420px 90px;
            opacity: 0.80;
            animation: stars-twinkle-near 14s ease-in-out infinite alternate;
            animation-delay: -7s;
        }

        @keyframes stars-twinkle-far {
            0%   { opacity: 0.50; }
            40%  { opacity: 0.62; }
            100% { opacity: 0.48; }
        }
        @keyframes stars-twinkle-mid {
            0%   { opacity: 0.60; }
            60%  { opacity: 0.72; }
            100% { opacity: 0.55; }
        }
        @keyframes stars-twinkle-near {
            0%   { opacity: 0.75; }
            50%  { opacity: 0.90; }
            100% { opacity: 0.68; }
        }

        /* ══════════════════════════════════════════════════════════════
           LUNA / SOL — elemento decorativo centrado que sigue el parallax
           ══════════════════════════════════════════════════════════════ */

        .menu-celestial {
            position: absolute;
            top: 10%;
            right: 18%;
            width: 64px;
            height: 64px;
            border-radius: 50%;
            pointer-events: none;
            /* Dark: luna blanca con halo */
            background: radial-gradient(circle at 38% 38%,
                rgba(255, 255, 240, 0.95) 0%,
                rgba(220, 225, 235, 0.88) 42%,
                rgba(180, 190, 215, 0.5)  65%,
                transparent 80%);
            box-shadow:
                0 0 18px 4px rgba(220, 225, 255, 0.18),
                0 0 45px 12px rgba(180, 200, 240, 0.10);
            opacity: 0;
            transition: opacity 1.4s ease;
            animation: celestial-pulse 9s ease-in-out infinite alternate;
        }

        [data-theme="dark"]  .menu-celestial { opacity: 0.88; }
        [data-theme="light"] .menu-celestial {
            /* Sol dorado */
            background: radial-gradient(circle,
                rgba(255, 240, 160, 1)   0%,
                rgba(255, 210, 80, 0.85) 40%,
                rgba(255, 180, 40, 0.4)  65%,
                transparent 80%);
            box-shadow:
                0 0 24px 8px  rgba(255, 220, 80,  0.28),
                0 0 60px 20px rgba(255, 200, 40,  0.12);
            opacity: 0.72;
        }

        @keyframes celestial-pulse {
            0%   { box-shadow: 0 0 18px 4px rgba(220,225,255,0.18), 0 0 45px 12px rgba(180,200,240,0.10); }
            100% { box-shadow: 0 0 26px 8px rgba(220,225,255,0.26), 0 0 65px 20px rgba(180,200,240,0.16); }
        }

        /* ── Overlay oscurecedor / tinte nocturno (dark mode) ── */
        [data-theme="dark"] .menu-parallax::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: var(--z-i-5);
            pointer-events: none;
            background:
                radial-gradient(ellipse at 50% 0%, rgba(10,15,42,0.48) 0%, transparent 62%),
                linear-gradient(to bottom,
                    rgba(8,12,36,0.65) 0%,
                    rgba(5,10,28,0.40) 35%,
                    rgba(3,8,22,0.28) 65%,
                    rgba(0,5,15,0.48) 100%);
            mix-blend-mode: multiply;
        }

        /* Light mode: velo cálido */
        [data-theme="light"] .menu-parallax::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: var(--z-i-5);
            pointer-events: none;
            background: linear-gradient(to bottom,
                rgba(245, 238, 215, 0.35) 0%,
                rgba(230, 220, 190, 0.18) 55%,
                rgba(200, 210, 180, 0.28) 100%);
        }

        /* ── Clases layer-sky/midforest/foreground eliminadas — reemplazadas por layer-*-day/night ── */
        [data-theme="light"] .fog-ribbon--1,
        [data-theme="light"] .fog-ribbon--2,
        [data-theme="light"] .fog-ribbon--3 {
            /* En light: niebla más cálida, tonos marfil */
            background: radial-gradient(ellipse at 50% 100%,
                rgba(240, 235, 210, 0.15) 0%,
                rgba(220, 215, 190, 0.08) 45%,
                transparent 72%);
        }

        /* ══════════════════════════════════════════════════════════════
           REDUCED-MOTION — sin animaciones, sin parallax
           ══════════════════════════════════════════════════════════════ */
        @media (prefers-reduced-motion: reduce) {
            .parallax-layer { will-change: auto; animation: none !important; }
            .fog-ribbon      { animation: none !important; opacity: 0.55; }
            .star-field      { animation: none !important; }
            .menu-celestial  { animation: none !important; }
            .menu-fireflies  { display: none !important; } /* Canvas: ocultar todo */
        }

        /* Canvas de partículas — fuera del parallax, sin herencia de filtros */
        .menu-fireflies {
            position: absolute;
            inset: 0;
            width: 100% !important;
            height: 100% !important;
            z-index: var(--z-i-8);
            pointer-events: none;
            isolation: isolate;
            display: block;
        }

        /* Las clases .firefly y .leaf ya no se usan con el sistema Canvas */
        /* .firefly y .leaf eliminados — reemplazados por sistema Canvas */

        .menu-sidebar {
            width: 380px;
            height: 100%;
            background: var(--glass-bg);
            backdrop-filter: blur(20px);
            border-right: 3px double var(--accent-wood);
            display: flex;
            flex-direction: column;
            padding: 3rem 2rem;
            box-shadow: 10px 0 40px rgba(0,0,0,0.2);
            position: relative;
            z-index: var(--z-i-10);
        }

        .menu-brand { margin-bottom: 3rem; }
        .menu-title {
            font-family: 'Cinzel', serif;
            font-size: 3rem;
            color: var(--accent-gold);
            margin-bottom: 0.5rem;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
        }
        /* Línea ornamental bajo el título */
        .menu-brand::after {
            content: '✦ ─── ✦ ─── ✦';
            display: block;
            font-size: 0.9rem;
            letter-spacing: 0.15em;
            color: var(--accent-gold);
            opacity: 0.28;
            margin-top: 0.3rem;
            margin-bottom: 0.8rem;
            font-family: serif;
            pointer-events: none;
        }
        .menu-subtitle {
            font-size: 1rem;
            color: var(--text-secondary);
            font-style: italic;
            font-family: 'Crimson Text', serif;
        }

        .menu-container {
            display: flex;
            flex-direction: column;
            gap: 0.8rem;
            flex: 1;
        }

        .menu-button {
            background: var(--menu-button-bg);
            border: 2px solid var(--border-color);
            color: var(--text-primary);
            padding: 1rem 1.5rem;
            border-radius: 12px;
            cursor: pointer;
            font-family: 'Cinzel', serif;
            font-size: 1.1rem;
            font-weight: 600;
            transition: all 0.3s;
            display: flex;
            align-items: center;
            gap: 1rem;
            text-align: left;
            position: relative;
            overflow: hidden;
            text-shadow: 0 1px 2px rgba(0,0,0,0.2);
            box-shadow: 0 4px 15px var(--shadow);
        }
        .menu-button::before {
            content: '';
            position: absolute;
            top: 0; left: -100%;
            width: 100%; height: 100%;
            background: linear-gradient(90deg, transparent, rgba(139, 115, 85, 0.3), transparent);
            transition: left 0.5s;
        }
        /* Cursor triangular ► a la izquierda */
        .menu-button::after {
            content: '►';
            position: absolute;
            left: 0.8rem;
            top: 50%;
            transform: translateY(-50%) scale(0);
            font-size: 0.65rem;
            color: var(--accent-gold);
            opacity: 0;
            transition: opacity 0.25s ease, transform 0.25s ease;
            pointer-events: none;
        }
        .menu-button:hover::before { left: 100%; }
        .menu-button:hover::after {
            opacity: 0.9;
            transform: translateY(-50%) scale(1);
        }
        .menu-button:hover {
            background: rgba(139, 115, 85, 0.22);
            border-color: var(--accent-wood);
            transform: translateX(6px);
            box-shadow: 0 4px 15px rgba(139, 115, 85, 0.3), inset 0 0 20px rgba(160,128,220,0.04);
            color: var(--accent-gold);
        }
        .menu-button:hover .menu-icon::before {
            content: none;
        }
        .menu-button.primary {
            background: linear-gradient(135deg, var(--accent-wood), var(--accent-sage));
            color: white;
            border-color: var(--accent-wood);
            text-shadow: 0 1px 2px rgba(0,0,0,0.3);
        }
        .menu-button.primary:hover {
            box-shadow: 0 4px 20px rgba(139, 115, 85, 0.5);
