        }

        .menu-button-console {
            min-height: 72px;
            border-radius: 16px;
            padding: 1rem 1.2rem;
            gap: 0.9rem;
        }
        .menu-button-console .menu-icon {
            width: 2.2rem;
            font-size: 1.45rem;
            text-align: center;
            flex: 0 0 auto;
        }
        .menu-button-console .menu-label {
            font-size: 1.05rem;
            letter-spacing: 0.02em;
        }

        .menu-footer {
            margin-top: auto;
            padding-top: 2rem;
            border-top: 1px solid var(--border-color);
            color: var(--text-muted);
            font-family: 'Inter', sans-serif;
            font-size: 0.9rem;
        }
        .menu-footer button {
            background: transparent;
            border: 1px solid var(--border-color);
            color: var(--text-secondary);
            padding: 0.3rem 0.8rem;
            border-radius: 6px;
            cursor: pointer;
            margin-left: 0.5rem;
