        .game-section {
    display: none;
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
    background: var(--bg-primary);
    flex-direction: column;
}

        /* Textura de papel en todas las secciones internas — sutil en modo oscuro, más visible en claro */
        #gallerySection,
        #optionsSection,
        #topicsSection {
            position: relative;
            isolation: isolate;
            background: linear-gradient(180deg, rgba(110, 84, 58, 0.05), rgba(41, 29, 20, 0.08)), var(--bg-primary);
        }
        #gallerySection::before,
        #optionsSection::before,
        #topicsSection::before {
            content: '';
            position: absolute;
            inset: 0;
            pointer-events: none;
            z-index: var(--z-i-0);
            opacity: 0.18;
            background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='paperNoise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.78' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23paperNoise)' opacity='0.45'/%3E%3C/svg%3E");
            mix-blend-mode: multiply;
        }
        /* En modo claro la textura es más evidente */
        [data-theme="light"] #gallerySection::before,
        [data-theme="light"] #optionsSection::before,
        [data-theme="light"] #topicsSection::before {
            opacity: 0.32;
        }
        #gallerySection > *,
        #optionsSection > *,
        #topicsSection > * { position: relative; z-index: var(--z-i-1); }
        .game-section.active { display: flex; animation: fadeIn 0.4s ease; }

        .section-header-bar {
            background: linear-gradient(to right, var(--bg-secondary), rgba(26,18,12,0.98));
            border-bottom: 1px solid rgba(160,128,220,0.2);
            box-shadow: 0 1px 0 rgba(160,128,220,0.08), 0 4px 24px rgba(0,0,0,0.4);
            padding: 0.85rem 2rem;
            display: flex; justify-content: space-between; align-items: center;
            flex-shrink: 0;
            backdrop-filter: blur(8px);
            -webkit-backdrop-filter: blur(8px);
        }
        .section-title {
            font-family: 'Cinzel', serif;
            font-size: 1.4rem;
            color: var(--accent-gold);
            letter-spacing: 0.06em;
            font-weight: 400;
            text-shadow: 0 0 20px rgba(160,128,220,0.25);
        }
        .back-button {
            background: transparent;
            border: 1px solid rgba(160,128,220,0.3);
            color: rgba(160,128,220,0.7);
            padding: 0.45rem 1rem;
            border-radius: 4px;
            cursor: pointer;
            font-family: 'Cinzel', serif;
            font-size: 0.78rem;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            transition: all 0.2s;
        }
        .back-button:hover {
            border-color: rgba(160,128,220,0.8);
            color: var(--accent-gold);
            background: rgba(160,128,220,0.08);
            box-shadow: 0 0 12px rgba(160,128,220,0.2);
        }
        .section-content {
    max-width: 1400px;
    margin: 0 auto;
    padding: 2rem;
    flex: 1;
    overflow-y: auto;
    overflow-x: hidden;
}

        /* ============================================
           SECCIÓN HISTORIAS (TOPICS)
        ============================================ */
        .topics-layout {
            display: grid;
            grid-template-columns: 1fr 280px;
            gap: 2rem;
            align-items: start;
        }
        @media (max-width: 900px) {
            .topics-layout { grid-template-columns: 1fr; }
        }

        .topics-main {
            display: flex;
            flex-direction: column;
            gap: 1.2rem;
        }

        /* ── COMMAND BAR (nueva barra de control) ── */
        .topics-command-bar {
            display: flex;
            align-items: center;
            gap: 0.75rem;
            flex-wrap: wrap;
        }

        .btn-create-topic {
            display: inline-flex;
            align-items: center;
            gap: 0.5rem;
            background: linear-gradient(135deg, rgba(139,115,85,0.22), rgba(160,128,220,0.12));
            color: var(--accent-gold);
            border: 1px solid rgba(160,128,220,0.5);
            padding: 0.6rem 1.3rem;
            border-radius: 10px;
            cursor: pointer;
            font-family: 'Cinzel', serif;
            font-size: 0.8rem;
            letter-spacing: 0.07em;
            text-transform: uppercase;
            transition: all 0.2s;
            white-space: nowrap;
            flex-shrink: 0;
        }
        .btn-create-topic:hover {
            border-color: rgba(160,128,220,0.9);
            background: linear-gradient(135deg, rgba(139,115,85,0.35), rgba(160,128,220,0.2));
            box-shadow: 0 0 18px rgba(160,128,220,0.22);
            text-shadow: 0 0 8px rgba(160,128,220,0.4);
        }
        .btn-create-icon {
            font-size: 0.95rem;
            opacity: 0.8;
        }

        .topics-search-wrap {
            flex: 1;
            min-width: 160px;
            position: relative;
            display: flex;
            align-items: center;
        }
        .topics-search-icon {
            position: absolute;
            left: 0.75rem;
            font-size: 0.85rem;
            pointer-events: none;
            opacity: 0.5;
        }
        .topics-search-input {
            width: 100%;
            background: var(--bg-card);
            border: 1px solid var(--border-color);
            border-radius: 10px;
            padding: 0.55rem 0.9rem 0.55rem 2.2rem;
            color: var(--text-primary);
            font-family: 'Inter', sans-serif;
            font-size: 0.88rem;
            transition: border-color 0.2s, box-shadow 0.2s;
        }
        .topics-search-input:focus {
            outline: none;
            border-color: rgba(160,128,220,0.5);
            box-shadow: 0 0 0 2px rgba(160,128,220,0.1);
        }
        .topics-search-input::placeholder { color: var(--text-muted); }

        .topics-filter-group {
            display: flex;
            gap: 0.3rem;
            background: var(--bg-secondary);
            border-radius: 10px;
            padding: 0.25rem;
            flex-shrink: 0;
        }
        .topic-filter-btn {
            padding: 0.4rem 0.9rem;
            border-radius: 8px;
            border: none;
            background: transparent;
            color: var(--text-muted);
            font-family: 'Inter', sans-serif;
            font-size: 0.8rem;
            font-weight: 500;
            cursor: pointer;
            transition: all 0.18s;
            white-space: nowrap;
        }
        .topic-filter-btn:hover { color: var(--text-primary); }
        .topic-filter-btn.active {
            background: var(--bg-card);
            color: var(--accent-gold);
            box-shadow: 0 1px 4px rgba(0,0,0,0.12);
        }

        /* ── LEGEND in sidebar ── */
        .topics-mode-legend {
            margin-top: 1rem;
            background: var(--bg-card);
            border: 1.5px solid var(--border-color);
            border-radius: 14px;
            padding: 1.1rem 1.2rem;
            display: flex;
            flex-direction: column;
            gap: 0.85rem;
        }
        .legend-item {
            display: flex;
            align-items: center;
            gap: 0.75rem;
        }
        .legend-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            flex-shrink: 0;
        }
        .legend-rpg .legend-dot {
            background: var(--accent-wood);
            box-shadow: 0 0 6px rgba(139,115,85,0.5);
        }
        .legend-classic .legend-dot {
            background: var(--accent-sage);
            box-shadow: 0 0 6px rgba(107,142,125,0.5);
        }
        .legend-name {
            font-family: 'Cinzel', serif;
            font-size: 0.8rem;
            color: var(--text-primary);
            letter-spacing: 0.03em;
        }
        .legend-desc {
            font-size: 0.73rem;
            color: var(--text-muted);
            font-family: 'Inter', sans-serif;
            margin-top: 0.1rem;
        }

        .topics-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(270px, 1fr));
            gap: 1.1rem;
            padding-bottom: 1rem;
        }

