/* -- css/components/03-topic-cards.css -- */
/* ═══════════════════════════════════════════════════════════════
   03-TOPIC-CARDS — Tarjetas de historia (estilo tarot) — identidad visual por modo
   (Generado por split-components.js desde css/components.css)
   ═══════════════════════════════════════════════════════════════ */

           TOPIC CARDS — identidad visual por modo
        ═══════════════════════════════════════════ */
        .topic-card {
            position: relative;
            border-radius: 14px;
            overflow: hidden;
            cursor: pointer;
            transition: transform 0.25s ease, box-shadow 0.3s ease;
        }

        /* ── RPG: piedra arenisca fría ── */
        .topic-card--rol {
            background: #3e3a34;
            border: 1px solid rgba(180, 165, 140, 0.3);
            box-shadow: 0 4px 20px rgba(0,0,0,0.2);
        }
        .topic-card--rol:hover {
            transform: translateY(-3px);
            box-shadow: 0 14px 40px rgba(0,0,0,0.3), 0 0 0 1px rgba(180,165,140,0.4);
            border-color: rgba(180, 165, 140, 0.55);
        }

        /* ── Clásico: pergamino sepia ── */
        .topic-card--historia {
            background: #f7f2e8;
            border: 1px solid rgba(160, 128, 80, 0.35);
            box-shadow: 0 4px 16px rgba(120, 90, 50, 0.14);
        }
        [data-theme="dark"] .topic-card--historia {
            background: #28200f;
            border-color: rgba(190, 155, 90, 0.28);
            box-shadow: 0 4px 16px rgba(0,0,0,0.3);
        }
        .topic-card--historia:hover {
            transform: translateY(-3px);
            box-shadow: 0 12px 32px rgba(120,90,50,0.22), 0 0 0 1px rgba(160,128,80,0.45);
            border-color: rgba(160, 128, 80, 0.6);
        }
        [data-theme="dark"] .topic-card--historia:hover {
            box-shadow: 0 12px 32px rgba(0,0,0,0.4), 0 0 0 1px rgba(190,155,90,0.4);
        }

        /* ── Marca de agua decorativa (ilustración) ── */
        .topic-card-watermark {
            position: absolute;
            right: -8px;
            top: 50%;
            transform: translateY(-50%);
            width: 110px;
            height: 110px;
            pointer-events: none;
            opacity: 0.06;
            transition: opacity 0.3s;
        }
        .topic-card:hover .topic-card-watermark { opacity: 0.12; }

        /* ── Banda lateral ── */
        .topic-card-accent {
            position: absolute;
            left: 0; top: 0; bottom: 0;
            width: 4px;
        }
        .topic-card--rol .topic-card-accent {
            background: linear-gradient(180deg, #a09070 0%, #6a5c48 70%, transparent 100%);
        }
        .topic-card--historia .topic-card-accent {
            background: linear-gradient(180deg, #c4a060 0%, #8a6030 70%, transparent 100%);
        }

        /* ── Ornamentos de esquina ── */
        .topic-card-corner {
            position: absolute;
            width: 22px;
            height: 22px;
            pointer-events: none;
            opacity: 0.35;
            transition: opacity 0.25s;
        }
        .topic-card:hover .topic-card-corner { opacity: 0.7; }
        .topic-card-corner--tl { top: 7px; left: 10px; }
        .topic-card-corner--tr { top: 7px; right: 10px; transform: scaleX(-1); }
        .topic-card-corner--bl { bottom: 7px; left: 10px; transform: scaleY(-1); }
        .topic-card-corner--br { bottom: 7px; right: 10px; transform: scale(-1); }

        /* ── Interior ── */
        .topic-card-inner {
            padding: 1.1rem 7rem 0.6rem 1.6rem;
            position: relative;
            z-index: var(--z-i-1);
        }

        .topic-card-top {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            margin-bottom: 0.65rem;
        }

        .topic-card-badges {
            display: flex;
            flex-wrap: wrap;
            gap: 0.35rem;
            flex: 1;
        }

        .topic-badge {
            font-size: 0.63rem;
            font-family: 'Cinzel', serif;
            font-weight: 700;
            letter-spacing: 0.08em;
            text-transform: uppercase;
            padding: 0.18rem 0.65rem;
            border-radius: 20px;
        }
        .topic-badge.mode {
            color: #c8b898;
            background: rgba(180, 155, 110, 0.15);
            border: 1px solid rgba(180, 155, 110, 0.3);
        }
        .topic-card--historia .topic-badge.mode {
            color: #8a6030;
            background: rgba(160, 110, 50, 0.12);
            border-color: rgba(160, 110, 50, 0.3);
        }
        [data-theme="dark"] .topic-card--historia .topic-badge.mode {
            color: #a080e0;
            background: rgba(160,128,220,0.13);
            border-color: rgba(160,128,220,0.3);
        }
        .topic-badge.weather {
            color: #6495ed;
            background: rgba(100, 149, 237, 0.1);
            border: 1px solid rgba(100, 149, 237, 0.25);
        }
        .topic-card-count { display: none; }

        .topic-card-title {
            font-family: 'Cinzel', serif;
            font-size: 1rem;
            margin-bottom: 0.2rem;
            line-height: 1.3;
            letter-spacing: 0.02em;
        }
        .topic-card--rol .topic-card-title { color: #e8dcc8; }
        .topic-card--historia .topic-card-title { color: #4a3520; }
        [data-theme="dark"] .topic-card--historia .topic-card-title { color: #d4a84a; }

        .topic-card-author {
            font-size: 0.73rem;
            font-family: 'Inter', sans-serif;
            margin-bottom: 0.55rem;
        }
        .topic-card--rol .topic-card-author { color: rgba(190, 172, 145, 0.55); }
        .topic-card--historia .topic-card-author { color: rgba(110, 80, 40, 0.6); }
        [data-theme="dark"] .topic-card--historia .topic-card-author { color: rgba(160,128,220,0.5); }

        .topic-card-excerpt {
            font-family: 'Crimson Text', serif;
            font-style: italic;
            font-size: 0.91rem;
            line-height: 1.55;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }
        .topic-card--rol .topic-card-excerpt { color: rgba(200, 180, 148, 0.7); }
        .topic-card--historia .topic-card-excerpt { color: rgba(90, 64, 30, 0.75); }
        [data-theme="dark"] .topic-card--historia .topic-card-excerpt { color: rgba(160,128,220,0.6); }
        .topic-card-excerpt--empty {
            font-style: normal;
            font-size: 0.8rem;
            opacity: 0.7;
        }
        .topic-card-excerpt--meta {
            font-style: normal;
            font-size: 0.72rem;
            opacity: 0.75;
            margin-bottom: 0.45rem;
        }

        /* ── Footer ── */
        .topic-card-footer {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0.5rem 1.2rem 0.6rem 1.6rem;
            border-top: 1px solid;
            position: relative;
            z-index: var(--z-i-1);
        }
        .topic-card--rol .topic-card-footer { border-top-color: rgba(160,140,105,0.2); }
        .topic-card--historia .topic-card-footer { border-top-color: rgba(160,120,60,0.18); }
        [data-theme="dark"] .topic-card--historia .topic-card-footer { border-top-color: rgba(160,128,220,0.14); }

        .topic-card-footer-msgs {
            display: flex;
            align-items: center;
            gap: 0.4rem;
            font-family: 'Inter', sans-serif;
            font-size: 0.74rem;
        }
        .topic-card--rol .topic-card-footer-msgs { color: rgba(190, 165, 125, 0.6); }
        .topic-card--historia .topic-card-footer-msgs { color: rgba(120, 85, 40, 0.6); }
        [data-theme="dark"] .topic-card--historia .topic-card-footer-msgs { color: rgba(160,128,220,0.5); }
        .topic-card-footer-msgs-icon { font-size: 0.75rem; opacity: 0.7; }
        .topic-card-progress {
            position: relative;
            flex: 1;
            margin: 0 0.6rem;
            height: 6px;
            border-radius: 999px;
            background: rgba(255,255,255,0.12);
            overflow: hidden;
        }
        .topic-card-progress-bar {
            height: 100%;
            background: linear-gradient(90deg, rgba(112,214,149,0.85), rgba(76,186,211,0.85));
            transition: width 0.25s ease;
        }
        .topic-card-progress-text {
            position: absolute;
            right: 2px;
            top: -14px;
            font-size: 0.62rem;
            font-family: 'Inter', sans-serif;
            opacity: 0.8;
        }

        .topic-card-char-avatar {
            width: 30px; height: 30px;
            border-radius: 50%;
            object-fit: cover; object-position: top center;
            opacity: 0.8; transition: opacity 0.2s; flex-shrink: 0;
        }
        .topic-card--rol .topic-card-char-avatar { border: 1.5px solid rgba(180,155,110,0.45); }
        .topic-card--historia .topic-card-char-avatar { border: 1.5px solid rgba(190,148,80,0.45); }
        .topic-card:hover .topic-card-char-avatar { opacity: 1; }

        /* Estado vacío */
        .topics-empty {
            grid-column: 1 / -1;
            text-align: center;
            padding: 4rem 2rem;
            color: var(--text-muted);
            font-family: 'Crimson Text', serif;
            font-size: 1.1rem;
            line-height: 2;
        }
        .topics-empty span {
            display: block;
            font-size: 0.9rem;
            font-family: 'Inter', sans-serif;
            opacity: 0.6;
        }

