        .topic-modal .form-group textarea {
            border-radius: 12px;
            border: 2px solid var(--border-color);
            background: linear-gradient(135deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02));
            transition: border-color 0.25s ease, box-shadow 0.25s ease, transform 0.2s ease;
        }

        .topic-modal .form-group {
            margin-bottom: 0;
        }

        .topic-modal .form-group input:focus,
        .topic-modal .form-group select:focus,
        .topic-modal .form-group textarea:focus {
            outline: none;
            border-color: var(--accent-gold);
            box-shadow: 0 0 0 3px rgba(160,128,220, 0.15), inset 0 0 18px rgba(160,128,220, 0.08), 0 0 16px rgba(160,128,220, 0.22);
        }

        .topic-modal-footer {
            display: flex;
            flex-direction: column;
            gap: 0.85rem;
            margin-top: 0.9rem;
            flex-shrink: 0;
