        }

        .topic-create-btn {
            width: 100%;
            margin-top: 0;
            align-self: center;
            position: static;
            padding: 1rem 2rem;
            font-size: 1.05rem;
            letter-spacing: 0.35px;
            background: linear-gradient(135deg, var(--accent-gold), var(--accent-wood));
            box-shadow: 0 0 20px rgba(160,128,220, 0.35), 0 8px 20px rgba(0,0,0,0.35);
        }

        .topic-create-btn:hover {
            transform: translateY(-2px) scale(1.02);
            box-shadow: 0 0 24px rgba(160,128,220, 0.45), 0 12px 24px rgba(0,0,0,0.4);
        }

        .topic-inicio-group {
            display: flex;
            flex-direction: column;
        }

        #topicFirstMsg,
        textarea[name="inicio"] {
            width: 100%;
            box-sizing: border-box;
            min-height: 150px;
            max-height: 220px;
            overflow-y: auto;
            resize: none;
            padding: 1rem;
            border-radius: 8px;
            scrollbar-width: thin;
            scrollbar-color: var(--accent-gold) rgba(255,255,255,0.08);
        }

        .topic-weather-inline {
            display: flex;
            align-items: center;
            gap: 0.45rem;
            flex-wrap: wrap;
        }

        .topic-weather-btn {
            width: 30px;
            height: 30px;
            border: 2px solid var(--border-color);
            border-radius: 999px;
            font-size: 0.95rem;
            line-height: 1;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            padding: 0;
            flex: 0 0 30px;
            color: var(--text-primary);
            font-family: 'Inter', sans-serif;
            background: rgba(255,255,255,0.06);
            box-shadow: 0 0 0 rgba(160,128,220, 0);
            transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
        }

        .topic-weather-btn:hover {
            transform: translateY(-1px);
            border-color: rgba(160,128,220, 0.78);
            background: rgba(160,128,220, 0.16);
        }

        .topic-weather-btn.active {
            border-color: var(--accent-gold);
            background: rgba(160,128,220, 0.24);
            box-shadow: 0 0 12px rgba(160,128,220, 0.42), inset 0 0 8px rgba(160,128,220, 0.26);
