            background: transparent;
        }

        #topicFirstMsg::-webkit-scrollbar-track,
        textarea[name="inicio"]::-webkit-scrollbar-track {
            background: rgba(255,255,255,0.08);
            border-radius: 8px;
        }

        #topicFirstMsg::-webkit-scrollbar-thumb,
        textarea[name="inicio"]::-webkit-scrollbar-thumb {
            background: var(--accent-gold);
            border-radius: 10px;
        }

        body.modal-open {
            overflow: hidden;
        }

        @media (max-width: 768px) {
            .topic-modal {
                width: min(94vw, 620px);
                max-height: min(90vh, 720px);
                padding: 0.9rem 0.9rem 0.75rem;
            }

            .topic-modal-body {
                gap: 0.55rem;
            }

