                margin-bottom: 0 !important;
            }

            .topic-mode-toggle {
                grid-template-columns: 1fr;
            }

            .topic-header-row {
                align-items: flex-start;
                gap: 0.55rem;
                margin-bottom: 0.45rem;
            }

            .topic-weather-inline {
                width: 100%;
                justify-content: flex-start;
            }

            .topic-weather-btn {
                width: 28px;
                height: 28px;
                flex-basis: 28px;
            }


            #topicFirstMsg,
            textarea[name="inicio"] {
                min-height: 130px;
                max-height: 180px;
            }
        }

        /* VN MODE */
        .vn-section {
            position: relative;
            min-height: 100vh;
            min-height: 100dvh;
            color: #fff;
            background-size: cover;
            background-position: center;
            /* Fondo por defecto: gradiente de bosque nocturno cuando no hay imagen */
            background-image: linear-gradient(
                180deg,
                #0d1a2e 0%,
                #1a2d4a 20%,
                #162438 45%,
                #0f1e10 70%,
                #081208 100%
            );
            /* BUGFIX: overflow:visible para no crear stacking context en Safari iOS.
               overflow:clip puede causar que position:fixed hijos se comporten como
               position:absolute en ciertos motores (WebKit/Blink con compositing layers).
               contain:layout style aisla el elemento sin afectar fixed children. */
            overflow: visible;
            contain: layout style;
            /* BUGFIX: eliminamos transform de la transición base para no relativizar
               los position:fixed durante las transiciones de escena. */
            transition: filter 0.5s ease, background-image 1s ease;
            transform-origin: center center;
        }

        .vn-section.entering-scene {
            /* BUGFIX: en lugar de aplicar filter/transform al propio elemento (lo que
               crea un stacking context y relativiza los position:fixed hijos),
               usamos un pseudo-elemento ::after para el efecto visual de entrada. */
            transform: none;
            filter: none;
        }

        .vn-section.entering-scene::after {
            content: '';
            position: absolute;
            inset: 0;
            backdrop-filter: blur(2px) saturate(0.9);
            pointer-events: none;
            z-index: var(--z-i-2);
            animation: entering-scene-fade 550ms ease forwards;
        }

        @keyframes entering-scene-fade {
            from { opacity: 1; }
            to   { opacity: 0; }
        }

        .vn-scene-transition {
            position: absolute;
            inset: 0;
            pointer-events: none;
            z-index: var(--z-i-175);
            opacity: 0;
            background: radial-gradient(ellipse at center,
                rgba(10, 8, 6, 0.6) 0%,
                rgba(0, 0, 0, 0.98) 100%);
        }

        .vn-scene-transition.active {
            animation: vn-scene-cinematic 750ms cubic-bezier(0.4, 0, 0.2, 1) forwards;
        }

        /* Variante wipe (barrido lateral) */
        .vn-scene-transition.wipe {
            background: linear-gradient(90deg,
                transparent 0%,
                rgba(0, 0, 0, 0.97) 50%,
                transparent 100%);
            animation: vn-scene-wipe 700ms ease-in-out forwards;
        }

        @keyframes vn-scene-wipe {
            0%   { transform: translateX(-110%); opacity: 1; }
            100% { transform: translateX(110%);  opacity: 1; }
        }

        .vn-section::before {
            content: '';
            position: absolute;
            inset: 0;
            background: rgba(0, 0, 0, 0.4);
            backdrop-filter: blur(3px);
            pointer-events: none;
            z-index: var(--z-i-0);
        }
        .vn-section.mode-classic::before {
            background: linear-gradient(135deg, rgba(56, 38, 20, 0.45), rgba(24, 16, 10, 0.55));
        }
        .vn-section.mode-rpg::before {
            background: linear-gradient(135deg, rgba(42, 26, 8, 0.35), rgba(18, 12, 6, 0.55));
        }
        .vn-section.mode-rpg .vn-info-card {
            border-color: rgba(160,128,220, 0.6);
            box-shadow: 0 0 24px rgba(160,128,220, 0.25), 0 8px 30px rgba(0,0,0,0.35);
        }
        .vn-section.mode-rpg #vnInfoPills,
        .vn-section.mode-rpg #affinityDisplay,
        .vn-section.mode-rpg #vnInfoAffection {
            display: none !important;
        }


        #roomCodeWrap {
            position: fixed;
            top: 62px;
            right: 20px;
            z-index: var(--z-i-195);
        }

        @media (max-width: 900px) {
            #roomCodeWrap {
                width: calc(100vw - 2rem);
                top: 90px;
            }
        }

        .vn-section > * {
            position: relative;
        }

        .vn-section.sepia { filter: sepia(0.6) contrast(1.1); }
        .vn-section.bw { filter: grayscale(1) contrast(1.2); }
        .vn-section.cinematic { filter: contrast(1.3) saturate(1.2) brightness(0.9); }



/* -- css/components/04-info-card.css -- */
/* ═══════════════════════════════════════════════════════════════
   04-INFO-CARD — Info card con sistema de afinidad
   (Generado por split-components.js desde css/components.css)
   ═══════════════════════════════════════════════════════════════ */

        /* INFO CARD CON SISTEMA DE AFINIDAD */
        .vn-info-card {
            position: fixed;
            top: 20px;
            left: 20px;
            z-index: var(--z-controls, 200);
            background: rgba(20, 15, 10, 0.62);
            border: 1px solid rgba(160,128,220, 0.3);
            border-radius: 14px;
            padding: 0.9rem 1rem 0.9rem 0.9rem;
            display: flex;
            align-items: flex-start;
            gap: 0.85rem;
            backdrop-filter: blur(5px);
            -webkit-backdrop-filter: blur(5px);
            box-shadow: 0 8px 20px rgba(0,0,0,0.35);
            min-width: 220px;
            max-width: 290px;
            transition: border-color 0.5s ease, box-shadow 0.5s ease;
            overflow: visible;
            /* El borde adopta el color del personaje activo */
            border-color: var(--char-color, rgba(160,128,220, 0.4));
        }

        /* Panel de hover — ocupación + personalidad */
        .vn-info-hover-details {
            position: absolute;
            top: calc(100% + 8px);
            left: 0;
            width: 100%;
            border-radius: 12px;
            padding: 0.7rem 0.85rem;
            border: 1px solid rgba(160,128,220, 0.3);
            background: rgba(10, 7, 4, 0.94);
            box-shadow: 0 14px 32px rgba(0, 0, 0, 0.5);
            opacity: 0;
            transform: translateY(-4px);
            pointer-events: none;
            transition: opacity 200ms ease, transform 200ms ease;
            z-index: var(--z-i-10);
            backdrop-filter: blur(10px);
        }

        .vn-info-card:hover .vn-info-hover-details,
        .vn-info-card:focus-within .vn-info-hover-details {
            opacity: 1;
            transform: translateY(0);
        }

        .vn-hover-row {
            font-size: 0.78rem;
            color: rgba(200, 185, 160, 0.75);
            line-height: 1.5;
            font-family: 'Inter', sans-serif;
        }
        .vn-hover-row:empty { display: none; }
        .vn-hover-row + .vn-hover-row:not(:empty) {
            margin-top: 0.35rem;
            padding-top: 0.35rem;
            border-top: 1px solid rgba(160,128,220, 0.1);
        }
        .vn-hover-personality {
            font-family: 'Crimson Text', serif;
            font-style: italic;
            font-size: 0.85rem;
            color: rgba(200, 185, 160, 0.6);
        }


        .vn-info-rpg {
            margin-top: 0.42rem;
            border-top: 1px solid rgba(160,128,220, 0.16);
            padding-top: 0.4rem;
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 0.45rem;
        }
        .vn-info-rpg.hidden { display: none; }
        .vn-info-rpg-summary {
            font-size: 0.68rem;
            color: rgba(210, 188, 148, 0.86);
            letter-spacing: 0.02em;
            font-family: 'Inter', sans-serif;
        }
        .vn-info-rpg-sheet-btn {
            border: 1px solid rgba(160,128,220, 0.36);
            background: rgba(160,128,220, 0.1);
            color: var(--accent-gold);
            border-radius: 8px;
            padding: 0.22rem 0.48rem;
            font-size: 0.72rem;
            cursor: pointer;
            flex-shrink: 0;
            white-space: nowrap;
        }

        /* Avatar */
        .vn-info-avatar {
            width: 56px;
            height: 56px;
            border-radius: 50%;
            border: 2px solid var(--char-color-full, rgba(160,128,220, 0.7));
            overflow: hidden;
            flex-shrink: 0;
            background: var(--bg-tertiary);
            transition: border-color 0.5s ease;
            box-shadow: 0 0 10px -2px var(--char-color, rgba(160,128,220,0.3));
        }

        .vn-info-avatar img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: top center;
        }

        /* Contenedor de texto */
        .vn-info-details {
            display: flex;
            flex-direction: column;
            gap: 0.18rem;
            flex: 1;
            min-width: 0;
            position: relative;
        }

        /* Fila de nombre — nombre + badge Ficha */
        .vn-info-name-row {
            display: flex;
            align-items: center;
            gap: 0.4rem;
            overflow: hidden;
        }

        .vn-info-name {
            font-family: 'Cinzel', serif;
            color: rgba(230, 205, 155, 0.95);
            font-size: 0.95rem;
            font-weight: 600;
            line-height: 1.2;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            flex: 1;
        }

        /* Badge Ficha — pequeño icono-botón junto al nombre */
        .vn-ficha-badge {
            flex-shrink: 0;
            width: 22px;
            height: 22px;
            border-radius: 6px;
            border: 1px solid rgba(160,128,220, 0.4);
            background: rgba(160,128,220, 0.1);
            color: rgba(160,128,220, 0.8);
            font-size: 0.75rem;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            padding: 0;
            line-height: 1;
            transition: all 0.15s;
        }
        .vn-ficha-badge:hover {
            background: rgba(160,128,220, 0.25);
            border-color: rgba(160,128,220, 0.7);
        }
        .vn-ficha-badge.hidden { display: none; }

        /* Subtítulo dinámico: ocupación (clásico) o nivel RPG */
        .vn-info-subtitle {
            font-family: 'Inter', sans-serif;
            font-size: 0.72rem;
            color: rgba(160,128,220, 0.65);
            letter-spacing: 0.03em;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            min-height: 1em;
        }
        .vn-info-subtitle:empty { display: none; }

        /* Píldoras de datos: edad · raza · género */
        .vn-info-pills {
            display: flex;
            align-items: center;
            gap: 0.25rem;
            flex-wrap: nowrap;
            overflow: hidden;
            margin-top: 0.1rem;
        }

        .vn-info-pill {
            font-size: 0.72rem;
            font-family: 'Inter', sans-serif;
            color: rgba(180, 162, 130, 0.75);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 90px;
        }
        .vn-info-pill:empty { display: none; }

        .vn-info-pill-sep {
            font-size: 0.65rem;
            color: rgba(160,128,220, 0.3);
            flex-shrink: 0;
            line-height: 1;
        }
        /* Ocultar separador si la píldora adyacente está vacía */
        .vn-info-pill:empty + .vn-info-pill-sep,
        .vn-info-pill-sep:has(+ .vn-info-pill:empty) { display: none; }
        .vn-info-pills:empty { display: none; }

        /* SISTEMA DE AFINIDAD REVAMP - Estilo visual novel */
        .affinity-rank-display {
            display: flex;
            flex-direction: column;
            gap: 0.2rem;
            margin-top: 0.4rem;
            border-top: 1px solid rgba(160,128,220, 0.15);
            padding-top: 0.4rem;
        }

        .affinity-rank-row {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 0.4rem;
        }

        .affinity-rank-name {
            font-family: 'Cinzel', serif;
            font-size: 0.8rem;
            color: var(--accent-gold);
            text-shadow: 0 0 8px currentColor;
            letter-spacing: 0.03em;
            flex: 1;
        }

        .affinity-rank-value {
            font-size: 0.8rem;
            color: var(--text-muted);
        }

        /* Controles de afinidad pequeños tipo VN */
        .affinity-controls-inline {
            display: flex;
            align-items: center;
            gap: 0.3rem;
        }

        .affinity-btn-inline {
            width: 18px;
            height: 18px;
            border-radius: 4px;
            border: 1px solid rgba(160,128,220, 0.5);
            background: rgba(160,128,220, 0.1);
            color: rgba(160,128,220, 0.8);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 0.75rem;
            font-weight: bold;
            line-height: 1;
            transition: all 0.15s;
            padding: 0;
        }

        .affinity-btn-inline:hover {
            transform: scale(1.15);
        }

        .affinity-btn-inline.minus {
            border-color: rgba(199, 91, 91, 0.5);
            color: rgba(199, 91, 91, 0.8);
            background: rgba(199, 91, 91, 0.1);
        }

        .affinity-btn-inline.minus:hover {
            background: rgba(199, 91, 91, 0.25);
            border-color: #c75b5b;
            color: #c75b5b;
        }

        .affinity-btn-inline.plus {
            border-color: rgba(107, 142, 125, 0.5);
            color: rgba(107, 142, 125, 0.8);
            background: rgba(107, 142, 125, 0.1);
        }

        .affinity-btn-inline.plus:hover {
            background: rgba(107, 142, 125, 0.25);
            border-color: var(--accent-sage);
            color: var(--accent-sage);
        }

        /* Notificación de afinidad — inline dentro del card, no en esquina */
        .affinity-feedback {
            font-family: 'Cinzel', serif;
            font-size: 0.7rem;
            text-align: center;
            letter-spacing: 0.05em;
            opacity: 0;
            transform: translateY(-3px);
            transition: opacity 0.3s, transform 0.3s;
            pointer-events: none;
            height: 0;
            overflow: hidden;
        }
        .affinity-feedback.visible {
            opacity: 1;
            transform: translateY(0);
            height: auto;
        }
        .affinity-feedback.up { color: var(--accent-sage); }
        .affinity-feedback.down { color: #c75b5b; }

        /* Controles */
        .vn-controls {
            position: fixed;
            top: 18px;
            right: 20px;
            z-index: var(--z-controls, 200);
            display: flex;
            gap: 0.35rem;
            background: rgba(8, 8, 10, 0.72);
            padding: 0.4rem;
            border-radius: 12px;
            border: 1px solid rgba(160,128,220, 0.6);
            backdrop-filter: blur(15px);
            -webkit-backdrop-filter: blur(15px);
            overflow: visible;
            box-shadow: 0 6px 24px rgba(0, 0, 0, 0.28);
        }

        .vn-control-slot {
            width: 32px;
            height: 32px;
            flex: 0 0 32px;
            position: relative;
        }

        .vn-control-slot:has(> .vn-control-btn.hidden) {
            display: none;
        }

        .vn-control-btn {
            background: rgba(0,0,0,0.3);
            border: 2px solid var(--border-color);
            color: var(--accent-gold);
            width: 32px;
            height: 32px;
            border-radius: 8px;
            cursor: pointer;
            font-family: 'Inter', sans-serif;
            font-size: 1.2rem;
            transition: background-color 200ms ease-out, color 200ms ease-out, border-color 200ms ease-out, box-shadow 200ms ease-out;
            backdrop-filter: blur(5px);
            display: flex;
            align-items: center;
            justify-content: center;
            position: absolute;
            top: 0;
            right: 0;
            overflow: hidden;
            white-space: nowrap;
            padding: 0;
            gap: 0;
            text-align: left;
        }

        .vn-control-btn::after {
            content: attr(aria-label);
            position: absolute;
            top: calc(100% + 8px);
            left: 50%;
            transform: translateX(-50%) translateY(-4px);
            opacity: 0;
            padding: 0.3rem 0.5rem;
            border-radius: 8px;
            border: 1px solid rgba(160,128,220, 0.6);
            background: rgba(10, 10, 10, 0.82);
            color: #fff;
            font-size: 0.72rem;
            letter-spacing: 0.01em;
            white-space: nowrap;
            pointer-events: none;
            z-index: var(--z-i-500);
            transition: opacity 200ms ease, transform 200ms ease;
            transition-delay: 0s;
        }

        .vn-control-btn:hover {
            background: rgba(139, 105, 20, 0.18);
            color: var(--accent-gold);
            border-color: rgba(160,128,220, 0.5);
            box-shadow: 0 0 8px rgba(160,128,220, 0.25);
        }

        .vn-control-btn:hover::after,
        .vn-control-btn:focus-visible::after,
        .vn-control-btn:active::after {
            opacity: 1;
            transform: translateX(-50%) translateY(0);
            transition-delay: 0.4s;
        }

        .vn-control-btn:active::after {
            transition-delay: 0s;
        }

        .vn-control-icon {
            flex: 0 0 auto;
            width: 1.1rem;
            text-align: center;
            line-height: 1;
            font-size: 0.95rem;
        }

        .vn-control-label {
            display: none;
        }

        .vn-control-btn.save-btn {
            background: rgba(107, 142, 125, 0.4);
            border-color: var(--accent-sage);
        }

        /* Separador entre grupos de botones */
        .vn-control-divider {
            width: 1px;
            height: 22px;
            background: rgba(160,128,220, 0.25);
            border-radius: 1px;
            flex-shrink: 0;
            align-self: center;
            margin: 0 0.1rem;
        }

        /* SPRITES EN MODO FANFIC - PERSISTENTES */
        .vn-sprite-container {
            position: fixed;
            bottom: 0;
            left: 0;
            right: 0;
            height: 75vh;
            pointer-events: none;
            z-index: var(--z-i-100);
            perspective: 1200px;
            overflow: visible; /* Allow manga-emotes to overflow sprite bounds */
        }

        .vn-sprite {
            position: absolute;
            bottom: 0;
            height: 100%;
            display: flex;
            align-items: flex-end;
            justify-content: center;
            transition: opacity 0.6s cubic-bezier(0.4, 0, 0.2, 1),
                        filter 0.6s cubic-bezier(0.4, 0, 0.2, 1),
                        transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
        }

        .vn-sprite img {
            height: 95%;
            width: auto;
            max-width: none;
            object-fit: cover;
            object-position: top center;
            transform-origin: center bottom;
            /* Desvanecido en los pies para integrarse con el fondo */
            mask-image: linear-gradient(to bottom, black 82%, transparent 100%);
            -webkit-mask-image: linear-gradient(to bottom, black 82%, transparent 100%);
        }

        .vn-sprite.no-sprite {
            width: min(34vw, 360px);
            min-width: 220px;
        }
        .vn-sprite-hitbox {
            width: 100%;
            height: 95%;
            border-radius: 18px 18px 10px 10px;
            border: 1px dashed rgba(160,128,220, 0.22);
            background: linear-gradient(to bottom, rgba(160,128,220, 0.06), rgba(160,128,220, 0.01));
            mask-image: linear-gradient(to bottom, black 82%, transparent 100%);
            -webkit-mask-image: linear-gradient(to bottom, black 82%, transparent 100%);
        }

        /* Posiciones con ligera profundidad Z — se combina con la animación via CSS vars */
        .vn-sprite.position-left {
            left: 5%;
            transform: translateZ(10px);
        }
        .vn-sprite.position-center {
            left: 50%;
            transform: translateX(-50%) translateZ(30px);
        }
        .vn-sprite.position-right {
            right: 5%;
            transform: translateZ(10px);
        }

        /* INACTIVO: oscuro, desaturado, retraído */
        .vn-sprite.inactive {
            opacity: 0.38;
        }
        .vn-sprite.inactive img {
            filter:
                brightness(0.5)
                contrast(0.85)
                grayscale(0.35)
                drop-shadow(0 10px 18px rgba(0,0,0,0.3));
            animation: none;
        }
        /* Posiciones inactivas: mantenemos el translate original */
        .vn-sprite.inactive.position-left  { transform: scale(0.94) translateZ(0px); }
        .vn-sprite.inactive.position-center { transform: translateX(-50%) scale(0.94) translateZ(0px); }
        .vn-sprite.inactive.position-right { transform: scale(0.94) translateZ(0px); }

        /* ACTIVO: brillante, con glow dorado suave, animación de respiración */
        .vn-sprite.active {
            opacity: 1;
            z-index: var(--z-i-105);
        }
        .vn-sprite.active img {
            filter:
                brightness(1.08)
                contrast(1.04)
                drop-shadow(0 25px 35px rgba(0,0,0,0.45))
                drop-shadow(0 0 25px rgba(160,128,220, 0.12));
            animation: sprite-breathing 4.8s ease-in-out infinite;
            animation-play-state: var(--section-animations, running);
        }
        .vn-sprite.active.position-left   { transform: scale(1) translateZ(10px); }
        .vn-sprite.active.position-center { transform: translateX(-50%) scale(1) translateZ(30px); }
        .vn-sprite.active.position-right  { transform: scale(1) translateZ(10px); }

        /* Modo clásico: sprites inactivos desaparecen */
        .vn-section.classic-mode .vn-sprite.inactive {
            opacity: 0;
        }
        .vn-section.classic-mode .vn-sprite.inactive.position-center {
            transform: translateX(-50%) scale(0.88) translateZ(0px);
        }

        /* CAJA DE DIÁLOGO PREMIUM */
        .vn-dialogue-box {
            position: fixed;
            left: 50%;
            transform: translateX(-50%);
            bottom: 2rem;
            width: min(900px, 85%);

            background: rgba(18, 12, 8, 0.78);
            border-radius: 14px;
            /* El borde usa el color del personaje activo vía JS → --char-color */
            border: 1px solid rgba(160,128,220,0.35);
            border-top: 1px solid rgba(255,255,255,0.06);
            padding: 2.8rem 2rem 1.2rem 9rem; /* top extra space for nameplate */

            box-shadow:
                0 18px 40px rgba(0,0,0,0.55),
                0 2px 0 rgba(0,0,0,0.35),
                inset 0 1px 0 rgba(255,255,255,0.05);

            backdrop-filter: blur(6px);
            -webkit-backdrop-filter: blur(6px);
            z-index: var(--z-i-150);
            cursor: pointer;
            /* Transición suave del color del personaje */
            transition: border-color 0.6s ease,
                        box-shadow 0.6s ease,
                        transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
        }

        /* Línea interior sutil */
        .vn-dialogue-box::before {
            content: '';
            position: absolute;
            inset: 8px;
            border-radius: 14px;
            border: 1px solid rgba(248, 223, 183, 0.1);
            pointer-events: none;
        }

        /* Decoraciones de esquina ornamentales usando ::after */
        .vn-dialogue-box::after {
            content: '❧';
            position: absolute;
            bottom: 0.9rem;
            right: 1.1rem;
            color: rgba(160,128,220, 0.3);
            font-size: 1.1rem;
            font-family: serif;
            transform: rotate(135deg);
            pointer-events: none;
            line-height: 1;
        }

        /* Elevación suave al hover */
        .vn-dialogue-box:hover {
            transform: translateX(-50%) translateY(-3px);
            box-shadow:
                0 32px 80px rgba(0, 0, 0, 0.70),
                0 0 28px rgba(160,128,220, 0.14),
                inset 0 1px 0 rgba(255, 255, 255, 0.08);
        }

        /* En móvil no hay translateX, solo el box-shadow */
        @media (max-width: 768px) {
            .vn-dialogue-box:hover {
                transform: none;
            }
        }

        .vn-dialogue-box.fade-in {
            animation: vn-message-fade-in 0.45s ease;
        }

        @keyframes vn-message-fade-in {
            from { opacity: 0; }
            to   { opacity: 1; }
        }

        .vn-speaker-avatar {
            position: absolute;
            left: 1.5rem;
            top: 50%;
            transform: translateY(-50%);
            width: 98px;
            height: 98px;
            border-radius: 50%;
            /* El borde usa el color del personaje activo */
            border: 2.5px solid var(--char-color-full, rgba(160,128,220, 0.75));
            background: var(--bg-tertiary);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 2.4rem;
            overflow: hidden;
            box-shadow:
                0 10px 32px rgba(0,0,0,0.45),
                0 0 14px -2px var(--char-color, rgba(160,128,220,0.3)),
                inset 0 2px 4px rgba(255, 255, 255, 0.1);
            z-index: var(--z-i-10);
            isolation: isolate;
            transition: border-color 0.6s ease, box-shadow 0.6s ease;
        }
        /* El ::before (runa ornamental) se pone encima con un wrapper externo */
        .vn-speaker-avatar-wrap {
            position: absolute;
            left: 1.5rem;
            top: 50%;
            transform: translateY(-50%);
            width: 98px;
            height: 98px;
            pointer-events: none;
            z-index: var(--z-i-11);
        }
        .vn-speaker-avatar-wrap::before {
            content: '';
            position: absolute;
            inset: -10px;
            border-radius: 50%;
            border: 2px solid rgba(191, 159, 113, 0.72);
            background:
                conic-gradient(from 0deg, transparent 0deg 24deg, rgba(160,128,220,0.42) 24deg 34deg, transparent 34deg 60deg, rgba(160,128,220,0.36) 60deg 70deg, transparent 70deg 360deg);
            -webkit-mask: radial-gradient(circle, transparent 62%, #000 63%);
            mask: radial-gradient(circle, transparent 62%, #000 63%);
        }
        /* La imagen dentro del avatar ocupa todo el círculo */
        .vn-speaker-avatar img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: center top;
            border-radius: 0; /* el padre ya es redondo */
            display: block;
        }
        /* Pulso suave al hablar */
        .vn-speaker-avatar.is-speaking {
            box-shadow:
                0 10px 32px rgba(0,0,0,0.45),
                0 0 22px rgba(160,128,220, 0.28),
                inset 0 2px 4px rgba(255, 255, 255, 0.1);
            animation: avatar-speaking-pulse 2.2s ease-in-out infinite;
        }
        /* La runa está en .vn-speaker-avatar-wrap::before */
        .vn-speaker-avatar.is-speaking ~ .vn-speaker-avatar-wrap::before {
            animation: avatar-rune-pulse 1.6s ease-in-out infinite;
        }
        @keyframes avatar-speaking-pulse {
            0%, 100% { transform: translateY(-50%) scale(1); }
            50%       { transform: translateY(-50%) scale(1.025); }
        }
        .vn-speaker-plate {
            position: absolute;
            top: -1px;
            bottom: auto;
            left: 8.5rem;
            display: inline-block;
            padding: 0.28rem 1.1rem 0.28rem 0.85rem;
            border-radius: 0 0 12px 0;
            font-family: 'Cinzel', serif;
            font-size: 0.82rem;
            letter-spacing: 0.07em;
            color: rgba(255,255,255,0.92);
            border: 1px solid rgba(160,128,220, 0.45);
            border-top: none;
            border-left: none;
            background: linear-gradient(135deg, rgba(60, 40, 18, 0.97), rgba(80, 52, 22, 0.97));
            box-shadow: 2px 3px 12px rgba(0,0,0,0.35);
            z-index: var(--z-i-10);
            text-shadow: 0 1px 3px rgba(0,0,0,0.7);
            text-transform: uppercase;
            max-width: 280px;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .vn-oracle-consequence-badge {
            position: absolute;
            bottom: 3.8rem;
            left: 8.4rem;
            right: 1.5rem;
            font-family: 'Crimson Text', 'EB Garamond', serif;
            font-style: italic;
            font-size: 0.82rem;
            line-height: 1.55;
            color: rgba(220, 185, 110, 0.88);
            border-top: 1px solid rgba(180, 130, 40, 0.25);
            border-bottom: 1px solid rgba(180, 130, 40, 0.15);
            background: linear-gradient(90deg, rgba(60, 35, 5, 0.45), rgba(40, 22, 3, 0.3));
            padding: 0.35rem 0.7rem;
            letter-spacing: 0.01em;
            backdrop-filter: blur(3px);
            z-index: var(--z-i-9);
            /* Separación visual del texto principal */
            margin-top: 0.2rem;
        }
        /* Símbolo decorativo antes del texto */
        .vn-oracle-consequence-badge::before {
            content: '∿ ';
            color: rgba(180, 130, 40, 0.6);
            font-style: normal;
            font-size: 0.75rem;
        }
        .vn-dialogue-text {
            font-family: 'EB Garamond', 'Crimson Text', serif;
            font-size: calc(var(--font-size-base) + 0.05rem);
            line-height: 1.84;
            letter-spacing: 0.2px;
            color: #f5e6ca;
            text-shadow: 1px 1px 3px rgba(0,0,0,0.86);
            min-height: 4rem;
            margin-top: 0.5rem;
            padding-left: 0.5rem;
        }
        .vn-dialogue-text strong, .vn-dialogue-text b {
            color: var(--accent-gold);
            font-weight: 700;
        }
        .vn-dialogue-text em, .vn-dialogue-text i {
            color: var(--text-secondary);
            font-style: italic;
        }
        .vn-oracle-result {
            margin-top: 0.95rem;
            padding-top: 0.75rem;
            border-top: 1px solid rgba(160,128,220, 0.2);
            font-size: 0.95rem;
        }
        .vn-oracle-rule {
            display: block;
            color: rgba(160,128,220, 0.68);
            letter-spacing: 0.12em;
            margin-bottom: 0.35rem;
        }
        .vn-oracle-question {
            color: rgba(229, 219, 194, 0.92);
            margin-bottom: 0.25rem;
        }
        .vn-oracle-outcome {
            font-weight: 700;
            letter-spacing: 0.03em;
        }
        .vn-oracle-outcome.result-cara { color: #e9cc7b; }
        .vn-oracle-outcome.result-cruz { color: #bd7667; }

        /* El indicador de continuar ahora se renderiza al final del texto,
           alineado de forma inline, no con position absolute */
        .vn-continue-indicator {
            display: inline-block;
            width: 0;
            height: 0;
            border-left: 6px solid transparent;
            border-right: 6px solid transparent;
            border-top: 9px solid rgba(160,128,220, 0.88);
            opacity: 0;
            margin-left: 0.5rem;
            vertical-align: middle;
            filter: drop-shadow(0 0 5px rgba(160,128,220, 0.6));
            animation: continue-bounce 1.6s ease-in-out infinite;
            position: static;
        }

        @keyframes continue-bounce {
            0%, 100% { transform: translateY(0);   opacity: 0.55; }
            50%       { transform: translateY(5px); opacity: 1; }
        }


        .vn-message-counter {
            position: absolute;
            right: 2rem;
            top: 1rem;
            color: rgba(255,255,255,0.6);
            font-family: 'Inter', sans-serif;
            font-size: 0.85rem;
            background: rgba(0,0,0,0.3);
            padding: 0.3rem 0.8rem;
            border-radius: 12px;
        }

        /* ── FOOTER DE LA CAJA DE DIÁLOGO ── */
        .vn-dialogue-footer {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-top: 1rem;
            padding-top: 0.6rem;
            border-top: 1px solid rgba(160,128,220, 0.12);
        }

        .vn-message-counter {
            color: rgba(160,128,220, 0.45);
            font-family: 'Inter', sans-serif;
            font-size: 0.75rem;
            letter-spacing: 0.05em;
            font-variant-numeric: tabular-nums;
            user-select: none;
        }

        .vn-dialogue-actions {
            display: flex;
            align-items: center;
            gap: 0.3rem;
            opacity: 0.35;
            transition: opacity 0.25s ease;
        }

        /* Mostrar botones con más peso al hover de la caja */
        .vn-dialogue-box:hover .vn-dialogue-actions {
            opacity: 1;
        }

        .vn-dialogue-action-btn {
            display: inline-flex;
            align-items: center;
            gap: 0.35rem;
            padding: 0.3rem 0.75rem;
            border-radius: 6px;
            border: 1px solid rgba(160,128,220, 0.25);
            background: transparent;
            color: rgba(160,128,220, 0.7);
            font-family: 'Inter', sans-serif;
            font-size: 0.75rem;
            cursor: pointer;
            transition: all 0.18s ease;
            white-space: nowrap;
        }

        .action-icon {
            font-size: 0.85rem;
            line-height: 1;
        }

        .action-label {
            letter-spacing: 0.02em;
        }

        /* Responder — el más prominente */
        .vn-dialogue-action-btn.reply-btn {
            background: rgba(160,128,220, 0.1);
            border-color: rgba(160,128,220, 0.45);
            color: rgba(160,128,220, 0.9);
            font-weight: 500;
        }

        .vn-dialogue-action-btn.reply-btn:hover {
            background: rgba(160,128,220, 0.2);
            border-color: rgba(160,128,220, 0.8);
            color: #f0d99a;
            box-shadow: 0 0 12px rgba(160,128,220, 0.2);
        }

        /* Editar — neutro */
        .vn-dialogue-action-btn:not(.reply-btn):not(.delete-message-btn):hover {
            background: rgba(255,255,255,0.06);
            border-color: rgba(160,128,220, 0.4);
            color: rgba(160,128,220, 0.9);
        }

        /* Borrar — sin label, solo icono, color rojo apagado */
        .vn-dialogue-action-btn.delete-message-btn {
            border-color: rgba(180, 80, 80, 0.2);
            color: rgba(200, 100, 100, 0.5);
            padding: 0.3rem 0.5rem;
        }

        .vn-dialogue-action-btn.delete-message-btn:hover {
            background: rgba(120, 30, 30, 0.35);
            border-color: rgba(255, 100, 100, 0.45);
            color: rgba(255, 140, 140, 0.9);
        }

        /* En móvil ocultar labels para ahorrar espacio */
        @media (max-width: 600px) {
            .action-label { display: none; }
            .vn-dialogue-action-btn { padding: 0.3rem 0.5rem; }
        }
        .message-has-options {
            position: absolute;
            top: -12px;
            right: 30px;
            background: linear-gradient(135deg, var(--accent-gold), var(--accent-warm));
            color: var(--bg-primary);
            padding: 0.4rem 1rem;
            border-radius: 15px;
            font-size: 0.8rem;
            font-weight: bold;
            font-family: 'Inter', sans-serif;
            box-shadow: 0 4px 15px rgba(160,128,220, 0.4);
            animation: pulse 2s infinite;
        }

        /* OPCIONES FLOTANTES */
        .vn-options-container {
            position: fixed;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            display: none;
            flex-direction: column;
            gap: 0.75rem;
            width: min(560px, 82%);
            z-index: var(--z-i-160);
            pointer-events: none;
        }
        .vn-options-container.active {
            display: flex;
            pointer-events: all;
            animation: fadeIn 0.4s ease;
        }
        .vn-options-title {
            text-align: center;
            font-family: 'Cinzel', serif;
            font-size: 1rem;
            color: var(--accent-gold);
            text-shadow: 0 1px 3px rgba(0,0,0,0.65);
            letter-spacing: 0.03em;
        }
        .vn-options-subtitle {
            text-align: center;
            font-size: 0.88rem;
            color: rgba(255, 241, 214, 0.9);
            margin-top: -0.35rem;
            margin-bottom: 0.25rem;
            text-shadow: 0 1px 2px rgba(0,0,0,0.6);
        }

        /* Móvil */
        @media (max-width: 768px) {
            .vn-options-container {
                width: calc(100vw - 2rem);
            }
        }

        .vn-option-btn {
            background: rgba(30, 22, 15, 0.88);
            border: 1.5px solid rgba(160,128,220, 0.55);
            color: #f0dfc0;
            padding: 1rem 1.5rem;
            border-radius: 50px;
            cursor: pointer;
            font-family: 'Crimson Text', serif;
            font-size: 1.1rem;
            text-align: center;
            transition: all 0.3s ease;
            box-shadow: 0 4px 18px rgba(0,0,0,0.5);
            position: relative;
            overflow: hidden;
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            text-shadow: 0 1px 3px rgba(0,0,0,0.8);
        }

        .vn-option-btn::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(160,128,220, 0.18), transparent);
            transition: left 0.5s;
        }

        .vn-option-btn:hover {
            transform: translateX(8px) scale(1.02);
            background: rgba(50, 36, 22, 0.95);
            border-color: rgba(160,128,220, 0.9);
            box-shadow: 0 6px 28px rgba(0,0,0,0.6), 0 0 14px rgba(160,128,220, 0.2);
            color: #faebd0;
        }

        .vn-option-btn:hover::before {
            left: 100%;
        }

        .vn-option-btn.chosen {
            background: rgba(107, 142, 125, 0.75);
            border-color: var(--accent-sage);
            color: #e8f5f0;
            opacity: 0.82;
        }

        .vn-option-btn:disabled {
            cursor: not-allowed;
            opacity: 0.5;
        }

        .vn-continuation-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0,0,0,0.85);
            display: none;
            justify-content: center;
            align-items: center;
            z-index: var(--z-i-500);
            backdrop-filter: blur(5px);
        }
        .vn-continuation-overlay.active { display: flex; }
        .vn-continuation-box {
            background: var(--glass-bg);
            border: 3px double var(--accent-gold);
            border-radius: 24px;
            padding: 2.5rem;
            max-width: 700px;
            width: 90%;
            max-height: 60vh;
            overflow-y: auto;
            position: relative;
            backdrop-filter: blur(20px);
            box-shadow: 0 40px 80px rgba(0,0,0,0.5);
        }
        .vn-continuation-title {
            font-family: 'Cinzel', serif;
            font-size: 1.5rem;
            color: var(--accent-gold);
            text-align: center;
            margin-bottom: 1.5rem;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
        }
        .vn-continuation-text {
            font-size: 1.2rem;
            line-height: 2;
            font-style: italic;
            text-align: center;
        }
        .vn-continuation-close {
