            z-index: var(--z-i-2);
            transition: border-color 180ms ease, background-color 180ms ease, box-shadow 180ms ease;
        }

        .reply-emote-toggle::after {
            content: 'Emotes';
            position: absolute;
            top: -100%;
            left: 50%;
            transform: translateX(-50%);
            opacity: 0;
            padding: 0.25rem 0.45rem;
            border-radius: 8px;
            border: 1px solid rgba(160,128,220, 0.6);
            background: rgba(10, 10, 10, 0.82);
            color: #fff;
            font-size: 0.7rem;
            pointer-events: none;
            transition: opacity 180ms ease, transform 180ms ease;
            transition-delay: 0s;
            white-space: nowrap;
            z-index: var(--z-i-30);
