        }
        .options-card:hover { border-color: rgba(160,128,220,0.4); }
        .options-card-icon { font-size: 2rem; margin-bottom: 0.5rem; }
        .options-card-title {
            font-family: 'Cinzel', serif;
            color: var(--accent-wood);
            font-size: 1.1rem;
            margin-bottom: 1.2rem;
            padding-bottom: 0.6rem;
            border-bottom: 1px solid var(--border-light);
