        .opt-switch-slider {
            position: absolute; inset: 0;
            background: var(--border-color);
            border-radius: 24px;
            cursor: pointer;
            transition: 0.3s;
        }
        .opt-switch-slider::before {
            content: '';
            position: absolute;
            width: 18px; height: 18px;
            left: 3px; top: 3px;
            background: white;
            border-radius: 50%;
            transition: 0.3s;
        }
        .opt-switch input:checked + .opt-switch-slider { background: var(--accent-gold); }
        .opt-switch input:checked + .opt-switch-slider::before { transform: translateX(20px); }
        .opt-text-input {
            background: var(--input-bg);
