            box-shadow: 0 40px 80px rgba(0,0,0,0.5);
            display: flex;
            flex-direction: column;
            backdrop-filter: blur(20px);
        }

        .branch-editor-header {
            background: linear-gradient(135deg, rgba(139, 115, 85, 0.3), rgba(107, 142, 125, 0.3));
            padding: 1.5rem;
            border-bottom: 3px double var(--border-color);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .branch-editor-title {
            font-family: 'Cinzel', serif;
            color: var(--accent-gold);
            font-size: 1.4rem;
        }

        .branch-editor-content {
            flex: 1;
            overflow-y: auto;
            padding: 2rem;
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
        }

        .branch-list {
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .branch-item {
            background: rgba(255,255,255,0.05);
            border: 2px solid var(--border-color);
            border-radius: 12px;
            padding: 1rem;
            display: flex;
            flex-direction: column;
            gap: 0.8rem;
