        }

        .branch-textarea {
            width: 100%;
            min-height: 80px;
            padding: 0.8rem;
            border-radius: 8px;
            border: 1px solid var(--border-color);
            background: rgba(0,0,0,0.2);
            color: white;
            font-family: inherit;
            resize: vertical;
        }

        .add-branch-btn {
            background: rgba(139, 115, 85, 0.3);
            border: 2px dashed var(--accent-gold);
            color: var(--accent-gold);
            padding: 1rem;
            border-radius: 12px;
            cursor: pointer;
            text-align: center;
            font-family: 'Cinzel', serif;
            transition: all 0.3s;
        }

        .add-branch-btn:hover {
            background: rgba(160,128,220, 0.2);
