        .weather-btn:hover, .weather-btn.active {
            border-color: var(--accent-gold);
            color: var(--accent-gold);
            background: rgba(160,128,220, 0.1);
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
