}
.cip-rel-header {
    font-family: 'Cinzel', serif;
    font-size: 0.6rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(200,168,108,0.45);
    margin-bottom: 0.5rem;
    padding-top: 0.4rem;
    border-top: 1px solid rgba(160,128,220,0.12);
}
.cip-rel-row {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    margin-bottom: 0.45rem;
}
.cip-rel-avatar {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    border: 1.5px solid;
    overflow: hidden;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    color: rgba(200,168,108,0.8);
    background: rgba(0,0,0,0.3);
}
.cip-rel-avatar img { width: 100%; height: 100%; object-fit: cover; }
.cip-rel-info { flex: 1; min-width: 0; }
.cip-rel-name {
    font-family: 'Cinzel', serif;
    font-size: 0.65rem;
    color: rgba(200,185,160,0.8);
    letter-spacing: 0.04em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.cip-rel-rank {
    font-size: 0.6rem;
    font-family: 'Inter', sans-serif;
    margin: 0.1rem 0;
    opacity: 0.85;
}
.cip-rel-bar {
    height: 3px;
    border-radius: 3px;
    background: rgba(255,255,255,0.07);
