/* Barras de progreso */
body.mode-classic .sheet-rpg-progress-fill.hp  { background: rgba(160, 80, 32, 0.85); }
body.mode-classic .sheet-rpg-progress-fill.exp { background: rgba(139, 105, 20, 0.85); }


/* ══════════════════════════════════════════
   OPTIMIZACIONES RESPONSIVE — PATCH 21+
   Mejoras de layout para desktop y móvil
   ══════════════════════════════════════════ */

/* content-visibility eliminado — causaba conflictos con modales en Firefox/Safari */

/* ── Tipografía base más grande en pantallas grandes ── */
@media (min-width: 1700px) {
    :root { --font-size-base: 1.3rem; }
    .vn-dialogue-text { font-size: 1.15em; line-height: 1.8; }
}

/* ── Topics: sidebar oculto en pantalla media, visible en escritorio ── */
@media (max-width: 900px) {
    .topics-sidebar { display: none; }
    .topics-layout { gap: 0; }
}

/* ── Sección de opciones: grid adaptable ── */
@media (max-width: 600px) {
    .options-grid {
        grid-template-columns: 1fr;
    }
}

/* ── Gallery header en móvil ── */
@media (max-width: 600px) {
    .gallery-toolbar {
        flex-direction: column;
        gap: 0.5rem;
    }
    .gallery-toolbar .search-input,
    .gallery-toolbar .sort-select {
        width: 100%;
    }
    #gallerySection .section-header-bar {
        flex-wrap: wrap;
        gap: 0.5rem;
    }
    #gallerySection .section-header-bar > div {
        flex-wrap: wrap;
        gap: 0.5rem;
    }
}

/* ── Botones de acción VN: labels ocultos en pantalla muy pequeña ── */
@media (max-width: 380px) {
    .vn-dialogue-action-btn .action-label {
        display: none;
    }
    .vn-dialogue-action-btn {
        padding: 0.45rem 0.6rem;
    }
}

/* ── Info-card: en pantallas pequeñas evitar overflow del lado izquierdo ── */
@media (max-width: 480px) {
    .vn-info-card {
        top: 8px;
        left: 8px;
        padding: 0.6rem 0.7rem;
        max-width: calc(60vw);
        min-width: 0;
    }
    .vn-info-name { font-size: 0.82rem; }
    .vn-info-avatar { width: 32px; height: 32px; font-size: 1rem; }
    .affinity-rank-name { font-size: 0.7rem; }
    .affinity-controls-inline { gap: 0.1rem; }
    .affinity-btn-inline { width: 20px; height: 20px; font-size: 0.7rem; }
}

/* ── Controls VN: en pantalla muy pequeña, tamaño mínimo ── */
@media (max-width: 380px) {
    .vn-controls {
        gap: 0.15rem;
        padding: 0.2rem;
    }
    .vn-control-btn {
        width: 30px;
        height: 30px;
        font-size: 0.75rem;
    }
    .vn-control-divider {
        height: 20px;
    }
}

/* ── Modal de personaje: pantalla completa en móvil ── */
@media (max-width: 600px) {
    .character-modal {
        width: 100vw;
        max-width: 100vw;
        height: 100dvh;
        max-height: 100dvh;
        border-radius: 0;
        margin: 0;
    }
    .editor-container {
        flex-direction: column;
    }
    .editor-preview {
        padding: 1rem;
    }
}

/* ── RPG Stats modal: full-width en móvil ── */
@media (max-width: 600px) {
    .rpg-stats-modal {
        width: 100vw;
        max-width: 100vw;
        max-height: 90dvh;
    }
}

/* ── History modal: full-width en móvil ── */
@media (max-width: 600px) {
    .history-modal {
        width: 100vw;
        max-width: 100vw;
        border-radius: 16px 16px 0 0;
        position: fixed;
        bottom: 0;
        left: 0;
        margin: 0;
    }
}

/* ── Mejora: transición de opacity en vez de display para .active ── */
/* Usar visibility para no romper accessibility tree */
.game-section {
    /* ya definido arriba como display:none */
}

/* ── VN dialogue-box: altura mínima en móvil para evitar texto cortado ── */
@media (max-width: 768px) {
    .vn-dialogue-box {
        min-height: 140px;
    }
    .vn-dialogue-text {
        max-height: 45vh;
        overflow-y: auto;
    }
}

/* ── Onboarding overlay: centrado en móvil ── */
@media (max-width: 480px) {
    .onboarding-box {
        width: calc(100vw - 2rem);
        margin: 0 1rem;
    }
}

/* ── Shortcuts modal: scroll en móvil ── */
@media (max-width: 480px) {
    .shortcuts-modal {
        max-height: 85dvh;
        overflow-y: auto;
    }
}

/* ── Emote picker: scroll horizontal si overflow ── */
@media (max-width: 380px) {
    .emote-picker {
        overflow-x: auto;
        flex-wrap: nowrap;
        max-width: calc(100vw - 2rem);
    }
}

/* ── Topic card: layout en columna en pantallas muy pequeñas ── */
@media (max-width: 380px) {
    .topics-command-bar {
        flex-direction: column;
        align-items: stretch;
    }
    .btn-create-topic {
        justify-content: center;
    }
    .topics-search-wrap {
        width: 100%;
    }
    .topics-filter-group {
        justify-content: flex-start;
    }
}

/* ── Selector de usuario: grid adaptable ── */
@media (max-width: 480px) {
    .user-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 0.75rem;
        padding: 0 0.5rem;
    }
}

/* ── Dialogue footer en pantalla muy pequeña ── */
@media (max-width: 380px) {
    .vn-dialogue-footer {
        flex-direction: column;
        gap: 0.4rem;
        align-items: flex-start;
    }
    .vn-dialogue-actions {
        gap: 0.2rem;
    }
}

/* ── Prevent horizontal overflow en toda la app ── */
html, body {
    max-width: 100vw;
    overflow-x: hidden;
}

/* ── Mejora de tap target: botones mínimo 44px en dispositivos táctiles ── */
@media (pointer: coarse) {
    .vn-control-btn {
        min-width: 36px;
        min-height: 36px;
    }
    .filter-btn,
    .topic-filter-btn {
        min-height: 36px;
        padding: 0.5rem 0.9rem;
    }
    .emote-btn {
        min-width: 36px;
        min-height: 36px;
    }
    .btn-primary,
    .btn-secondary {
        min-height: 44px;
    }
}

/* ══ FIN OPTIMIZACIONES RESPONSIVE ══ */

