/* ═══════════════════════════════════════════════════════════════════
   IHP v2 — SISTEMA DE ESTADOS: hidden | peek | pinned
   ═══════════════════════════════════════════════════════════════════ */

/* ── Avatar clickeable (cursor pointer para indicar pin) ── */
.vn-info-avatar {
    cursor: pointer;
    position: relative;
}
.vn-info-avatar::after {
    content: '📌';
    position: absolute;
    bottom: -4px;
    right: -4px;
    font-size: 0.6rem;
    opacity: 0;
    transition: opacity 0.2s;
    pointer-events: none;
}
.vn-info-card.ihp-pinned .vn-info-avatar::after {
    opacity: 1;
}

/* ── Botón cerrar (solo en pinned) ── */
.ihp-close-btn {
    position: absolute;
    top: 6px;
    right: 8px;
    background: none;
    border: none;
    color: rgba(200, 175, 130, 0.5);
    font-size: 0.72rem;
    cursor: pointer;
    padding: 0.15rem 0.3rem;
    border-radius: 4px;
    z-index: var(--z-i-5);
    transition: color 0.15s, background 0.15s;
    display: none;
}
.ihp-close-btn:hover {
    color: rgba(200, 175, 130, 0.9);
    background: rgba(255, 255, 255, 0.06);
}
.vn-info-hover-details[data-state="pinned"] .ihp-close-btn {
    display: block;
}

/* ── Indicador pin ── */
.ihp-pin-indicator {
    position: absolute;
    top: 6px;
    left: 8px;
    font-size: 0.6rem;
    opacity: 0;
    transition: opacity 0.2s;
    pointer-events: none;
    z-index: var(--z-i-5);
}
.vn-info-hover-details[data-state="pinned"] .ihp-pin-indicator {
    opacity: 0.6;
}

/* ── IHP: estado PEEK (hover existente, igual que antes) ── */
.vn-info-card:hover .vn-info-hover-details[data-state="hidden"],
.vn-info-card:focus-within .vn-info-hover-details[data-state="hidden"] {
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0) scaleY(1);
}

/* ── IHP: estado PINNED — fijo, pointer-events, sin hover needed ── */
.vn-info-hover-details[data-state="pinned"] {
    opacity: 1 !important;
    pointer-events: auto !important;
    transform: translateY(0) scaleY(1) !important;
    animation: none !important;
    /* Borde más prominente para indicar que está fijado */
    box-shadow:
        0 20px 50px rgba(0,0,0,0.75),
        0 0 0 2px rgba(160,128,220, 0.4),
        inset 0 1px 0 rgba(255,255,255,0.06) !important;
}

/* ── HP bar permanente en info-card (RPG) ── */
.vn-info-hp-wrap {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    margin-top: 0.35rem;
}
.vn-info-hp-label {
    font-family: 'Cinzel', serif;
    font-size: 0.56rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: rgba(160, 80, 32, 0.8);
    flex-shrink: 0;
}
.vn-info-hp-bar {
    flex: 1;
    height: 5px;
    background: rgba(255, 255, 255, 0.08);
    border-radius: 3px;
    overflow: hidden;
    border: 1px solid rgba(140, 70, 20, 0.25);
}
.vn-info-hp-fill {
    height: 100%;
    background: linear-gradient(90deg, #6b3a10, #c05820, #e07030);
    border-radius: 3px;
    transition: width 0.5s cubic-bezier(0.34, 1.2, 0.64, 1);
    position: relative;
}
/* Brillo de cristal sobre la barra */
.vn-info-hp-fill::after {
    content: '';
    position: absolute;
    inset: 0 0 50% 0;
    background: rgba(255, 200, 100, 0.15);
    border-radius: 3px 3px 0 0;
}
.vn-info-hp-val {
    font-family: 'Cinzel', serif;
    font-size: 0.6rem;
    color: rgba(200, 160, 100, 0.75);
    flex-shrink: 0;
    min-width: 28px;
    text-align: right;
}
.vn-info-rpg.hidden { display: none !important; }

/* ── IHP: barras HP/EXP dentro del panel ── */
.ihp-rpg-bars {
    padding: 0.35rem 0.9rem 0.1rem;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
    border-top: 1px solid rgba(255,255,255,0.06);
    position: relative;
    z-index: var(--z-i-1);
}
.ihp-rpg-bars:empty { display: none; }
.ihp-bar-row {
    display: flex;
    align-items: center;
    gap: 0.4rem;
}
.ihp-bar-lbl {
    font-family: 'Cinzel', serif;
    font-size: 0.56rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    min-width: 22px;
    flex-shrink: 0;
}
.ihp-bar-track {
    flex: 1;
    height: 6px;
    background: rgba(0,0,0,0.35);
    border-radius: 4px;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.06);
}
.ihp-bar-fill {
    height: 100%;
    border-radius: 4px;
    transition: width 0.5s cubic-bezier(0.34, 1.2, 0.64, 1);
}
.ihp-bar-fill.hp  { background: linear-gradient(90deg, #6b3a10, #c05820, #e07030); }
.ihp-bar-fill.exp { background: linear-gradient(90deg, #5a4a10, #a08020, #c0a030); }
.ihp-bar-val {
    font-family: 'Cinzel', serif;
    font-size: 0.6rem;
    min-width: 28px;
    text-align: right;
    flex-shrink: 0;
}

/* ── IHP: sección relaciones (Clásico pinned) ── */
.ihp-relations {
    padding: 0.35rem 0.9rem 0.5rem;
    border-top: 1px solid rgba(255,255,255,0.06);
    position: relative;
    z-index: var(--z-i-1);
}
.ihp-relations:empty { display: none; }
.ihp-relations-title {
    font-family: 'Cinzel', serif;
    font-size: 0.58rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    opacity: 0.5;
    margin-bottom: 0.3rem;
    display: block;
}
.ihp-rel-row {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.18rem 0;
    font-size: 0.75rem;
}
.ihp-rel-name {
    flex: 1;
    opacity: 0.85;
    font-family: 'Inter', sans-serif;
}
.ihp-rel-stars {
    font-size: 0.65rem;
    letter-spacing: 0.05em;
    opacity: 0.7;
}
.ihp-rel-rank {
    font-size: 0.65rem;
    opacity: 0.55;
    font-style: italic;
    font-family: 'Crimson Text', serif;
    max-width: 70px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

/* ── IHP: botón oráculo (RPG pinned) ── */
.ihp-oracle-hint {
    padding: 0.3rem 0.9rem 0.5rem;
    border-top: 1px solid rgba(255,255,255,0.06);
    position: relative;
    z-index: var(--z-i-1);
}
.ihp-oracle-btn {
    width: 100%;
    background: rgba(160, 80, 32, 0.12);
    border: 1px solid rgba(160, 80, 32, 0.3);
    border-radius: 8px;
    color: rgba(220, 160, 80, 0.9);
    font-family: 'Cinzel', serif;
    font-size: 0.7rem;
    letter-spacing: 0.05em;
    padding: 0.35rem 0.6rem;
    cursor: pointer;
