}
.ihp-oracle-btn:hover {
    background: rgba(160, 80, 32, 0.22);
    border-color: rgba(160, 80, 32, 0.55);
}

/* ── Secciones que solo aparecen en pinned ── */
.ihp-pinned-only {
    display: none;
}
.vn-info-hover-details[data-state="pinned"] .ihp-pinned-only {
    display: block;
}

/* ── Grafo: controles de afinidad ── */
.graph-affinity-controls {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.5rem 0.8rem;
    background: rgba(160,128,220, 0.06);
    border: 1px solid rgba(160,128,220, 0.15);
    border-radius: 10px;
    margin: 0.5rem 0;
    flex-wrap: wrap;
}
.graph-affinity-controls.hidden { display: none; }
.graph-affinity-label {
    font-size: 0.8rem;
    color: rgba(200, 180, 140, 0.75);
    font-family: 'Inter', sans-serif;
}
.graph-affinity-rank {
    font-family: 'Cinzel', serif;
    font-size: 0.78rem;
    color: var(--accent-gold);
    flex: 1;
}
.graph-affinity-btn {
    width: 28px;
    height: 28px;
    border-radius: 8px;
    border: 1px solid rgba(160,128,220, 0.3);
    background: rgba(160,128,220, 0.08);
    color: var(--accent-gold);
    font-size: 1rem;
    font-weight: 700;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
    display: flex;
    align-items: center;
    justify-content: center;
}
.graph-affinity-btn:hover {
    background: rgba(160,128,220, 0.2);
    border-color: rgba(160,128,220, 0.5);
}

/* ── Estilos por modo para las nuevas secciones del IHP ── */
body.mode-rpg .ihp-bar-lbl.hp  { color: rgba(200, 80, 30, 0.8); }
body.mode-rpg .ihp-bar-lbl.exp { color: rgba(180, 150, 30, 0.75); }
body.mode-rpg .ihp-bar-val     { color: rgba(200, 175, 130, 0.7); }
body.mode-rpg .ihp-oracle-hint { border-top-color: rgba(160, 120, 50, 0.2); }

body.mode-classic .ihp-relations-title { color: rgba(190, 148, 70, 0.55); }
body.mode-classic .ihp-rel-name  { color: rgba(230, 205, 160, 0.88); }
body.mode-classic .ihp-rel-stars { color: rgba(190, 148, 70, 0.7); }
body.mode-classic .ihp-relations { border-top-color: rgba(190, 148, 70, 0.12); }

/* En modo clásico, IHP peek NO muestra stats/relaciones */
body.mode-classic .vn-info-hover-details[data-state="hidden"] .ihp-stats,
body.mode-classic .vn-info-hover-details[data-state="hidden"] .ihp-relations,
body.mode-classic .vn-info-hover-details[data-state="hidden"] .ihp-rpg-bars {
    display: none;
}
/* En modo clásico, IHP pinned muestra descripción y relaciones */
body.mode-classic .vn-info-hover-details[data-state="pinned"] .ihp-desc { display: block; }
body.mode-classic .vn-info-hover-details[data-state="pinned"] .ihp-relations { display: block; }

/* En modo RPG, IHP peek muestra stats; pinned muestra todo + oráculo */
body.mode-rpg .vn-info-hover-details[data-state="hidden"] .ihp-oracle-hint { display: none; }
body.mode-rpg .vn-info-hover-details[data-state="pinned"] .ihp-oracle-hint { display: block; }


/* ═══════════════════════════════════════════════════════════════════
   SPRITE SOMBRA — silueta cuando no hay imagen definida
   Tres variantes: shadow-masc / shadow-fem / neutral (sin clase)
   ═══════════════════════════════════════════════════════════════════ */

/* ── Contenedor ─────────────────────────────────────────────────── */
.sprite-shadow {
    width: 100%;
    height: 95%;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    position: relative;
    pointer-events: none;
    mask-image: linear-gradient(to bottom, black 75%, transparent 100%);
    -webkit-mask-image: linear-gradient(to bottom, black 75%, transparent 100%);
}

/* SVG inline de la silueta — ocupa todo el alto del contenedor */
.sprite-shadow svg {
    width: auto;
    height: 100%;
    max-width: 100%;
    display: block;
}

/* ── Wrapper de silueta SVG ──────────────────────────────────────── */
.shadow-silhouette {
    /* El color del SVG se hereda desde CSS via currentColor */
    color: rgba(18, 12, 6, 0.97);
    position: relative;
    flex-shrink: 0;
    height: 88%;
    display: flex;
    align-items: flex-end;

    filter: blur(1.5px);
    transform-origin: bottom center;
    transition: filter 0.6s ease, transform 0.6s ease, opacity 0.6s ease;
}

.shadow-silhouette.shadow-masc {
    /* Silueta masc es ligeramente más ancha */
    filter: blur(1px);
}

.shadow-silhouette.shadow-fem {
    filter: blur(1.8px);
}

/* ── Glow base ───────────────────────────────────────────────────── */
.shadow-glow {
    position: absolute;
    inset: -8% -15% -5%;
    background: radial-gradient(
        ellipse 80% 50% at 50% 95%,
        rgba(160,128,220, 0.13) 0%,
        transparent 70%
    );
    opacity: 0;
    transition: opacity 0.6s ease;
    pointer-events: none;
}

/* Tinte de glow según género (imperceptible conscientemente) */
.shadow-glow.shadow-masc {
    background: radial-gradient(
        ellipse 80% 50% at 50% 95%,
        rgba(160, 120, 80, 0.16) 0%,
        transparent 70%
    );
}
.shadow-glow.shadow-fem {
    background: radial-gradient(
        ellipse 80% 50% at 50% 95%,
        rgba(180, 140, 120, 0.16) 0%,
        transparent 70%
    );
}

/* ── Hitbox dentro de la sombra (accesibilidad / emotes) ─────────── */
.sprite-shadow .vn-sprite-hitbox {
    position: absolute;
    inset: 0;
    border: none;
    background: transparent;
    /* Sin mask para que cubra toda la zona */
    mask-image: none;
    -webkit-mask-image: none;
}

/* ── ACTIVO: glow encendido + respiración ────────────────────────── */
.vn-sprite.active .shadow-glow {
    opacity: 1;
}

.vn-sprite.active .shadow-silhouette {
    animation: shadow-breathe 4.8s ease-in-out infinite;
}

/* ── INACTIVO: más oscuro, más difuminado, retraído ─────────────── */
.vn-sprite.inactive .shadow-silhouette {
    filter: blur(5px);
    opacity: 0.45;
    transform: scaleX(0.94) scaleY(0.96);
}
.vn-sprite.inactive .shadow-glow { opacity: 0; }

/* ── Modo RPG: más definido, más amenazante ─────────────────────── */
body.mode-rpg .shadow-silhouette {
    color: rgba(10, 7, 4, 0.99);
    filter: blur(1px);
}
body.mode-rpg .shadow-silhouette.shadow-masc { filter: blur(0.6px); }
body.mode-rpg .shadow-silhouette.shadow-fem  { filter: blur(1.2px); }

body.mode-rpg .shadow-glow {
    background: radial-gradient(
        ellipse 80% 50% at 50% 95%,
        rgba(160, 100, 40, 0.22) 0%,
        transparent 70%
    );
}
body.mode-rpg .shadow-glow.shadow-masc {
    background: radial-gradient(
        ellipse 80% 50% at 50% 95%,
        rgba(140, 90, 30, 0.24) 0%,
        transparent 70%
    );
}
body.mode-rpg .shadow-glow.shadow-fem {
    background: radial-gradient(
        ellipse 80% 50% at 50% 95%,
        rgba(170, 110, 60, 0.22) 0%,
        transparent 70%
    );
}

/* ── Modo Clásico: más etéreo, melancólico ──────────────────────── */
body.mode-classic .shadow-silhouette {
    color: rgba(28, 20, 10, 0.92);
    filter: blur(2.5px);
}
body.mode-classic .shadow-silhouette.shadow-masc { filter: blur(2px); }
body.mode-classic .shadow-silhouette.shadow-fem  { filter: blur(3px); }

body.mode-classic .shadow-glow {
    background: radial-gradient(
        ellipse 80% 50% at 50% 95%,
        rgba(201, 164, 90, 0.10) 0%,
        transparent 70%
    );
}


