    font-size: 0.82rem;
    letter-spacing: 0.06em;
    font-weight: 500;
    transition: all 0.2s;
}
.ncw-go-btn:hover {
    border-color: rgba(160,128,220,0.9);
    background: linear-gradient(135deg, rgba(139,115,85,0.45), rgba(160,128,220,0.28));
    box-shadow: 0 0 16px rgba(160,128,220,0.2);
}

/* ══════════════════════════════════════════════════════════════
   MODAL STATS RPG — barra de confirmación bloqueante
   ══════════════════════════════════════════════════════════════ */
.rpg-stats-confirm-bar {
    border-top: 1px solid rgba(160,128,220,0.15);
    padding: 1rem 1.25rem 0.75rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.75rem;
}
.rpg-stats-confirm-hint {
    font-size: 0.8rem;
    color: var(--text-muted);
    text-align: center;
    margin: 0;
    line-height: 1.5;
}
.rpg-stats-confirm-hint strong {
    color: var(--accent-gold);
    font-weight: 600;
}
.rpg-stats-confirm-btn {
    background: linear-gradient(135deg, rgba(139,115,85,0.35), rgba(160,128,220,0.2));
    color: var(--accent-gold);
    border: 1px solid rgba(160,128,220,0.6);
    padding: 0.7rem 1.8rem;
    border-radius: 10px;
    cursor: pointer;
    font-family: 'Cinzel', serif;
    font-size: 0.85rem;
    letter-spacing: 0.07em;
    font-weight: 600;
