/* body.mode-rpg overrides para los nuevos elementos */
body.mode-rpg .rpg-class-select {
    border-color: rgba(160,80,32,0.35);
    background-color: rgba(160,80,32,0.06);
    color: rgba(230,190,120,0.9);
}
body.mode-rpg .rpg-class-select:hover {
    border-color: rgba(160,128,220,0.5);
    background-color: rgba(160,80,32,0.14);
}
body.mode-rpg .rpg-stats-card-mod { color: rgba(200,160,80,0.55); }
body.mode-rpg .ihp-stats-edit-btn {
    border-color: rgba(160,80,32,0.3);
    color: rgba(220,160,80,0.75);
