/* ── Modificador en la celda del IHP ── */
.ihp-stat-mod {
    font-size: 0.55rem;
    display: block;
    opacity: 0.5;
    line-height: 1;
    font-family: 'Cinzel', serif;
}
body.mode-rpg .ihp-stat-mod { color: rgba(200,160,80,0.7); opacity: 1; }

/* IHP: 6 stats en 3 columnas para D&D */
.ihp-stats {
    grid-template-columns: repeat(3, 1fr) !important;
}

/* ═══════════════════════════════════════════════════════════════════
