/* ═══════════════════════════════════════════════════════════════════
   MODAL DE SUBIDA DE NIVEL
   ═══════════════════════════════════════════════════════════════════ */
.rpg-levelup-modal {
    background: linear-gradient(160deg, rgba(18,10,3,0.98), rgba(30,18,6,0.97));
    border: 1px solid rgba(160,128,220,0.5);
    border-radius: 16px;
    padding: 1.8rem 1.6rem 1.4rem;
    max-width: 340px;
    width: 90%;
    text-align: center;
    box-shadow: 0 16px 48px rgba(0,0,0,0.7), inset 0 1px 0 rgba(255,220,140,0.08);
}
.levelup-header { margin-bottom: 1.1rem; }
.levelup-icon {
    display: block;
    font-size: 2rem;
    margin-bottom: 0.4rem;
    color: rgba(235,205,140,0.9);
    animation: levelupPulse 1.8s ease-in-out infinite;
}
@keyframes levelupPulse {
    0%,100% { opacity: 0.8; transform: scale(1); }
    50%      { opacity: 1;   transform: scale(1.12); }
}
.levelup-title {
    font-family: 'Cinzel', serif;
    font-size: 1.4rem;
    font-weight: 700;
    color: rgba(235,205,140,1);
    letter-spacing: 0.06em;
    margin-bottom: 0.3rem;
}
.levelup-sub {
    font-size: 0.75rem;
    color: rgba(200,180,130,0.6);
    font-family: 'Crimson Text', serif;
    font-style: italic;
}
.levelup-gains {
    background: rgba(160,128,220,0.05);
    border: 1px solid rgba(160,128,220,0.15);
    border-radius: 10px;
    padding: 0.8rem 1rem;
    margin-bottom: 1rem;
    text-align: left;
}
.levelup-gain {
    font-size: 0.72rem;
    font-family: 'Cinzel', serif;
    color: rgba(220,190,130,0.85);
    padding: 0.18rem 0;
    display: flex;
    align-items: flex-start;
    gap: 0.4rem;
}
.levelup-gain::before { content: '◆'; color: rgba(160,128,220,0.5); flex-shrink: 0; }
.levelup-gain.unlock { color: rgba(160,220,120,0.9); }
.levelup-gain.unlock::before { content: '⚡'; }
.levelup-stat-hint {
    font-size: 0.65rem;
    color: rgba(180,160,120,0.5);
    font-style: italic;
    margin-bottom: 1rem;
}
.rpg-levelup-confirm {
    width: 100%;
    padding: 0.65rem;
    border-radius: 10px;
    border: 1px solid rgba(160,128,220,0.45);
    background: rgba(160,80,32,0.18);
    color: rgba(235,205,140,0.95);
    font-family: 'Cinzel', serif;
    font-size: 0.8rem;
    letter-spacing: 0.06em;
    cursor: pointer;
    transition: all 0.15s;
}
.rpg-levelup-confirm:hover {
    background: rgba(160,80,32,0.35);
    border-color: rgba(160,128,220,0.7);
}

