    border-radius: 14px;
    box-shadow: 0 12px 40px rgba(0,0,0,0.65), inset 0 1px 0 rgba(255,220,140,0.06);
    backdrop-filter: blur(20px);
    overflow: hidden;
    animation: fadeIn 0.18s ease;
}
.vn-dm-panel-header {
    display: flex;
