/* ═══════════════════════════════════════════════════════════════════
   TOAST DE SUBIDA DE NIVEL — privado, solo visible para el dueño
   ═══════════════════════════════════════════════════════════════════ */

.levelup-toast {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 9999;
    width: 260px;
    background: linear-gradient(160deg, rgba(18,10,3,0.97), rgba(28,16,5,0.98));
    border: 1px solid rgba(160,128,220,0.55);
    border-radius: 16px;
    padding: 1.4rem 1.3rem 1.1rem;
    text-align: center;
    box-shadow: 0 20px 60px rgba(0,0,0,0.7), 0 0 40px rgba(160,128,220,0.08);
    cursor: pointer;
    animation: lut-appear 0.35s cubic-bezier(0.34,1.56,0.64,1) both;
    user-select: none;
}
@keyframes lut-appear {
    from { opacity: 0; transform: translate(-50%, -48%) scale(0.88); }
    to   { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}
.levelup-toast.lut-fadeout {
    animation: lut-fade 0.6s ease forwards;
}
@keyframes lut-fade {
    to { opacity: 0; transform: translate(-50%, -52%) scale(0.92); }
}
.lut-glow {
    position: absolute;
    inset: -1px;
    border-radius: 16px;
    background: radial-gradient(ellipse at 50% 0%, rgba(160,128,220,0.15) 0%, transparent 70%);
    pointer-events: none;
}
.lut-close {
    position: absolute;
    top: 0.5rem;
    right: 0.6rem;
    background: none;
    border: none;
    color: rgba(160,128,220,0.3);
    font-size: 0.65rem;
    cursor: pointer;
    padding: 0.15rem 0.25rem;
    transition: color 0.12s;
    z-index: 1;
}
.lut-close:hover { color: rgba(160,128,220,0.7); }
.lut-icon {
    font-size: 1.6rem;
    color: rgba(220,185,100,0.9);
    margin-bottom: 0.35rem;
    animation: lut-pulse 2s ease-in-out infinite;
}
@keyframes lut-pulse {
    0%,100% { opacity: 0.8; transform: scale(1); }
    50%      { opacity: 1;   transform: scale(1.15); }
}
.lut-title {
    font-family: 'Cinzel', serif;
    font-size: 1.25rem;
    font-weight: 700;
    color: rgba(235,205,140,1);
    letter-spacing: 0.06em;
    margin-bottom: 0.2rem;
}
.lut-char {
    font-size: 0.68rem;
    color: rgba(200,180,130,0.55);
    font-style: italic;
    margin-bottom: 0.7rem;
}
.lut-gains {
    display: flex;
    justify-content: center;
    gap: 0.5rem;
    flex-wrap: wrap;
    margin-bottom: 0.5rem;
}
.lut-gain {
    font-size: 0.62rem;
    font-family: 'Cinzel', serif;
    color: rgba(180,220,140,0.85);
    background: rgba(40,100,40,0.15);
    border: 1px solid rgba(80,160,80,0.25);
    border-radius: 20px;
    padding: 0.15rem 0.55rem;
}
.lut-passive {
    font-size: 0.62rem;
    color: rgba(180,150,240,0.8);
    background: rgba(80,50,160,0.12);
    border: 1px solid rgba(120,90,200,0.2);
    border-radius: 8px;
    padding: 0.3rem 0.5rem;
    margin-bottom: 0.5rem;
    line-height: 1.3;
}
.lut-hint {
    font-size: 0.58rem;
    color: rgba(180,160,120,0.4);
    font-style: italic;
    margin-top: 0.4rem;
}

/* ═══════════════════════════════════════════════════════════════════
   PANEL DE INVENTARIO DEL IHP
   Se despliega a la derecha del panel fijado en modo RPG
   ═══════════════════════════════════════════════════════════════════ */

/* Botón de inventario en el footer del IHP — junto a Editar stats */
.ihp-inventory-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    background: rgba(160,128,220,0.07);
    border: 1px solid rgba(160,128,220,0.2);
    border-radius: 6px;
    color: rgba(200,180,130,0.75);
    font-size: 0.65rem;
    font-family: 'Cinzel', serif;
    letter-spacing: 0.04em;
    padding: 0.22rem 0.55rem;
    cursor: pointer;
    transition: all 0.14s;
    margin-top: 0.3rem;
}
.ihp-inventory-btn:hover {
    background: rgba(160,128,220,0.15);
    border-color: rgba(160,128,220,0.45);
    color: rgba(230,205,150,0.95);
}

/* Panel lateral — aparece a la derecha del IHP */
.ihp-inventory-panel {
    position: absolute;
    left: calc(100% + 8px);
    top: 0;
    width: 220px;
    max-height: 420px;
    background: linear-gradient(160deg, rgba(18,11,4,0.98), rgba(12,7,2,0.99));
    border: 1px solid rgba(160,128,220,0.35);
    border-radius: 12px;
    box-shadow: 0 12px 36px rgba(0,0,0,0.6);
    backdrop-filter: blur(18px);
    flex-direction: column;
    overflow: hidden;
    z-index: var(--z-i-211);
    animation: ihpInvSlide 0.2s cubic-bezier(0.34,1.3,0.64,1) both;
}
@keyframes ihpInvSlide {
    from { opacity: 0; transform: translateX(-8px) scale(0.97); }
    to   { opacity: 1; transform: translateX(0) scale(1); }
}

.ihp-inv-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.6rem 0.75rem 0.4rem;
    border-bottom: 1px solid rgba(160,128,220,0.12);
    flex-shrink: 0;
}
.ihp-inv-title {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-family: 'Cinzel', serif;
    font-size: 0.65rem;
    color: rgba(160,128,220,0.7);
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.ihp-inv-header button {
    background: none;
    border: none;
    color: rgba(160,128,220,0.35);
    cursor: pointer;
    font-size: 0.7rem;
    padding: 0.1rem 0.2rem;
    transition: color 0.12s;
}
.ihp-inv-header button:hover { color: rgba(160,128,220,0.75); }

.ihp-inv-body {
    flex: 1;
    overflow-y: auto;
    padding: 0.4rem 0.5rem;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
    scrollbar-width: thin;
    scrollbar-color: rgba(160,128,220,0.2) transparent;
}

/* Hint de uso automático al fondo del panel */
.ihp-inv-auto-hint {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.35rem 0.6rem;
    border-top: 1px solid rgba(160,128,220,0.08);
    font-size: 0.58rem;
    color: rgba(180,220,140,0.55);
    font-style: italic;
    flex-shrink: 0;
}

/* Items dentro del panel lateral — versión compacta */
.ihp-inv-body .rpg-inventory-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    background: rgba(255,255,255,0.02);
    border: 1px solid rgba(160,128,220,0.1);
    border-radius: 7px;
    padding: 0.35rem 0.45rem;
    font-size: 0.65rem;
}
.ihp-inv-body .rpg-item-icon { font-size: 1rem; flex-shrink: 0; }
.ihp-inv-body .rpg-item-info {
    display: flex;
    flex-direction: column;
    gap: 0.05rem;
    flex: 1;
    min-width: 0;
}
.ihp-inv-body .rpg-item-name {
    font-size: 0.65rem;
    font-family: 'Cinzel', serif;
    color: rgba(220,195,150,0.9);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.ihp-inv-body .rpg-item-desc {
    font-size: 0.57rem;
    color: rgba(180,160,120,0.45);
    display: none; /* Ocultar desc en la vista compacta lateral */
}
.ihp-inv-body .rpg-item-qty {
    font-size: 0.62rem;
    color: rgba(160,128,220,0.6);
    font-family: 'Cinzel', serif;
    flex-shrink: 0;
}
.ihp-inv-body .rpg-item-use-btn {
    flex-shrink: 0;
    padding: 0.15rem 0.4rem;
    border-radius: 5px;
    border: 1px solid rgba(80,160,80,0.3);
    background: rgba(40,100,40,0.12);
    color: rgba(120,220,140,0.85);
    font-size: 0.58rem;
    cursor: pointer;
    transition: all 0.13s;
    font-family: 'Cinzel', serif;
}
.ihp-inv-body .rpg-item-use-btn:hover {
    background: rgba(40,100,40,0.25);
    border-color: rgba(80,180,100,0.5);
}
.ihp-inv-body .rpg-inventory-empty {
    font-size: 0.65rem;
    color: rgba(180,160,120,0.4);
    font-style: italic;
    text-align: center;
    padding: 0.8rem 0;
}

/* En móvil el panel aparece debajo en lugar de a la derecha */
@media (max-width: 768px) {
    .ihp-inventory-panel {
        left: 0;
        top: calc(100% + 6px);
        width: 260px;
        max-height: 300px;
    }
}

/* ═══════════════════════════════════════════════════════════════════
   PANEL DE PRESENCIA — participantes del tema activo
   Posicionado en la esquina superior derecha, bajo los controles
   ═══════════════════════════════════════════════════════════════════ */

.vn-presence-panel {
    position: fixed;
    top: 14px;
    right: 14px;
    z-index: var(--z-controls, 200);
    display: flex;
    align-items: center;
    gap: 0.35rem;
    background: rgba(14,8,2,0.72);
    border: 1px solid rgba(160,128,220,0.15);
    border-radius: 22px;
    padding: 0.3rem 0.55rem 0.3rem 0.4rem;
    backdrop-filter: blur(10px);
    pointer-events: none; /* no interfiere con clicks */
    transition: opacity 0.2s;
}
.vn-presence-panel:empty { display: none; }

.vn-presence-list {
    display: flex;
    align-items: flex-end;
    gap: 0.3rem;
}

/* ── Avatar individual de presencia ── */
.vn-presence-avatar {
    position: relative;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    border: 2px solid rgba(160, 128, 220, 0.35);
    background: rgba(75, 50, 120, 0.65) center / cover;
    flex-shrink: 0;
    cursor: default;
    transition: border-color 0.2s;
}

.vn-presence-avatar:hover {
    border-color: rgba(190, 160, 255, 0.7);
}

/* Letra inicial (cuando no hay avatar) */
.vn-presence-avatar-initial {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    color: rgba(225, 205, 255, 0.92);
    font-size: 0.72rem;
    font-weight: 700;
    font-family: 'Cinzel', serif;
    letter-spacing: 0.02em;
}

/* Punto verde "online" */
.vn-presence-dot {
    position: absolute;
    bottom: 1px;
    right: 1px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #5dda72;
    border: 1.5px solid rgba(10, 6, 2, 0.88);
    animation: eth-presence-pulse 2.8s ease-in-out infinite;
}

@keyframes eth-presence-pulse {
    0%, 100% { box-shadow: 0 0 3px rgba(93, 218, 114, 0.4); }
    50%       { box-shadow: 0 0 7px rgba(93, 218, 114, 0.8); }
}

/* En móvil, moverlo un poco para no solapar los controles */
@media (max-width: 768px) {
    .vn-presence-panel {
        top: auto;
        bottom: 80px;
        right: 10px;
    }
}

/* ═══════════════════════════════════════════════════════════════════
   PARTY PANEL — relevo de escenas
   ═══════════════════════════════════════════════════════════════════ */

.vn-party-backdrop {
    position: fixed;
    inset: 0;
    background: rgba(8, 6, 4, 0.38);
    z-index: calc(var(--z-controls, 200) - 2);
}

.vn-party-shell {
    position: fixed;
    top: max(6.7rem, calc(env(safe-area-inset-top) + 5.9rem));
    left: 0.85rem;
    transform: none;
    z-index: calc(var(--z-controls, 200) + 1);
    display: flex;
    align-items: stretch;
    pointer-events: none;
}
.vn-party-shell > * {
    pointer-events: auto;
}
.vn-party-shell.open .vn-party-panel {
    transform: translateX(0);
}

.vn-party-tab {
    display: none;
}
.vn-party-tab-label {
    writing-mode: vertical-rl;
    transform: rotate(180deg);
    font-size: 0.72rem;
    letter-spacing: 0.08em;
}

.vn-party-panel {
    width: min(232px, calc(100vw - 1.5rem));
    max-height: min(55vh, 460px);
    overflow: auto;
    transform: none;
    transition: transform 0.24s ease;
    background:
        linear-gradient(180deg, rgba(42,29,18,0.96), rgba(24,17,11,0.98)),
        repeating-linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.02) 12px, rgba(0,0,0,0.02) 12px, rgba(0,0,0,0.02) 24px);
    border: 1px solid rgba(160,128,220,0.2);
    border-radius: 16px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.3);
    padding: 0.62rem 0.6rem 0.68rem;
}
.vn-party-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 0.65rem;
    padding-bottom: 0.55rem;
    margin-bottom: 0.65rem;
    border-bottom: 1px solid rgba(160,128,220,0.13);
}
.vn-party-title {
    font-family: 'Cinzel', serif;
    color: #f0e3cc;
    letter-spacing: 0.08em;
    font-size: 0.92rem;
}
.vn-party-subtitle {
    color: rgba(214,196,168,0.62);
    font-size: 0.7rem;
    letter-spacing: 0.05em;
}
.vn-party-list {
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
}
.vn-party-empty {
    color: rgba(214,196,168,0.62);
    font-size: 0.8rem;
    padding: 0.4rem 0.1rem;
}
.vn-party-member {
    display: block;
    width: 100%;
    align-items: start;
    padding: 0.45rem 0.5rem;
    border-radius: 10px;
    border: 1px solid rgba(160,128,220,0.12);
    background: rgba(255,248,235,0.03);
    transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, opacity 0.18s ease;
    text-align: left;
    cursor: pointer;
}
.vn-party-member:hover {
    transform: translateX(0);
}
.vn-party-member[data-state="active"] {
    border-color: rgba(224,190,104,0.52);
    box-shadow: 0 0 0 1px rgba(224,190,104,0.12), 0 10px 22px rgba(0,0,0,0.18);
}
.vn-party-member[data-state="waiting"] {
    opacity: 0.72;
}
.vn-party-member[data-state="critical"] {
    border-color: rgba(164,74,74,0.46);
    box-shadow: 0 0 0 1px rgba(164,74,74,0.12);
}
.vn-party-main {
    min-width: 0;
}
.vn-party-topline {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 0.55rem;
}
.vn-party-name {
    color: #f4e7d0;
    font-size: 0.79rem;
    font-family: 'Cinzel', serif;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.vn-party-meta {
    color: rgba(214,196,168,0.68);
    font-size: 0.61rem;
    margin-top: 0.12rem;
}
.vn-party-state {
    flex-shrink: 0;
    font-size: 0.59rem;
    color: rgba(236,223,198,0.78);
    padding-top: 0.08rem;
}
.vn-party-bars {
    margin-top: 0.34rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}
.vn-party-bar-row {
    display: grid;
    grid-template-columns: 24px minmax(0, 1fr) auto;
    gap: 0.32rem;
    align-items: center;
}
.vn-party-bar-label,
.vn-party-bar-value {
    font-size: 0.56rem;
    color: rgba(214,196,168,0.68);
    letter-spacing: 0.05em;
}
.vn-party-bar-track {
    position: relative;
    height: 6px;
    border-radius: 999px;
    background: rgba(11,8,6,0.78);
    overflow: hidden;
    border: 1px solid rgba(160,128,220,0.08);
}
.vn-party-bar-fill {
    position: absolute;
    inset: 0 auto 0 0;
    width: 0;
    border-radius: inherit;
    background: linear-gradient(90deg, rgba(140,82,64,0.95), rgba(199,124,84,0.95));
}
.vn-party-bar-fill.exp {
    background: linear-gradient(90deg, rgba(112,108,164,0.95), rgba(172,155,220,0.95));
}
.vn-party-member-highlight {
    animation: vnPartyPulse 0.9s ease;
}
.vn-sprite.party-highlight,
.vn-speaker-plate.party-highlight {
    animation: vnPartyPulse 0.9s ease;
}
@keyframes vnPartyPulse {
    0% { box-shadow: 0 0 0 0 rgba(224,190,104,0.38); }
    100% { box-shadow: 0 0 0 16px rgba(224,190,104,0); }
}

@media (max-width: 768px) {
    .vn-party-shell {
        top: max(5.8rem, calc(env(safe-area-inset-top) + 4.9rem));
        left: 0.6rem;
        right: auto;
        transform: none;
    }
    .vn-party-panel {
        width: min(180px, calc(100vw - 1.2rem));
        max-height: min(44vh, 300px);
    }
}



/* -- css/menu.css -- */
/* ══════════════════════════════════════════════════════════════════════════
   ETHERIA — MENÚ PRINCIPAL REDISEÑADO
   Concepto: "Bosque Vivo" — Título e iconografía centrados sobre el fondo.
   Inspirado en la estética de pantalla de título RPG clásico.
   ══════════════════════════════════════════════════════════════════════════ */

@import url('https://fonts.googleapis.com/css2?family=Cinzel+Decorative:wght@400;700;900&family=Cinzel:wght@400;600;700&display=swap');

/* ─── Variables del menú ─── */
:root {
    --menu-gold:        #a080e0;
    --menu-gold-light:  #f0d898;
    --menu-gold-dark:   #8b6914;
    --menu-btn-h:       64px;
    --menu-btn-w:       320px;
    --menu-transition:  0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    --menu-sidebar-w:   0px; /* sin sidebar */
}

/* ══════════════════════════════════════════════════════════════════════════
   LAYOUT PRINCIPAL — centrado completo
   ══════════════════════════════════════════════════════════════════════════ */

.main-menu {
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
}

/* Ocultar sidebar completamente */
.menu-sidebar {
    display: none !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   PARALLAX — 3 capas PNG reales, movimiento suave mouse
   ══════════════════════════════════════════════════════════════════════════ */

.menu-parallax {
    position: absolute !important;
    inset: 0 !important;
    z-index: var(--z-i-1) !important;
    overflow: hidden !important;
    background: #1a2a1a !important;
    transition: background 1.8s ease !important;
}

[data-theme="light"] .menu-parallax  { background: #4a7a3a !important; }
[data-theme="dark"]  .menu-parallax  { background: #03061a !important; }

.parallax-layer {
    position: absolute !important;
    top: -5% !important;
    left: -5% !important;
    width: 110% !important;
    height: 110% !important;
    background-size: cover !important;
    background-position: center center !important;
    background-repeat: no-repeat !important;
    will-change: transform !important;
    transition: filter 1.8s ease !important;
}

/* Imágenes de día */
.layer-bg-day  { background-image: url('../assets/parallax/layer_bg.png') !important;       z-index: 1 !important; }
.layer-mid-day { background-image: url('../assets/parallax/layer_mid.png') !important;      z-index: 2 !important; }
.layer-fg-day  { background-image: url('../assets/parallax/layer_fg.png') !important;       z-index: 3 !important; }

/* Imágenes de noche (procesadas píxel a píxel) */
.layer-bg-night  { background-image: url('../assets/parallax/layer_bg_night.png') !important;  z-index: 1 !important; }
.layer-mid-night { background-image: url('../assets/parallax/layer_mid_night.png') !important; z-index: 2 !important; }
.layer-fg-night  { background-image: url('../assets/parallax/layer_fg_night.png') !important;  z-index: 3 !important; }

/* Por defecto todas ocultas */
.layer-bg-day, .layer-mid-day, .layer-fg-day,
.layer-bg-night, .layer-mid-night, .layer-fg-night { opacity: 0 !important; transition: opacity 1.8s ease !important; }

/* Día */
[data-theme="light"] .layer-bg-day,
[data-theme="light"] .layer-mid-day,
[data-theme="light"] .layer-fg-day  { opacity: 1 !important; }

/* Noche */
[data-theme="dark"] .layer-bg-night,
[data-theme="dark"] .layer-mid-night,
[data-theme="dark"] .layer-fg-night { opacity: 1 !important; }

/* ─── Overlay de atmósfera general ─── */
[data-theme="light"] .main-menu::before {
    background: linear-gradient(
        180deg,
        rgba(0,0,0,0.04) 0%,
        rgba(0,0,0,0.10) 55%,
        rgba(0,0,0,0.22) 100%
    ) !important;
    backdrop-filter: none !important;
}

[data-theme="dark"] .main-menu::before {
    background:
        radial-gradient(circle at 50% -15%, rgba(60, 90, 160, 0.22) 0%, transparent 55%),
        linear-gradient(180deg, rgba(5, 10, 22, 0.72) 0%, rgba(4, 10, 24, 0.65) 48%, rgba(3, 7, 16, 0.82) 100%) !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   CONTENEDOR CENTRAL — título + botones
   ══════════════════════════════════════════════════════════════════════════ */

.menu-center-content {
    position: relative;
    z-index: var(--z-i-10);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0;
    pointer-events: all;
    animation: contentReveal 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
    /* Evita que el contenido quede tapado por el footer fijo */
    max-height: calc(100vh - 80px - env(safe-area-inset-bottom, 0px) - env(safe-area-inset-top, 0px));
    max-height: calc(100dvh - 80px - env(safe-area-inset-bottom, 0px) - env(safe-area-inset-top, 0px));
    overflow-y: auto;
    overflow-x: hidden;
    padding-bottom: 4px;
    /* Ocultar scrollbar visualmente, mantener funcionalidad */
    scrollbar-width: none;
    -ms-overflow-style: none;
}

.menu-center-content::-webkit-scrollbar {
    display: none;
}

@keyframes contentReveal {
    from { opacity: 0; transform: translateY(20px); filter: blur(6px); }
    to   { opacity: 1; transform: translateY(0);    filter: blur(0);   }
}

/* ══════════════════════════════════════════════════════════════════════════
   BRAND / TÍTULO CENTRADO
   ══════════════════════════════════════════════════════════════════════════ */

.menu-brand {
    text-align: center !important;
    margin-bottom: 2.5rem !important;
    padding: 0 !important;
    border: none !important;
}

/* Estrellitas ornamentales */
.menu-brand::before {
    display: none !important;
}
.menu-brand::after {
    display: none !important;
}

.menu-title {
    font-family: 'Cinzel Decorative', 'Cinzel', serif !important;
    font-size: clamp(3.5rem, 8vw, 6.5rem) !important;
    font-weight: 900 !important;
    letter-spacing: 0.06em !important;
    line-height: 1.05 !important;
    margin-bottom: 0.5rem !important;
    text-align: center !important;
    position: relative;
    display: block !important;
}

/* Modo día: texto oscuro con sombra cálida (como imagen 2) */
[data-theme="light"] .menu-title {
    color: #2a1a0a !important;
    text-shadow:
        0 2px 8px rgba(255,200,100,0.5),
        0 4px 24px rgba(180,120,40,0.3),
        2px 2px 0 rgba(200,150,60,0.2) !important;
}

/* Modo noche: texto verde-blanco luminoso (como imagen 1) */
[data-theme="dark"] .menu-title {
    color: #b8d4b0 !important;
    text-shadow:
        0 0 24px rgba(140, 200, 130, 0.6),
        0 0 56px rgba(100, 180, 90, 0.3),
        0 2px 10px rgba(0,0,0,0.8) !important;
}

.menu-title-animated {
    display: inline !important;
}

@keyframes letterReveal {
    from { opacity: 0; transform: translateY(-12px) scale(0.85); filter: blur(4px); }
    to   { opacity: 1; transform: translateY(0) scale(1);         filter: blur(0);   }
}

.menu-title-animated .title-letter {
    display: inline-block !important;
    animation: letterReveal 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) both !important;
    transition: transform 0.3s ease, text-shadow 0.3s ease !important;
}

.menu-title-animated .title-letter:nth-child(1) { animation-delay: 0.08s !important; }
.menu-title-animated .title-letter:nth-child(2) { animation-delay: 0.16s !important; }
.menu-title-animated .title-letter:nth-child(3) { animation-delay: 0.24s !important; }
.menu-title-animated .title-letter:nth-child(4) { animation-delay: 0.32s !important; }
.menu-title-animated .title-letter:nth-child(5) { animation-delay: 0.40s !important; }
.menu-title-animated .title-letter:nth-child(6) { animation-delay: 0.48s !important; }
.menu-title-animated .title-letter:nth-child(7) { animation-delay: 0.56s !important; }

.menu-subtitle {
    font-family: 'Cinzel', serif !important;
    font-size: clamp(0.7rem, 1.5vw, 0.95rem) !important;
    font-style: normal !important;
    letter-spacing: 0.35em !important;
    text-transform: uppercase !important;
    text-align: center !important;
    margin-top: 0.4rem !important;
    opacity: 0.75 !important;
}

[data-theme="light"] .menu-subtitle {
    color: #3d2608 !important;
}
[data-theme="dark"] .menu-subtitle {
    color: #9bbf92 !important;
}

/* Icono 📖 — ocultar emoji, no encaja con el estilo */
.menu-title > :not(.menu-title-animated) {
    display: none !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   CONTENEDOR DE BOTONES — columna centrada
   ══════════════════════════════════════════════════════════════════════════ */

.menu-container {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    gap: 0.6rem !important;
    padding: 0 !important;
    justify-content: center !important;
    width: var(--menu-btn-w) !important;
    max-width: 90vw !important;
    flex: 0 0 auto !important;
}

/* Sin líneas ornamentales arriba/abajo */
.menu-container::before,
.menu-container::after {
    display: none !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   BOTONES — estilo RPG pantalla de título
   ══════════════════════════════════════════════════════════════════════════ */

.menu-button,
.menu-button-console {
    position: relative !important;
    width: 100% !important;
    min-height: var(--menu-btn-h) !important;
    margin-bottom: 0 !important;
    padding: 0.9rem 2rem !important;
    border-radius: 6px !important;
    overflow: hidden !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 0.75rem !important;

    font-family: 'Cinzel', serif !important;
    font-size: 0.88rem !important;
    font-weight: 600 !important;
    letter-spacing: 0.12em !important;
    text-transform: uppercase !important;
    text-align: center !important;

    transition:
        transform var(--menu-transition),
        box-shadow var(--menu-transition),
        border-color var(--menu-transition),
        color var(--menu-transition),
        background var(--menu-transition) !important;

    animation: buttonSlideIn 0.5s both !important;
}

/* Modo día */
/* Modo día — ámbar/pergamino */
[data-theme="light"] .menu-button,
[data-theme="light"] .menu-button-console {
    background: rgba(18, 12, 4, 0.86) !important;
    border: 1px solid rgba(160,128,220, 0.5) !important;
    color: #e8d4a0 !important;
    text-shadow: 0 1px 6px rgba(0,0,0,0.8) !important;
    box-shadow:
        0 2px 16px rgba(0,0,0,0.55),
        inset 0 1px 0 rgba(255,220,140,0.06) !important;
    backdrop-filter: blur(12px) !important;
}

[data-theme="light"] .menu-button:hover,
[data-theme="light"] .menu-button-console:hover {
    background: rgba(30, 20, 6, 0.88) !important;
    border-color: rgba(160,128,220, 0.85) !important;
    color: #f0dfa8 !important;
    transform: translateY(-2px) !important;
    box-shadow:
        0 6px 24px rgba(0,0,0,0.45),
        0 0 20px rgba(160,128,220, 0.18),
        inset 0 1px 0 rgba(255,220,140,0.08) !important;
}

/* Modo noche — ámbar más frío */
[data-theme="dark"] .menu-button,
[data-theme="dark"] .menu-button-console {
    background: rgba(18, 13, 6, 0.82) !important;
    border: 1px solid rgba(160,128,220, 0.35) !important;
    color: #d4b87a !important;
    text-shadow: 0 1px 4px rgba(0,0,0,0.7) !important;
    box-shadow:
        0 2px 12px rgba(0,0,0,0.5),
        inset 0 1px 0 rgba(255,200,100,0.04) !important;
    backdrop-filter: blur(10px) !important;
}

[data-theme="dark"] .menu-button:hover,
[data-theme="dark"] .menu-button-console:hover {
    background: rgba(28, 20, 8, 0.9) !important;
    border-color: rgba(160,128,220, 0.7) !important;
    color: #e8cc88 !important;
    transform: translateY(-2px) !important;
    box-shadow:
        0 6px 24px rgba(0,0,0,0.55),
        0 0 22px rgba(160,128,220, 0.15) !important;
}

/* Botón primario (Nueva Partida) — dorado más intenso */
[data-theme="light"] .menu-button.primary,
[data-theme="light"] .menu-button-console.primary {
    background: rgba(25, 16, 4, 0.9) !important;
    border-color: rgba(160,128,220, 0.7) !important;
    color: #f0dfa8 !important;
    box-shadow:
        0 3px 18px rgba(0,0,0,0.5),
        0 0 28px rgba(160,128,220, 0.15) !important;
}

[data-theme="dark"] .menu-button.primary,
[data-theme="dark"] .menu-button-console.primary {
    background: rgba(22, 14, 4, 0.9) !important;
    border-color: rgba(160,128,220, 0.6) !important;
    color: #e8cc88 !important;
    box-shadow:
        0 3px 18px rgba(0,0,0,0.6),
        0 0 30px rgba(160,128,220, 0.12) !important;
}

/* Shimmer sweep */
.menu-button::before,
.menu-button-console::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important; left: -120% !important;
    width: 60% !important; height: 100% !important;
    background: linear-gradient(
        108deg,
        transparent 20%,
        rgba(200, 255, 180, 0.06) 50%,
        transparent 80%
    ) !important;
    transition: left 0.6s ease !important;
    pointer-events: none !important;
    z-index: var(--z-i-1)!important;
}

.menu-button:hover::before,
.menu-button-console:hover::before {
    left: 150% !important;
}

/* Flecha — ocultar en este diseño */
.menu-button::after,
.menu-button-console::after {
    display: none !important;
}

/* Icono */
.menu-button-console .menu-icon {
    font-size: 1.1rem !important;
    width: auto !important;
    height: auto !important;
    background: none !important;
    border: none !important;
    flex: 0 0 auto !important;
    position: relative;
    z-index: var(--z-i-2);
}

.menu-button-console .menu-label {
    position: relative;
    z-index: var(--z-i-2);
    font-size: 0.88rem !important;
    letter-spacing: 0.12em !important;
}

/* Animación entrada escalonada */
@keyframes buttonSlideIn {
    from { opacity: 0; transform: translateY(14px); filter: blur(2px); }
    to   { opacity: 1; transform: translateY(0);    filter: blur(0);   }
}

.menu-container > :nth-child(1) { animation-delay: 0.55s !important; }
.menu-container > :nth-child(2) { animation-delay: 0.68s !important; }
.menu-container > :nth-child(3) { animation-delay: 0.81s !important; }
.menu-container > :nth-child(4) { animation-delay: 0.94s !important; }
.menu-container > :nth-child(5) { animation-delay: 1.07s !important; }

/* Activo */
.menu-button:active,
.menu-button-console:active {
    transform: translateY(0) !important;
    transition-duration: 0.08s !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   VIGNETTE lateral — innecesaria sin sidebar
   ══════════════════════════════════════════════════════════════════════════ */

.menu-parallax::before {
    display: none !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   FOOTER y BOTÓN SALIR — reposicionados abajo centrados
   ══════════════════════════════════════════════════════════════════════════ */

/* ══════════════════════════════════════════════════════════════════════════
   ICONO SVG EN BOTONES
   ══════════════════════════════════════════════════════════════════════════ */

.menu-svg-icon {
    width: 17px !important;
    height: 17px !important;
    flex: 0 0 auto !important;
    position: relative;
    z-index: var(--z-i-2);
    opacity: 0.80;
    transition: opacity 0.22s ease !important;
}

.menu-button:hover .menu-svg-icon,
.menu-button-console:hover .menu-svg-icon {
    opacity: 1;
}

/* ══════════════════════════════════════════════════════════════════════════
   FOOTER — perfil + botón sutil de guardado
   ══════════════════════════════════════════════════════════════════════════ */

.menu-footer {
    position: fixed !important;
    bottom: calc(1.2rem + env(safe-area-inset-bottom, 0px)) !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    display: flex !important;
    align-items: center !important;
    gap: 0.6rem !important;
    z-index: var(--z-i-20)!important;
    margin: 0 !important;
    animation: buttonSlideIn 0.5s 1.1s both !important;
    white-space: nowrap;
}

/* Botón de perfil — tarjeta horizontal */
.menu-profile-btn {
    display: flex !important;
    align-items: center !important;
    gap: 0.65rem !important;
    background: rgba(0,0,0,0.72) !important;
    border: 1px solid rgba(120,180,90,0.45) !important;
    border-radius: 10px !important;
    padding: 0.42rem 0.85rem 0.42rem 0.5rem !important;
    backdrop-filter: blur(12px) !important;
    cursor: pointer !important;
    transition: all 0.22s ease !important;
    text-align: left !important;
}

.menu-profile-btn:hover {
    background: rgba(10,30,14,0.72) !important;
    border-color: rgba(130,200,100,0.45) !important;
    transform: translateY(-1px) !important;
}

/* Avatar pequeño en el footer */
.menu-profile-avatar {
    width: 32px !important;
    height: 32px !important;
    border-radius: 50% !important;
    background: rgba(80,140,60,0.35) !important;
    border: 1.5px solid rgba(120,190,90,0.4) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    overflow: hidden !important;
    flex: 0 0 32px !important;
    position: relative !important;
}

.menu-profile-initial {
    font-family: 'Cinzel', serif !important;
    font-size: 0.75rem !important;
    font-weight: 600 !important;
    color: #a8d890 !important;
    line-height: 1 !important;
}

.menu-profile-img {
    position: absolute !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    border-radius: 50% !important;
}

/* Info de texto del perfil */
.menu-profile-info {
    display: flex !important;
    flex-direction: column !important;
    gap: 0.05rem !important;
}

.menu-profile-name {
    font-family: 'Cinzel', serif !important;
    font-size: 0.76rem !important;
    letter-spacing: 0.06em !important;
    color: #c8eaaa !important;
    line-height: 1.2 !important;
}

.menu-profile-hint {
    font-size: 0.62rem !important;
    color: rgba(190,230,160,0.75) !important;
    letter-spacing: 0.04em !important;
    font-family: sans-serif !important;
}

.menu-profile-chevron {
    width: 10px !important;
    height: 10px !important;
    color: rgba(120,180,90,0.5) !important;
    flex: 0 0 auto !important;
    transition: color 0.2s ease !important;
}

.menu-profile-btn:hover .menu-profile-chevron {
    color: rgba(160,220,120,0.85) !important;
}

/* Botón sutil de import/export */
.menu-save-btn {
    width: 36px !important;
    height: 36px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: rgba(0,0,0,0.40) !important;
    border: 1px solid rgba(100,160,80,0.18) !important;
    border-radius: 8px !important;
    backdrop-filter: blur(12px) !important;
    cursor: pointer !important;
    color: rgba(140,200,110,0.55) !important;
    transition: all 0.22s ease !important;
    flex: 0 0 36px !important;
}

.menu-save-btn svg {
    width: 15px !important;
    height: 15px !important;
}

.menu-save-btn:hover {
    background: rgba(10,30,14,0.65) !important;
    border-color: rgba(120,190,90,0.45) !important;
    color: rgba(180,230,140,0.9) !important;
    transform: translateY(-1px) !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   MODAL DE PERFIL RÁPIDO
   ══════════════════════════════════════════════════════════════════════════ */

.profile-modal {
    background: var(--bg-primary, #1a1815) !important;
    border: 1px solid rgba(120,180,90,0.22) !important;
    border-radius: 14px !important;
    width: min(420px, 92vw) !important;
    overflow: hidden !important;
    box-shadow: 0 20px 60px rgba(0,0,0,0.55) !important;
    animation: contentReveal 0.28s cubic-bezier(0.22,1,0.36,1) both !important;
}

.profile-modal-header {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    padding: 1.1rem 1.3rem 0.8rem !important;
    border-bottom: 1px solid rgba(120,180,90,0.10) !important;
}

.profile-modal-header h3 {
    font-family: 'Cinzel', serif !important;
    font-size: 1rem !important;
    color: var(--accent-gold, #a080e0) !important;
    margin: 0 !important;
    letter-spacing: 0.08em !important;
}

.profile-modal-close {
    background: transparent !important;
    border: none !important;
    color: rgba(160,200,130,0.55) !important;
    cursor: pointer !important;
    padding: 0.3rem !important;
    border-radius: 6px !important;
    transition: color 0.2s !important;
    display: flex !important;
}

.profile-modal-close:hover { color: rgba(200,240,160,0.9) !important; }

/* Avatar grande */
.profile-modal-avatar-zone {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    gap: 0.55rem !important;
    padding: 1.2rem 1.3rem 0.6rem !important;
}

.profile-modal-avatar-wrap {
    width: 80px !important;
    height: 80px !important;
    border-radius: 50% !important;
    background: rgba(60,100,45,0.35) !important;
    border: 2px solid rgba(120,190,90,0.35) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer !important;
    position: relative !important;
    overflow: hidden !important;
    transition: border-color 0.22s ease !important;
}

.profile-modal-avatar-wrap:hover { border-color: rgba(160,230,110,0.65) !important; }

.profile-modal-initial {
    font-family: 'Cinzel', serif !important;
    font-size: 1.8rem !important;
    font-weight: 700 !important;
    color: #9ec88e !important;
}

.profile-modal-avatar-img {
    position: absolute !important;
    inset: 0 !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
}

.profile-modal-avatar-overlay {
    position: absolute !important;
    inset: 0 !important;
    background: rgba(0,0,0,0.45) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    opacity: 0 !important;
    transition: opacity 0.2s !important;
    color: white !important;
}

.profile-modal-avatar-wrap:hover .profile-modal-avatar-overlay { opacity: 1 !important; }

.profile-modal-remove-avatar {
    background: transparent !important;
    border: none !important;
    color: rgba(200,100,100,0.6) !important;
    font-size: 0.72rem !important;
    cursor: pointer !important;
    letter-spacing: 0.04em !important;
    transition: color 0.2s !important;
}
.profile-modal-remove-avatar:hover { color: rgba(230,110,110,0.9) !important; }

/* Campos del formulario */
.profile-modal-fields {
    padding: 0.4rem 1.3rem 0.8rem !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 0.75rem !important;
}

.pm-field {
    display: flex !important;
    flex-direction: column !important;
    gap: 0.3rem !important;
}

.pm-field label {
    font-size: 0.72rem !important;
    text-transform: uppercase !important;
    letter-spacing: 0.1em !important;
    color: rgba(160,200,130,0.6) !important;
    font-family: 'Cinzel', serif !important;
}

.pm-input-row {
    display: flex !important;
    gap: 0.5rem !important;
}

.pm-input, .pm-select, .pm-date {
    flex: 1 !important;
    background: rgba(255,255,255,0.05) !important;
    border: 1px solid rgba(120,180,90,0.20) !important;
    border-radius: 7px !important;
    color: var(--text-primary, #e8e0d0) !important;
    font-size: 0.88rem !important;
    padding: 0.5rem 0.7rem !important;
    outline: none !important;
    transition: border-color 0.2s !important;
    font-family: inherit !important;
}

.pm-input:focus, .pm-select:focus, .pm-date:focus {
    border-color: rgba(140,210,100,0.50) !important;
}

.pm-select option { background: #1a2018; }

.pm-save-btn {
    background: rgba(70,120,50,0.35) !important;
    border: 1px solid rgba(120,190,90,0.30) !important;
    color: #9ec88e !important;
    border-radius: 7px !important;
    padding: 0.5rem 0.9rem !important;
    font-size: 0.78rem !important;
    font-family: 'Cinzel', serif !important;
    cursor: pointer !important;
    transition: all 0.2s ease !important;
    white-space: nowrap !important;
}

.pm-save-btn:hover {
    background: rgba(80,140,55,0.55) !important;
    border-color: rgba(150,220,100,0.55) !important;
}

.pm-close-btn {
    display: block !important;
    width: calc(100% - 2.6rem) !important;
    margin: 0 1.3rem 1.1rem !important;
    padding: 0.65rem !important;
    background: rgba(60,100,45,0.40) !important;
    border: 1px solid rgba(120,190,90,0.28) !important;
    border-radius: 8px !important;
    color: #a8d890 !important;
    font-family: 'Cinzel', serif !important;
    font-size: 0.82rem !important;
    letter-spacing: 0.08em !important;
    cursor: pointer !important;
    transition: all 0.2s ease !important;
}

.pm-close-btn:hover {
    background: rgba(80,140,55,0.55) !important;
    border-color: rgba(150,220,100,0.55) !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   BOTÓN SALIR Y RESPONSIVE
   ══════════════════════════════════════════════════════════════════════════ */


.menu-exit-btn {
    position: fixed !important;
    bottom: calc(1.2rem + env(safe-area-inset-bottom, 0px)) !important;
    right: calc(1.5rem + env(safe-area-inset-right, 0px)) !important;
    display: flex !important;
    align-items: center !important;
    gap: 0.4rem !important;
    background: rgba(0,0,0,0.45) !important;
    border: 1px solid rgba(180,70,70,0.22) !important;
    color: rgba(200,100,100,0.55) !important;
    padding: 0.4rem 0.85rem !important;
    border-radius: 7px !important;
    cursor: pointer !important;
    font-family: 'Cinzel', serif !important;
    font-size: 0.72rem !important;
    letter-spacing: 0.06em !important;
    backdrop-filter: blur(10px) !important;
    transition: all 0.22s ease !important;
    margin: 0 !important;
    z-index: var(--z-i-20)!important;
}

.menu-exit-btn:hover {
    background: rgba(120,30,30,0.4) !important;
    border-color: rgba(200,75,75,0.5) !important;
    color: rgba(230,110,110,0.9) !important;
}

/* ══════════════════════════════════════════════════════════════════════════
   ANIMACIÓN ENTRADA GENERAL
   ══════════════════════════════════════════════════════════════════════════ */

@keyframes sidebarReveal {
    from { opacity: 0; filter: blur(4px); }
    to   { opacity: 1; filter: blur(0);   }
}

.main-menu:not(.hidden) .menu-center-content {
    animation: contentReveal 0.8s cubic-bezier(0.22, 1, 0.36, 1) both;
}

/* ══════════════════════════════════════════════════════════════════════════
   RESPONSIVE
   ══════════════════════════════════════════════════════════════════════════ */

@media (max-width: 600px) {
    :root {
        --menu-btn-w: 88vw;
        --menu-btn-h: 58px;
    }
    .menu-title {
        font-size: clamp(2.8rem, 12vw, 4rem) !important;
    }
    .menu-subtitle {
        font-size: 0.65rem !important;
        letter-spacing: 0.25em !important;
    }
    .menu-brand {
        margin-bottom: 1.6rem !important;
    }
    .menu-container {
        gap: 0.45rem !important;
    }
    /* En móvil pequeño (Honor X7, etc.): footer en columna para evitar solapamientos */
    .menu-footer {
        bottom: calc(0.6rem + env(safe-area-inset-bottom, 0px)) !important;
        flex-direction: row !important;
        align-items: center !important;
        gap: 0.4rem !important;
        left: 0.6rem !important;
        right: 0.6rem !important;
        transform: none !important;
        width: auto !important;
    }

    .menu-profile-btn {
        flex: 1 1 auto !important;
        min-width: 0 !important;
    }

    .menu-profile-name {
        max-width: 38vw !important;
        overflow: hidden !important;
        text-overflow: ellipsis !important;
        white-space: nowrap !important;
    }

    .menu-profile-hint {
        display: none !important;
    }

    /* Botón salir: fixed encima del footer en móvil (no superpuesto) */
    .menu-exit-btn {
        bottom: calc(4.4rem + env(safe-area-inset-bottom, 0px)) !important;
        right: calc(0.7rem + env(safe-area-inset-right, 0px)) !important;
        padding: 0.3rem 0.55rem !important;
        font-size: 0.65rem !important;
    }

    /* Botón de guardado más compacto */
    .menu-save-btn {
        width: 32px !important;
        height: 32px !important;
        flex: 0 0 32px !important;
    }

    /* Buzón junto al botón de tema arriba */
    .menu-inbox-float {
        top: 0.6rem !important;
        right: 3.6rem !important;
        width: 36px !important;
        height: 36px !important;
    }

    .pwa-standalone .menu-center-content,
    body.is-pwa .menu-center-content {
        max-height: calc(100vh - 100px
            - env(safe-area-inset-bottom, 0px)
            - env(safe-area-inset-top, 0px));
        max-height: calc(100dvh - 100px
            - env(safe-area-inset-bottom, 0px)
            - env(safe-area-inset-top, 0px));
        padding-top: 8px;
    }
}

@media (max-width: 900px) and (orientation: landscape) {
    .menu-footer {
        left: calc(0.8rem + env(safe-area-inset-left, 0px)) !important;
        right: calc(4.8rem + env(safe-area-inset-right, 0px)) !important;
        bottom: calc(0.6rem + env(safe-area-inset-bottom, 0px)) !important;
        transform: none !important;
        justify-content: flex-start !important;
        max-width: none !important;
    }

    .menu-profile-btn {
        flex: 1 1 auto !important;
        min-width: 0 !important;
    }

    .menu-profile-name {
        max-width: 40vw;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .menu-exit-btn {
        top: calc(0.7rem + env(safe-area-inset-top, 0px)) !important;
        right: calc(0.8rem + env(safe-area-inset-right, 0px)) !important;
        bottom: auto !important;
        padding: 0.34rem 0.66rem !important;
    }
}

@media (min-width: 601px) and (max-width: 900px) {
    :root { --menu-btn-w: 340px; }
    .menu-title { font-size: clamp(3rem, 7vw, 5rem) !important; }
}

/* ── Botón día/noche en el menú principal ───────────────────────────────── */
.menu-theme-toggle {
    position: absolute !important;
    top: 1.2rem !important;
    right: 1.4rem !important;
    z-index: 50 !important;
    width: 42px !important;
    height: 42px !important;
    border-radius: 50% !important;
    border: 1.5px solid rgba(255,255,255,0.18) !important;
    background: rgba(0,0,0,0.35) !important;
    backdrop-filter: blur(8px) !important;
    cursor: pointer !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 1.1rem !important;
    transition: background 0.3s, border-color 0.3s, transform 0.2s !important;
    pointer-events: all !important;
}

.menu-theme-toggle:hover {
    background: rgba(255,255,255,0.12) !important;
    border-color: rgba(255,255,255,0.35) !important;
    transform: scale(1.1) !important;
}

[data-theme="light"] .menu-theme-toggle {
    background: rgba(255,240,200,0.35) !important;
    border-color: rgba(180,120,20,0.4) !important;
}


/* -- css/options.css -- */
/* ============================================
   OPTIONS MENU — Menú tipo videojuego con tabs
   ============================================ */

/* ── Sección base ───────────────────────────────────────────────────────── */
#optionsSection {
    background:
        linear-gradient(165deg, rgba(6, 5, 4, 0.94) 0%, rgba(19, 15, 11, 0.94) 54%, rgba(7, 6, 4, 0.95) 100%),
        radial-gradient(circle at 78% 18%, rgba(201, 168, 108, 0.1) 0%, transparent 52%),
        radial-gradient(circle at 18% 84%, rgba(130, 80, 38, 0.08) 0%, transparent 48%);
    min-height: 100vh;
    min-height: 100dvh;
    /* display gestionado por .game-section { display:none } y .game-section.active { display:flex }
       NO sobreescribir aquí — un ID selector tiene mayor especificidad que .game-section
       y causaría que la sección fuera siempre visible. */
    flex-direction: column;
}
/* Solo visible cuando el sistema de navegación añade .active */
#optionsSection.active {
    display: flex;
}

#optionsSection .section-header-bar {
    background: linear-gradient(90deg, rgba(201,168,108,0.12) 0%, transparent 100%);
    border-bottom: 1px solid rgba(201,168,108,0.18);
    padding: 1.1rem 2rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-shrink: 0;
}
#optionsSection .section-title {
    font-family: 'Cinzel', serif;
    font-size: 1.45rem;
    color: #c9a86c;
    margin: 0;
    letter-spacing: 0.08em;
}
.section-header-left {
    display: flex;
    align-items: center;
    gap: 0.65rem;
}
.section-header-breadcrumb {
    color: rgba(201,168,108,0.35);
    font-size: 1.1rem;
}
.back-button {
    padding: 0.6rem 1.25rem;
    border: 1px solid rgba(201,168,108,0.3);
    border-radius: 8px;
    background: rgba(201,168,108,0.08);
    color: #c9a86c;
    font-family: 'Cinzel', serif;
    font-size: 0.88rem;
    cursor: pointer;
    transition: all 0.2s ease;
    letter-spacing: 0.06em;
}
.back-button:hover {
    background: rgba(201,168,108,0.16);
    border-color: #c9a86c;
    transform: translateX(-3px);
}

/* ════════ TAB BAR ════════ */
.opt-tab-bar {
    display: flex;
    align-items: stretch;
    border-bottom: 1px solid rgba(201,168,108,0.12);
    background: rgba(0,0,0,0.25);
    padding: 0 1.5rem;
    flex-shrink: 0;
    overflow-x: auto;
    scrollbar-width: none;
}
.opt-tab-bar::-webkit-scrollbar { display: none; }

.opt-tab {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.85rem 1.4rem;
    background: none;
    border: none;
    border-bottom: 2px solid transparent;
    color: rgba(201,168,108,0.45);
    font-family: 'Cinzel', serif;
    font-size: 0.82rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    cursor: pointer;
    transition: color 0.2s, border-color 0.2s, background 0.2s;
    white-space: nowrap;
    position: relative;
    top: 1px;
}
.opt-tab:hover { color: rgba(201,168,108,0.75); background: rgba(201,168,108,0.04); }
.opt-tab.active { color: #c9a86c; border-bottom-color: #c9a86c; background: rgba(201,168,108,0.06); }
.opt-tab-icon { font-size: 1rem; line-height: 1; }

/* ════════ PANELES ════════ */
.opt-panels {
    flex: 1;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: rgba(201,168,108,0.15) transparent;
}
.opt-panels::-webkit-scrollbar { width: 4px; }
.opt-panels::-webkit-scrollbar-thumb { background: rgba(201,168,108,0.15); border-radius: 4px; }

.opt-panel { display: none; max-width: 600px; margin: 0 auto; padding: 2rem 2rem 3rem; }
.opt-panel.active { display: block; }

.opt-section-title {
    font-family: 'Cinzel', serif;
    font-size: 0.72rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
    color: rgba(201,168,108,0.45);
    margin-bottom: 1.25rem;
    padding-bottom: 0.6rem;
    border-bottom: 1px solid rgba(201,168,108,0.1);
}

/* ── Filas ─── */
.opt-rows { display: flex; flex-direction: column; }

.option-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1.5rem;
    padding: 1rem 0;
    border-bottom: 1px solid rgba(255,255,255,0.035);
}
.option-row:last-child { border-bottom: none; }
.opt-row-stacked { flex-direction: column; align-items: flex-start; gap: 0.6rem; }
.opt-row-filters { flex-wrap: wrap; gap: 0.75rem; }

.option-label {
    font-size: 0.92rem;
    color: rgba(232,213,163,0.82);
    font-weight: 500;
    flex-shrink: 0;
}

/* Toggle tema */
.opt-toggle-btn {
    padding: 0.5rem 1.1rem;
    border: 1px solid rgba(201,168,108,0.3);
    border-radius: 8px;
    background: rgba(201,168,108,0.08);
    color: #c9a86c;
    font-family: 'Cinzel', serif;
    font-size: 0.85rem;
    cursor: pointer;
    transition: all 0.2s;
    white-space: nowrap;
}
.opt-toggle-btn:hover { background: rgba(201,168,108,0.18); border-color: #c9a86c; }

/* Sliders */
.option-slider-wrap { display: flex; align-items: center; gap: 0.9rem; flex: 1; justify-content: flex-end; }
.setting-slider { -webkit-appearance: none; appearance: none; width: 160px; height: 4px; border-radius: 2px; background: rgba(255,255,255,0.12); outline: none; cursor: pointer; }
.setting-slider::-webkit-slider-thumb { -webkit-appearance: none; width: 18px; height: 18px; border-radius: 50%; background: linear-gradient(145deg, #c9a86c, #a88b52); cursor: pointer; box-shadow: 0 2px 8px rgba(201,168,108,0.4); transition: transform 0.15s; }
.setting-slider::-webkit-slider-thumb:hover { transform: scale(1.25); }
.setting-slider::-moz-range-thumb { width: 18px; height: 18px; border-radius: 50%; background: linear-gradient(145deg, #c9a86c, #a88b52); cursor: pointer; border: none; }
.option-slider-val { font-size: 0.85rem; color: #c9a86c; min-width: 42px; text-align: right; font-weight: 600; font-variant-numeric: tabular-nums; }

/* Filtros */
.filter-buttons { display: flex; gap: 0.45rem; flex-wrap: wrap; }
.filter-btn { padding: 0.4rem 0.9rem; border: 1px solid rgba(201,168,108,0.2); border-radius: 6px; background: rgba(0,0,0,0.2); color: rgba(232,213,163,0.6); font-family: 'Cinzel', serif; font-size: 0.8rem; cursor: pointer; transition: all 0.2s; letter-spacing: 0.05em; }
.filter-btn:hover { border-color: rgba(201,168,108,0.45); color: #e8d5a3; background: rgba(201,168,108,0.08); }
.filter-btn.active { background: linear-gradient(145deg, #c9a86c, #a88b52); color: #1a1815; border-color: #c9a86c; font-weight: 700; }

/* Switches */
.opt-switch { position: relative; display: inline-block; width: 50px; height: 27px; flex-shrink: 0; }
.opt-switch input { opacity: 0; width: 0; height: 0; position: absolute; }
.opt-slider { position: absolute; cursor: pointer; inset: 0; background: rgba(255,255,255,0.1); border-radius: 27px; transition: background 0.25s; }
.opt-slider::before { content: ''; position: absolute; height: 20px; width: 20px; left: 3.5px; bottom: 3.5px; background: linear-gradient(145deg, #e8d5a3, #c9a86c); border-radius: 50%; transition: transform 0.25s cubic-bezier(0.34,1.56,0.64,1); box-shadow: 0 2px 6px rgba(0,0,0,0.3); }
.opt-switch input:checked + .opt-slider { background: rgba(201,168,108,0.28); }
.opt-switch input:checked + .opt-slider::before { transform: translateX(23px); background: linear-gradient(145deg, #c9a86c, #a88b52); }
.opt-switch-slider { position: absolute; cursor: pointer; inset: 0; background: rgba(255,255,255,0.1); border-radius: 27px; transition: background 0.25s; }
.opt-switch-slider::before { content: ''; position: absolute; height: 20px; width: 20px; left: 3.5px; bottom: 3.5px; background: linear-gradient(145deg, #e8d5a3, #c9a86c); border-radius: 50%; transition: transform 0.25s cubic-bezier(0.34,1.56,0.64,1); box-shadow: 0 2px 6px rgba(0,0,0,0.3); }
.opt-switch input:checked + .opt-switch-slider { background: rgba(201,168,108,0.28); }
.opt-switch input:checked + .opt-switch-slider::before { transform: translateX(23px); background: linear-gradient(145deg, #c9a86c, #a88b52); }

/* ════════ PERFIL ════════ */
.opt-profile-avatar-zone {
    display: flex;
    align-items: center;
    gap: 1.5rem;
    padding: 1.25rem 0 1.75rem;
    border-bottom: 1px solid rgba(201,168,108,0.1);
    margin-bottom: 0.25rem;
}
.opt-avatar-preview {
    position: relative;
    width: 80px;
    height: 80px;
