.opt-date-input:focus { border-color: rgba(201,168,108,0.55); }
.opt-birthday-hint { font-size: 0.82rem; color: rgba(201,168,108,0.55); font-style: italic; }

/* ════════ TARJETAS DE PERFIL ════════ */
.user-avatar-wrap {
    width: 72px; height: 72px; border-radius: 50%;
    background: linear-gradient(135deg, rgba(120, 90, 180, 0.18), rgba(12, 9, 28, 0.55));
