.user-avatar-wrap img { width: 100%; height: 100%; object-fit: cover; }
.user-avatar-wrap .user-avatar-initials {
    font-family: 'Cinzel', serif;
    font-size: 1.55rem;
    color: rgba(185, 160, 240, 0.65);
}
.user-gender-badge {
    display: inline-block;
    font-size: 0.65rem;
    padding: 0.12rem 0.5rem;
    border-radius: 20px;
    background: rgba(120, 90, 180, 0.08);
    border: 1px solid rgba(140, 110, 200, 0.18);
    color: rgba(185, 162, 235, 0.72);
    font-family: 'Cinzel', serif;
