}
.user-birthday-row { font-size: 0.72rem; color: rgba(185, 162, 220, 0.52); margin-top: 0.15rem; }

/* ════════ PWA LANDSCAPE sidebar nav ════════ */
@media (orientation: landscape) and (min-width: 700px) {
    body.is-pwa #optionsSection { flex-direction: row; }
    body.is-pwa #optionsSection .section-header-bar { display: none; }
    body.is-pwa .opt-tab-bar { flex-direction: column; width: 180px; flex-shrink: 0; border-bottom: none; border-right: 1px solid rgba(201,168,108,0.12); padding: 1.5rem 0; overflow-y: auto; overflow-x: hidden; gap: 2px; }
    body.is-pwa .opt-tab { border-bottom: none; border-right: 2px solid transparent; padding: 0.85rem 1.25rem; top: 0; justify-content: flex-start; }
    body.is-pwa .opt-tab.active { border-right-color: #c9a86c; border-bottom: none; }
    body.is-pwa .opt-panels { flex: 1; }
}

/* ════════ RESPONSIVE móvil ════════ */
@media (max-width: 600px) {
    #optionsSection .section-header-bar { padding: 0.85rem 1rem; }
    #optionsSection .section-title { font-size: 1.2rem; }
    .opt-tab-bar { padding: 0 0.5rem; }
    .opt-tab { padding: 0.75rem 0.9rem; font-size: 0.76rem; gap: 0.35rem; }
    .opt-tab-label { display: none; }
    .opt-panel { padding: 1.25rem 1rem 2rem; }
    .setting-slider { width: 120px; }
    .opt-profile-avatar-zone { flex-direction: column; align-items: center; text-align: center; gap: 0.75rem; }
    .opt-avatar-actions { align-items: center; }
    .opt-birthday-wrap { flex-wrap: wrap; }
}

/* Decoración fondo */
#optionsSection::before { content: ''; position: fixed; inset: 0; background: linear-gradient(180deg, rgba(8,7,5,0.78) 0%, rgba(8,7,5,0.62) 100%), radial-gradient(ellipse at 10% 20%, rgba(201,168,108,0.07) 0%, transparent 45%), radial-gradient(ellipse at 90% 80%, rgba(201,168,108,0.06) 0%, transparent 45%); pointer-events: none; z-index: var(--z-i-0); }
#optionsSection > * { position: relative; z-index: var(--z-i-1); }
[data-theme="light"] #optionsSection {
    background:
        linear-gradient(168deg, rgba(235, 224, 203, 0.92) 0%, rgba(216, 198, 168, 0.93) 52%, rgba(227, 212, 187, 0.94) 100%),
        radial-gradient(circle at 82% 24%, rgba(164, 119, 63, 0.2) 0%, transparent 52%),
        radial-gradient(circle at 20% 78%, rgba(128, 84, 36, 0.16) 0%, transparent 46%);
}
[data-theme="light"] #optionsSection::before {
    background: linear-gradient(180deg, rgba(251, 247, 238, 0.76) 0%, rgba(242, 232, 214, 0.7) 100%);
}


/* -- css/mascot.css -- */
/* ============================================
   ETHY - La mascota guía de Etheria
   ============================================ */

/* Contenedor principal de Ethy */
.ethy-container {
    position: fixed;
    bottom: 20px;
    right: 20px;
    z-index: var(--z-max);
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    pointer-events: none;
    opacity: 1;
    transform: scale(1);
    transition: opacity 0.3s ease, transform 0.3s ease;
}

.ethy-container.active {
    pointer-events: auto;
}

/* Posición alternativa: cerca del perfil en el menú */
.ethy-container.near-profile {
    bottom: 80px;
    right: auto;
    left: 400px;
}

/* En pantallas pequeñas, mantener posición original */
@media (max-width: 1024px) {
    .ethy-container.near-profile {
        bottom: 20px;
        right: 20px;
        left: auto;
    }
}

/* ── Cuerpo de Ethy — SVG ────────────────────────────────────────────────── */
/* .ethy-float-wrapper tiene la animación de flotación.                      */
/* .ethy-body es hijo y solo lleva expresiones (transform libre de animación)*/

.ethy-float-wrapper {
    animation: ethyFloat 3s ease-in-out infinite;
    display: inline-block;
    line-height: 0;
}

.ethy-body {
    pointer-events: auto;
    width: 80px;
    height: 80px;
    position: relative;
    cursor: grab;
    transition: transform 0.3s cubic-bezier(0.68, -0.55, 0.265, 1.55), opacity 0.3s ease,
                filter 0.3s ease;
    filter: drop-shadow(0 4px 18px rgba(124, 77, 255, 0.28))
            drop-shadow(0 0 8px rgba(157, 107, 255, 0.18));
}
[data-theme="light"] .ethy-body {
    filter: drop-shadow(0 4px 14px rgba(100, 60, 200, 0.28))
            drop-shadow(0 0 10px rgba(140, 100, 230, 0.18))
            contrast(1.08) saturate(1.12);
}

.ethy-body:hover {
    transform: scale(1.1);
    filter: drop-shadow(0 6px 22px rgba(124, 77, 255, 0.45))
            drop-shadow(0 0 14px rgba(183, 148, 246, 0.30));
}
.ethy-body:active { transform: scale(0.95); }

/* SVG inline de Ethy */
.ethy-svg {
    width: 100%;
    height: 100%;
    overflow: visible;
}

/* Transiciones de grupos de ojos y boca */
.ethy-svg [class^="ethy-eyes-"],
.ethy-svg [class^="ethy-mouth-"],
.ethy-svg .ethy-part-cheeks {
    transition: opacity 0.28s ease;
}

/* Blink sigue usando ethy-eye-left/right dentro del grupo activo */
.ethy-svg .ethy-eye-left,
.ethy-svg .ethy-eye-right {
    transform-box: fill-box;
    transform-origin: center;
}

/* Antena — estática, sin rotación.
   La vibración causaba artefactos visuales. El glow del filtro excited la anima. */

/* Parpadeo automático */
@keyframes ethyBlink {
    0%, 90%, 100% { transform: scaleY(1); }
    95%           { transform: scaleY(0.08); }
}
.ethy-blinking .ethy-eye-left,
.ethy-blinking .ethy-eye-right {
    animation: ethyBlink 0.18s ease-in-out forwards;
    transform-box: fill-box;
    transform-origin: center;
}

/* Animación de flotación */
@keyframes ethyFloat {
    0%, 100% { transform: translateY(0) rotate(0deg); }
    25%       { transform: translateY(-8px) rotate(-2deg); }
    50%       { transform: translateY(-4px) rotate(0deg); }
    75%       { transform: translateY(-10px) rotate(2deg); }
}

/* Expresiones — solo filtros de color, sin transforms en el body
   (los transforms en .ethy-body rompían las animaciones de cara y causaban
   rotaciones que daban aspecto uncanny; el JS ya anima las partes del SVG) */
.ethy-expression-neutral    { /* base */ }

.ethy-expression-happy {
    filter: drop-shadow(0 0 10px rgba(124, 77, 255, 0.35))
            brightness(1.12) saturate(1.20);
}

.ethy-expression-excited {
    filter: drop-shadow(0 0 14px rgba(157, 107, 255, 0.50))
            brightness(1.18) saturate(1.45);
    animation: ethyExcitedBounce 0.55s ease-in-out infinite;
}

.ethy-expression-sad {
    filter: brightness(0.80) saturate(0.50);
}

.ethy-expression-surprised {
    filter: drop-shadow(0 0 12px rgba(183, 148, 246, 0.45))
            brightness(1.12);
}

.ethy-expression-thoughtful {
    filter: brightness(0.90) saturate(0.80) hue-rotate(10deg);
}

.ethy-expression-wink {
    filter: drop-shadow(0 0 8px rgba(124, 77, 255, 0.30))
            brightness(1.10) saturate(1.15);
}

.ethy-expression-love {
    filter: drop-shadow(0 0 12px rgba(183, 148, 246, 0.40))
            brightness(1.10) saturate(1.50) hue-rotate(-10deg);
}

.ethy-expression-mystic {
    filter: drop-shadow(0 0 14px rgba(183, 148, 246, 0.55))
            brightness(1.10) saturate(1.20);
}

.ethy-expression-saving {
    filter: drop-shadow(0 0 12px rgba(143, 224, 194, 0.45))
            brightness(1.08) saturate(1.15);
}

/* Bounce suave sin rotaciones */
@keyframes ethyExcitedBounce {
    0%, 100% { transform: translateY(0); }
    50%       { transform: translateY(-5px); }
}

/* Burbuja de diálogo */
.ethy-speech-bubble {
    position: absolute;
    bottom: 100%;
    right: 0;
    margin-bottom: 12px;
    background: linear-gradient(160deg, rgba(30, 20, 56, 0.94) 0%, rgba(16, 10, 38, 0.96) 100%);
    border: 1px solid rgba(124, 77, 255, 0.38);
    /* Misma familia de forma que .ethy-tutorial-panel: esquina inferior
       derecha achatada como guiño direccional hacia el avatar, en vez del
       clip-path de burbuja de cómic que usaba antes. */
    border-radius: 14px 14px 4px 14px;
    padding: 12px 18px 16px;
    min-width: 240px;
    max-width: 340px;
    color: #f3eeff;
    font-family: 'Cormorant Garamond', 'Crimson Text', serif;
    font-size: 0.88rem;
    line-height: 1.65;
    box-shadow:
        0 8px 32px rgba(0, 0, 0, 0.50),
        0 0 0 1px rgba(124, 77, 255, 0.12) inset,
        0 0 26px rgba(124, 77, 255, 0.16);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    opacity: 0;
    transform: translateY(18px) scale(0.92);
    transition: all 0.38s cubic-bezier(0.34, 1.56, 0.64, 1);
    pointer-events: auto;
}

.ethy-speech-bubble.visible {
    opacity: 1;
    transform: translateY(0) scale(1);
}

.ethy-speech-bubble::before,
.ethy-speech-bubble::after {
    display: none;
}

/* Título en la burbuja — banda de cabecera separada, como en .ethy-tp-header */
.ethy-speech-bubble .ethy-title {
    font-family: 'Outfit', sans-serif;
    font-size: 0.625rem;
    font-weight: 700;
    color: var(--cel-gold, #e8c878);
    margin: 0 -18px 10px;
    padding: 0 18px 8px;
    border-bottom: 1px solid rgba(124, 77, 255, 0.16);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
    letter-spacing: 0.28em;
    text-transform: uppercase;
}
.ethy-title-label {
    display: flex;
    align-items: center;
    gap: 6px;
}
.ethy-title-gem {
    font-size: 0.55rem;
    color: var(--cel-gold, #e8c878);
    line-height: 1;
}
.ethy-bubble-close {
    background: none;
    border: none;
    color: rgba(203, 182, 255, 0.55);
    cursor: pointer;
    font-size: 0.7rem;
    letter-spacing: 0;
    text-transform: none;
    padding: 2px 4px;
    border-radius: 4px;
    line-height: 1;
    transition: color 0.15s, background 0.15s;
    flex-shrink: 0;
}
.ethy-bubble-close:hover {
    color: rgba(244, 217, 138, 1);
    background: rgba(124, 77, 255, 0.20);
}

/* Botones de acción en la burbuja */
.ethy-actions {
    display: flex;
    gap: 10px;
    margin-top: 15px;
    flex-wrap: wrap;
}

.ethy-btn {
    padding: 7px 14px;
    border: 1px solid rgba(124, 77, 255, 0.45);
    background: rgba(124, 77, 255, 0.08);
    color: rgba(203, 182, 255, 0.9);
    border-radius: 9px;
    cursor: pointer;
    font-family: 'Cinzel', serif;
    font-size: 0.78rem;
    letter-spacing: 0.04em;
    box-shadow: inset 0 1px 0 rgba(203, 182, 255, 0.10);
    transition: background 0.18s, border-color 0.18s, color 0.18s, box-shadow 0.18s;
}

.ethy-btn:hover {
    background: rgba(124, 77, 255, 0.20);
    border-color: rgba(183, 148, 246, 0.75);
    color: rgba(245, 215, 120, 1);
    box-shadow: inset 0 1px 0 rgba(245, 215, 120, 0.14);
}

.ethy-btn.primary {
    background: rgba(124, 77, 255, 0.22);
    border-color: rgba(183, 148, 246, 0.70);
    color: rgba(244, 217, 138, 1);
    box-shadow: inset 0 1px 0 rgba(244, 217, 138, 0.16);
}

.ethy-btn.primary:hover {
    background: rgba(124, 77, 255, 0.34);
    border-color: rgba(244, 217, 138, 0.90);
    box-shadow: inset 0 1px 0 rgba(244, 217, 138, 0.22);
}

/* Textarea del formulario de sugerencias */
.ethy-feedback-input {
    width: 100%;
    min-height: 72px;
    resize: vertical;
    background: rgba(0, 0, 0, 0.22);
    border: 1px solid rgba(124, 77, 255, 0.34);
    border-radius: 6px;
    padding: 8px 10px;
    color: #f3eeff;
    font-family: 'Cormorant Garamond', 'Crimson Text', serif;
    font-size: 0.88rem;
    line-height: 1.5;
}
.ethy-feedback-input:focus {
    outline: none;
    border-color: rgba(183, 148, 246, 0.75);
}
.ethy-feedback-input::placeholder {
    color: rgba(203, 182, 255, 0.45);
}

/* Indicador de pasos */
.ethy-steps {
    display: flex;
    gap: 5px;
    margin-top: 10px;
    justify-content: center;
}

.ethy-step {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: rgba(124, 77, 255, 0.2);
    transition: all 0.3s ease;
}

.ethy-step.active {
    background: var(--cel-violet, #7c4dff);
    transform: scale(1.2);
}

.ethy-step.completed {
    background: #27ae60;
}

/* Modo minimalista (solo el icono) */
.ethy-container.minimal .ethy-speech-bubble {
    display: none;
}

.ethy-container.minimal .ethy-body {
    width: 50px;
    height: 50px;
}

/* Animaciones especiales */

/* Saludo inicial */
.ethy-hello {
    animation: ethyHello 0.6s ease;
}

@keyframes ethyHello {
    0% { transform: scale(0) rotate(-180deg); }
    50% { transform: scale(1.2) rotate(10deg); }
    100% { transform: scale(1) rotate(0deg); }
}

/* Despedida */
.ethy-bye {
    animation: ethyBye 0.5s ease forwards;
}

@keyframes ethyBye {
    0% { transform: scale(1); opacity: 1; }
    100% { transform: scale(0) rotate(180deg); opacity: 0; }
}

/* Señalar elemento */
.ethy-pointing::before {
    content: '☞';
    position: absolute;
    font-size: 2rem;
    color: var(--cel-gold, #e8c878);
    animation: ethyPoint 1s ease-in-out infinite;
}

@keyframes ethyPoint {
    0%, 100% { transform: translateX(0); }
    50% { transform: translateX(10px); }
}

/* Efecto de ondas al aparecer */
.ethy-ripple {
    position: absolute;
    width: 100%;
    height: 100%;
    border-radius: inherit;
    border: 2px solid var(--cel-violet, #7c4dff);
    animation: ethyRipple 1s ease-out forwards;
    pointer-events: none;
}

@keyframes ethyRipple {
    0% { transform: scale(1); opacity: 1; }
    100% { transform: scale(1.5); opacity: 0; }
}

/* Responsive */
@media (max-width: 768px) {
    .ethy-container {
        bottom: 10px;
        right: 10px;
    }

    .ethy-body {
        width: 60px;
        height: 60px;
    }

    .ethy-speech-bubble {
        min-width: 220px;
        max-width: min(280px, calc(100vw - 30px));
        padding: 10px 15px 14px;
        font-size: 0.85rem;
        /* Fix: anclar a la derecha del viewport sin salirse */
        right: 0;
        left: auto;
    }

    .ethy-speech-bubble .ethy-title {
        margin: 0 -15px 8px;
        padding: 0 15px 8px;
    }

    /* Fix: botones en columna en móvil para evitar overflow horizontal */
    .ethy-actions {
        flex-direction: column;
        gap: 6px;
    }

    .ethy-btn {
        width: 100%;
        padding: 7px 10px;
        font-size: 0.78rem;
        text-align: center;
    }
}

/* Modo oscuro — el diseño nuevo ya es dark-native, ajustes mínimos */
[data-theme="dark"] .ethy-body {
    filter: drop-shadow(0 5px 22px rgba(124, 77, 255, 0.35))
            drop-shadow(0 0 10px rgba(157, 107, 255, 0.18));
}

[data-theme="dark"] .ethy-speech-bubble {
    background: linear-gradient(150deg, rgba(20, 14, 6, 0.99) 0%, rgba(10, 7, 2, 0.99) 100%);
    border-color: rgba(124, 77, 255, 0.50);
    color: #f2e4c0;
}

/* Overlay de enfoque */
.ethy-focus-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.0); /* el oscurecimiento lo hace el box-shadow del highlight */
    z-index: var(--z-notice);
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.4s ease;
}

.ethy-focus-overlay.active {
    opacity: 1;
}

.ethy-focus-overlay .ethy-highlight {
    position: absolute;
    /* Oscurecer todo lo que hay fuera */
    box-shadow: 0 0 0 9999px rgba(0, 0, 0, 0.82);
    border-radius: 10px;
    transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
    /* Borde dorado brillante para que el elemento destaque claramente */
    outline: 2px solid rgba(124, 77, 255, 0.9);
    outline-offset: 2px;
    /* Brillo alrededor del elemento señalado */
    filter: drop-shadow(0 0 12px rgba(124, 77, 255, 0.6))
            drop-shadow(0 0 24px rgba(124, 77, 255, 0.2));
    animation: ethySpotlightPulse 2s ease-in-out infinite;
}

@keyframes ethySpotlightPulse {
    0%, 100% {
        outline-color: rgba(124, 77, 255, 0.9);
        filter: drop-shadow(0 0 10px rgba(124, 77, 255, 0.5))
                drop-shadow(0 0 22px rgba(124, 77, 255, 0.22));
    }
    50% {
        outline-color: rgba(232, 213, 163, 1);
        filter: drop-shadow(0 0 16px rgba(124, 77, 255, 0.85))
                drop-shadow(0 0 32px rgba(124, 77, 255, 0.45));
    }
}

/* Animación de escritura */
.ethy-typing {
    display: inline-flex;
    gap: 3px;
    margin-left: 5px;
}

.ethy-typing span {
    width: 6px;
    height: 6px;
    background: var(--cel-violet, #7c4dff);
    border-radius: 50%;
    animation: ethyTyping 1.4s ease-in-out infinite;
}

.ethy-typing span:nth-child(2) {
    animation-delay: 0.2s;
}

.ethy-typing span:nth-child(3) {
    animation-delay: 0.4s;
}

@keyframes ethyTyping {
    0%, 60%, 100% { transform: translateY(0); }
    30% { transform: translateY(-8px); }
}

/* ── Botón de minimizar ─────────────────────────────────────────────────── */
.ethy-minimize-btn {
    position: absolute;
    top: -6px;
    right: -6px;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: rgba(26, 24, 21, 0.85);
    border: 1px solid rgba(124, 77, 255, 0.5);
    color: rgba(124, 77, 255, 0.9);
    font-size: 14px;
    line-height: 1;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity 0.2s, background 0.2s;
    z-index: var(--z-i-10);
    pointer-events: auto;
    padding: 0;
    font-family: monospace;
}
.ethy-container:hover .ethy-minimize-btn {
    opacity: 1;
}
.ethy-minimize-btn:hover {
    background: rgba(124, 77, 255, 0.22);
}

/* ── Estado minimizado ──────────────────────────────────────────────────── */
.ethy-container.ethy-minimized .ethy-body {
    width: 40px;
    height: 40px;
    opacity: 0.6;
    transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.ethy-container.ethy-minimized:hover .ethy-body {
    opacity: 1;
    transform: scale(1.15);
}
.ethy-container.ethy-minimized .ethy-speech-bubble {
    display: none;
}
.ethy-container.ethy-minimized .ethy-minimize-btn {
    opacity: 1;
    top: -4px;
    right: -4px;
    width: 16px;
    height: 16px;
    font-size: 11px;
}

/* ── Arrastrable ────────────────────────────────────────────────────────── */
.ethy-container.ethy-dragging {
    cursor: grabbing;
    z-index: calc(var(--z-max) + 1);
}
.ethy-container.ethy-dragging .ethy-body {
    transform: scale(1.1) rotate(-5deg);
}
/* cursor: grab ya aplicado en el bloque principal de .ethy-body */

/* ── Estado dormido — ZZZ flotantes ─────────────────────────────────────── */
.ethy-container.ethy-sleeping .ethy-body {
    animation: ethy-doze 3s ease-in-out infinite;
}

@keyframes ethy-doze {
    0%, 100% { transform: rotate(0deg);    }
    25%       { transform: rotate(-4deg);   }
    75%       { transform: rotate(4deg);    }
}

/* ZZZ pseudo-animación via ::before/::after y shadow extra */
.ethy-body.ethy-zzz::before {
    content: 'z';
    position: absolute;
    top: -10px;
    right: -5px;
    font-size: 0.9rem;
    font-weight: bold;
    color: rgba(201, 168, 108, 0.8);
    animation: ethy-zzz1 2s ease-in-out infinite;
    font-family: 'Cinzel', serif;
}
.ethy-body.ethy-zzz::after {
    content: 'z';
    position: absolute;
    top: -22px;
    right: -14px;
    font-size: 1.2rem;
    font-weight: bold;
    color: rgba(124, 77, 255, 0.6);
    animation: ethy-zzz1 2s ease-in-out infinite 0.7s;
    font-family: 'Cinzel', serif;
}

@keyframes ethy-zzz1 {
    0%   { opacity: 0;   transform: translateY(0)    scale(0.7); }
    30%  { opacity: 1;   transform: translateY(-6px)  scale(1);   }
    70%  { opacity: 0.6; transform: translateY(-14px) scale(1.1); }
    100% { opacity: 0;   transform: translateY(-22px) scale(0.8); }
}

/* ── Mobile: minimizar más pequeño ─────────────────────────────────────── */
@media (max-width: 768px) {
    .ethy-minimize-btn {
        opacity: 1; /* Siempre visible en mobile */
        width: 18px;
        height: 18px;
        font-size: 12px;
    }
}

/* ================================================================
   PANEL DE TUTORIALES — independiente de la burbuja de diálogo
   ================================================================ */

.ethy-tutorial-panel {
    position: absolute;
    bottom: calc(100% + 12px); /* justo encima de Ethy */
    right: 0;
    width: 290px;
    background: linear-gradient(160deg,
        rgba(26, 22, 18, 0.97) 0%,
        rgba(20, 17, 14, 0.97) 100%);
    border: 1px solid rgba(201, 168, 108, 0.35);
    border-radius: 14px 14px 4px 14px;
    box-shadow:
        0 8px 32px rgba(0, 0, 0, 0.5),
        0 0 0 1px rgba(201, 168, 108, 0.08) inset;
    padding: 0;
    overflow: hidden;
    opacity: 0;
    transform: translateY(8px) scale(0.97);
    pointer-events: none;
    transition: opacity 0.25s ease, transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
    z-index: var(--z-i-10);
}

.ethy-tutorial-panel.visible {
    opacity: 1;
    transform: translateY(0) scale(1);
    pointer-events: auto;
}

/* Header */
.ethy-tp-header {
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 10px 12px 8px;
    border-bottom: 1px solid rgba(201, 168, 108, 0.15);
    background: rgba(201, 168, 108, 0.06);
}

.ethy-tp-icon {
    color: rgba(201, 168, 108, 0.7);
    font-size: 0.75rem;
    flex-shrink: 0;
}

.ethy-tp-title {
    flex: 1;
    font-family: 'Cinzel', serif;
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.06em;
    color: rgba(124, 77, 255, 0.9);
    text-transform: uppercase;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.ethy-tp-close {
    background: none;
    border: none;
    color: rgba(201, 168, 108, 0.4);
    cursor: pointer;
    font-size: 0.75rem;
    padding: 2px 4px;
    border-radius: 4px;
    line-height: 1;
    transition: color 0.15s, background 0.15s;
    flex-shrink: 0;
}
.ethy-tp-close:hover {
    color: rgba(124, 77, 255, 0.9);
    background: rgba(201, 168, 108, 0.1);
}

/* Contenido — sin animación de tipeo, texto completo */
.ethy-tp-content {
    padding: 13px 14px;
    font-family: 'EB Garamond', Georgia, serif;
    font-size: 0.88rem;
    line-height: 1.6;
    color: rgba(220, 200, 170, 0.92);
    min-height: 60px;
}

/* Footer */
.ethy-tp-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 12px 8px;
    border-top: 1px solid rgba(201, 168, 108, 0.1);
    gap: 8px;
}

/* Dots */
.ethy-tp-dots {
    display: flex;
    gap: 5px;
    align-items: center;
    flex-wrap: wrap;
    flex: 1;
}

.ethy-tp-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: rgba(201, 168, 108, 0.2);
    border: none;
    padding: 0;
    cursor: pointer;
    transition: background 0.2s, transform 0.2s;
    flex-shrink: 0;
}
.ethy-tp-dot:hover {
    background: rgba(124, 77, 255, 0.45);
    transform: scale(1.3);
}
.ethy-tp-dot.done {
    background: rgba(124, 77, 255, 0.45);
}
.ethy-tp-dot.active {
    background: rgba(124, 77, 255, 0.9);
    transform: scale(1.2);
}

/* Botones de navegación */
.ethy-tp-nav {
    display: flex;
    gap: 6px;
    flex-shrink: 0;
}

.ethy-tp-btn {
    background: rgba(201, 168, 108, 0.08);
    border: 1px solid rgba(124, 77, 255, 0.22);
    color: rgba(201, 168, 108, 0.8);
    border-radius: 6px;
    padding: 4px 10px;
    font-size: 0.78rem;
    font-family: 'Cinzel', serif;
    cursor: pointer;
    transition: all 0.15s ease;
    white-space: nowrap;
}
.ethy-tp-btn:hover {
    background: rgba(201, 168, 108, 0.15);
    border-color: rgba(124, 77, 255, 0.5);
    color: rgba(201, 168, 108, 1);
}
.ethy-tp-btn[style*="hidden"] { pointer-events: none; }

.ethy-tp-primary {
    background: rgba(201, 168, 108, 0.18);
    border-color: rgba(124, 77, 255, 0.5);
    color: rgba(201, 168, 108, 1);
}
.ethy-tp-primary:hover {
    background: rgba(201, 168, 108, 0.28);
}
.ethy-tp-finish {
    background: rgba(124, 77, 255, 0.22);
    border-color: rgba(201, 168, 108, 0.7);
}

/* Botón saltar — discreto, debajo del footer */
.ethy-tp-skip {
    display: block;
    width: 100%;
    background: none;
    border: none;
    border-top: 1px solid rgba(201, 168, 108, 0.08);
    color: rgba(124, 77, 255, 0.2);
    font-size: 0.72rem;
    font-family: 'Cinzel', serif;
    letter-spacing: 0.04em;
    padding: 6px;
    cursor: pointer;
    text-align: center;
    transition: color 0.2s, background 0.2s;
}
.ethy-tp-skip:hover {
    color: rgba(124, 77, 255, 0.6);
    background: rgba(201, 168, 108, 0.05);
}

/* Mobile: panel más estrecho */
@media (max-width: 480px) {
    .ethy-tutorial-panel {
        width: 260px;
        right: -10px; /* compensar si Ethy está muy al borde */
    }
    .ethy-tp-content {
        font-size: 0.84rem;
        padding: 10px 12px;
    }
}

/* Si el panel se sale por arriba (Ethy muy arriba), aparece abajo */
.ethy-container.panel-below .ethy-tutorial-panel {
    bottom: auto;
    top: calc(100% + 12px);
    border-radius: 4px 14px 14px 14px;
}


/* -- css/rpg-scene.css -- */
/* ============================================================
   RPG SCENE STYLES
   Estilos para los elementos que RPGRenderer genera al DOM.
   No sobreescribe nada del VN existente — solo añade clases
   nuevas prefijadas con rpg- o vn- específicas del motor RPG.
   ============================================================ */


/* ── Área de elecciones ──────────────────────────────────── */

/* ── Layout base VN + RPG (estructura única de pantalla) ── */
#vnSection .game-frame {
    position: relative;
    width: 100vw;
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
}

#vnSection .scene-layer {
    position: absolute;
    inset: 0;
    z-index: 0;
}

#vnSection .ui-layer {
    --ui-frame-separator: rgba(188, 148, 84, 0.46);
    position: absolute;
    inset: 0;
    z-index: 2;
    display: grid;
    grid-template-areas:
        "left center right"
        "bottom bottom bottom";
    grid-template-columns: 260px 1fr 260px;
    grid-template-rows: 1fr auto;
    gap: 0;
    pointer-events: none;
}

#vnSection .left-panel,
#vnSection .center-panel,
#vnSection .right-panel,
#vnSection .bottom-panel {
    pointer-events: auto;
    margin: 0 !important;
    min-width: 0;
    min-height: 0;
    border-radius: 0 !important;
    box-shadow: none !important;
    background: transparent !important;
    box-sizing: border-box;
}

#vnSection .left-panel {
    grid-area: left;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: stretch;
    border-right: 1px solid var(--ui-frame-separator);
}

#vnSection .center-panel {
    grid-area: center;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

#vnSection .right-panel {
    grid-area: right;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-items: stretch;
    border-left: 1px solid var(--ui-frame-separator);
}

#vnSection .bottom-panel {
    grid-area: bottom;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    align-self: stretch;
    border-top: 1px solid var(--ui-frame-separator);
}

/* Neutralizar look de "tarjeta" en paneles estructurales */
#vnSection .left-panel .vn-info-card,
#vnSection .right-panel .vn-controls,
#vnSection .bottom-panel .vn-dialogue-box,
#vnSection .bottom-panel #vnReplyPanel {
    position: static !important;
    inset: auto !important;
    width: 100% !important;
    max-width: 100% !important;
    margin: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background: transparent !important;
}

#vnChoiceArea {
    display: none;
    flex-direction: column;
    gap: 0.55rem;
    position: absolute;
    bottom: 6rem;
    left: 50%;
    transform: translateX(-50%);
    width: min(520px, 92vw);
    z-index: var(--z-dialogue);
    padding: 0.5rem;
}

.rpg-choice-prompt {
    text-align: center;
    font-size: 0.85rem;
    color: rgba(220, 210, 185, 0.7);
    margin-bottom: 0.2rem;
    letter-spacing: 0.03em;
    text-transform: uppercase;
}

.rpg-choice-btn {
    position: relative;
    width: 100%;
    padding: 0.75rem 1.1rem;
    background: rgba(10, 8, 20, 0.82);
    border: 1px solid rgba(180, 150, 90, 0.35);
    border-radius: 6px;
    color: #e8dcc8;
    font-size: 0.95rem;
    text-align: left;
    cursor: pointer;
    transition: background 0.18s, border-color 0.18s, transform 0.12s;
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
}

.rpg-choice-btn:hover,
.rpg-choice-btn:focus-visible {
    background: rgba(180, 150, 90, 0.18);
    border-color: rgba(180, 150, 90, 0.65);
    transform: translateX(3px);
    outline: none;
}

.rpg-choice-btn:active {
    transform: translateX(1px);
    background: rgba(180, 150, 90, 0.28);
}

/* Coste visible en el botón (e.g. "-5 HP") */
.rpg-choice-cost {
    position: absolute;
    right: 0.9rem;
    top: 50%;
    transform: translateY(-50%);
    font-size: 0.78rem;
    color: #e87a7a;
    opacity: 0.85;
    font-weight: 600;
}

/* Opción disponible por condición especial: tono diferente */
.rpg-choice-btn[data-condition]::before {
    content: attr(data-condition-icon);
    margin-right: 0.4rem;
    opacity: 0.8;
}


/* ── Barra de stats (HP / XP) ────────────────────────────── */

#vnRpgStatBar {
    position: absolute;
    top: 0.8rem;
    right: 0.8rem;
    z-index: var(--z-sprites);
    pointer-events: none;
}

body.mode-rpg #vnRpgStatBar {
    width: min(360px, calc(100vw - 1.4rem));
    display: flex;
    align-items: stretch;
    gap: 0.72rem;
    padding: 0.45rem 0.55rem;
    border-radius: 14px;
    border: 1px solid rgba(190, 158, 100, 0.62);
    background:
        linear-gradient(135deg, rgba(38, 26, 14, 0.92), rgba(19, 13, 8, 0.95)),
        repeating-linear-gradient(90deg, rgba(255, 230, 188, 0.03) 0 2px, transparent 2px 5px);
    box-shadow:
        inset 0 1px 0 rgba(255, 236, 200, 0.12),
        inset 0 -1px 0 rgba(0, 0, 0, 0.5),
        0 10px 24px rgba(0, 0, 0, 0.42);
}

.rpg-stat-avatar {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    border: 2px solid rgba(240, 194, 92, 0.9);
    background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.2), rgba(20,20,24,0.95));
    box-shadow: 0 0 0 2px rgba(39, 23, 9, 0.92), 0 4px 12px rgba(0,0,0,0.5);
    overflow: hidden;
    flex-shrink: 0;
}

.rpg-stat-avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.rpg-stat-body {
    min-width: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 0.4rem;
    flex: 1;
}

.rpg-stat-row {
    display: grid;
    grid-template-columns: 40px 1fr auto;
    align-items: center;
    gap: 0.5rem;
}

.rpg-stat-label {
    font-size: 0.65rem;
    letter-spacing: 0.08em;
    color: rgba(245, 224, 187, 0.86);
    font-weight: 700;
    text-transform: uppercase;
}

.rpg-stat-track {
    height: 11px;
    border-radius: 5px;
    border: 1px solid rgba(12, 8, 5, 0.9);
    background: linear-gradient(180deg, rgba(20, 16, 11, 0.92), rgba(5, 4, 3, 0.95));
    box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.7);
    overflow: hidden;
}

.rpg-stat-fill {
    display: block;
    height: 100%;
    width: 0;
    transition: width 0.25s ease;
}

.rpg-stat-fill--hp {
    background: linear-gradient(90deg, #8d1212 0%, #e53333 55%, #ff8d67 100%);
}

.rpg-stat-fill--xp {
    background: linear-gradient(90deg, #0f3f7a 0%, #2e7ce8 55%, #6db2ff 100%);
}

.rpg-stat-value {
    font-size: 0.7rem;
    font-weight: 700;
    color: rgba(243, 234, 214, 0.95);
    text-shadow: 0 1px 2px rgba(0,0,0,0.65);
}


/* ── Overlay de tirada stat_check ────────────────────────── */

.rpg-stat-check-overlay {
    position: fixed;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: var(--z-controls);
    pointer-events: none;
    animation: rpg-overlay-in 0.2s ease;
}

@keyframes rpg-overlay-in {
    from { opacity: 0; transform: scale(0.88); }
    to   { opacity: 1; transform: scale(1); }
}


/* ── Efectos de cámara ───────────────────────────────────── */

@keyframes vn-shake-kf {
    0%   { transform: translate(0, 0) rotate(0deg); }
    20%  { transform: translate(-4px, 2px) rotate(-0.5deg); }
    40%  { transform: translate(4px, -2px) rotate(0.5deg); }
    60%  { transform: translate(-3px, 1px) rotate(-0.3deg); }
    80%  { transform: translate(3px, -1px) rotate(0.3deg); }
    100% { transform: translate(0, 0) rotate(0deg); }
}

#vnSection.vn-shake {
    animation: vn-shake-kf 0.35s ease;
}

@keyframes vn-flash-kf {
    0%   { filter: brightness(1); }
    30%  { filter: brightness(2.2); }
    100% { filter: brightness(1); }
}

#vnSection.vn-flash {
    animation: vn-flash-kf 0.3s ease;
}


/* ── Clase activa de escena ──────────────────────────────── */

/* Mientras hay una escena RPG activa, el cursor por defecto en el
   área de diálogo indica que hay que hacer clic para avanzar */
#vnSection.rpg-scene-active #vnDialogBox {
    cursor: pointer;
}

#vnSection.rpg-scene-active #vnDialogBox::after {
    content: '▼';
    position: absolute;
    bottom: 0.6rem;
    right: 0.9rem;
    font-size: 0.65rem;
    color: rgba(220, 210, 185, 0.45);
    animation: rpg-bounce 1.4s ease-in-out infinite;
}

/* ── Frame RPG clásico (solo modo RPG) ───────────────────── */
body.mode-rpg #vnSection .vn-info-card {
    border-radius: 14px;
    border: 1px solid rgba(188, 151, 86, 0.62);
    background:
        linear-gradient(180deg, rgba(31, 22, 11, 0.95), rgba(14, 10, 6, 0.94));
    box-shadow:
        inset 0 1px 0 rgba(253, 226, 173, 0.12),
        inset 0 -1px 0 rgba(0, 0, 0, 0.5),
        0 8px 18px rgba(0, 0, 0, 0.42);
}

body.mode-rpg #vnSection .vn-info-card::after {
    content: '';
    position: absolute;
    left: -12px;
    top: -8px;
    bottom: -12px;
    width: 11px;
    border-radius: 9px 0 0 9px;
    border: 1px solid rgba(188, 151, 86, 0.62);
    border-right: none;
    background: linear-gradient(180deg, rgba(125, 91, 40, 0.9), rgba(88, 60, 24, 0.92));
    box-shadow: inset 0 1px 0 rgba(255, 228, 172, 0.16);
}

body.mode-rpg #vnSection .vn-dialogue-box {
    border-radius: 15px;
    border: 2px solid rgba(168, 132, 74, 0.62);
    background:
        linear-gradient(180deg, rgba(24, 17, 11, 0.94), rgba(13, 10, 8, 0.97));
    box-shadow:
        inset 0 0 0 2px rgba(255, 228, 180, 0.05),
        0 12px 30px rgba(0, 0, 0, 0.5);
}

body.mode-rpg #vnSection .vn-controls {
    border: 1px solid rgba(188, 151, 86, 0.58);
    border-radius: 14px;
    background: linear-gradient(180deg, rgba(34, 23, 12, 0.92), rgba(16, 11, 7, 0.96));
    box-shadow: inset 0 1px 0 rgba(255, 225, 170, 0.1), 0 10px 24px rgba(0,0,0,0.44);
    padding: 0.42rem 0.34rem;
}

@keyframes rpg-bounce {
    0%, 100% { transform: translateY(0); }
    50%       { transform: translateY(3px); }
}


/* ── Responsive ──────────────────────────────────────────── */

@media (max-width: 480px) {
    #vnChoiceArea {
        bottom: 4.5rem;
        width: 96vw;
    }

    .rpg-choice-btn {
        font-size: 0.88rem;
        padding: 0.65rem 0.9rem;
    }

    #vnRpgStatBar {
        top: 0.4rem;
        right: 0.4rem;
    }

    body.mode-rpg #vnRpgStatBar {
        width: min(96vw, 330px);
        gap: 0.5rem;
        padding: 0.4rem;
    }

    .rpg-stat-avatar {
        width: 40px;
        height: 40px;
    }

    .rpg-stat-row {
        grid-template-columns: 30px 1fr auto;
        gap: 0.35rem;
    }

    .rpg-stat-label,
    .rpg-stat-value {
        font-size: 0.62rem;
    }
}


/* -- css/features/vn/index.css -- */
/* Feature module: Visual Novel (VN)
 * Art Deco Fantasy themed visual novel components
 */

:root {
    /* === Etheria VN Palette === */
    --etheria-night-deep: #050810;
    --etheria-night-blue: #0a0e1a;
    --etheria-gold-aged: #c9a86c;
    --etheria-gold-light: #f6dda0;
    --etheria-gold-dim: #8a6f3e;
    --etheria-pearl: #e8dfc8;
}

.vn-avatar-frame-speaker {
    width: 140px;
    height: 140px;
    background-image: url('./assets/avatar-frame-speaker.svg');
    background-size: contain;
    background-repeat: no-repeat;
}

.vn-avatar-frame-info {
    width: 86px;
    height: 86px;
    background-image: url('./assets/avatar-frame-info.svg');
    background-size: contain;
}

.vn-dialog-frame {
    background-image: url('./assets/dialog-frame.svg');
    background-size: cover;
    min-height: 200px;
    padding: 20px;
    color: var(--etheria-pearl);
}

.vn-dialog-frame-mobile {
    background-image: url('./assets/dialog-frame.svg');
    background-size: cover;
    min-height: 180px;
    padding: 15px;
    color: var(--etheria-pearl);
}

.vn-name-badge {
    background-image: url('./assets/name-badge.svg');
    height: 44px;
    display: flex;
    align-items: center;
}

.vn-divider-ornament {
    background-image: url('./assets/divider-ornament.svg');
    height: 24px;
    width: 600px;
    margin: 20px auto;
}

.vn-btn-advance {
    width: 64px;
    height: 64px;
    background-image: url('./assets/btn-advance.svg');
    border: none;
    cursor: pointer;
}

@media (max-width: 768px) {
    .vn-dialog-frame { display: none; }
    .vn-dialog-frame-mobile { display: block; }
}

