/* ════════════════════════════════════════════════════════════════════
   Sección 12 — TOPICS SCREEN — Mesa Mística de Adivinación v2
   Cartas de tarot ornamentadas · mandala SVG · numeración romana
   ════════════════════════════════════════════════════════════════════ */

/* ── 12.1  Barra superior ────────────────────────────────────────── */
#topicsSection .section-header-bar {
    background: rgba(6,4,18,0.75) !important;
    backdrop-filter: blur(16px) saturate(1.4) !important;
    -webkit-backdrop-filter: blur(16px) saturate(1.4) !important;
    border-bottom: 1px solid rgba(140,110,220,0.18) !important;
    box-shadow: 0 4px 32px rgba(0,0,0,0.60),
                inset 0 -1px 0 rgba(140,110,220,0.08) !important;
}

/* ── 12.2  Tapete oscuro — contenedor centrado ───────────────────── */
.topics-layout {
    display: block !important;
    padding: 0.8rem !important;
}
#topicsSection .topics-main {
    max-width: 1100px !important;
    margin: 0 auto !important;
    /* Panel: cristal con mayor opacidad para que backdrop-filter
       no revele el landscape — la luz viene del cielo propio del section */
    background:
        radial-gradient(ellipse at 50% 0%, rgba(120,80,220,0.10) 0%, transparent 65%),
        radial-gradient(ellipse at 80% 100%, rgba(80,40,180,0.06) 0%, transparent 55%),
        rgba(6, 3, 18, 0.58) !important; /* 0.58 = semitransparente: el cielo se ve, las tarjetas se leen */
    backdrop-filter: blur(14px) saturate(1.3) !important;
    -webkit-backdrop-filter: blur(14px) saturate(1.3) !important;
    border: 1px solid rgba(180,165,230,0.26) !important;
    border-radius: 14px !important;
    padding: 1.2rem !important;
    position: relative !important;
    box-shadow:
        /* Borde luminoso plateado-violeta */
        0 0 0 1px rgba(190,178,235,0.10),
        /* Highlight superior — plata fría sobre el cristal */
        inset 0 1px 0 rgba(210,205,245,0.22),
        /* Sombra de profundidad */
        0 8px 48px rgba(0,0,0,0.70),
        /* Glow amatista tenue alrededor del panel */
        0 0 60px rgba(100,60,200,0.15) !important;
}
/* topics-main light override eliminado — fondo siempre oscuro/violeta en esta sección */
/* Esquinas decorativas del tapete */
#topicsSection .topics-main::before,
#topicsSection .topics-main::after {
    content: '' !important;
    position: absolute !important;
    width: 18px !important;
    height: 18px !important;
    opacity: 0.52 !important;
    pointer-events: none !important;
    z-index: 0 !important;
}
#topicsSection .topics-main::before {
    top: 7px !important;
    left: 7px !important;
    border-top: 1.5px solid #7858c0 !important;
    border-left: 1.5px solid #7858c0 !important;
}
#topicsSection .topics-main::after {
    bottom: 7px !important;
    right: 7px !important;
    border-bottom: 1.5px solid #7858c0 !important;
    border-right: 1.5px solid #7858c0 !important;
}

/* ── 12.2b  Título ornamental del panel ─────────────────────────── */
.topics-panel-title {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 10px !important;
    padding-bottom: 0.85rem !important;
    margin-bottom: 0.85rem !important;
    border-bottom: 1px solid rgba(130,100,210,0.18) !important;
}
.tpt-text {
    font-family: 'Cinzel', serif !important;
    font-size: 0.88rem !important;
    font-weight: 600 !important;
    letter-spacing: 0.26em !important;
    text-transform: uppercase !important;
    color: #a080e0 !important;
    margin: 0 !important;
    line-height: 1 !important;
    white-space: nowrap !important;
}
.tpt-deco {
    font-size: 0.55rem !important;
    color: rgba(160,128,220,0.40) !important;
    flex-shrink: 0 !important;
}
.tpt-line {
    flex: 1 !important;
    height: 1px !important;
    background: linear-gradient(90deg, transparent, rgba(130,100,210,0.28)) !important;
    max-width: 80px !important;
}
.tpt-line + .tpt-line,
.tpt-line:last-child {
    background: linear-gradient(90deg, rgba(130,100,210,0.28), transparent) !important;
}
[data-theme="light"] .tpt-text  { color: #5a3898 !important; }
[data-theme="light"] .tpt-deco  { color: rgba(80,50,130,0.35) !important; }
[data-theme="light"] .topics-panel-title { border-bottom-color: rgba(90,60,140,0.16) !important; }
[data-theme="light"] .tpt-line  { background: linear-gradient(90deg, transparent, rgba(90,60,140,0.22)) !important; }
[data-theme="light"] .tpt-line:last-child { background: linear-gradient(90deg, rgba(90,60,140,0.22), transparent) !important; }

/* ── 12.2c  Layout dos columnas (grid + sidebar) ────────────────── */
/* El contenedor tiene un mínimo garantizado para que la zona de cartas
   nunca se vea pequeña, aunque haya pocas tarjetas */
.topics-content {
    display: flex !important;
    gap: 1rem !important;
    align-items: stretch !important;
    min-height: clamp(400px, 55vh, 560px) !important;
    overflow: visible !important;
}
/* El grid-wrap tiene ancho natural (5 col × 130px + gaps + padding).
   No crece ni encoge — el panel se dimensiona por su contenido. */
.topics-grid-wrap {
    flex: none !important;
    max-height: clamp(400px, 60vh, 580px) !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    /* Scrollbar fina dorada */
    scrollbar-width: thin !important;
    scrollbar-color: rgba(130,100,210,0.28) transparent !important;
}
.topics-grid-wrap::-webkit-scrollbar { width: 5px !important; }
.topics-grid-wrap::-webkit-scrollbar-track { background: transparent !important; }
.topics-grid-wrap::-webkit-scrollbar-thumb {
    background: rgba(130,100,210,0.28) !important;
    border-radius: 3px !important;
}
[data-theme="light"] .topics-grid-wrap::-webkit-scrollbar-thumb { background: rgba(90,60,140,0.25) !important; }

/* ── 12.2d  Panel lateral de estadísticas ────────────────────────── */
.topics-sidebar {
    width: 195px !important;
    flex-shrink: 0 !important;
    display: flex !important;
    flex-direction: column !important;
    border-radius: 10px !important;
    border: 1px solid rgba(130,100,210,0.18) !important;
    background: rgba(6,5,18,0.40) !important;
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
    box-shadow: inset 0 1px 0 rgba(130,100,210,0.08),
                0 4px 20px rgba(0,0,0,0.30) !important;
    overflow-y: auto !important;
    scrollbar-width: thin !important;
    scrollbar-color: rgba(130,100,210,0.20) transparent !important;
}
/* topics-sidebar light override eliminado — fondo siempre oscuro/violeta */
.tsi-block {
    padding: 0.9rem 1rem !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 0.5rem !important;
}
/* Heading ornamental con líneas laterales */
.tsi-heading {
    font-family: 'Cinzel', serif !important;
    font-size: 0.56rem !important;
    font-weight: 600 !important;
    letter-spacing: 0.20em !important;
    text-transform: uppercase !important;
    color: rgba(160,128,220,0.65) !important;
    margin-bottom: 0.3rem !important;
    display: flex !important;
    align-items: center !important;
    gap: 6px !important;
    white-space: nowrap !important;
}
.tsi-heading::before,
.tsi-heading::after {
    content: '' !important;
    flex: 1 !important;
    height: 1px !important;
    background: linear-gradient(90deg, transparent, rgba(130,100,210,0.25)) !important;
}
.tsi-heading::after {
    background: linear-gradient(90deg, rgba(130,100,210,0.25), transparent) !important;
}
.tsi-stat {
    display: flex !important;
    flex-direction: row !important;
    align-items: baseline !important;
    gap: 7px !important;
}
.tsi-val {
    font-family: 'Cinzel', serif !important;
    font-size: 1.05rem !important;
    font-weight: 700 !important;
    color: #a080e0 !important;
    line-height: 1.2 !important;
    letter-spacing: 0.05em !important;
    flex-shrink: 0 !important;
    text-shadow: 0 0 12px rgba(160,128,220,0.35) !important;
}
.tsi-lbl {
    font-family: 'Crimson Text', serif !important;
    font-size: 0.80rem !important;
    font-style: italic !important;
    color: rgba(160,128,220,0.45) !important;
    line-height: 1.3 !important;
}
.tsi-sep {
    height: 1px !important;
    margin: 0 0.75rem !important;
    background: linear-gradient(90deg, transparent, rgba(130,100,210,0.22), transparent) !important;
    flex-shrink: 0 !important;
}
.tsi-mode-row {
    display: flex !important;
    align-items: center !important;
    gap: 0.5rem !important;
}
.tsi-mode-dot {
    width: 7px !important;
    height: 7px !important;
    border-radius: 50% !important;
    flex-shrink: 0 !important;
    box-shadow: 0 0 6px currentColor !important;
}
.tsi-mode-dot--rpg     { background: rgba(152,120,216,0.80) !important; color: rgba(152,120,216,0.80) !important; }
.tsi-mode-dot--classic { background: rgba(130,160,230,0.80) !important; color: rgba(130,160,230,0.80) !important; }
.tsi-mode-name {
    font-family: 'Outfit', sans-serif !important;
    font-size: 0.70rem !important;
    font-weight: 600 !important;
    letter-spacing: 0.06em !important;
    color: rgba(160,128,220,0.52) !important;
    flex: 1 !important;
}
.tsi-mode-count {
    font-family: 'Cinzel', serif !important;
    font-size: 0.90rem !important;
    font-weight: 700 !important;
    color: #a080e0 !important;
    text-shadow: 0 0 10px rgba(160,128,220,0.30) !important;
}
.tsi-quote-block {
    flex: 1 !important;
    display: flex !important;
    align-items: flex-end !important;
    padding-bottom: 0.25rem !important;
}
.tsi-quote {
    font-family: 'Cormorant Garamond', serif !important;
    font-style: italic !important;
    font-size: 0.82rem !important;
    line-height: 1.6 !important;
    color: rgba(160,128,220,0.30) !important;
    margin: 0 !important;
    text-align: center !important;
    padding: 0.5rem 0.25rem !important;
    border-top: 1px solid rgba(130,100,210,0.12) !important;
    width: 100% !important;
}
/* Sidebar overrides claro eliminados — la sección Historias siempre es oscura */

/* ── 12.3  Command bar ───────────────────────────────────────────── */
.topics-command-bar {
    display: flex !important;
    align-items: center !important;
    gap: 0.6rem !important;
    flex-wrap: wrap !important;
    margin-bottom: 1.1rem !important;
    background: rgba(14, 10, 38, 0.24) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(185, 170, 228, 0.20) !important;
    border-radius: 9px !important;
    padding: 0.6rem 0.75rem !important;
    box-shadow: inset 0 1px 0 rgba(210, 205, 242, 0.10) !important;
}
/* topics-command-bar: la sección siempre es oscura, no necesita override claro */

/* ── 12.4  Botón Nueva Historia ──────────────────────────────────── */
.btn-create-topic {
    font-family: 'Cinzel', serif !important;
    font-size: 0.77rem !important;
    letter-spacing: 0.09em !important;
    background: linear-gradient(145deg, #6040a0 0%, #30186a 100%) !important;
    border: 1px solid rgba(205, 192, 245, 0.55) !important; /* borde plateado-violeta */
    color: #d4bcfc !important;
    padding: 0.48rem 1.2rem !important;
    border-radius: 6px !important;
    box-shadow: 0 0 0 1px rgba(190, 175, 235, 0.10),
                inset 0 1px 0 rgba(225, 218, 255, 0.28), /* shimmer plateado superior */
                0 3px 12px rgba(0,0,0,0.45) !important;
    transition: box-shadow 0.22s, border-color 0.22s, filter 0.22s !important;
    white-space: nowrap !important;
}
.btn-create-topic:hover {
    filter: brightness(1.12) !important;
    border-color: rgba(218, 208, 250, 0.88) !important;
    box-shadow: 0 0 20px rgba(160,128,220,0.35),
                inset 0 1px 0 rgba(235, 228, 255, 0.45), /* shimmer plateado más brillante en hover */
                0 4px 16px rgba(0,0,0,0.50) !important;
}
/* btn-create-topic: la sección siempre es oscura, el violet funciona en ambos temas */

/* ── 12.4b  Botón Gestionar ─────────────────────────────────────────
   menu-gamefeel.css sobreescribe .btn-manage-topics con fondo marrón
   y borde ámbar (viene DESPUÉS en el build). Scopeamos bajo #topicsSection
   para ganar por especificidad sin tocar otros menús.
   ────────────────────────────────────────────────────────────────── */
#topicsSection .btn-manage-topics {
    background: linear-gradient(145deg, rgba(38,26,72,0.92), rgba(20,13,46,0.96)) !important;
    border: 1px solid rgba(185, 170, 232, 0.48) !important;
    color: rgba(205, 195, 240, 0.90) !important;
    border-radius: 6px !important;
    font-family: 'Cinzel', serif !important;
    font-size: 0.77rem !important;
    letter-spacing: 0.06em !important;
    box-shadow: 0 0 0 1px rgba(192, 178, 236, 0.08),
                inset 0 1px 0 rgba(218, 210, 250, 0.24),
                0 3px 10px rgba(0,0,0,0.40) !important;
    transition: box-shadow 0.22s, border-color 0.22s, background 0.22s !important;
}
#topicsSection .btn-manage-topics:hover {
    background: linear-gradient(145deg, rgba(58,40,100,0.94), rgba(30,18,62,0.97)) !important;
    border-color: rgba(215, 205, 248, 0.72) !important;
    color: #dcd4fc !important;
    box-shadow: 0 0 18px rgba(160,128,220,0.28),
                inset 0 1px 0 rgba(228, 222, 255, 0.35),
                0 4px 14px rgba(0,0,0,0.45) !important;
    transform: translateY(-1px) !important;
}

/* ── 12.4c  Search wrap — quitar borde ámbar de menu-gamefeel.css ── */
#topicsSection .topics-search-wrap {
    border: none !important;
    background: transparent !important;
    border-radius: 8px !important;
}

/* ── 12.5  Pills de filtro ───────────────────────────────────────── */
.topics-filter-group {
    display: flex !important;
    gap: 0.35rem !important;
    flex-shrink: 0 !important;
}
.topic-filter-btn {
    font-family: 'Cinzel', serif !important;
    font-size: 0.63rem !important;
    letter-spacing: 0.07em !important;
    padding: 0.38rem 0.82rem !important;
    border-radius: 5px !important;
    /* Fondo más translúcido — plata fría + violeta */
    border: 1px solid rgba(190, 175, 230, 0.28) !important;
    background: rgba(22, 15, 55, 0.30) !important;
    color: rgba(205, 195, 238, 0.72) !important;
    cursor: pointer !important;
    transition: all 0.22s !important;
    white-space: nowrap !important;
    /* Highlight plateado en borde superior */
    box-shadow: inset 0 1px 0 rgba(220, 215, 248, 0.08) !important;
}
.topic-filter-btn:hover {
    background: rgba(105, 80, 175, 0.22) !important;
    color: #dcd4fc !important;
    border-color: rgba(210, 200, 242, 0.55) !important;
    box-shadow: inset 0 1px 0 rgba(230, 225, 255, 0.15),
                0 0 10px rgba(160,130,220,0.12) !important;
}
/* topic-filter-btn: la sección siempre es oscura, los estilos dark valen para ambos temas */
.topic-filter-btn.active {
    background: linear-gradient(135deg, rgba(100, 65, 178, 0.72), rgba(50, 28, 95, 0.88)) !important;
    border-color: rgba(215, 205, 245, 0.65) !important;
    color: #e2daff !important;
    box-shadow: 0 0 14px rgba(160, 130, 220, 0.25),
                inset 0 1px 0 rgba(235, 228, 255, 0.22) !important; /* brillo plateado superior */
}

/* ── 12.6  Buscador glassmorphism ────────────────────────────────── */
.topics-search-wrap {
    flex: 1 !important;
    min-width: 180px !important;
    position: relative !important;
}
.topics-search-icon { display: none !important; }
.topics-search-input {
    width: 100% !important;
    background: rgba(18, 12, 42, 0.42) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
    border: 1px solid rgba(185, 170, 228, 0.35) !important;
    border-radius: 8px !important;
    color: #d8d2f4 !important; /* plata-violeta, sin tonos ámbar */
    font-family: 'Crimson Text', serif !important;
    font-size: 0.9rem !important;
    padding: 0.52rem 0.95rem !important;
    outline: none !important;
    transition: border-color 0.22s, box-shadow 0.22s !important;
    box-sizing: border-box !important;
    box-shadow: inset 0 1px 0 rgba(220, 215, 248, 0.08) !important;
}
.topics-search-input::placeholder {
    color: rgba(185, 172, 228, 0.45) !important;
    font-style: italic !important;
}
.topics-search-input:focus {
    border-color: rgba(200, 185, 242, 0.68) !important;
    box-shadow: 0 0 0 2px rgba(160, 140, 225, 0.12),
                inset 0 0 20px rgba(130,100,210,0.05),
                inset 0 1px 0 rgba(220, 215, 248, 0.12) !important;
}

/* ── 12.7  Ocultar contador de mensajes y barra de sala ────────── */
/* El contador "N / N" no debe mostrarse en la caja de diálogo     */
#vnMessageCounter { display: none !important; }

/* El panel de código de sala aparece encima del toolbar — ocultarlo */
#vnSection #roomCodeWrap { display: none !important; }

/* ── 12.7b  Grid de tarjetas tarot (portrait) ───────────────────── */
.topics-grid {
    display: grid !important;
    /* 5 columnas fijas: el ancho del panel nunca cambia,
       ni con 1 tarjeta ni con 50. El scroll es siempre vertical. */
    grid-template-columns: repeat(5, 130px) !important;
    gap: 14px !important;
    padding: 8px 14px 18px !important;
    align-items: start !important;
}

/* ── 12.8  Tarot Card — base portrait (3D flip) ──────────────────── */
article.tc {
    position: relative !important;
    width: 100% !important;
    /* portrait forzado: altura = 1.5 × ancho */
    aspect-ratio: 2 / 3 !important;
    min-height: 170px !important;
    max-height: 240px !important;
    cursor: pointer !important;
    box-sizing: border-box !important;
    perspective: 900px !important;
    transition: transform 0.25s cubic-bezier(0.22,1,0.36,1) !important;
    animation: tc-in 0.40s cubic-bezier(0.22,1,0.36,1) both !important;
    user-select: none !important;
}
.tc:nth-child(1) { animation-delay: 0.03s !important; }
.tc:nth-child(2) { animation-delay: 0.08s !important; }
.tc:nth-child(3) { animation-delay: 0.13s !important; }
.tc:nth-child(4) { animation-delay: 0.18s !important; }
.tc:nth-child(n+5) { animation-delay: 0.24s !important; }
@keyframes tc-in {
    from { opacity: 0; transform: translateY(18px) scale(0.95); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
}
.tc:not(.tc--flipped):hover {
    transform: translateY(-5px) scale(1.02) !important;
}

/* ── 12.8b  Flip — wrapper 3D ──────────────────────────────────── */
.tc-inner {
    position: absolute !important;
    inset: 0 !important;
    transform-style: preserve-3d !important;
    transition: transform 0.55s cubic-bezier(0.45, 0.05, 0.55, 0.95) !important;
    border-radius: 6px !important;
}
.tc--flipped .tc-inner {
    transform: rotateY(180deg) !important;
}

/* ── 12.8c  Cara base (frente y dorso) ─────────────────────────── */
/* Por defecto: solo la cara frontal es interactiva.
   backface-visibility: hidden es insuficiente en algunos navegadores
   (p.ej. iOS Safari) para suprimir pointer-events en la cara oculta,
   así que lo controlamos explícitamente según el estado del flip. */
.tc-face--back            { pointer-events: none !important; }   /* dorso oculto → sin eventos  */
.tc--flipped .tc-face--back  { pointer-events: auto !important; }  /* dorso visible → con eventos */
.tc--flipped .tc-face--front { pointer-events: none !important; }  /* frente oculto → sin eventos */

.tc-face {
    position: absolute !important;
    inset: 0 !important;
    backface-visibility: hidden !important;
    -webkit-backface-visibility: hidden !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    padding: 10px 8px 8px !important;
    border-radius: 6px !important;
    overflow: hidden !important;
    border: 1px solid transparent !important;
    box-sizing: border-box !important;
    transition: border-color 0.25s ease, box-shadow 0.25s ease !important;
}
.tc-face--back {
    transform: rotateY(180deg) !important;
    justify-content: flex-end !important;
    padding: 14px 12px 14px !important;
    gap: 0 !important;
}

/* ── 12.9  Modo RPG — ámbar profundo ─────────────────────────────── */
.tc--rpg .tc-face {
    background: linear-gradient(170deg, #1f1408 0%, #120d04 48%, #1c1409 100%) !important;
    border-color: rgba(152,120,216, 0.40) !important;
    box-shadow:
        inset 0 0 0 1px rgba(152,120,216,0.08),
        0 8px 36px rgba(0,0,0,0.65) !important;
}
.tc--rpg:not(.tc--flipped):hover .tc-face--front,
.tc--rpg.tc--flipped:hover .tc-face--back {
    border-color: rgba(152,120,216, 0.72) !important;
    box-shadow:
        inset 0 0 0 1px rgba(152,120,216,0.14),
        0 18px 52px rgba(0,0,0,0.72),
        0 0 30px rgba(152,120,216,0.16) !important;
}

/* ── 12.10  Modo Clásico — azul marino profundo ──────────────────── */
.tc--classic .tc-face {
    background: linear-gradient(170deg, #0b1028 0%, #070c1c 48%, #0d1330 100%) !important;
    border-color: rgba(130,160,230, 0.30) !important;
    box-shadow:
        inset 0 0 0 1px rgba(130,160,230,0.06),
        0 8px 36px rgba(0,0,0,0.65) !important;
}
.tc--classic:not(.tc--flipped):hover .tc-face--front,
.tc--classic.tc--flipped:hover .tc-face--back {
    border-color: rgba(130,160,230, 0.62) !important;
    box-shadow:
        inset 0 0 0 1px rgba(130,160,230,0.12),
        0 18px 52px rgba(0,0,0,0.72),
        0 0 28px rgba(130,160,230,0.14) !important;
}

/* ── 12.11  Marco interior (double border) ───────────────────────── */
.tc-frame {
    position: absolute !important;
    inset: 5px !important;
    border-radius: 3px !important;
    pointer-events: none !important;
    z-index: 1 !important;
    border: 1px solid !important;
    display: block !important;
}
.tc--rpg    .tc-frame { border-color: rgba(212,174,92,0.18) !important; }
.tc--classic .tc-frame { border-color: rgba(130,160,230,0.14) !important; }

/* ── 12.12  Esquinas ornamentales en L ──────────────────────────── */
.tc-corner {
    position: absolute !important;
    width: 9px !important;
    height: 9px !important;
    z-index: 3 !important;
    pointer-events: none !important;
    display: block !important;
}
.tc-corner--tl { top: 9px !important;    left: 9px !important;    border-top: 1px solid !important; border-left: 1px solid !important; }
.tc-corner--tr { top: 9px !important;    right: 9px !important;   border-top: 1px solid !important; border-right: 1px solid !important; }
.tc-corner--bl { bottom: 9px !important; left: 9px !important;    border-bottom: 1px solid !important; border-left: 1px solid !important; }
.tc-corner--br { bottom: 9px !important; right: 9px !important;   border-bottom: 1px solid !important; border-right: 1px solid !important; }
.tc--rpg    .tc-corner { border-color: rgba(212,174,92,0.52) !important; }
.tc--classic .tc-corner { border-color: rgba(130,160,230,0.44) !important; }

/* ── 12.13  Cabecera — título y autor ───────────────────────────── */
.tc-header {
    position: relative !important;
    z-index: 2 !important;
    width: 100% !important;
    text-align: center !important;
    padding: 4px 14px 3px !important;
    flex-shrink: 0 !important;
}
.tc-title {
    font-family: 'Cinzel', 'Trajan Pro', serif !important;
    font-size: 9.5px !important;
    font-weight: 600 !important;
    letter-spacing: 0.10em !important;
    text-transform: uppercase !important;
    color: #f0e6cc !important;
    margin: 0 0 2px !important;
    line-height: 1.30 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
}
.tc-author {
    font-family: 'Cormorant Garamond', 'EB Garamond', serif !important;
    font-style: italic !important;
    font-size: 8px !important;
    margin: 0 !important;
    line-height: 1.2 !important;
    opacity: 0.55 !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
}
.tc--rpg    .tc-author { color: #d4ae5c !important; }
.tc--classic .tc-author { color: #8aa0e6 !important; }

/* ── 12.14  Separador decorativo ─────────────────────────────────── */
.tc-sep {
    position: relative !important;
    z-index: 2 !important;
    width: 55% !important;
    height: 1px !important;
    flex-shrink: 0 !important;
    margin: 3px auto !important;
}
.tc--rpg    .tc-sep { background: linear-gradient(90deg,transparent,rgba(212,174,92,0.38),transparent) !important; }
.tc--classic .tc-sep { background: linear-gradient(90deg,transparent,rgba(130,160,230,0.30),transparent) !important; }

/* ── 12.15  Cuerpo central ──────────────────────────────────────── */
.tc-body {
    position: relative !important;
    z-index: 2 !important;
    flex: 1 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 4px !important;
    width: 100% !important;
    min-height: 0 !important;
    padding: 0 6px !important;
}
.tc-numeral {
    font-family: 'Cinzel', serif !important;
    font-size: 8.5px !important;
    letter-spacing: 0.28em !important;
    text-align: center !important;
    line-height: 1 !important;
    flex-shrink: 0 !important;
}
.tc--rpg    .tc-numeral { color: rgba(212,174,92,0.52) !important; }
.tc--classic .tc-numeral { color: rgba(130,160,230,0.50) !important; }

.tc-mode {
    font-family: 'Outfit', sans-serif !important;
    font-size: 7px !important;
    font-weight: 600 !important;
    letter-spacing: 0.20em !important;
    text-transform: uppercase !important;
    padding: 2px 6px !important;
    border-radius: 2px !important;
    border: 1px solid !important;
    flex-shrink: 0 !important;
    line-height: 1.3 !important;
}
.tc--rpg    .tc-mode { color: rgba(212,174,92,0.80) !important; border-color: rgba(212,174,92,0.25) !important; background: rgba(212,174,92,0.06) !important; }
.tc--classic .tc-mode { color: rgba(130,160,230,0.80) !important; border-color: rgba(130,160,230,0.22) !important; background: rgba(130,160,230,0.05) !important; }

/* ── 12.16  Ilustración SVG ────────────────────────────────────── */
.tc-illus {
    flex: 1 !important;
    width: 100% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    min-height: 0 !important;
    padding: 2px 4px !important;
    overflow: hidden !important;
}
.tc-illus svg {
    width: 100% !important;
    height: auto !important;
    max-height: 100% !important;
    overflow: visible !important;
}
.tc--rpg    .tc-illus { color: rgba(212,174,92,0.62) !important; }
.tc--classic .tc-illus { color: rgba(130,160,230,0.60) !important; }

/* ── 12.17  Pie con badges ───────────────────────────────────────── */
.tc-footer {
    position: relative !important;
    z-index: 2 !important;
    width: 100% !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    padding: 3px 12px 3px !important;
    flex-shrink: 0 !important;
}
.tc-diamond {
    font-size: 9px !important;
    line-height: 1 !important;
    flex-shrink: 0 !important;
}
.tc--rpg    .tc-diamond { color: rgba(212,174,92,0.38) !important; }
.tc--classic .tc-diamond { color: rgba(130,160,230,0.32) !important; }
.tc-count {
    font-family: 'Outfit', sans-serif !important;
    font-size: 8.5px !important;
    font-weight: 600 !important;
    letter-spacing: 0.03em !important;
    line-height: 1 !important;
    padding: 1px 4px !important;
    border-radius: 2px !important;
}
.tc--rpg    .tc-count { color: rgba(212,174,92,0.65) !important; background: rgba(212,174,92,0.07) !important; }
.tc--classic .tc-count { color: rgba(130,160,230,0.65) !important; background: rgba(130,160,230,0.07) !important; }

/* ── 12.17b  Cara trasera — contenido ───────────────────────────── */
.tc-back-body {
    position: relative !important;
    z-index: 2 !important;
    flex: 1 !important;
    width: 100% !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 5px !important;
}
.tc-back-title {
    font-family: 'Cinzel', 'Trajan Pro', serif !important;
    font-size: 10px !important;
    font-weight: 600 !important;
    letter-spacing: 0.10em !important;
    text-transform: uppercase !important;
    color: #f0e6cc !important;
    text-align: center !important;
    margin: 0 !important;
    line-height: 1.30 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 3 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
}
.tc-back-author {
    font-family: 'Cormorant Garamond', 'EB Garamond', serif !important;
    font-style: italic !important;
    font-size: 9px !important;
    margin: 0 !important;
    opacity: 0.55 !important;
    text-align: center !important;
    line-height: 1.2 !important;
}
.tc--rpg    .tc-back-author { color: #d4ae5c !important; }
.tc--classic .tc-back-author { color: #8aa0e6 !important; }

.tc-back-sep {
    width: 55% !important;
    height: 1px !important;
    flex-shrink: 0 !important;
    margin: 4px auto !important;
}
.tc--rpg    .tc-back-sep { background: linear-gradient(90deg,transparent,rgba(212,174,92,0.38),transparent) !important; }
.tc--classic .tc-back-sep { background: linear-gradient(90deg,transparent,rgba(130,160,230,0.30),transparent) !important; }

.tc-back-stats {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    gap: 4px !important;
    width: 100% !important;
}
.tc-back-stat {
    font-family: 'Outfit', sans-serif !important;
    font-size: 8.5px !important;
    font-weight: 500 !important;
    letter-spacing: 0.04em !important;
    text-align: center !important;
    padding: 2px 8px !important;
    border-radius: 2px !important;
    line-height: 1.4 !important;
}
.tc--rpg    .tc-back-stat { color: rgba(212,174,92,0.80) !important; background: rgba(212,174,92,0.07) !important; }
.tc--classic .tc-back-stat { color: rgba(130,160,230,0.80) !important; background: rgba(130,160,230,0.07) !important; }

.tc-back-turn {
    font-family: 'Outfit', sans-serif !important;
    font-size: 8.5px !important;
    font-weight: 600 !important;
    letter-spacing: 0.06em !important;
    text-align: center !important;
    animation: tc-turn-pulse 2s ease-in-out infinite !important;
}
.tc--rpg    .tc-back-turn { color: rgba(212,174,92,0.95) !important; }
.tc--classic .tc-back-turn { color: rgba(130,160,230,0.95) !important; }
@keyframes tc-turn-pulse {
    0%,100% { opacity: 0.70; }
    50%     { opacity: 1.00; }
}

/* ── 12.18  Indicador de mensajes nuevos ─────────────────────────── */
.tc-unread-pill {
    font-family: 'Outfit', sans-serif !important;
    font-size: 7.5px !important;
    font-weight: 700 !important;
    letter-spacing: 0.06em !important;
    padding: 2px 6px !important;
    border-radius: 10px !important;
    margin-left: 6px !important;
    white-space: nowrap !important;
    flex-shrink: 0 !important;
    background: rgba(212,174,92,0.14) !important;
    color: rgba(212,174,92,1.00) !important;
    border: 1px solid rgba(212,174,92,0.38) !important;
    animation: tc-unread-pulse 2.8s ease-in-out infinite !important;
}
@keyframes tc-unread-pulse {
    0%,100% { opacity: 0.72; }
    50%      { opacity: 1.00; }
}
.tc-back-stat--unread {
    color: rgba(212,174,92,1.00) !important;
    background: rgba(212,174,92,0.13) !important;
    border: 1px solid rgba(212,174,92,0.25) !important;
    font-weight: 600 !important;
}
.tc--has-unread .tc-face--front {
    box-shadow: 0 0 18px rgba(212,174,92,0.14), inset 0 0 16px rgba(212,174,92,0.04) !important;
}

.tc-enter-btn {
    position: relative !important;
    z-index: 4 !important;
    flex-shrink: 0 !important;
    width: 100% !important;
    font-family: 'Cinzel', serif !important;
    font-size: 8px !important;
    font-weight: 600 !important;
    letter-spacing: 0.12em !important;
    text-transform: uppercase !important;
    text-align: center !important;
    padding: 7px 10px !important;
    border-radius: 4px !important;
    border: 1px solid !important;
    cursor: pointer !important;
    background: transparent !important;
    margin-top: 8px !important;
    transition: background 0.2s ease, color 0.2s ease, border-color 0.2s ease !important;
    line-height: 1.3 !important;
}
.tc--rpg    .tc-enter-btn { color: rgba(212,174,92,0.90) !important; border-color: rgba(212,174,92,0.35) !important; }
.tc--classic .tc-enter-btn { color: rgba(130,160,230,0.90) !important; border-color: rgba(130,160,230,0.32) !important; }
.tc--rpg    .tc-enter-btn:hover { background: rgba(212,174,92,0.14) !important; color: rgba(212,174,92,1.00) !important; border-color: rgba(212,174,92,0.60) !important; }
.tc--classic .tc-enter-btn:hover { background: rgba(130,160,230,0.12) !important; color: rgba(130,160,230,1.00) !important; border-color: rgba(130,160,230,0.55) !important; }

/* ── 12.18  Turno activo — glow pulsante ─────────────────────────── */
.tc--myturn.tc--rpg .tc-face {
    border-color: rgba(152,120,216,0.55) !important;
    animation: tc-pulse-gold 2.6s ease-in-out infinite !important;
}
.tc--myturn.tc--classic .tc-face {
    border-color: rgba(130,160,230,0.50) !important;
    animation: tc-pulse-blue 2.6s ease-in-out infinite !important;
}
@keyframes tc-pulse-gold {
    0%,100% { box-shadow: inset 0 0 0 1px rgba(152,120,216,0.10), 0 8px 36px rgba(0,0,0,0.65); border-color: rgba(152,120,216,0.45); }
    50%     { box-shadow: inset 0 0 0 1px rgba(152,120,216,0.18), 0 8px 36px rgba(0,0,0,0.65), 0 0 30px rgba(152,120,216,0.24); border-color: rgba(152,120,216,0.78); }
}
@keyframes tc-pulse-blue {
    0%,100% { box-shadow: inset 0 0 0 1px rgba(130,160,230,0.08), 0 8px 36px rgba(0,0,0,0.65); border-color: rgba(130,160,230,0.35); }
    50%     { box-shadow: inset 0 0 0 1px rgba(130,160,230,0.15), 0 8px 36px rgba(0,0,0,0.65), 0 0 26px rgba(130,160,230,0.22); border-color: rgba(130,160,230,0.65); }
}

/* ── 12.19  Mobile ───────────────────────────────────────────────── */
@media (max-width: 900px) {
    /* En tablet el sidebar se oculta; el grid pasa a 4 columnas */
    .topics-sidebar { display: none !important; }
    .topics-grid { grid-template-columns: repeat(4, 130px) !important; }
}
@media (max-width: 700px) {
    /* Móvil: 3 columnas más estrechas */
    .topics-grid {
        grid-template-columns: repeat(3, 110px) !important;
        gap: 10px !important;
        padding: 8px 10px 14px !important;
    }
    article.tc { min-height: 155px !important; }
}
@media (max-width: 420px) {
    /* Móvil pequeño: 2 columnas */
    .topics-grid {
        grid-template-columns: repeat(2, 110px) !important;
        gap: 8px !important;
    }
}

/* ════════════════════════════════════════════════════════════════════
   H. VN — BOTONES DE CONTROL (ambos modos)
   ════════════════════════════════════════════════════════════════════ */

.vn-control-btn {
    background: rgba(14,10,4,0.75) !important;
    border-color: rgba(160,128,220,0.22) !important;
    color: rgba(160,128,220,0.65) !important;
    border-radius: 8px !important;
}
.vn-control-btn:hover {
    background: rgba(160,128,220,0.1) !important;
    border-color: rgba(160,128,220,0.5) !important;
    color: var(--eth-gold) !important;
}

/* ════════════════════════════════════════════════════════════════════
   I. VN — OPCIONES BASE
   ════════════════════════════════════════════════════════════════════ */

.vn-option-btn {
    border-color: rgba(160,128,220,0.42) !important;
    background: rgba(18,12,5,0.9) !important;
}
.vn-option-btn:hover {
    border-color: rgba(160,128,220,0.88) !important;
    background: rgba(28,18,6,0.96) !important;
    box-shadow: 0 6px 28px rgba(0,0,0,0.5), 0 0 16px rgba(160,128,220,0.14) !important;
}
.vn-option-btn.chosen {
    background: rgba(38,62,28,0.75) !important;
    border-color: var(--eth-jade) !important;
    color: #c8f0d8 !important;
}

/* ════════════════════════════════════════════════════════════════════
   MODO CLÁSICO — Visual Novel
   Estética: pergamino iluminado, caligrafía, libro antiguo
   ════════════════════════════════════════════════════════════════════ */
/* ════════════════════════════════════════════════════════════════════
   MODO CLÁSICO — Visual Novel
   Paleta: pergamino claro, tinta sepia, dorado suave
   Sensación: libro iluminado por velas, cálido y acogedor
   ════════════════════════════════════════════════════════════════════ */

body.mode-classic {
    --cls-parch:    #f2e8d0;
    --cls-parch2:   #e8dcc0;
    --cls-parch3:   #ddd0a8;
    --cls-ink:      #2a1e0e;
    --cls-ink2:     #3d2e18;
    --cls-gold:     #b8902a;
    --cls-gold-l:   #d4aa50;
    --cls-gold-d:   rgba(184,144,42,0.38);
    --cls-sepia:    rgba(180,140,80,0.35);
    --cls-text:     #f4ead8;
    --cls-text-d:   rgba(230,210,165,0.62);
    --cls-border:   rgba(180,140,80,0.38);
}

/* Overlay: tinte sepia cálido sobre la escena */
body.mode-classic .vn-section::before {
    background: linear-gradient(160deg,
        rgba(80,55,20,0.18),
        rgba(50,32,8,0.12)) !important;
}

/* ── Caja de diálogo: pergamino encuadernado ── */
body.mode-classic .vn-dialogue-box {
    background: linear-gradient(160deg,
        rgba(42,28,10,0.97) 0%,
        rgba(32,20,6,0.99) 100%) !important;
    border: 1.5px solid var(--cls-gold-d) !important;
    border-radius: 18px !important;
    box-shadow:
        0 24px 64px rgba(0,0,0,0.5),
        0 0 0 1px rgba(184,144,42,0.06),
        0 0 40px -8px rgba(180,130,30,0.25),
        inset 0 1px 0 rgba(255,228,150,0.06),
        inset 0 -1px 0 rgba(0,0,0,0.3) !important;
}
body.mode-classic .vn-dialogue-box::before {
    border-color: rgba(184,144,42,0.1) !important;
    border-radius: 13px !important;
}
body.mode-classic .vn-dialogue-box::after {
    content: '❧' !important;
    color: rgba(184,144,42,0.22) !important;
    font-size: 1.3rem !important;
    transform: none !important;
}

/* ── Texto: serif cálida, espaciada ── */
body.mode-classic .vn-dialogue-text {
    font-family: 'Crimson Text', 'EB Garamond', serif !important;
    font-size: 1.12em !important;
    line-height: 1.85 !important;
    color: var(--cls-text) !important;
    letter-spacing: 0.01em !important;
}
body.mode-classic .vn-dialogue-text em,
body.mode-classic .vn-dialogue-text i {
    color: rgba(222,192,118,0.92) !important;
    font-style: italic !important;
}
body.mode-classic .vn-dialogue-text strong,
body.mode-classic .vn-dialogue-text b {
    color: rgba(240,215,155,0.98) !important;
    font-weight: 700 !important;
}

/* ── Placa del personaje: etiqueta de libro ── */
body.mode-classic .vn-speaker-plate {
    background: linear-gradient(135deg, #1e1408, #382a0c) !important;
    border-color: rgba(184,144,42,0.5) !important;
    color: #f4ead8 !important;
    border-radius: 0 0 12px 0 !important;
    font-family: 'Cinzel', serif !important;
    letter-spacing: 0.08em !important;
}

/* ── Panel de respuesta: madera cálida ── */
body.mode-classic .vn-reply-panel {
    background: linear-gradient(180deg,
        rgba(42,28,10,0.99),
        rgba(26,16,4,1)) !important;
    border-top: 2px solid rgba(184,144,42,0.28) !important;
    box-shadow:
        0 -3px 0 rgba(150,105,22,0.18),
        0 -18px 50px rgba(0,0,0,0.4) !important;
}
body.mode-classic .vn-reply-header {
    background: linear-gradient(90deg,
        rgba(180,130,38,0.1), transparent 60%) !important;
    border-bottom-color: rgba(184,144,42,0.1) !important;
}
body.mode-classic .vn-reply-textarea {
    background: rgba(52,34,10,0.9) !important;
    border-color: rgba(180,140,78,0.32) !important;
    color: var(--cls-text) !important;
    font-family: 'Crimson Text', serif !important;
    font-size: 1.05rem !important;
    border-radius: 8px !important;
}
body.mode-classic .vn-reply-textarea:focus {
    border-color: rgba(184,144,42,0.7) !important;
    box-shadow: 0 0 0 2px rgba(184,144,42,0.1) !important;
}

/* ── Botón Responder: sello de lacre dorado redondeado ── */
body.mode-classic .vn-dialogue-action-btn.reply-btn,
body.mode-classic .vn-dialogue-action-btn.reply-btn:hover {
    background: linear-gradient(135deg,
        rgba(152,108,26,0.9),
        rgba(100,68,10,0.95)) !important;
    border: 1px solid var(--cls-gold-l) !important;
    border-radius: 20px !important;
    color: #f8eed8 !important;
    font-family: 'Cinzel', serif !important;
    letter-spacing: 0.06em !important;
    padding: 0.36rem 1.2rem !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.4),
        0 0 12px rgba(180,130,30,0.15) !important;
}
body.mode-classic .vn-dialogue-action-btn:not(.reply-btn):not(.delete-message-btn) {
    border-color: rgba(184,144,42,0.2) !important;
    color: var(--cls-text-d) !important;
    border-radius: 20px !important;
}
body.mode-classic .vn-dialogue-action-btn:not(.reply-btn):not(.delete-message-btn):hover {
    background: rgba(152,108,26,0.16) !important;
    border-color: rgba(184,144,42,0.55) !important;
    color: var(--cls-text) !important;
}

/* ── Opciones: tarjetas de libro redondeadas ── */
body.mode-classic .vn-option-btn {
    background: rgba(42,28,10,0.92) !important;
    border: 1.5px solid rgba(184,144,42,0.4) !important;
    border-radius: 14px !important;
    font-family: 'Crimson Text', serif !important;
    font-size: 1.1rem !important;
    color: var(--cls-text) !important;
}
body.mode-classic .vn-option-btn:hover {
    background: rgba(56,36,10,0.97) !important;
    border-color: rgba(184,144,42,0.88) !important;
    transform: translateX(6px) !important;
    box-shadow: 0 4px 20px rgba(0,0,0,0.5),
        0 0 18px rgba(184,144,42,0.14) !important;
}
body.mode-classic .vn-option-btn.chosen {
    background: rgba(36,58,26,0.78) !important;
    border-color: #5a9470 !important;
    color: #c8f0d8 !important;
}

/* ── Botones de control ── */
body.mode-classic .vn-control-btn {
    background: rgba(34,22,8,0.82) !important;
    border-color: rgba(184,144,42,0.24) !important;
    border-radius: 10px !important;
}
body.mode-classic .vn-control-btn:hover {
    background: rgba(184,144,42,0.1) !important;
    border-color: rgba(184,144,42,0.6) !important;
}

/* ── Campo de estrellas animado — fondo nocturno ── */
body.mode-classic #vnSection::after {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    pointer-events: none !important;
    z-index: 0 !important;
    /* Cuatro capas de puntos con distinto tamaño y densidad */
    background-image:
        radial-gradient(circle, rgba(190,215,255,0.72) 1px,   transparent 1px),
        radial-gradient(circle, rgba(160,195,255,0.50) 1px,   transparent 1px),
        radial-gradient(circle, rgba(210,230,255,0.62) 1.5px, transparent 1.5px),
        radial-gradient(circle, rgba(140,180,255,0.40) 1px,   transparent 1px) !important;
    background-size:
        115px 115px,
        195px 195px,
        78px  78px,
        250px 250px !important;
    background-position:
        14px 20px,
        58px 85px,
        32px 48px,
        105px 25px !important;
    opacity: 0.50 !important;
    animation: cls-stars-drift 90s linear infinite !important;
}
@keyframes cls-stars-drift {
    from { background-position: 14px 20px, 58px 85px, 32px 48px, 105px 25px; }
    to   { background-position: 129px 135px, 253px 280px, 110px 126px, 355px 275px; }
}

/* ── Líneas divisoras: azul-plata en vez de dorado ── */
body.mode-classic #vnSection .ui-layer > .left-panel {
    border-right-color: rgba(100,155,220,0.28) !important;
}
body.mode-classic #vnSection .ui-layer > .right-panel {
    border-left-color: rgba(100,155,220,0.28) !important;
}
body.mode-classic #vnSection .ui-layer > .bottom-panel {
    border-top-color: rgba(100,155,220,0.22) !important;
}

/* ── Barra de controles (columna derecha): cristal nocturno ── */
body.mode-classic .vn-controls {
    background: linear-gradient(180deg,
        rgba(6,10,32,0.97) 0%,
        rgba(4,7,22,0.99) 100%) !important;
    border-color: rgba(90,145,210,0.32) !important;
    box-shadow: 0 0 0 1px rgba(0,0,0,0.8),
                0 4px 24px rgba(0,0,20,0.75) !important;
}
/* Botones diamante en azul-plata */
body.mode-classic .vn-control-btn {
    background: linear-gradient(135deg,
        rgba(14,24,68,1),
        rgba(8,15,44,1),
        rgba(5,10,30,1)) !important;
    border-color: rgba(90,145,210,0.42) !important;
    color: rgba(140,190,245,0.72) !important;
    box-shadow:
        inset 1px 1px 0 rgba(140,190,255,0.10),
        inset -1px -1px 0 rgba(0,0,0,0.5),
        0 2px 4px rgba(0,0,0,0.6) !important;
}
body.mode-classic .vn-control-btn:hover {
    background: rgba(50,100,200,0.20) !important;
    border-color: rgba(120,185,255,0.68) !important;
    color: rgba(190,225,255,0.95) !important;
    box-shadow: 0 0 14px rgba(80,155,255,0.32) !important;
}

/* ════════════════════════════════════════════════════════════════════
   MODO RPG — D&D / TTRPG
   Paleta: pergamino envejecido, tinta oscura, rojo sangre, cuero
   Gama oscura con toques cálidos — como un manual de D&D en penumbra
   ════════════════════════════════════════════════════════════════════ */

body.mode-rpg {
    /* Paleta arena oscura — pergamino envejecido */
    --rpg-parch:    #c8b890;   /* pergamino viejo */
    --rpg-parch-d:  rgba(200,184,144,0.35);
    --rpg-ink:      #1a1206;   /* tinta casi negra */
    --rpg-ink2:     #221808;
    --rpg-leather:  #3a2810;   /* cuero oscuro */
    --rpg-blood:    #7a1e1e;   /* rojo sangre D&D */
    --rpg-blood-b:  #a03030;
    --rpg-rust:     #8a4a18;   /* óxido/cobre viejo */
    --rpg-rust-b:   #b06828;
    --rpg-sand:     #c0a870;   /* arena dorada */
    --rpg-sand-d:   rgba(192,168,112,0.4);
    --rpg-text:     #e8d8b8;   /* crema arena */
    --rpg-text-b:   #f5ecd8;
    --rpg-silver:   #a8a090;   /* plata envejecida */
}

/* Overlay: oscuro con tinte cuero */
body.mode-rpg .vn-section::before {
    background: linear-gradient(180deg,
        rgba(18,10,4,0.52) 0%,
        rgba(22,14,6,0.32) 45%,
        rgba(16,10,4,0.58) 100%) !important;
}

/* ── Caja de diálogo: pergamino envejecido, bordes de libro de reglas ── */
body.mode-rpg .vn-dialogue-box {
    background:
        linear-gradient(180deg,
            rgba(28,18,8,0.97) 0%,
            rgba(20,12,4,0.99) 100%) !important;
    border: 1.5px solid var(--rpg-parch-d) !important;
    border-radius: 6px !important;
    box-shadow:
        0 0 0 3px rgba(14,8,2,0.8),
        0 0 0 4px rgba(200,184,144,0.08),
        0 20px 60px rgba(0,0,0,0.75),
        inset 0 1px 0 rgba(200,184,144,0.05),
        inset 0 0 50px rgba(0,0,0,0.35) !important;
