/* ════════════════════════════════════════════════════════════════════
   PANEL DE CONTROLES VN — Botones diamante estilo RPG clásico
   ════════════════════════════════════════════════════════════════════ */

.vn-controls {
    background: linear-gradient(180deg, rgba(10,7,3,0.96), rgba(6,4,2,0.98)) !important;
    border: 1px solid rgba(192,176,152,0.35) !important;
    border-radius: 4px !important;
    padding: 0.45rem 0.6rem !important;
    gap: 0.28rem !important;
    box-shadow: 0 0 0 1px rgba(0,0,0,0.8), 0 4px 24px rgba(0,0,0,0.7) !important;
}
body.mode-classic .vn-controls {
    background: linear-gradient(180deg, rgba(30,20,8,0.97), rgba(18,11,4,0.99)) !important;
    border-color: rgba(201,164,90,0.35) !important;
}

.vn-control-slot {
    width: 30px !important;
    height: 30px !important;
    flex: 0 0 30px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

.vn-control-btn {
    width: 22px !important;
    height: 22px !important;
    border-radius: 3px !important;
    transform: rotate(45deg) !important;
    padding: 0 !important;
    background: linear-gradient(135deg, rgba(52,42,28,1), rgba(28,20,10,1), rgba(20,14,6,1)) !important;
    border: 1px solid rgba(192,176,152,0.4) !important;
    box-shadow:
        inset 1px 1px 0 rgba(255,255,255,0.08),
        inset -1px -1px 0 rgba(0,0,0,0.5),
        0 2px 4px rgba(0,0,0,0.6) !important;
    color: rgba(192,176,152,0.75) !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    margin-top: -11px !important;
    margin-left: -11px !important;
    transition: background 0.15s, border-color 0.15s, box-shadow 0.15s, color 0.15s !important;
}
.vn-control-btn .vn-control-icon {
    transform: rotate(-45deg) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    width: 100% !important;
    height: 100% !important;
}
.vn-control-btn .vn-control-icon svg {
    width: 11px !important;
    height: 11px !important;
}
.vn-control-btn:hover {
    background: linear-gradient(135deg, rgba(80,60,20,1), rgba(50,36,12,1), rgba(36,24,8,1)) !important;
    border-color: rgba(160,128,220,0.75) !important;
    color: var(--eth-gold, #a080e0) !important;
    box-shadow:
        inset 1px 1px 0 rgba(255,220,140,0.15),
        inset -1px -1px 0 rgba(0,0,0,0.5),
        0 0 8px rgba(160,128,220,0.25),
        0 2px 6px rgba(0,0,0,0.7) !important;
}
.vn-control-btn:active {
    transform: rotate(45deg) scale(0.94) !important;
    box-shadow:
        inset 1px 1px 0 rgba(0,0,0,0.5),
        inset -1px -1px 0 rgba(255,255,255,0.04),
        0 1px 2px rgba(0,0,0,0.6) !important;
}
.vn-control-divider {
    width: 1px !important;
    background: linear-gradient(to bottom, transparent, rgba(192,176,152,0.3) 30%, rgba(192,176,152,0.3) 70%, transparent) !important;
    margin: 2px 3px !important;
}

/* Clásico: dorado */
body.mode-classic .vn-control-btn {
    background: linear-gradient(135deg, rgba(60,40,16,1), rgba(32,20,6,1), rgba(22,13,3,1)) !important;
    border-color: rgba(201,164,90,0.35) !important;
    color: rgba(201,164,90,0.7) !important;
    box-shadow: inset 1px 1px 0 rgba(255,200,100,0.08), inset -1px -1px 0 rgba(0,0,0,0.6), 0 2px 4px rgba(0,0,0,0.6) !important;
}
body.mode-classic .vn-control-btn:hover {
    background: linear-gradient(135deg, rgba(100,70,20,1), rgba(60,40,10,1), rgba(40,24,6,1)) !important;
    border-color: rgba(201,164,90,0.8) !important;
    color: #c9a45a !important;
    box-shadow: inset 1px 1px 0 rgba(255,210,120,0.15), inset -1px -1px 0 rgba(0,0,0,0.5), 0 0 10px rgba(201,164,90,0.22), 0 2px 6px rgba(0,0,0,0.6) !important;
}

/* RPG: plateado con hover crimson */
body.mode-rpg .vn-control-btn {
    background: linear-gradient(135deg, rgba(40,32,20,1), rgba(20,14,6,1), rgba(12,8,2,1)) !important;
    border: 1.5px solid rgba(192,176,152,0.38) !important;
    color: rgba(192,176,152,0.6) !important;
    box-shadow: inset 1px 1px 0 rgba(255,255,255,0.07), inset -1px -1px 0 rgba(0,0,0,0.7), 0 2px 5px rgba(0,0,0,0.7) !important;
}
body.mode-rpg .vn-control-btn:hover {
    background: linear-gradient(135deg, rgba(116,28,28,0.9), rgba(60,14,14,0.95), rgba(30,8,8,1)) !important;
    border-color: rgba(192,176,152,0.65) !important;
    color: rgba(220,200,168,0.9) !important;
    box-shadow: inset 1px 1px 0 rgba(255,200,180,0.1), inset -1px -1px 0 rgba(0,0,0,0.6), 0 0 10px rgba(140,32,32,0.35), 0 2px 6px rgba(0,0,0,0.7) !important;
}

/* Tooltip contrarotado */
.vn-control-btn::after {
    transform: translateX(-50%) translateY(-4px) rotate(-45deg) !important;
    left: 50% !important;
    top: calc(100% + 12px) !important;
}
.vn-control-btn:hover::after,
.vn-control-btn:focus-visible::after {
    transform: translateX(-50%) translateY(0) rotate(-45deg) !important;
    opacity: 1 !important;
    transition-delay: 0.4s !important;
}

/* ════════════════════════════════════════════════════════════════════
   MODO RPG — Fondo de aldea nocturna + efectos de ambientación
   ════════════════════════════════════════════════════════════════════ */

body.mode-rpg #vnSection {
    position: relative;
    background:
        url('./assets/backgrounds/rpg_background.png')
        center bottom / cover no-repeat !important;
}

/* Vignette + brasas */
body.mode-rpg #vnSection::after {
    content: '' !important;
    position: absolute !important;
    inset: 0 !important;
    pointer-events: none !important;
    mix-blend-mode: screen !important;
    opacity: 0.18 !important;
    z-index: 1 !important;
    background:
        radial-gradient(circle 2px at 20% 75%, rgba(255,160,40,0.9) 0%, transparent 100%),
        radial-gradient(circle 1.5px at 36% 68%, rgba(255,140,20,0.6) 0%, transparent 100%),
        radial-gradient(circle 2px at 50% 73%, rgba(255,180,60,0.7) 0%, transparent 100%),
        radial-gradient(circle 1px at 65% 70%, rgba(255,150,30,0.5) 0%, transparent 100%),
        radial-gradient(circle 1.5px at 80% 74%, rgba(255,170,50,0.65) 0%, transparent 100%),
        radial-gradient(ellipse at 50% 60%,
            transparent 25%,
            rgba(3,5,9,0.45) 65%,
            rgba(2,3,7,0.82) 100%) !important;
    animation: rpg-sparks 6s linear infinite alternate !important;
}

/* Pulso de antorcha — sobreescribe el overlay base del modo rpg */
body.mode-rpg .vn-section::before {
    animation: rpg-torch-pulse 4s ease-in-out infinite !important;
    background:
        radial-gradient(ellipse 38% 52% at 18% 72%, rgba(200,120,30,0.2) 0%, transparent 100%),
        radial-gradient(ellipse 38% 52% at 82% 72%, rgba(200,120,30,0.18) 0%, transparent 100%),
        linear-gradient(180deg, rgba(4,8,14,0.46) 0%, rgba(6,10,18,0.2) 45%, rgba(4,6,12,0.5) 100%) !important;
}

/* z-index en vnSection > * eliminado — rompe el panel de controles */

@keyframes rpg-torch-pulse {
    0%,100% { opacity: 1; }
    30%     { opacity: 1.0; filter: brightness(1.08); }
    55%     { opacity: 0.88; filter: brightness(0.95); }
    80%     { opacity: 1.0; filter: brightness(1.04); }
}
@keyframes rpg-sparks {
    0%   { background-position: 20% 75%, 36% 68%, 50% 73%, 65% 70%, 80% 74%, center; }
    50%  { background-position: 21% 55%, 34% 48%, 52% 52%, 64% 50%, 81% 54%, center; }
    100% { background-position: 19% 30%, 37% 25%, 49% 28%, 66% 26%, 79% 30%, center; }
}

@media (prefers-reduced-motion: reduce) {
    body.mode-rpg .vn-section::before,
    body.mode-rpg #vnSection::after { animation: none !important; }
}

/* ════════════════════════════════════════════════════════════════════
   VN FRAME HARD RESET — arquitectura unificada sin paneles tipo card
   ════════════════════════════════════════════════════════════════════ */
#vnSection .ui-layer,
#vnSection .ui-layer > .left-panel,
#vnSection .ui-layer > .center-panel,
#vnSection .ui-layer > .right-panel,
#vnSection .ui-layer > .bottom-panel {
    gap: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
}

#vnSection .ui-layer > .left-panel,
#vnSection .ui-layer > .center-panel,
#vnSection .ui-layer > .right-panel,
#vnSection .ui-layer > .bottom-panel {
    background: transparent !important;
}

#vnSection .ui-layer > .left-panel {
    border-right: 1px solid rgba(188, 148, 84, 0.46) !important;
}

#vnSection .ui-layer > .right-panel {
    border-left: 1px solid rgba(188, 148, 84, 0.46) !important;
}

#vnSection .ui-layer > .bottom-panel {
    border-top: 1px solid rgba(188, 148, 84, 0.46) !important;
}

#vnSection .left-panel .vn-info-card,
#vnSection .right-panel .vn-controls {
    margin: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background: transparent !important;
}

#vnSection .left-panel .vn-info-card::before,
#vnSection .left-panel .vn-info-card::after,
#vnSection .right-panel .vn-controls::before,
#vnSection .right-panel .vn-controls::after {
    content: none !important;
    box-shadow: none !important;
    border: 0 !important;
}

/* Restaurar caja de diálogo y acciones integradas del panel inferior.
   rpg-scene.css aplica position:static!important asumiendo que .bottom-panel
   está dentro del grid .ui-layer. Como en el HTML real está fuera del grid,
   restauramos el posicionamiento fijo original. */
#vnSection .bottom-panel .vn-dialogue-box {
    /* ── Posicionamiento ── */
    position: fixed !important;
    left: 50% !important;
    top: auto !important;
    right: auto !important;
    bottom: 2rem !important;
    transform: translateX(-50%) !important;
    width: min(900px, 85%) !important;
    max-width: calc(100vw - 2rem) !important;
    margin: 0 !important;
    /* ── Apariencia ── */
    background: rgba(18, 12, 8, 0.65) !important;
    border: 1px solid rgba(160,128,220,0.35) !important;
    border-top: 1px solid rgba(255,255,255,0.06) !important;
    border-radius: 14px !important;
    box-shadow:
        0 18px 40px rgba(0,0,0,0.55),
        0 2px 0 rgba(0,0,0,0.35),
        inset 0 1px 0 rgba(255,255,255,0.05) !important;
    backdrop-filter: blur(6px) !important;
    -webkit-backdrop-filter: blur(6px) !important;
    opacity: 1 !important;
    visibility: visible !important;
}

#vnSection .bottom-panel #vnReplyPanel {
    opacity: 1 !important;
    visibility: visible !important;
}

/* La toolbar principal debe seguir visible en RPG; la barra experimental fue retirada del DOM. */
body.mode-rpg .vn-controls {
    display: flex !important;
}

/* RESET FINAL DE UNIDAD VISUAL: una sola superficie continua */
#vnSection .ui-layer {
    position: absolute !important;
    inset: 0 !important;
    background: transparent !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#vnSection .ui-layer > .left-panel,
#vnSection .ui-layer > .center-panel,
#vnSection .ui-layer > .right-panel,
#vnSection .ui-layer > .bottom-panel {
    position: relative !important;
    background: transparent !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#vnSection .ui-layer > .left-panel > *,
#vnSection .ui-layer > .center-panel > *,
#vnSection .ui-layer > .right-panel > *,
#vnSection .ui-layer > .bottom-panel > * {
    border-radius: 0 !important;
    box-shadow: none !important;
    margin-top: 0 !important;
    margin-bottom: 0 !important;
}

#vnSection .left-panel,
#vnSection .center-panel,
#vnSection .right-panel,
#vnSection .bottom-panel,
#vnSection .left-panel::before,
#vnSection .center-panel::before,
#vnSection .right-panel::before,
#vnSection .bottom-panel::before,
#vnSection .left-panel::after,
#vnSection .center-panel::after,
#vnSection .right-panel::after,
#vnSection .bottom-panel::after {
    content: none !important;
    box-shadow: none !important;
    border-radius: 0 !important;
    filter: none !important;
}

