    box-shadow: 0 12px 40px rgba(0,0,0,0.65), inset 0 1px 0 rgba(200,165,80,0.08) !important;
}
body.mode-rpg .vn-dm-panel-header {
    border-bottom-color: rgba(180, 140, 80, 0.18) !important;
