}
body.mode-rpg .vn-dm-panel-title {
    color: rgba(220, 182, 100, 0.85) !important;
}
body.mode-rpg .vn-dm-panel-header button {
    color: rgba(180, 140, 80, 0.4) !important;
}
body.mode-rpg .vn-dm-panel-header button:hover {
    color: rgba(225, 185, 100, 0.85) !important;
}
body.mode-rpg .vn-dm-tabbar {
    border-bottom-color: rgba(180, 140, 80, 0.12) !important;
}
body.mode-rpg .vn-dm-tab {
    border-color: rgba(180, 140, 80, 0.20) !important;
    background: rgba(180, 140, 80, 0.05) !important;
    color: rgba(180, 140, 80, 0.60) !important;
}
body.mode-rpg .vn-dm-tab:hover {
    border-color: rgba(180, 140, 80, 0.45) !important;
    color: rgba(225, 194, 135, 0.90) !important;
}
body.mode-rpg .vn-dm-tab.active {
    background: rgba(180, 140, 80, 0.20) !important;
    border-color: rgba(180, 140, 80, 0.50) !important;
