}
body.mode-rpg .vn-dm-section {
    border-bottom-color: rgba(180, 140, 80, 0.08) !important;
}
body.mode-rpg .dm-char-row {
    border-color: rgba(180, 140, 80, 0.10) !important;
}
body.mode-rpg .dm-cond-tag {
    border-color: rgba(180, 140, 80, 0.20) !important;
}
body.mode-rpg .dm-select {
    border-color: rgba(180, 140, 80, 0.20) !important;
