}
body.mode-rpg .dm-btn,
body.mode-rpg .dm-btn-primary {
    border-color: rgba(180, 140, 80, 0.30) !important;
    color: rgba(220, 185, 110, 0.85) !important;
}
body.mode-rpg .dm-btn:hover,
body.mode-rpg .dm-btn-primary:hover {
    background: rgba(180, 140, 80, 0.15) !important;
