/* -- css/modules/09-vn-mode-menus.css -- */
/* ============================================================
   VN MODE MENUS
   Menús separados por modo para evitar que cambios visuales del
   clásico afecten al RPG y viceversa.
   ============================================================ */

#vnSection .vn-toolbar {
    position: fixed;
    top: max(1.2rem, env(safe-area-inset-top, 0px));
    right: 0.85rem;
    left: auto;
    bottom: auto;
    z-index: var(--z-controls, 200);
    display: none;
    flex-direction: column;
    align-items: center;
    gap: 0.35rem;
    max-height: calc(100dvh - 2.4rem - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
    overflow-y: auto;
    overflow-x: visible;
    pointer-events: auto;
    box-sizing: border-box;
}

body.mode-classic #vnSection .vn-classic-controls,
body:not(.mode-rpg) #vnSection .vn-classic-controls {
    display: flex;
}

body.mode-rpg #vnSection .vn-rpg-controls {
    display: flex;
}

body.mode-rpg #vnSection .vn-classic-controls,
body.mode-classic #vnSection .vn-rpg-controls,
body:not(.mode-rpg) #vnSection .vn-rpg-controls {
    display: none !important;
}

/* ── Menú clásico: cristal dorado de novela visual ─────────── */
#vnSection .vn-classic-controls {
    width: 54px;
    padding: 0.52rem 0.42rem;
    border: 1px solid rgba(246, 219, 149, 0.42);
    border-radius: 16px;
    background: linear-gradient(180deg, rgba(9, 13, 25, 0.88), rgba(16, 12, 8, 0.94));
    box-shadow: 0 12px 34px rgba(0, 0, 0, 0.48), inset 0 1px 0 rgba(255, 232, 180, 0.08);
    backdrop-filter: blur(12px) saturate(1.08);
    -webkit-backdrop-filter: blur(12px) saturate(1.08);
}

#vnSection .vn-classic-control-slot {
    width: 100%;
    display: flex;
    justify-content: center;
}

#vnSection .vn-classic-control-divider {
    width: 72%;
    height: 1px;
    margin: 0.2rem 0;
    background: linear-gradient(90deg, transparent, rgba(246, 219, 149, 0.34), transparent);
}

#vnSection .vn-classic-control-btn {
    width: 38px;
    height: 38px;
    min-width: 38px;
    padding: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1px solid rgba(246, 219, 149, 0.18);
    border-radius: 10px;
    background: rgba(20, 15, 8, 0.82);
    color: rgba(240, 227, 204, 0.78);
    cursor: pointer;
    transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;
}

#vnSection .vn-classic-control-btn:hover,
#vnSection .vn-classic-control-btn:focus-visible {
    transform: translateY(-1px);
    border-color: rgba(246, 219, 149, 0.58);
    background: rgba(70, 45, 18, 0.9);
    color: #ffe9b4;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.38);
    outline: none;
}

#vnSection .vn-classic-control-icon,
#vnSection .vn-classic-control-icon svg {
    width: 18px;
    height: 18px;
    display: block;
}

#vnSection .vn-classic-control-btn.is-syncing .vn-classic-control-icon {
    animation: syncSpin 1.2s linear infinite;
}

#vnSection .vn-classic-control-btn.is-upload-pending { color: rgba(255, 190, 78, 0.95); }
#vnSection .vn-classic-control-btn.is-download-pending { color: rgba(150, 205, 255, 0.95); }
#vnSection .vn-classic-control-btn.is-error { color: rgba(255, 112, 92, 0.95); }
#vnSection .vn-classic-control-btn[data-vn-control="favorite-message"].is-favorited,
#vnSection .vn-classic-control-btn[data-vn-control="favorite-message"].is-favorited .vn-classic-control-icon { color: #f4c842; }


#vnSection .vn-classic-active-story-badge {
    max-width: 42px;
    padding: 0.14rem 0.22rem;
    border-radius: 999px;
    border: 1px solid rgba(246, 219, 149, 0.34);
    background: rgba(25, 20, 12, 0.92);
    color: #ffe9b4;
    font-size: 0.58rem;
    line-height: 1.1;
    text-align: center;
    overflow: hidden;
    text-overflow: ellipsis;
}

#vnSection .vn-rpg-active-story-badge {
    max-width: 42px;
    padding: 0.12rem 0.2rem;
    border-radius: 4px;
    border: 1px solid rgba(180, 140, 80, 0.45);
    background: rgba(34, 23, 12, 0.96);
    color: #dec28f;
    font-size: 0.56rem;
    line-height: 1.1;
    text-align: center;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ── Menú RPG: pergamino oscuro, independiente del clásico ─── */
#vnSection .vn-rpg-controls {
    width: 58px;
    padding: 0.46rem 0.36rem;
    border: 2px solid rgba(180, 140, 80, 0.52);
    border-image: linear-gradient(180deg, rgba(213, 177, 103, 0.62), rgba(99, 70, 31, 0.5), rgba(213, 177, 103, 0.62)) 1;
    border-radius: 8px;
    background: linear-gradient(180deg, rgba(34, 23, 12, 0.94), rgba(15, 10, 6, 0.98));
    box-shadow: inset 0 1px 0 rgba(255, 225, 170, 0.1), 0 10px 24px rgba(0, 0, 0, 0.48);
}

#vnSection .vn-rpg-control-slot {
    width: 100%;
    display: flex;
    justify-content: center;
}

#vnSection .vn-rpg-control-divider {
    width: 78%;
    height: 1px;
    margin: 0.22rem 0;
    background: linear-gradient(90deg, transparent, rgba(180, 140, 80, 0.45), transparent);
}

#vnSection .vn-rpg-control-btn {
    width: 36px;
    height: 36px;
    min-width: 36px;
    padding: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border: 1.5px solid rgba(200, 184, 144, 0.28);
    border-radius: 4px;
    background: linear-gradient(145deg, rgba(49, 33, 17, 0.95), rgba(23, 14, 7, 0.96));
    color: rgba(222, 194, 143, 0.78);
    cursor: pointer;
    transition: transform 0.14s ease, border-color 0.14s ease, background 0.14s ease, color 0.14s ease, box-shadow 0.14s ease;
}

#vnSection .vn-rpg-control-btn:hover,
#vnSection .vn-rpg-control-btn:focus-visible {
    transform: translateX(-1px);
    border-color: rgba(220, 178, 105, 0.56);
    background: linear-gradient(145deg, rgba(100, 24, 24, 0.42), rgba(29, 18, 9, 0.98));
    color: #f3dfbf;
    box-shadow: 0 0 12px rgba(201, 168, 108, 0.12), 0 4px 16px rgba(0, 0, 0, 0.46);
    outline: none;
}

#vnSection .vn-rpg-control-icon,
#vnSection .vn-rpg-control-icon svg {
    width: 17px;
    height: 17px;
    display: block;
}

#vnSection .vn-rpg-control-btn.is-syncing .vn-rpg-control-icon {
    animation: syncSpin 1.2s linear infinite;
}

#vnSection .vn-rpg-control-btn.is-upload-pending { color: rgba(255, 180, 60, 0.95); }
#vnSection .vn-rpg-control-btn.is-download-pending { color: rgba(120, 190, 255, 0.95); }
#vnSection .vn-rpg-control-btn.is-error { color: rgba(255, 100, 80, 0.95); }
#vnSection .vn-rpg-control-btn[data-vn-control="favorite-message"].is-favorited,
#vnSection .vn-rpg-control-btn[data-vn-control="favorite-message"].is-favorited .vn-rpg-control-icon { color: #f0c04d; }

body.immersive-mode #vnSection .vn-toolbar {
    opacity: 0;
    pointer-events: none;
    transition: opacity 180ms ease;
}

body.immersive-mode.immersive-reveal #vnSection .vn-toolbar {
    opacity: 1;
    pointer-events: auto;
}

@media (max-width: 900px) {
    #vnSection .vn-toolbar {
        top: max(0.7rem, env(safe-area-inset-top, 0px));
        right: 0.7rem;
    }
}

@media (max-width: 768px) {
    #vnSection .vn-toolbar {
        display: none !important;
    }
}

@media (prefers-reduced-motion: reduce) {
    #vnSection .vn-classic-control-btn,
    #vnSection .vn-rpg-control-btn,
    #vnSection .vn-classic-control-btn.is-syncing .vn-classic-control-icon,
    #vnSection .vn-rpg-control-btn.is-syncing .vn-rpg-control-icon {
        animation: none !important;
        transition: none !important;
    }
}


/* -- css/modules/affinity-atmosphere.css -- */
/* ═══════════════════════════════════════════════════════════════════
   AFFINITY ATMOSPHERE — Modo Clásico
   Efectos visuales en el panel de personaje según rango de afinidad.
   Solo activos en body.mode-classic.
   ═══════════════════════════════════════════════════════════════════ */

/* ── Transición suave del fondo del info-card ── */
body.mode-classic .vn-info-card {
    transition:
        background 1.2s ease,
        box-shadow 1.2s ease,
        border-color 0.8s ease;
}

/* ── Ramas: temperatura del fondo del panel ──
   Clases del body: affinity-branch-<rama> + affinity-tier-<n>, con
   --affinity-rgb = color canónico del rango (fijado por affinity-atmosphere.js
   desde window.affinityRanks — única fuente de verdad).
   Fix cascada: #vnSection + !important necesarios para ganar a
   07-overrides.css, que fija estas propiedades con !important y #vnSection. ── */

/* Intensidad del glow según profundidad del rango en su rama */
body.affinity-tier-1 { --affinity-glow: 0.10; }
body.affinity-tier-2 { --affinity-glow: 0.16; }
body.affinity-tier-3 { --affinity-glow: 0.22; }
body.affinity-tier-4 { --affinity-glow: 0.28; }
body.affinity-tier-5 { --affinity-glow: 0.34; }

/* Borde y glow comunes a todas las ramas — color canónico del rango */
body.mode-classic[class*="affinity-branch-"] #vnSection .vn-info-card {
    border-color: rgba(var(--affinity-rgb), 0.5) !important;
    box-shadow:
        0 12px 36px rgba(0, 0, 0, 0.45),
        0 0 0 1px rgba(var(--affinity-rgb), 0.12),
        0 0 24px -4px rgba(var(--affinity-rgb), var(--affinity-glow, 0.15)) !important;
}

/* Temperatura de fondo por rama */
body.mode-classic.affinity-branch-common #vnSection .vn-info-card {
    background: linear-gradient(135deg,
        rgba(38, 34, 46, 0.96),
        rgba(28, 24, 36, 0.98)) !important;
}
body.mode-classic.affinity-branch-friendship #vnSection .vn-info-card {
    background: linear-gradient(135deg,
        rgba(20, 44, 32, 0.96),
        rgba(14, 34, 24, 0.98)) !important;
}
body.mode-classic.affinity-branch-romance #vnSection .vn-info-card {
    background: linear-gradient(135deg,
        rgba(54, 30, 18, 0.97),
        rgba(44, 18, 12, 0.99)) !important;
}
body.mode-classic.affinity-branch-negative #vnSection .vn-info-card {
    background: linear-gradient(135deg,
        rgba(46, 36, 16, 0.96),
        rgba(34, 26, 10, 0.98)) !important;
}
body.mode-classic.affinity-branch-rivalry #vnSection .vn-info-card {
    background: linear-gradient(135deg,
        rgba(52, 26, 14, 0.97),
        rgba(38, 16, 8, 0.99)) !important;
}
body.mode-classic.affinity-branch-enmity #vnSection .vn-info-card {
    background: linear-gradient(135deg,
        rgba(30, 34, 40, 0.97),
        rgba(20, 24, 30, 0.99)) !important;
}

/* ── Adorno del avatar: contenedor relativo para posicionar el ornamento ── */
.vn-info-avatar {
    position: relative;
}

/* Ornamento base — oculto por defecto */
.vn-affinity-ornament {
    position: absolute;
    pointer-events: none;
    z-index: 10;
    opacity: 0;
    transition: opacity 0.6s ease;
    font-size: 11px;
    line-height: 1;
    user-select: none;
}
.vn-affinity-ornament.visible {
    opacity: 1;
}

/* Ornamentos por rama — el emoji es el icon canónico del rango,
   el color del halo llega vía --affinity-rgb */
.vn-affinity-ornament.ornament-common,
.vn-affinity-ornament.ornament-friendship {
    top: -5px;
    right: -5px;
    font-size: 10px;
    filter: drop-shadow(0 0 4px rgba(var(--affinity-rgb, 52,152,219), 0.8));
    animation: ornament-twinkle 2.4s ease-in-out infinite;
}
.vn-affinity-ornament.ornament-romance {
    top: -8px;
    right: -6px;
    font-size: 13px;
    filter: drop-shadow(0 0 6px rgba(var(--affinity-rgb, 231,76,80), 0.9));
    animation: ornament-heartbeat 1.4s ease-in-out infinite;
}
.vn-affinity-ornament.ornament-negative {
    top: -6px;
    right: -5px;
    font-size: 11px;
    filter: drop-shadow(0 0 4px rgba(var(--affinity-rgb, 230,126,34), 0.85));
    animation: ornament-flicker 1.8s steps(2, jump-none) infinite;
}
.vn-affinity-ornament.ornament-rivalry {
    top: -7px;
    right: -6px;
    font-size: 12px;
    filter: drop-shadow(0 0 5px rgba(var(--affinity-rgb, 211,84,0), 0.9));
    animation: ornament-clash 2.2s ease-in-out infinite;
}
.vn-affinity-ornament.ornament-enmity {
    top: -6px;
    right: -5px;
    font-size: 11px;
    filter: drop-shadow(0 0 4px rgba(var(--affinity-rgb, 86,101,115), 0.9));
    animation: ornament-dim 3.2s ease-in-out infinite;
}

@keyframes ornament-twinkle {
    0%, 100% { transform: scale(1) rotate(0deg); opacity: 1; }
    50%       { transform: scale(1.2) rotate(15deg); opacity: 0.7; }
}
@keyframes ornament-butterfly {
    0%, 100% { transform: scale(1) translateY(0px) rotate(-5deg); opacity: 1; }
    30%       { transform: scale(1.1) translateY(-3px) rotate(5deg); opacity: 0.9; }
    60%       { transform: scale(0.95) translateY(-1px) rotate(-8deg); opacity: 1; }
}
@keyframes ornament-heartbeat {
    0%, 100% { transform: scale(1); }
    15%       { transform: scale(1.25); }
    30%       { transform: scale(1); }
    45%       { transform: scale(1.15); }
    60%       { transform: scale(1); }
}
@keyframes ornament-flicker {
    0%, 100% { opacity: 1; }
    50%       { opacity: 0.45; }
}
@keyframes ornament-clash {
    0%, 100% { transform: rotate(0deg) scale(1); }
    40%       { transform: rotate(-12deg) scale(1.1); }
    55%       { transform: rotate(8deg) scale(1.05); }
    70%       { transform: rotate(0deg) scale(1); }
}
@keyframes ornament-dim {
    0%, 100% { opacity: 1;    transform: scale(1); }
    50%       { opacity: 0.55; transform: scale(0.94); }
}

/* ── Partículas de afinidad — contenedor sobre el info-card ── */
.vn-affinity-particles {
    position: absolute;
    inset: 0;
    pointer-events: none;
    overflow: hidden;
    border-radius: inherit;
    z-index: 2;
}
.vn-affinity-particles canvas {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
}

/* ── Reduced motion: ornamentos estáticos ── */
@media (prefers-reduced-motion: reduce) {
    .vn-affinity-ornament {
        animation: none !important;
    }
}


/* -- css/bonds.css -- */
/* ═══════════════════════════════════════════════════════════════════
   VÍNCULOS — Sección de relaciones entre personajes
   Diseño: Vista previa compacta + panel de detalle por personaje
   ═══════════════════════════════════════════════════════════════════ */

/* ── Sección base ── */
#bondsSection {
    display: none;
    flex-direction: column;
    height: 100vh;
    height: 100dvh;
    overflow: hidden;
    background: var(--bg-primary);
}
#bondsSection.active {
    display: flex;
    animation: fadeIn 0.4s ease;
}

/* ── Header ── */
.bonds-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 18px 20px 14px;
    background: linear-gradient(to right, var(--bg-secondary), rgba(26,18,12,0.98));
    border-bottom: 1px solid rgba(201,168,108,0.2);
    flex-shrink: 0;
}
.bonds-header > div {
    flex: 1;
}
.bonds-back-btn {
    background: none;
    border: 1px solid rgba(201,168,108,0.3);
    border-radius: 8px;
    color: var(--accent-gold);
    padding: 6px 10px;
    cursor: pointer;
    font-size: 0.85rem;
    transition: background 0.2s, border-color 0.2s;
    margin-left: auto;
}
.bonds-back-btn:hover {
    background: rgba(201,168,108,0.1);
    border-color: rgba(201,168,108,0.6);
}
.bonds-title {
    font-family: var(--font-display, serif);
    font-size: 1.35rem;
    color: var(--accent-gold);
    letter-spacing: 0.06em;
    flex: 1;
}
.bonds-subtitle {
    font-size: 0.78rem;
    color: rgba(201,168,108,0.5);
    font-style: italic;
}

/* ── Scroll container — grid de tarjetas compactas ── */
#bondsContainer {
    flex: 1;
    overflow-y: auto;
    padding: 20px 16px 32px;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 14px;
    align-content: start;
}

/* ── Loading / Empty states ── */
.bonds-loading,
.bonds-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    min-height: 200px;
    color: rgba(201,168,108,0.45);
    font-style: italic;
    text-align: center;
    font-size: 0.95rem;
    grid-column: 1 / -1;
}
.bonds-empty-icon { font-size: 2.5rem; opacity: 0.5; }
.bonds-empty span { font-size: 0.82rem; opacity: 0.6; }

/* ═══════════════════════════════════════════════════════════════════
   TARJETA COMPACTA (vista previa)
   ═══════════════════════════════════════════════════════════════════ */
.bonds-char-card {
    background: linear-gradient(135deg,
        rgba(42, 30, 14, 0.96),
        rgba(32, 22, 8, 0.98));
    border: 1px solid color-mix(in srgb, var(--char-color, #c9a86c) 22%, transparent);
    border-radius: 14px;
    overflow: hidden;
    box-shadow: 0 4px 20px rgba(0,0,0,0.35);
    cursor: pointer;
    transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
    user-select: none;
}
.bonds-char-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 28px rgba(0,0,0,0.5);
    border-color: color-mix(in srgb, var(--char-color, #c9a86c) 55%, transparent);
}
.bonds-char-card:active { transform: translateY(0); }

.bonds-char-header {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 14px;
    background: linear-gradient(90deg,
        color-mix(in srgb, var(--char-color, #8b7355) 18%, transparent),
        transparent);
}
.bonds-char-avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid color-mix(in srgb, var(--char-color, #8b7355) 60%, transparent);
    flex-shrink: 0;
}
.bonds-char-avatar-img { width: 100%; height: 100%; object-fit: cover; }
.bonds-char-avatar-initial {
    width: 100%; height: 100%;
    display: flex; align-items: center; justify-content: center;
    background: color-mix(in srgb, var(--char-color, #8b7355) 30%, transparent);
    color: var(--char-color, #c9a86c);
    font-size: 1.1rem; font-weight: 600;
}
.bonds-char-info { flex: 1; min-width: 0; }
.bonds-char-name {
    font-size: 0.95rem;
    font-weight: 600;
    color: var(--char-color, #c9a86c);
    letter-spacing: 0.03em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.bonds-char-race {
    font-size: 0.72rem;
    color: rgba(201,168,108,0.5);
    font-style: italic;
    margin-top: 1px;
}
.bonds-char-count {
    font-size: 0.7rem;
    color: rgba(201,168,108,0.4);
    background: rgba(201,168,108,0.08);
    border: 1px solid rgba(201,168,108,0.12);
    border-radius: 10px;
    padding: 2px 8px;
    white-space: nowrap;
    flex-shrink: 0;
}

/* Preview de mini-avatares */
.bonds-preview {
    padding: 8px 14px 12px;
    display: flex;
    align-items: center;
    gap: 8px;
    min-height: 44px;
    border-top: 1px solid rgba(201,168,108,0.07);
}
.bonds-preview-avatars {
    display: flex;
    align-items: center;
}
.bonds-preview-avatar {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid rgba(26, 18, 12, 0.95);
    margin-left: -7px;
    flex-shrink: 0;
    background: rgba(201,168,108,0.1);
}
.bonds-preview-avatar:first-child { margin-left: 0; }
.bonds-preview-avatar img { width: 100%; height: 100%; object-fit: cover; }
.bonds-preview-avatar-init {
    width: 100%; height: 100%;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.66rem;
    color: rgba(201,168,108,0.7);
}
.bonds-preview-overflow {
    font-size: 0.7rem;
    color: rgba(201,168,108,0.4);
    margin-left: 6px;
    white-space: nowrap;
}
.bonds-preview-empty {
    font-size: 0.73rem;
    color: rgba(201,168,108,0.28);
    font-style: italic;
}
.bonds-preview-cta {
    margin-left: auto;
    font-size: 0.65rem;
    color: rgba(201,168,108,0.28);
    letter-spacing: 0.05em;
    text-transform: uppercase;
    transition: color 0.15s;
}
.bonds-char-card:hover .bonds-preview-cta {
    color: rgba(201,168,108,0.65);
}

/* ═══════════════════════════════════════════════════════════════════
   PANEL DE DETALLE (slide-over)
   ═══════════════════════════════════════════════════════════════════ */
#bondsDetailOverlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: var(--z-modals, 500);
    background: rgba(10, 6, 2, 0.62);
    backdrop-filter: blur(3px);
    -webkit-backdrop-filter: blur(3px);
}
#bondsDetailOverlay.open {
    display: flex;
    justify-content: flex-end;
    animation: bonds-overlay-in 0.2s ease;
}
@keyframes bonds-overlay-in {
    from { opacity: 0; }
    to   { opacity: 1; }
}

.bonds-detail-panel {
    width: min(460px, 100vw);
    height: 100%;
    background: linear-gradient(160deg, rgba(38,26,11,0.99), rgba(22,15,6,1));
    border-left: 1px solid rgba(201,168,108,0.18);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    animation: bonds-panel-in 0.25s cubic-bezier(0.22,1,0.36,1);
    box-shadow: -10px 0 44px rgba(0,0,0,0.65);
}
@keyframes bonds-panel-in {
    from { transform: translateX(100%); }
    to   { transform: translateX(0); }
}

.bonds-detail-header {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 16px 18px;
    background: linear-gradient(90deg,
        color-mix(in srgb, var(--char-color, #8b7355) 20%, transparent),
        transparent);
    border-bottom: 1px solid rgba(201,168,108,0.14);
    flex-shrink: 0;
}
.bonds-detail-avatar {
    width: 46px;
    height: 46px;
    border-radius: 50%;
    overflow: hidden;
    border: 2px solid color-mix(in srgb, var(--char-color, #8b7355) 65%, transparent);
    flex-shrink: 0;
}
.bonds-detail-avatar img { width: 100%; height: 100%; object-fit: cover; }
.bonds-detail-avatar-init {
    width: 100%; height: 100%;
    display: flex; align-items: center; justify-content: center;
    background: color-mix(in srgb, var(--char-color, #8b7355) 28%, transparent);
    color: var(--char-color, #c9a86c);
    font-size: 1.25rem; font-weight: 600;
}
.bonds-detail-charinfo { flex: 1; }
.bonds-detail-charname {
    font-family: var(--font-display, serif);
    font-size: 1.05rem;
    color: var(--char-color, #c9a86c);
    letter-spacing: 0.04em;
}
.bonds-detail-charrace {
    font-size: 0.72rem;
    color: rgba(201,168,108,0.48);
    font-style: italic;
    margin-top: 2px;
}
.bonds-detail-close {
    background: none;
    border: 1px solid rgba(201,168,108,0.18);
    border-radius: 8px;
    color: rgba(201,168,108,0.45);
    padding: 6px 9px;
    cursor: pointer;
    font-size: 1rem;
    line-height: 1;
    transition: background 0.15s, color 0.15s;
    flex-shrink: 0;
}
.bonds-detail-close:hover {
    background: rgba(201,168,108,0.1);
    color: var(--accent-gold, #c9a86c);
}

.bonds-detail-body {
    flex: 1;
    overflow-y: auto;
    padding: 6px 0 32px;
}

/* ── Fila de vínculo individual ── */
.bond-row {
    display: flex;
    gap: 12px;
    padding: 12px 18px;
    border-bottom: 1px solid rgba(201,168,108,0.06);
    transition: background 0.18s;
}
.bond-row:last-child { border-bottom: none; }
.bond-row:hover { background: rgba(201,168,108,0.04); }

.bond-other-avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    overflow: hidden;
    border: 1px solid rgba(201,168,108,0.2);
    flex-shrink: 0;
    margin-top: 2px;
}
.bond-other-avatar-img { width: 100%; height: 100%; object-fit: cover; }
.bond-other-avatar-initial {
    width: 100%; height: 100%;
    display: flex; align-items: center; justify-content: center;
    background: rgba(201,168,108,0.1);
    color: rgba(201,168,108,0.6);
    font-size: 0.95rem;
}

.bond-content { flex: 1; min-width: 0; }
.bond-other-name {
    font-size: 0.88rem;
    font-weight: 600;
    color: #f0e0c0;
    margin-bottom: 6px;
    display: flex;
    align-items: center;
    gap: 6px;
}

/* ── Pills de afinidad ── */
.bond-affinities {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
    margin-bottom: 8px;
}
.bond-aff-pill {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 3px 8px;
    border-radius: 20px;
    background: color-mix(in srgb, var(--rank-color, #ffffff) 12%, transparent);
    border: 1px solid color-mix(in srgb, var(--rank-color, #ffffff) 35%, transparent);
    font-size: 0.72rem;
}
.bond-aff-incoming { opacity: 0.65; }
.bond-aff-arrow  { color: color-mix(in srgb, var(--rank-color, #ffffff) 70%, transparent); font-size: 0.65rem; }
.bond-aff-rank   { color: var(--rank-color, #ffffff); font-weight: 600; }
.bond-aff-val    { color: rgba(255,255,255,0.4); font-size: 0.67rem; }
/* Icono de rama (♦ ♡ ⚔ ✗) — mismo color que el rank */
.bond-aff-icon   { color: var(--rank-color, #ffffff); font-size: 0.75rem; opacity: .85; }
/* Etiqueta de rama — discreta, debajo del rank */
.bond-aff-branch {
    display: block;
    font-size: 0.6rem;
    letter-spacing: .06em;
    color: color-mix(in srgb, var(--rank-color, #ffffff) 55%, transparent);
    margin-top: 1px;
    white-space: nowrap;
}

/* ── Nota ── */
.bond-note-text {
    font-size: 0.8rem;
    color: rgba(220,190,140,0.7);
    font-style: italic;
    margin: 0 0 6px;
    line-height: 1.5;
}
.bond-note-empty {
    font-size: 0.75rem;
    color: rgba(201,168,108,0.25);
    font-style: italic;
    margin: 0 0 6px;
}
.bond-note-editor {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-top: 4px;
}
.bond-note-textarea {
    width: 100%;
    min-height: 64px;
    background: rgba(20,14,6,0.7);
    border: 1px solid rgba(201,168,108,0.3);
    border-radius: 8px;
    color: #f0e0c0;
    font-size: 0.82rem;
    padding: 8px 10px;
    resize: vertical;
    font-family: inherit;
    line-height: 1.5;
    box-sizing: border-box;
}
.bond-note-textarea:focus {
    outline: none;
    border-color: rgba(201,168,108,0.6);
}
.bond-note-actions { display: flex; gap: 6px; }

.btn-sm {
    padding: 4px 12px;
    border-radius: 6px;
    font-size: 0.76rem;
    cursor: pointer;
    border: 1px solid rgba(201,168,108,0.4);
    background: rgba(201,168,108,0.12);
    color: var(--accent-gold, #c9a86c);
    transition: background 0.2s;
}
.btn-sm:hover { background: rgba(201,168,108,0.22); }
.btn-sm:disabled { opacity: 0.5; cursor: not-allowed; }
.btn-ghost {
    background: transparent;
    border-color: rgba(201,168,108,0.2);
    color: rgba(201,168,108,0.5);
}
.btn-ghost:hover {
    background: rgba(201,168,108,0.07);
    color: rgba(201,168,108,0.8);
}

/* ── Historial ── */
.bond-history-toggle {
    display: inline-block;
    background: none;
    border: none;
    color: rgba(201,168,108,0.35);
    font-size: 0.72rem;
    cursor: pointer;
    padding: 0;
    margin-top: 2px;
    transition: color 0.15s;
}
.bond-history-toggle:hover { color: rgba(201,168,108,0.7); }
.bond-history-list {
    display: flex;
    flex-direction: column;
    gap: 3px;
    margin-top: 6px;
    padding: 6px 8px;
    background: rgba(10,6,2,0.4);
    border-radius: 6px;
    border: 1px solid rgba(201,168,108,0.08);
}
.bond-history-entry {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.72rem;
}
.bond-history-arrow { font-weight: 700; color: rgba(201,168,108,0.6); }
.bond-history-rank  { color: var(--rank-color, #c9a86c); font-weight: 600; }
.bond-history-date  { color: rgba(201,168,108,0.3); margin-left: auto; font-size: 0.67rem; }

/* ── Sin vínculos ── */
.bonds-no-relations {
    padding: 28px 18px;
    color: rgba(201,168,108,0.35);
    font-size: 0.82rem;
    font-style: italic;
    text-align: center;
}
.bonds-no-relations span { font-size: 0.76rem; opacity: 0.7; }

/* ── Responsive ── */
@media (max-width: 480px) {
    #bondsContainer {
        grid-template-columns: 1fr;
        padding: 14px 12px 28px;
        gap: 10px;
    }
    .bonds-detail-panel { width: 100vw; }
    .bond-row { padding: 10px 14px; }
}



/* -- css/features.css -- */
/* ═══════════════════════════════════════════════════════════════════
   MESSAGE SEARCH — Panel de búsqueda en mensajes
   ═══════════════════════════════════════════════════════════════════ */

#msgSearchPanel {
    position: absolute;
    top: 0; left: 0; right: 0;
    background: rgba(20, 14, 6, 0.97);
    border-bottom: 1px solid rgba(201,168,108,0.25);
    z-index: 120;
    transform: translateY(-100%);
    transition: transform 0.25s cubic-bezier(0.4,0,0.2,1);
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    max-height: 55vh;
}
#msgSearchPanel.active {
    transform: translateY(0);
}
.msg-search-bar {
    display: flex;
    gap: 8px;
    align-items: center;
}
.msg-search-input {
    flex: 1;
    background: rgba(40,28,12,0.9);
    border: 1px solid rgba(201,168,108,0.35);
    border-radius: 8px;
    color: #f0e0c0;
    font-size: 0.88rem;
    padding: 7px 12px;
    outline: none;
    font-family: inherit;
}
.msg-search-input:focus {
    border-color: rgba(201,168,108,0.65);
}
.msg-search-input::placeholder { color: rgba(201,168,108,0.3); }
.msg-search-close {
    background: none;
    border: 1px solid rgba(201,168,108,0.2);
    border-radius: 6px;
    color: rgba(201,168,108,0.5);
    cursor: pointer;
    padding: 4px 9px;
    font-size: 0.8rem;
    transition: all 0.15s;
}
.msg-search-close:hover {
    background: rgba(201,168,108,0.1);
    color: rgba(201,168,108,0.9);
}
#msgSearchResults {
    overflow-y: auto;
    max-height: 38vh;
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.msg-search-empty {
    color: rgba(201,168,108,0.3);
    font-style: italic;
    font-size: 0.82rem;
    padding: 8px 4px;
}
.msg-search-result {
    padding: 8px 10px;
    border-radius: 8px;
    cursor: pointer;
    background: rgba(201,168,108,0.04);
    border: 1px solid rgba(201,168,108,0.08);
    transition: background 0.15s;
}
.msg-search-result:hover {
    background: rgba(201,168,108,0.10);
    border-color: rgba(201,168,108,0.2);
}
.msg-search-author {
    font-size: 0.72rem;
    color: rgba(201,168,108,0.55);
    font-weight: 600;
    margin-bottom: 3px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.msg-search-text {
    font-size: 0.82rem;
    color: rgba(240,224,192,0.8);
    line-height: 1.45;
}
mark.msg-search-mark {
    background: rgba(241,193,80,0.3);
    color: #f1c140;
    border-radius: 2px;
    padding: 0 1px;
}

/* ═══════════════════════════════════════════════════════════════════
   PRESENCE INDICATORS — Puntos de estado online
   ═══════════════════════════════════════════════════════════════════ */

/* Punto online genérico */
.presence-dot {
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #27ae60;
    box-shadow: 0 0 5px rgba(39,174,96,0.6);
    flex-shrink: 0;
    animation: presence-pulse 2.5s ease-in-out infinite;
}
.presence-dot.offline {
    background: rgba(201,168,108,0.2);
    box-shadow: none;
    animation: none;
}
@keyframes presence-pulse {
    0%, 100% { opacity: 1; transform: scale(1); }
    50%       { opacity: 0.7; transform: scale(0.85); }
}

/* En la galería de personajes */
.char-card-v2 .presence-dot {
    position: absolute;
    bottom: 6px;
    right: 6px;
    width: 9px;
    height: 9px;
    border: 1.5px solid rgba(20,14,6,0.8);
}

/* En el tablón de vínculos */
.bond-row .presence-dot {
    width: 7px;
    height: 7px;
    margin-left: 5px;
    vertical-align: middle;
}

