   AFFINITY HISTORY — Historial en el tablón de vínculos
   ═══════════════════════════════════════════════════════════════════ */

.bond-history-toggle {
    font-size: 0.72rem;
    color: rgba(201,168,108,0.4);
    background: none;
    border: none;
    cursor: pointer;
    padding: 2px 0;
    text-decoration: underline;
    text-underline-offset: 2px;
    transition: color 0.15s;
}
.bond-history-toggle:hover { color: rgba(201,168,108,0.8); }

.bond-history-list {
    margin-top: 6px;
    display: flex;
    flex-direction: column;
    gap: 3px;
    max-height: 120px;
    overflow-y: auto;
}
.bond-history-entry {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.72rem;
    color: rgba(201,168,108,0.5);
}
.bond-history-arrow {
    font-size: 0.7rem;
    color: rgba(201,168,108,0.3);
}
.bond-history-rank {
    font-weight: 600;
    color: var(--rank-color, rgba(201,168,108,0.7));
