}


/* -- css/vn-cinematic.css -- */
/* Visual novel presentation layer */
:root {
    --vn-cinematic-panel-bg: linear-gradient(180deg, rgba(7, 10, 20, 0.92) 0%, rgba(11, 16, 30, 0.88) 100%);
    --vn-cinematic-border: rgba(246, 219, 149, 0.5);
    --vn-cinematic-shadow: 0 20px 44px rgba(0, 0, 0, 0.55);
    --vn-cinematic-gold: #f6db95;
}

#vnSection.vn-section.active {
    padding: 2.6rem 1.2rem 1.4rem;
    min-height: 100dvh;
}

#vnSection.vn-section.active::before {
    background:
        linear-gradient(180deg, rgba(0, 0, 0, 0.58) 0%, rgba(0, 0, 0, 0.18) 28%, rgba(0, 0, 0, 0.2) 72%, rgba(0, 0, 0, 0.68) 100%),
        radial-gradient(circle at 50% 15%, rgba(112, 163, 255, 0.15) 0%, rgba(0, 0, 0, 0) 55%);
    opacity: 1;
}

#vnSection .vn-dialogue-box {
    position: absolute;
    left: 50%;
    bottom: max(1.35rem, env(safe-area-inset-bottom));
    transform: translateX(-50%);
    width: min(1080px, calc(100vw - 2.2rem));
    border: 1px solid var(--vn-cinematic-border);
    border-radius: 20px;
    background: var(--vn-cinematic-panel-bg);
    box-shadow: var(--vn-cinematic-shadow);
    backdrop-filter: blur(9px) saturate(1.1);
    -webkit-backdrop-filter: blur(9px) saturate(1.1);
    padding-top: 3.35rem;
}

#vnSection .vn-dialogue-box::before,
#vnSection .vn-dialogue-box::after {
    pointer-events: none;
}

#vnSection .vn-speaker-plate {
    top: -1.15rem;
    left: 1.4rem;
    border-radius: 999px;
    border: 1px solid rgba(255, 223, 153, 0.55);
    background: linear-gradient(180deg, rgba(40, 25, 11, 0.95), rgba(23, 15, 9, 0.9));
    box-shadow: 0 8px 18px rgba(0, 0, 0, 0.45);
    color: #ffe8b4;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-weight: 700;
}

#vnSection .vn-dialogue-text {
    font-size: clamp(1.02rem, 1.45vw, 1.2rem);
    line-height: 1.82;
    letter-spacing: 0.015em;
    text-shadow: 0 1px 1px rgba(0, 0, 0, 0.42);
    color: #f6f1df;
}

#vnSection .vn-options-container {
    left: 50%;
    bottom: calc(max(1.35rem, env(safe-area-inset-bottom)) + 12.8rem);
    transform: translateX(-50%);
    width: min(980px, calc(100vw - 2.8rem));
    padding: 0.35rem;
    gap: 0.75rem;
}

#vnSection .vn-option-btn,
#vnSection .vn-option {
    border-radius: 14px;
    border: 1px solid rgba(245, 221, 170, 0.36);
    background: linear-gradient(180deg, rgba(26, 32, 48, 0.88), rgba(15, 18, 29, 0.92));
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.28);
}

#vnSection .vn-option-btn:hover,
#vnSection .vn-option:hover {
    border-color: rgba(255, 227, 168, 0.74);
    transform: translateY(-2px);
}

body.mode-rpg #vnSection .vn-controls,
body.mode-classic #vnSection .vn-controls {
    flex-direction: column;
    align-items: stretch;
}

/* Controls ahora manejados por theme-menu/index.css */
/* Se mantiene solo para asegurar posición absoluta dentro de vnSection */
#vnSection .vn-controls {
    position: fixed;
}

#vnSection .vn-control-divider {
    margin: 0.3rem 0;
    width: 100%;
}

#vnSection .vn-info-card {
    top: max(1rem, env(safe-area-inset-top));
    left: 1rem;
    border-radius: 16px;
    border: 1px solid rgba(236, 221, 185, 0.34);
    background: rgba(10, 12, 22, 0.7);
    backdrop-filter: blur(5px);
}

#vnSection .vn-party-panel,
#vnSection .vn-narrate-panel,
#vnSection .vn-dm-panel,
#vnSection .vn-oracle-minipanel {
    border-radius: 16px;
    border: 1px solid rgba(255, 226, 170, 0.28);
    background: rgba(12, 16, 27, 0.94);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.45);
}

/* ── Responsive: desktop medio (≤ 900px) ─────────────────────────────────── */
/* Controls responsive ahora manejado por theme-menu/index.css */
@media (max-width: 900px) {
    #vnSection .vn-info-card {
        left: 0.75rem;
        top: 0.75rem;
        max-width: min(88vw, 380px);
    }

    #vnSection .vn-dialogue-box {
        width: calc(100vw - 1rem);
        bottom: max(0.5rem, env(safe-area-inset-bottom));
        border-radius: 16px;
        padding-top: 2.9rem;
    }

    #vnSection .vn-options-container {
        width: calc(100vw - 1.1rem);
        bottom: calc(max(0.5rem, env(safe-area-inset-bottom)) + 13rem);
    }
}

