        0 32px 80px rgba(0, 0, 0, 0.65),
        0 0 100px -30px rgba(201, 168, 108, 0.20) !important;
    background: rgba(12, 8, 4, 0.97) !important;
    display: flex;
    flex-direction: column;
}

/* â”€â”€ Steps â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
#topicModal .tw-step {
    display: none;
    flex-direction: column;
    min-height: 0;
    width: 100%;
}
#topicModal .tw-step--active {
    display: flex;
    animation: tw-fade-in 0.26s ease;
}
@keyframes tw-fade-in {
    from { opacity: 0; transform: translateY(6px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* â”€â”€ PASO 1: Gran Selector â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
#topicModal .tw-step--1 {
    padding: 2rem 2rem 1.6rem;
    align-items: center;
    gap: 1.4rem;
}
.tw-main-title {
    font-family: 'Cinzel Decorative', 'Cinzel', serif;
    font-size: 1.25rem;
    letter-spacing: 0.06em;
    background: linear-gradient(135deg, #f0d898, #c8a84a, #f0d898);
    -webkit-background-clip: text; background-clip: text;
    -webkit-text-fill-color: transparent;
    text-align: center; margin: 0;
}
.tw-main-sub {
    color: rgba(220, 195, 145, 0.60); font-size: 0.87rem;
    text-align: center; margin: 0; font-style: italic;
}
.tw-card-row {
    display: flex; gap: 1.2rem; width: 100%; flex: 1;
}
.tw-card {
    flex: 1; position: relative;
    display: flex; flex-direction: column; align-items: center;
    padding: 2rem 1.4rem 1.8rem; border-radius: 18px;
    border: 1.5px solid transparent; cursor: pointer;
    text-align: center; background: none; outline: none;
    gap: 0.65rem; min-height: 240px; overflow: hidden;
    transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
}
.tw-card:hover { transform: translateY(-5px); }

/* Classic card */
.tw-card--classic {
    background:
        radial-gradient(ellipse at 50% 0%, rgba(60,90,200,0.18) 0%, transparent 60%),
        radial-gradient(ellipse at 20% 100%, rgba(40,70,180,0.12) 0%, transparent 50%),
        rgba(7, 11, 34, 0.90);
    border-color: rgba(120, 165, 255, 0.28);
    box-shadow: 0 8px 32px rgba(0, 0, 30, 0.50);
}
.tw-card--classic:hover {
    border-color: rgba(130, 175, 255, 0.65);
    box-shadow: 0 14px 48px rgba(50,90,255,0.18), 0 0 60px -20px rgba(100,150,255,0.30);
}
.tw-card--classic::before {
    content: '✦  ✦  ✦'; position: absolute; top: 0.8rem; right: 0.9rem;
    font-size: 0.42rem; letter-spacing: 0.3em;
    color: rgba(155, 200, 255, 0.30); animation: vnt-star-twinkle 3.5s ease-in-out infinite;
    pointer-events: none;
}

/* RPG card */
.tw-card--rpg {
    background:
        radial-gradient(ellipse at 50% 0%, rgba(150,100,20,0.22) 0%, transparent 60%),
        radial-gradient(ellipse at 80% 100%, rgba(120,80,15,0.15) 0%, transparent 50%),
        rgba(18, 12, 5, 0.95);
    border-color: rgba(180, 140, 60, 0.30);
    box-shadow: 0 8px 32px rgba(0,0,0,0.55);
}
.tw-card--rpg:hover {
    border-color: rgba(201, 168, 108, 0.75);
    box-shadow: 0 14px 48px rgba(180,120,20,0.20), 0 0 60px -20px rgba(201,168,108,0.30);
}
.tw-card--rpg::before {
    content: '⚜'; position: absolute; bottom: 0.8rem; left: 1rem;
    font-size: 1.1rem; color: rgba(180,140,60,0.18); pointer-events: none;
}

.tw-card-glyph { font-size: 2.4rem; line-height: 1; display: block; }
.tw-card--classic .tw-card-glyph { color: rgba(155, 200, 255, 0.80); }
.tw-card--rpg     .tw-card-glyph { color: rgba(201, 168, 108, 0.88); }

.tw-card-name {
    font-family: 'Cinzel', serif; font-size: 0.98rem; font-weight: 700;
    letter-spacing: 0.04em; margin: 0; line-height: 1.2;
}
.tw-card--classic .tw-card-name { color: #cce4ff; }
.tw-card--rpg     .tw-card-name { color: #f0ddb0; }

.tw-card-mode-tag {
    font-family: 'Cinzel', serif; font-size: 0.64rem;
    letter-spacing: 0.10em; text-transform: uppercase;
    padding: 0.18rem 0.7rem; border-radius: 999px; border: 1px solid;
}
.tw-card--classic .tw-card-mode-tag { color: rgba(155,200,255,0.78); border-color: rgba(130,175,255,0.28); background: rgba(60,90,200,0.10); }
.tw-card--rpg     .tw-card-mode-tag { color: rgba(201,168,108,0.82); border-color: rgba(180,140,60,0.28); background: rgba(140,100,20,0.10); }

.tw-card-desc {
    font-size: 0.79rem; line-height: 1.55; margin: 0; flex: 1;
    display: flex; align-items: flex-end;
}
.tw-card--classic .tw-card-desc { color: rgba(180, 210, 255, 0.55); }
.tw-card--rpg     .tw-card-desc { color: rgba(220, 185, 130, 0.50); }

.tw-link-cancel {
    background: none; border: none;
    color: rgba(200, 170, 110, 0.38); font-size: 0.8rem;
    cursor: pointer; padding: 0.3rem 0.6rem;
    transition: color 0.15s ease;
}
.tw-link-cancel:hover { color: rgba(200, 170, 110, 0.70); }

/* â”€â”€ PASOS 2 & 3: cabecera â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.tw-step-head {
    display: flex; align-items: center; gap: 0.75rem;
    padding: 1.1rem 1.4rem 0.85rem;
    border-bottom: 1px solid rgba(201, 168, 108, 0.13);
    flex-shrink: 0; flex-wrap: wrap;
}
.tw-back-btn {
    background: none; border: 1px solid rgba(201, 168, 108, 0.24);
    color: rgba(220, 190, 130, 0.65); border-radius: 8px;
    padding: 0.26rem 0.65rem; font-size: 0.79rem; cursor: pointer;
    transition: border-color 0.14s, color 0.14s; white-space: nowrap;
}
.tw-back-btn:hover { border-color: rgba(201,168,108,0.50); color: #f0d898; }
.tw-step-title {
    flex: 1; font-family: 'Cinzel', serif; font-size: 0.98rem; font-weight: 700;
    letter-spacing: 0.04em; color: #e8cc88; margin: 0;
}
.tw-step-sub {
    width: 100%; color: rgba(220,195,145,0.50); font-size: 0.79rem;
    margin: 0; font-style: italic; padding-left: 0;
    order: 10;
}
.tw-weather-row { display: flex; gap: 0.3rem; margin-left: auto; }

/* â”€â”€ Body â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.tw-body {
    flex: 1; overflow-y: auto; padding: 1.1rem 1.4rem;
    display: flex; flex-direction: column; gap: 1rem; min-height: 0;
}
.tw-field { display: flex; flex-direction: column; gap: 0.45rem; }
.tw-label-row { display: flex; align-items: center; gap: 0.55rem; }
.tw-label { font-size: 0.81rem; font-weight: 600; color: rgba(220,190,130,0.78); letter-spacing: 0.02em; }
.tw-note { font-size: 0.74rem; color: rgba(200,170,110,0.42); font-weight: 400; font-style: italic; }
.tw-required { color: rgba(255,140,100,0.70); font-size: 0.9em; }
.tw-input, .tw-textarea {
    width: 100%; box-sizing: border-box;
    background: rgba(255,255,255,0.042); border: 1px solid rgba(201,168,108,0.20);
    border-radius: 10px; color: #e8d8b0; padding: 0.62rem 0.88rem;
    font-size: 0.9rem; font-family: inherit; transition: border-color 0.14s; resize: vertical;
}
.tw-input::placeholder, .tw-textarea::placeholder { color: rgba(200,170,110,0.26); }
.tw-input:focus, .tw-textarea:focus { outline: none; border-color: rgba(201,168,108,0.48); background: rgba(255,255,255,0.058); }

/* â”€â”€ Character list â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.tw-char-list { display: flex; gap: 0.65rem; flex-wrap: wrap; }
.tw-no-chars { color: rgba(200,170,110,0.44); font-size: 0.82rem; font-style: italic; margin: 0; }
.tw-char-card {
    position: relative; display: flex; flex-direction: column;
    align-items: center; gap: 0.32rem; padding: 0.58rem 0.65rem 0.48rem;
    border-radius: 12px; border: 1.5px solid rgba(201,168,108,0.16);
    background: rgba(255,255,255,0.028); cursor: pointer;
    transition: border-color 0.14s, background 0.14s, transform 0.14s;
    min-width: 78px; max-width: 98px; outline: none;
}
.tw-char-card:hover { border-color: rgba(201,168,108,0.44); background: rgba(201,168,108,0.055); transform: translateY(-2px); }
.tw-char-card--sel { border-color: rgba(201,168,108,0.80); background: rgba(201,168,108,0.095); box-shadow: 0 0 14px -4px rgba(201,168,108,0.28); }
.tw-char-avatar {
    width: 50px; height: 50px; border-radius: 50%; overflow: hidden;
    background: rgba(201,168,108,0.10); display: flex; align-items: center;
    justify-content: center; border: 1.5px solid rgba(201,168,108,0.18); flex-shrink: 0;
}
.tw-char-img { width: 100%; height: 100%; object-fit: cover; }
.tw-char-initial { font-family: 'Cinzel', serif; font-size: 1.25rem; color: rgba(201,168,108,0.68); font-weight: 700; }
.tw-char-name {
    font-size: 0.72rem; color: rgba(230,205,155,0.82); text-align: center;
    line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 88px;
}
.tw-char-check {
    position: absolute; top: 0.28rem; right: 0.28rem;
    background: rgba(201,168,108,0.90); color: #1a1008; border-radius: 50%;
    width: 15px; height: 15px; font-size: 0.60rem;
    display: flex; align-items: center; justify-content: center; font-weight: 900;
}

/* â”€â”€ RPG Step 3: class grid â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.tw-class-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.52rem; }
.tw-class-card {
    display: flex; flex-direction: column; align-items: center; gap: 0.28rem;
    padding: 0.58rem 0.45rem 0.52rem; border-radius: 10px;
    border: 1.5px solid rgba(180,140,60,0.16); background: rgba(180,120,20,0.045);
    cursor: pointer; text-align: center; outline: none;
    transition: border-color 0.14s, background 0.14s, transform 0.14s;
}
.tw-class-card:hover { border-color: rgba(201,168,108,0.44); background: rgba(180,120,20,0.095); transform: translateY(-2px); }
.tw-class-card--sel { border-color: rgba(201,168,108,0.82); background: rgba(180,120,20,0.155); box-shadow: 0 0 12px -4px rgba(201,168,108,0.25); }
.tw-class-glyph { font-size: 1.22rem; line-height: 1; display: block; }
.tw-class-name { font-size: 0.74rem; font-family: 'Cinzel', serif; color: rgba(230,200,140,0.88); font-weight: 600; letter-spacing: 0.02em; }

/* â”€â”€ RPG Step 3: stat grid â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.tw-points-badge {
    font-family: 'Cinzel', serif; font-size: 0.71rem; padding: 0.14rem 0.58rem;
    border-radius: 999px; border: 1px solid rgba(180,140,60,0.28);
    color: rgba(220,185,110,0.72); background: rgba(180,120,20,0.075); white-space: nowrap;
    transition: all 0.2s ease;
}
.tw-points-badge--done { color: rgba(120,200,120,0.85); border-color: rgba(100,180,100,0.32); background: rgba(60,130,60,0.09); }
.tw-stat-grid { display: flex; flex-direction: column; gap: 0.42rem; }
.tw-stat-row { display: grid; grid-template-columns: 7rem 28px 2.1rem 28px 2.4rem; align-items: center; gap: 0.32rem; }
.tw-stat-name { font-size: 0.79rem; color: rgba(220,190,130,0.78); font-weight: 500; }
.tw-stat-btn {
    width: 28px; height: 28px; border-radius: 6px; border: 1px solid rgba(180,140,60,0.26);
    background: rgba(180,120,20,0.075); color: rgba(220,185,110,0.78);
    font-size: 1rem; cursor: pointer; display: flex; align-items: center;
    justify-content: center; transition: border-color 0.11s, background 0.11s; padding: 0;
}
.tw-stat-btn:hover:not(:disabled) { border-color: rgba(201,168,108,0.52); background: rgba(180,120,20,0.17); color: #f0d070; }
.tw-stat-btn:disabled { opacity: 0.26; cursor: not-allowed; }
.tw-stat-val { font-family: 'Cinzel', serif; font-size: 1.02rem; font-weight: 700; color: #f0d898; text-align: center; }
.tw-stat-mod { font-size: 0.74rem; color: rgba(180,200,180,0.58); font-family: 'Cinzel', serif; }

/* â”€â”€ Footer â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */
.tw-footer {
    display: flex; align-items: center; justify-content: space-between;
    gap: 0.8rem; padding: 0.95rem 1.4rem 1.25rem;
    border-top: 1px solid rgba(201,168,108,0.11); flex-shrink: 0;
}
.tw-btn-cancel {
    background: none; border: 1px solid rgba(201,168,108,0.20);
    color: rgba(200,170,110,0.52); border-radius: 9px;
    padding: 0.52rem 1.05rem; font-size: 0.82rem; cursor: pointer;
    transition: border-color 0.14s, color 0.14s;
}
.tw-btn-cancel:hover { border-color: rgba(201,168,108,0.42); color: rgba(200,170,110,0.82); }

/* Next / Crear button (step 2) */
.tw-btn-next {
    padding: 0.58rem 1.4rem; border-radius: 10px;
    border: 1.5px solid rgba(201,168,108,0.20);
    background: rgba(201,168,108,0.06); color: rgba(201,168,108,0.40);
    font-size: 0.86rem; font-family: 'Cinzel', serif; letter-spacing: 0.04em;
    cursor: not-allowed; transition: all 0.2s ease;
}
.tw-btn-next--ready {
    border-color: rgba(201,168,108,0.62); background: rgba(201,168,108,0.11); color: #f0d898;
    cursor: pointer; box-shadow: 0 4px 16px -4px rgba(201,168,108,0.22);
}
.tw-btn-next--ready:hover { background: rgba(201,168,108,0.17); box-shadow: 0 6px 22px -4px rgba(201,168,108,0.35); }

/* Forjar Historia button (step 3) */
.tw-btn-create {
    display: flex; align-items: center; gap: 0.65rem;
    padding: 0.68rem 1.7rem; border-radius: 12px;
    border: 2px solid rgba(201,168,108,0.16);
    background: rgba(201,168,108,0.04); color: rgba(201,168,108,0.28);
    font-family: 'Cinzel Decorative', 'Cinzel', serif; font-size: 0.87rem;
    letter-spacing: 0.07em; cursor: not-allowed; transition: all 0.3s ease;
}
.tw-btn-create--ready {
    border-color: rgba(201,168,108,0.78);
    background: linear-gradient(135deg, rgba(201,168,108,0.14), rgba(240,210,112,0.09), rgba(201,168,108,0.14));
    color: #f0d070; cursor: pointer;
    box-shadow: 0 0 0 1px rgba(240,208,112,0.11) inset, 0 6px 24px -6px rgba(201,168,108,0.38), 0 0 40px -15px rgba(201,168,108,0.28);
    animation: tw-plaque-glow 2.5s ease-in-out infinite;
}
.tw-btn-create--ready:hover {
    box-shadow: 0 0 0 1px rgba(240,208,112,0.18) inset, 0 8px 32px -6px rgba(201,168,108,0.52), 0 0 60px -15px rgba(201,168,108,0.42);
    transform: translateY(-1px);
}
.tw-create-gem { font-size: 0.68rem; opacity: 0.68; }

@keyframes tw-plaque-glow {
    0%, 100% { box-shadow: 0 0 0 1px rgba(240,208,112,0.11) inset, 0 6px 24px -6px rgba(201,168,108,0.38), 0 0 40px -15px rgba(201,168,108,0.28); }
    50%       { box-shadow: 0 0 0 1px rgba(240,208,112,0.17) inset, 0 6px 28px -4px rgba(201,168,108,0.52), 0 0 60px -10px rgba(201,168,108,0.38); }
}

@media (max-width: 540px) {
    .tw-card-row { flex-direction: column; }
    .tw-card { min-height: 160px; padding: 1.2rem 1rem; flex-direction: row; text-align: left; gap: 0.8rem; }
    .tw-card-desc { display: none; }
    .tw-class-grid { grid-template-columns: repeat(2, 1fr); }
    .tw-stat-row { grid-template-columns: 5.5rem 28px 2.1rem 28px 2.4rem; }
}


/* -- css/features/vn-mode-identity.css -- */
/* ── vn-mode-identity.css ─────────────────────────────────────────────────
   FASE 1 — Identidad por modo para la periferia de la pantalla VN:
   barra de controles (.vn-controls) y panel Responder (.vn-reply-panel).

   Capa ADITIVA: no modifica layout, estructura ni comportamiento.
   Solo re-skinea sobre los estilos base de 10-vn-controls.css y
   05-reply-panel.css, extendiendo las dos identidades ya establecidas
   en vn-themes.css:

     body.theme-classic → "Constelaciones" (cristal nocturno · plata · ✦)
     body.theme-rpg     → "Pergamino/Tarot" (pergamino oscuro · oro · ⚜)

   Registrado en non-critical.css y en NON_CRITICAL_CSS_ORDER (build.js)
   inmediatamente después de vn-themes.css.
   ───────────────────────────────────────────────────────────────────────── */


/* ═════════════════════════════════════════════════════════════════════════
   MODO CLÁSICO — Constelaciones
   ═════════════════════════════════════════════════════════════════════════ */

/* ── Barra de controles: cristal estelar ─────────────────────────────────── */
body.theme-classic #vnSection .vn-controls {
    background: rgba(7, 11, 34, 0.62) !important;
    backdrop-filter: blur(18px) saturate(1.3) !important;
    -webkit-backdrop-filter: blur(18px) saturate(1.3) !important;
    border: 1px solid rgba(155, 195, 255, 0.24) !important;
    box-shadow:
        0 0 0 1px rgba(130, 175, 255, 0.06) inset,
        0 0 42px -12px rgba(70, 115, 255, 0.16),
        0 10px 34px rgba(0, 0, 30, 0.5) !important;
}

/* Divisor: hilo de plata */
body.theme-classic #vnSection .vn-control-divider {
    background: linear-gradient(
        to bottom,
        transparent,
        rgba(150, 195, 255, 0.38) 30%,
        rgba(150, 195, 255, 0.38) 70%,
        transparent
    ) !important;
}

/* Botones: frío celestial */
body.theme-classic #vnSection .vn-control-btn {
    color: rgba(196, 216, 255, 0.72) !important;
}

body.theme-classic #vnSection .vn-control-btn:hover {
    background: rgba(120, 165, 255, 0.12) !important;
    border-color: rgba(150, 195, 255, 0.32) !important;
    color: #dcE9ff !important;
    box-shadow: 0 0 14px rgba(90, 140, 255, 0.22) !important;
}

body.theme-classic #vnSection .vn-control-btn:active {
    background: rgba(120, 165, 255, 0.2) !important;
}

/* ── Panel Responder: cristal nocturno ───────────────────────────────────── */
body.theme-classic .vn-reply-panel {
    background: linear-gradient(180deg,
