        0 0 0 1px rgba(140, 175, 255, 0.14),
        inset 0 0 60px rgba(55, 85, 175, 0.10) !important;
}

/* Constelación en la franja superior: puntos unidos por un trazo fino */
body.theme-classic .modal::before,
body.theme-classic .character-modal::before {
    content: '' !important;
    position: absolute;
    top: 12px;
    left: 14%;
    right: 14%;
    height: 10px;
    pointer-events: none;
    background:
        radial-gradient(circle 2.2px at 6% 60%,  rgba(198, 220, 255, 0.95), transparent 70%),
        radial-gradient(circle 1.4px at 24% 25%, rgba(178, 205, 255, 0.8),  transparent 70%),
        radial-gradient(circle 1.8px at 45% 70%, rgba(198, 220, 255, 0.9),  transparent 70%),
        radial-gradient(circle 1.3px at 64% 30%, rgba(178, 205, 255, 0.75), transparent 70%),
        radial-gradient(circle 2.4px at 82% 55%, rgba(205, 225, 255, 0.95), transparent 70%),
        radial-gradient(circle 1.5px at 96% 35%, rgba(178, 205, 255, 0.8),  transparent 70%),
        linear-gradient(90deg,
            transparent,
            rgba(150, 185, 255, 0.28) 12%,
            rgba(150, 185, 255, 0.28) 88%,
            transparent) center / 100% 1px no-repeat;
}

/* Constelación espejada al pie */
body.theme-classic .modal::after,
body.theme-classic .character-modal::after {
    content: '' !important;
    position: absolute;
    bottom: 12px;
    left: 20%;
    right: 20%;
    height: 10px;
    pointer-events: none;
    background:
        radial-gradient(circle 1.6px at 10% 45%, rgba(178, 205, 255, 0.8), transparent 70%),
        radial-gradient(circle 2.1px at 50% 60%, rgba(198, 220, 255, 0.9), transparent 70%),
        radial-gradient(circle 1.6px at 90% 40%, rgba(178, 205, 255, 0.8), transparent 70%),
