/* ═════════════════════════════════════════════════════════════════════════
   5 · Responsive + rendimiento
   ═════════════════════════════════════════════════════════════════════════ */

@media (max-width: 767px) {
    body.compose-bar #vnReplyPanel {
        padding-bottom: clamp(70px, 12vh, 120px) !important;
    }
    body.compose-bar #vnReplyPanel .vrp-modal {
