}
body.theme-classic.compose-bar #vnReplyPanel .vrp-footer::before {
    content: 'cada palabra teje un vínculo que aún no puedes ver';
    color: rgba(150, 180, 235, 0.45);
}
body.theme-rpg.compose-bar #vnReplyPanel .vrp-footer::before {
    content: 'el destino de tu acción permanece velado';
