    color: #d4ccf8 !important;
    box-shadow: 0 0 16px rgba(150, 120, 215, 0.22), inset 0 1px 0 rgba(220, 215, 252, 0.28), 0 4px 12px rgba(0, 0, 0, 0.42) !important;
    transform: translateY(-1px) !important;
}

/* ── 8. BUSCADOR ─────────────────────────────────────────────────────────
   menu-gamefeel.css → .topics-search-wrap con borde ámbar;
                        .topics-search-input con color: #efe4ca (ámbar).  */
#topicsSection .topics-search-wrap {
    border: none !important;
    background: transparent !important;
}
#topicsSection .topics-search-input {
    background: rgba(18, 12, 42, 0.44) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
