    box-shadow: inset 0 1px 0 rgba(220, 215, 248, 0.08) !important;
}
#topicsSection .topics-search-input::placeholder {
    color: rgba(185, 172, 228, 0.46) !important;
    font-style: italic !important;
}
#topicsSection .topics-search-input:focus {
    border-color: rgba(200, 185, 242, 0.70) !important;
    box-shadow:
        0 0 0 2px rgba(160, 140, 225, 0.13),
        inset 0 0 20px rgba(130, 100, 210, 0.05),
        inset 0 1px 0 rgba(220, 215, 248, 0.12) !important;
}

/* ── 9. FILTROS ──────────────────────────────────────────────────────────
   menu-gamefeel.css → .topics-filter-group borde ámbar;
                        .topic-filter-btn.active fondo marrón.            */
#topicsSection .topics-filter-group {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}
#topicsSection .topic-filter-btn {
    border: 1px solid rgba(190, 175, 230, 0.30) !important;
    background: rgba(22, 15, 55, 0.32) !important;
    color: rgba(205, 195, 238, 0.74) !important;
    border-radius: 5px !important;
    box-shadow: inset 0 1px 0 rgba(220, 215, 248, 0.08) !important;
    transition: all 0.22s !important;
}
#topicsSection .topic-filter-btn:hover {
    background: rgba(105, 80, 175, 0.24) !important;
    color: #dcd4fc !important;
    border-color: rgba(210, 200, 242, 0.58) !important;
}
#topicsSection .topic-filter-btn.active {
    background: linear-gradient(135deg, rgba(100, 65, 178, 0.74), rgba(50, 28, 95, 0.90)) !important;
    border-color: rgba(215, 205, 245, 0.68) !important;
    color: #e2daff !important;
    box-shadow:
        0 0 14px rgba(160, 130, 220, 0.26),
        inset 0 1px 0 rgba(235, 228, 255, 0.24) !important;
}

/* ── 10. PANEL PRINCIPAL (tapete) ────────────────────────────────────── */
#topicsSection .topics-main {
    background:
        radial-gradient(ellipse at 50%   0%, rgba(120,  80, 220, 0.10) 0%, transparent 65%),
        radial-gradient(ellipse at 80% 100%, rgba( 80,  40, 180, 0.06) 0%, transparent 55%),
        rgba(6, 3, 18, 0.58) !important;
    backdrop-filter: blur(14px) saturate(1.3) !important;
    -webkit-backdrop-filter: blur(14px) saturate(1.3) !important;
    border: 1px solid rgba(180, 165, 230, 0.26) !important;
    border-radius: 14px !important;
    box-shadow:
        0 0 0 1px rgba(190, 178, 235, 0.10),
        inset 0 1px 0 rgba(210, 205, 245, 0.22),
        0 8px 48px rgba(0, 0, 0, 0.72),
        0 0 60px rgba(100, 60, 200, 0.14) !important;
}

/* ── 11. SIDEBAR DE ESTADÍSTICAS — paleta plateada ──────────────────────
   Tonos silver-blue fríos en vez de violeta puro → más legibles y místicos. */
#topicsSection .topics-sidebar {
    border: 1px solid rgba(130, 100, 210, 0.20) !important;
    background: rgba(6, 5, 18, 0.42) !important;
    backdrop-filter: blur(16px) !important;
    -webkit-backdrop-filter: blur(16px) !important;
}

/* Headings ornamentales (EL MUNDO, POR MODO) — plata tenue */
#topicsSection .tsi-heading {
    color: rgba(185, 198, 220, 0.68) !important;
}
#topicsSection .tsi-heading::before,
#topicsSection .tsi-heading::after {
    background: linear-gradient(90deg, transparent, rgba(170, 190, 218, 0.28)) !important;
}

/* Número grande (2, 0…) — plata brillante con halo sutil */
#topicsSection .tsi-val {
    color: #c2d0e8 !important;
    text-shadow: 0 0 14px rgba(175, 205, 240, 0.42), 0 0 4px rgba(200, 220, 248, 0.18) !important;
}

/* Etiqueta de stat ("historias en el mundo") — plata media */
#topicsSection .tsi-lbl {
    color: rgba(178, 192, 218, 0.58) !important;
}

/* Separador horizontal */
#topicsSection .tsi-sep {
    background: linear-gradient(90deg, transparent, rgba(165, 185, 215, 0.22), transparent) !important;
}

/* Nombre de modo (RPG, Clásico) */
#topicsSection .tsi-mode-name {
    color: rgba(172, 187, 215, 0.56) !important;
}

/* Contador por modo */
#topicsSection .tsi-mode-count {
    color: #b8cce2 !important;
    text-shadow: 0 0 10px rgba(165, 200, 235, 0.36) !important;
}

/* Cita final — plata muy tenue, atmosférica */
#topicsSection .tsi-quote {
    color: rgba(168, 185, 212, 0.40) !important;
    border-top-color: rgba(150, 175, 210, 0.14) !important;
}

/* ── 12. ESTADO VACÍO ────────────────────────────────────────────────── */
#topicsSection .topics-empty {
    color: rgba(160, 128, 220, 0.56) !important;
}
#topicsSection .topics-empty span {
    color: rgba(160, 128, 220, 0.38) !important;
}

/* ── 13. TARJETAS TAROT — hover sin fondo ámbar ─────────────────────── */
#topicsSection .topic-card:hover {
    box-shadow: 0 22px 36px rgba(0, 0, 0, 0.40), 0 0 0 1px rgba(180, 160, 235, 0.16) !important;
}

/* ── 14. RESPONSIVE ──────────────────────────────────────────────────── */
@media (max-width: 900px) {
    #topicsSection .topics-command-bar {
        border-radius: 8px !important;
        padding: 0.42rem !important;
    }
    #topicsSection .btn-create-topic,
    #topicsSection .btn-manage-topics,
    #topicsSection .btn-global-search {
        border-radius: 5px !important;
    }
}


/* -- css/sections/user-profile.css -- */
/* ============================================================
   Etheria — User Profile Modal + Classic Party Panel
   ============================================================ */

/* ── Modal overlay ────────────────────────────────────────── */
.upm-overlay {
    position: fixed;
    inset: 0;
    z-index: 9000;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(0, 0, 0, 0.65);
    backdrop-filter: blur(4px);
    padding: 1rem;
}

/* ── Card base ────────────────────────────────────────────── */
.upm-card {
    position: relative;
    width: min(420px, 96vw);
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 12px;
    padding: 1.75rem 1.5rem 1.5rem;
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.7);
    scrollbar-width: thin;
    scrollbar-color: rgba(201, 168, 108, 0.3) transparent;
}

.upm-card::-webkit-scrollbar { width: 5px; }
.upm-card::-webkit-scrollbar-track { background: transparent; }
.upm-card::-webkit-scrollbar-thumb { background: rgba(201, 168, 108, 0.3); border-radius: 3px; }

/* ── Tema Clásico ─────────────────────────────────────────── */
.upm-card--classic {
    background: #2a1e0f;
    border: 1px solid rgba(201, 168, 108, 0.45);
    font-family: 'Crimson Text', Georgia, 'Times New Roman', serif;
    color: #e8d5b0;
}

/* ── Tema RPG ─────────────────────────────────────────────── */
.upm-card--rpg {
    background: linear-gradient(175deg, #1c150a, #120e07);
    border: 1px solid rgba(180, 140, 80, 0.48);
    box-shadow: 0 24px 60px rgba(0, 0, 0, 0.75), inset 0 1px 0 rgba(255, 225, 160, 0.06);
    font-family: 'Rajdhani', 'Exo 2', system-ui, sans-serif;
    color: #e8d5b0;
    letter-spacing: 0.02em;
}

/* ── Cierre ───────────────────────────────────────────────── */
.upm-close {
    position: absolute;
    top: 0.75rem;
    right: 0.75rem;
    background: transparent;
    border: none;
    color: rgba(201, 168, 108, 0.6);
    font-size: 1.1rem;
    cursor: pointer;
    line-height: 1;
    padding: 0.25rem 0.4rem;
    border-radius: 4px;
    transition: color 0.2s, background 0.2s;
}
.upm-close:hover { color: #c9a86c; background: rgba(201, 168, 108, 0.12); }
.upm-card--rpg .upm-close { color: rgba(180, 140, 80, 0.55); }
.upm-card--rpg .upm-close:hover { color: #c9a86c; background: rgba(180, 140, 80, 0.12); }

/* ── Cargando ─────────────────────────────────────────────── */
.upm-loading {
    text-align: center;
    padding: 2.5rem 1rem;
    color: rgba(201, 168, 108, 0.5);
    font-style: italic;
    font-size: 0.9rem;
}

/* ── Ornamentos clásicos ──────────────────────────────────── */
.upm-classic-ornament {
    text-align: center;
    color: rgba(201, 168, 108, 0.5);
    font-size: 0.8rem;
    letter-spacing: 0.15em;
}
.upm-classic-ornament--top { margin-bottom: 1rem; }
.upm-classic-ornament--bottom { margin-top: 1rem; }

/* ── Header RPG ───────────────────────────────────────────── */
.upm-rpg-header {
    margin-bottom: 1rem;
    padding-bottom: 0.6rem;
    border-bottom: 1px solid rgba(180, 140, 80, 0.2);
}
.upm-rpg-kicker {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: #c9a86c;
    font-weight: 700;
}

/* ── Identidad (avatar + nombre) ─────────────────────────── */
.upm-identity {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1rem;
    flex-wrap: wrap;
}

.upm-avatar {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid rgba(201, 168, 108, 0.4);
    flex-shrink: 0;
}
.upm-card--rpg .upm-avatar {
    border-color: rgba(180, 140, 80, 0.45);
    box-shadow: 0 0 0 3px rgba(100, 65, 15, 0.35), 0 0 18px rgba(180, 140, 80, 0.18);
}

.upm-avatar--initials {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #7a5c1e, #c9a86c);
    color: #1a1208;
    font-size: 1.75rem;
    font-weight: 700;
    font-style: normal;
}
.upm-card--rpg .upm-avatar--initials {
    background: linear-gradient(135deg, #5c3a0a, #b87e30);
    color: #fdf0d8;
}

.upm-identity-text {
    flex: 1;
    min-width: 0;
}

.upm-name {
    font-size: 1.25rem;
    font-weight: 700;
    color: #c9a86c;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.upm-card--rpg .upm-name { color: #dec28f; }

.upm-gender-badge {
    font-size: 0.8rem;
    color: rgba(201, 168, 108, 0.65);
    margin-top: 0.2rem;
}
.upm-card--rpg .upm-gender-badge { color: rgba(200, 168, 108, 0.65); }

.upm-edit-btn {
    align-self: flex-start;
    background: rgba(201, 168, 108, 0.1);
    border: 1px solid rgba(201, 168, 108, 0.35);
    color: #c9a86c;
    font-size: 0.75rem;
    padding: 0.3rem 0.65rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background 0.2s, border-color 0.2s, color 0.2s;
    white-space: nowrap;
    flex-shrink: 0;
}
.upm-edit-btn:hover { background: rgba(201, 168, 108, 0.2); border-color: rgba(201, 168, 108, 0.6); }
.upm-card--rpg .upm-edit-btn {
    background: rgba(180, 140, 80, 0.1);
    border-color: rgba(180, 140, 80, 0.35);
    color: #c9a86c;
}
.upm-card--rpg .upm-edit-btn:hover { background: rgba(180, 140, 80, 0.2); border-color: rgba(180, 140, 80, 0.6); }

/* ── Divisor ──────────────────────────────────────────────── */
.upm-divider {
    border: none;
    border-top: 1px solid rgba(201, 168, 108, 0.2);
    margin: 0.9rem 0;
}
.upm-divider--rpg { border-top-color: rgba(180, 140, 80, 0.22); }

/* ── Stats grid ───────────────────────────────────────────── */
.upm-stats-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.75rem;
    margin-bottom: 0.9rem;
}

.upm-stat {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    background: rgba(0, 0, 0, 0.2);
    border-radius: 8px;
    padding: 0.65rem 0.75rem;
}

.upm-stat-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: rgba(201, 168, 108, 0.55);
}
.upm-card--rpg .upm-stat-label { color: rgba(200, 168, 100, 0.55); }

.upm-stat-value {
    font-size: 1.4rem;
    font-weight: 700;
    color: #c9a86c;
    line-height: 1.1;
}
.upm-card--rpg .upm-stat-value { color: #dec28f; }

/* ── Personajes ───────────────────────────────────────────── */
.upm-chars-row {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
    margin-bottom: 0.5rem;
}

.upm-chars-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: rgba(201, 168, 108, 0.55);
}
.upm-card--rpg .upm-chars-label { color: rgba(200, 168, 100, 0.55); }

.upm-chars-value {
    font-size: 0.88rem;
    color: #e8d5b0;
    line-height: 1.5;
}
.upm-card--rpg .upm-chars-value { color: #e8d5b0; }

.upm-extra {
    font-size: 0.78rem;
    color: rgba(201, 168, 108, 0.5);
}

/* ── Meta (bio, timezone) ─────────────────────────────────── */
.upm-meta-row {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.upm-meta-item {
    font-size: 0.82rem;
    color: rgba(201, 168, 108, 0.6);
}
.upm-card--rpg .upm-meta-item { color: rgba(200, 168, 100, 0.6); }

.upm-bio {
    font-style: italic;
    font-size: 0.88rem;
    color: rgba(232, 213, 176, 0.7);
    line-height: 1.5;
    margin: 0;
}
.upm-card--rpg .upm-bio { color: rgba(232, 213, 176, 0.65); }

/* ── Edición de perfil (inline — sin segundo modal) ───────── */
.upm-edit-section {
    /* contenedor: la animación de reveal la hace el display toggle en JS */
}

.upm-edit-title {
    font-size: 1.1rem;
    font-weight: 700;
    color: #c9a86c;
    margin: 0 0 1rem;
}
.upm-card--rpg .upm-edit-title { color: #dec28f; }

.upm-edit-form {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
}

.upm-edit-label {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    font-size: 0.82rem;
    color: rgba(201, 168, 108, 0.7);
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.upm-card--rpg .upm-edit-label { color: rgba(200, 168, 100, 0.7); }

.upm-edit-hint {
    text-transform: none;
    letter-spacing: 0;
    font-size: 0.72rem;
    color: rgba(201, 168, 108, 0.4);
}

.upm-edit-select,
.upm-edit-input,
.upm-edit-textarea {
    width: 100%;
    background: rgba(0, 0, 0, 0.35);
    border: 1px solid rgba(201, 168, 108, 0.3);
    border-radius: 6px;
    color: #e8d5b0;
    font-family: inherit;
    font-size: 0.9rem;
    padding: 0.5rem 0.65rem;
    outline: none;
    transition: border-color 0.2s;
    box-sizing: border-box;
}
.upm-edit-select:focus,
.upm-edit-input:focus,
.upm-edit-textarea:focus {
    border-color: rgba(201, 168, 108, 0.7);
}
.upm-card--rpg .upm-edit-select,
.upm-card--rpg .upm-edit-input,
.upm-card--rpg .upm-edit-textarea {
    border-color: rgba(180, 140, 80, 0.3);
    color: #e8d5b0;
    background: rgba(0, 0, 0, 0.4);
}
.upm-card--rpg .upm-edit-select:focus,
.upm-card--rpg .upm-edit-input:focus,
.upm-card--rpg .upm-edit-textarea:focus {
    border-color: rgba(180, 140, 80, 0.65);
}
.upm-edit-textarea { resize: vertical; min-height: 72px; }

/* select arrow fix en dark */
.upm-edit-select option { background: #1a1208; color: #e8d5b0; }
.upm-card--rpg .upm-edit-select option { background: #1c150a; color: #e8d5b0; }

.upm-edit-actions {
    display: flex;
    gap: 0.6rem;
    margin-top: 0.25rem;
}

.upm-edit-save {
    flex: 1;
    background: rgba(201, 168, 108, 0.15);
    border: 1px solid rgba(201, 168, 108, 0.5);
    color: #c9a86c;
    font-size: 0.88rem;
    font-weight: 600;
    padding: 0.55rem 1rem;
    border-radius: 7px;
    cursor: pointer;
    transition: background 0.2s, border-color 0.2s;
}
.upm-edit-save:hover { background: rgba(201, 168, 108, 0.28); border-color: rgba(201, 168, 108, 0.8); }
.upm-card--rpg .upm-edit-save {
    background: rgba(180, 140, 80, 0.15);
    border-color: rgba(180, 140, 80, 0.5);
    color: #c9a86c;
}
.upm-card--rpg .upm-edit-save:hover { background: rgba(180, 140, 80, 0.28); border-color: rgba(180, 140, 80, 0.8); }

.upm-edit-cancel {
    background: rgba(255, 255, 255, 0.05);
    border: 1px solid rgba(255, 255, 255, 0.1);
    color: rgba(201, 168, 108, 0.55);
    font-size: 0.85rem;
    padding: 0.5rem 0.85rem;
    border-radius: 7px;
    cursor: pointer;
    transition: background 0.2s;
}
.upm-edit-cancel:hover { background: rgba(255, 255, 255, 0.1); }

/* ── Stats RPG inline (ficha de atributos en el modal) ─────── */
.upm-rpg-stat-block {
    margin-top: 0.1rem;
}

.upm-rpg-stat-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    margin-bottom: 0.6rem;
}

.upm-rpg-stat-title {
    font-size: 0.76rem;
    font-weight: 700;
    color: #c9a86c;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}

.upm-rpg-free-pts {
    font-size: 0.68rem;
    background: rgba(180, 140, 80, 0.14);
    border: 1px solid rgba(180, 140, 80, 0.38);
    color: #dec28f;
    padding: 0.14rem 0.5rem;
    border-radius: 999px;
    white-space: nowrap;
}

.upm-rpg-pts-done {
    font-size: 0.68rem;
    color: rgba(180, 140, 80, 0.38);
}

.upm-rpg-stat-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.38rem 0.5rem;
}

.upm-rpg-stat-row {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    background: rgba(0, 0, 0, 0.22);
    border: 1px solid rgba(180, 140, 80, 0.12);
    border-radius: 6px;
    padding: 0.3rem 0.45rem;
}

.upm-rpg-stat-name {
    font-size: 0.66rem;
    font-weight: 700;
    color: rgba(200, 168, 100, 0.62);
    letter-spacing: 0.08em;
    min-width: 26px;
}

.upm-rpg-stat-val {
    font-size: 1rem;
    font-weight: 700;
    color: #dec28f;
    flex: 1;
    text-align: center;
    line-height: 1;
}

.upm-stat-adj {
    width: 20px;
    height: 20px;
    min-width: 20px;
    background: rgba(180, 140, 80, 0.1);
    border: 1px solid rgba(180, 140, 80, 0.28);
    border-radius: 4px;
    color: #c9a86c;
    font-size: 0.9rem;
    font-weight: 700;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    line-height: 1;
    transition: background 0.15s, border-color 0.15s, color 0.15s;
    flex-shrink: 0;
}
.upm-stat-adj:hover {
    background: rgba(180, 140, 80, 0.24);
    border-color: rgba(200, 160, 90, 0.6);
    color: #f0d8a0;
}
.upm-stat-adj:active {
    background: rgba(180, 140, 80, 0.38);
    transform: scale(0.92);
}
.upm-stat-adj--minus { border-color: rgba(220, 100, 80, 0.35); color: #e08070; }
.upm-stat-adj--minus:hover { background: rgba(220, 100, 80, 0.2); border-color: rgba(220, 100, 80, 0.6); color: #f0a090; }
.upm-stat-adj--plus  { border-color: rgba(100, 200, 120, 0.35); color: #80c890; }
.upm-stat-adj--plus:hover  { background: rgba(100, 200, 120, 0.2); border-color: rgba(100, 200, 120, 0.6); color: #a0e0b0; }

/* Valor de stat en staging (aún no confirmado) */
.upm-rpg-stat-val--up {
    color: #a8e090;
    text-shadow: 0 0 8px rgba(120, 220, 100, 0.45);
}

/* Barra confirmar/cancelar cambios de stats */
.upm-rpg-confirm-bar {
    display: flex;
    gap: 0.5rem;
    justify-content: flex-end;
    padding: 0.55rem 0 0.1rem;
    margin-top: 0.3rem;
    border-top: 1px solid rgba(180, 140, 80, 0.15);
}
.upm-rpg-btn {
    font-family: 'Cinzel', serif;
    font-size: 0.65rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 0.3rem 0.75rem;
    border-radius: 6px;
    cursor: pointer;
    border: 1px solid;
    transition: background 0.15s, border-color 0.15s, color 0.15s;
}
.upm-rpg-btn--cancel {
    background: rgba(180, 140, 80, 0.06);
    border-color: rgba(180, 140, 80, 0.22);
    color: rgba(200, 165, 110, 0.65);
}
.upm-rpg-btn--cancel:hover {
    background: rgba(180, 140, 80, 0.14);
    border-color: rgba(180, 140, 80, 0.45);
    color: rgba(220, 185, 130, 0.90);
}
.upm-rpg-btn--confirm {
    background: rgba(100, 175, 80, 0.12);
    border-color: rgba(100, 200, 90, 0.35);
    color: #90d878;
}
.upm-rpg-btn--confirm:hover {
    background: rgba(100, 175, 80, 0.24);
    border-color: rgba(100, 200, 90, 0.60);
    color: #b0f090;
}

/* ============================================================
   Panel de party clásico — estética otome/constelaciones
   Posición idéntica al panel RPG (top-right), diseño independiente.
   ============================================================ */

.classic-party-shell {
    position: fixed;
    right: 4.2rem;
    top: 1.4rem;
    z-index: 800;
    width: 172px;
}

.classic-party-panel {
    background: rgba(7, 5, 18, 0.93);
    border: 1px solid rgba(155, 135, 200, 0.22);
    border-radius: 12px;
    backdrop-filter: blur(18px);
    box-shadow:
        0 8px 32px rgba(0, 0, 0, 0.60),
        0 0 0 1px rgba(120, 100, 180, 0.06),
        inset 0 1px 0 rgba(200, 185, 245, 0.05);
    overflow: hidden;
}

.classic-party-header {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.48rem 0.7rem 0.42rem;
    border-bottom: 1px solid rgba(155, 135, 200, 0.12);
    background: rgba(120, 100, 180, 0.04);
}

.classic-party-ornament {
    font-size: 0.5rem;
    color: rgba(180, 162, 225, 0.35);
    line-height: 1;
}

.classic-party-title {
    font-family: 'Cinzel', Georgia, serif;
    font-size: 0.58rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: rgba(195, 178, 238, 0.60);
}

.classic-party-list {
    display: flex;
    flex-direction: column;
    gap: 0.08rem;
    padding: 0.35rem 0.4rem;
    max-height: 55vh;
    overflow-y: auto;
    scrollbar-width: thin;
    scrollbar-color: rgba(155, 135, 200, 0.15) transparent;
}
.classic-party-list::-webkit-scrollbar { width: 3px; }
.classic-party-list::-webkit-scrollbar-thumb { background: rgba(155, 135, 200, 0.18); border-radius: 2px; }

/* ── Tarjeta de miembro ───────────────────────────────────── */
.cp-member {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.35rem;
    width: 100%;
    padding: 0.36rem 0.48rem;
    background: rgba(255, 255, 255, 0.018);
    border: 1px solid rgba(155, 135, 200, 0.10);
    border-radius: 7px;
    cursor: pointer;
    text-align: left;
    color: rgba(215, 205, 245, 0.82);
    font-family: 'Crimson Text', Georgia, serif;
    transition: background 0.22s, border-color 0.22s, opacity 0.35s, filter 0.35s, box-shadow 0.35s;
}
.cp-member:hover {
    background: rgba(155, 135, 200, 0.08);
    border-color: rgba(155, 135, 200, 0.30);
    color: rgba(235, 225, 255, 0.96);
}

.cp-name {
    flex: 1;
    min-width: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    font-size: 0.82rem;
    letter-spacing: 0.01em;
}

.cp-gender {
    font-size: 0.72rem;
    flex-shrink: 0;
    opacity: 0.65;
}

/* ── Online: destello suave de constelación ───────────────── */
.cp-member--online {
    border-color: rgba(155, 135, 200, 0.26);
    animation: cp-star-pulse 3.2s ease-in-out infinite;
}
@keyframes cp-star-pulse {
    0%,  100% {
        box-shadow: 0 0 5px rgba(150, 130, 210, 0.06),
                    inset 0 0 3px rgba(150, 130, 210, 0.04);
    }
    50% {
        box-shadow: 0 0 14px rgba(150, 130, 210, 0.18),
                    inset 0 0 7px rgba(150, 130, 210, 0.08);
    }
}

/* ── Respondió: atenuado pero legible ────────────────────── */
/* opacity 0.25 era demasiado agresivo — estado más común mientras avanza
   la historia, así que los nombres tienen que seguir siendo legibles.
   0.45 + brightness(0.75) da claramente "inactivo" sin desaparecer. */
.cp-member--responded {
    opacity: 0.45;
    filter: saturate(0.35) brightness(0.75);
    background: rgba(4, 3, 12, 0.55);
    border-color: rgba(155, 135, 200, 0.08);
    cursor: default;
    animation: none;
}
.cp-member--responded:hover {
    background: rgba(4, 3, 12, 0.55);
    border-color: rgba(155, 135, 200, 0.08);
}
/* Conectado pero ya respondió: pulso muy suave */
.cp-member--online.cp-member--responded {
    animation: cp-star-dim 4.5s ease-in-out infinite;
}
@keyframes cp-star-dim {
    0%,  100% { opacity: 0.45; }
    50%        { opacity: 0.55; }
}

/* ── Responsive ───────────────────────────────────────────── */
@media (max-width: 768px) {
    .classic-party-shell {
        right: 3.8rem;
        top: 1.2rem;
        width: 150px;
    }
}
@media (max-width: 400px) {
    .upm-card { padding: 1.25rem 1rem 1rem; }
    .upm-stats-grid { grid-template-columns: 1fr; }
    .upm-rpg-stat-grid { grid-template-columns: 1fr; }
}



/* -- css/sections/hub.css -- */
/* ══════════════════════════════════════════════════════════════
   HUB / MENÚ PRINCIPAL — Estancia aislada
   Layout: título abajo-izquierda · botones columna derecha
   Selectores bajo #mainMenu → especificidad (1,1,0).
   ══════════════════════════════════════════════════════════════ */

/* ── Variables ─────────────────────────────────────────────── */
#mainMenu {
    --hub-accent:      rgba(175, 130, 255, 1);
    --hub-accent-dim:  rgba(155, 110, 240, 0.55);
    --hub-gold:        rgba(228, 200, 255, 1);
    --hub-text:        rgba(242, 232, 255, 1);
    --hub-text-muted:  rgba(200, 175, 240, 0.78);
    --hub-btn-bg:      rgba(10, 5, 22, 0.76);
    --hub-btn-border:  rgba(152, 110, 238, 0.46);
    --hub-shadow:      rgba(20, 6, 48, 0.70);
    --hub-icon-bg:     rgba(145, 100, 230, 0.18);
    --hub-icon-border: rgba(145, 100, 230, 0.30);
}

/* ── Degradados de legibilidad sobre el fondo ──────────────── */
/* Izquierda: oscurece la zona del título */
#mainMenu .menu-vignette-left {
    position: absolute;
    inset: 0;
    background: linear-gradient(
        to right,
        rgba(6, 3, 16, 0.55) 0%,
        rgba(6, 3, 16, 0.22) 38%,
        transparent 60%
    );
    pointer-events: none;
    z-index: 2;
}

/* Derecha: oscurece la zona de los botones */
#mainMenu .menu-vignette-right {
    position: absolute;
    inset: 0;
    background: linear-gradient(
        to left,
        rgba(6, 3, 16, 0.55) 0%,
        rgba(6, 3, 16, 0.22) 38%,
        transparent 60%
    );
    pointer-events: none;
    z-index: 2;
}

/* ── BARRA SUPERIOR ────────────────────────────────────────── */
#mainMenu .menu-top-bar {
    position: absolute !important;
    top: 0;
    left: 0;
    right: 0;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    padding: 1rem 1.4rem !important;
    z-index: 20 !important;
    gap: 1rem;
}

/* Acciones del lado derecho */
#mainMenu .menu-top-actions {
    display: flex !important;
    align-items: center !important;
    gap: 0.5rem !important;
}

/* Ocultar el antiguo footer si quedara en DOM */
#mainMenu .menu-footer {
    display: none !important;
}

/* ── PERFIL (barra superior) ───────────────────────────────── */
#mainMenu .menu-profile-btn {
    display: flex !important;
    align-items: center !important;
    gap: 0.6rem !important;
    background: rgba(10, 5, 22, 0.72) !important;
    border: 1px solid rgba(150, 108, 238, 0.38) !important;
    border-radius: 10px !important;
    padding: 0.38rem 0.75rem 0.38rem 0.42rem !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    cursor: pointer !important;
    transition: background 0.22s, border-color 0.22s, transform 0.22s !important;
    animation: hubSlideDown 0.5s 0.1s both !important;
}

#mainMenu .menu-profile-btn:hover {
    background: rgba(20, 10, 40, 0.82) !important;
    border-color: rgba(178, 132, 255, 0.62) !important;
    transform: translateY(1px) !important;
}

#mainMenu .menu-profile-avatar {
    width: 30px !important;
    height: 30px !important;
    border-radius: 50% !important;
    background: rgba(120, 78, 195, 0.30) !important;
    border: 1.5px solid rgba(160, 118, 242, 0.42) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    overflow: hidden !important;
    flex: 0 0 30px !important;
}

#mainMenu .menu-profile-initial {
    font-family: 'Cinzel', serif !important;
    font-size: 0.72rem !important;
    font-weight: 600 !important;
    color: rgba(222, 192, 255, 1) !important;
    line-height: 1 !important;
}

#mainMenu .menu-profile-img {
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
}

#mainMenu .menu-profile-info {
    display: flex !important;
    flex-direction: column !important;
    gap: 0.04rem !important;
}

#mainMenu .menu-profile-name {
    font-family: 'Cinzel', serif !important;
    font-size: 0.74rem !important;
    letter-spacing: 0.06em !important;
    color: rgba(228, 202, 255, 1) !important;
    line-height: 1.2 !important;
}

#mainMenu .menu-profile-hint {
    font-size: 0.60rem !important;
    color: rgba(185, 155, 238, 0.72) !important;
    letter-spacing: 0.03em !important;
    font-family: sans-serif !important;
}

/* ── CONTROLES (tema, inbox, guardado) ─────────────────────── */
#mainMenu .menu-theme-toggle,
#mainMenu .menu-save-btn,
#mainMenu .menu-inbox-float {
    background: rgba(10, 5, 22, 0.72) !important;
    border: 1px solid rgba(148, 108, 235, 0.32) !important;
    color: rgba(178, 138, 250, 0.72) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    transition: background 0.22s, border-color 0.22s, color 0.22s !important;
    animation: hubSlideDown 0.5s 0.2s both !important;
}

#mainMenu .menu-theme-toggle:hover,
#mainMenu .menu-save-btn:hover,
#mainMenu .menu-inbox-float:hover {
    background: rgba(20, 10, 40, 0.82) !important;
    border-color: rgba(175, 130, 255, 0.58) !important;
    color: rgba(215, 180, 255, 0.96) !important;
}

/* ── TÍTULO (abajo-izquierda) ──────────────────────────────── */
#mainMenu .menu-brand {
    position: absolute !important;
    bottom: clamp(1.8rem, 5vh, 3.2rem) !important;
    left: clamp(1.8rem, 4vw, 3.5rem) !important;
    z-index: 10 !important;
    text-align: left !important;
    overflow: hidden !important; /* necesario para el shimmer */
    animation: hubSlideUp 0.7s 0.15s both !important;
}

/* Shimmer periódico que barre el área del brand cada ~8s */
#mainMenu .menu-brand::after {
    content: '' !important;
    position: absolute !important;
    top: -10%; bottom: -10% !important;
    left: -80% !important;
    width: 45% !important;
    background: linear-gradient(
        105deg,
        transparent 0%,
        rgba(228, 205, 255, 0.05) 35%,
        rgba(240, 220, 255, 0.13) 50%,
        rgba(228, 205, 255, 0.05) 65%,
        transparent 100%
    ) !important;
    transform: skewX(-10deg) !important;
    animation: hubBrandShimmer 8s ease-in-out infinite 1.8s !important;
    pointer-events: none !important;
}

#mainMenu .menu-title {
    font-family: 'Cinzel', serif !important;
    font-weight: 400 !important;
    font-size: clamp(3.6rem, 7.5vw, 6.8rem) !important;
    letter-spacing: 0.04em !important;
    text-transform: none !important;
    line-height: 1.0 !important;
    margin-bottom: 0.6rem !important;
    color: rgba(240, 222, 255, 1) !important;
    background: none !important;
    -webkit-background-clip: unset !important;
    background-clip: unset !important;
    filter: none !important;
    /* Glow que respira suavemente */
    animation: hubTitleBreath 4.5s ease-in-out infinite 0.85s,
               hubTitleFloat   7s   ease-in-out infinite 0.85s !important;
}

[data-theme="dark"] #mainMenu .menu-title {
    color: rgba(250, 235, 255, 1) !important;
}

#mainMenu .title-letter {
    color: inherit !important;
    text-transform: none !important;
}

/* ── SUBTÍTULO ─────────────────────────────────────────────── */
#mainMenu .menu-subtitle {
    font-size: clamp(0.60rem, 1.1vw, 0.76rem) !important;
    color: rgba(210, 180, 250, 0.80) !important;
    font-style: italic !important;
    letter-spacing: 0.22em !important;
    text-transform: uppercase !important;
    text-shadow: 0 0 12px rgba(182, 132, 255, 0.45), 0 1px 5px rgba(0,0,0,0.60) !important;
    position: relative !important;
    padding-left: 1.1rem !important;
    /* Animación retardada para que entre después del título */
    animation: hubSubtitleReveal 1s ease-out 0.75s both !important;
}

/* Guión ornamental izquierdo */
#mainMenu .menu-subtitle::before {
    content: '' !important;
    position: absolute !important;
    left: 0 !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: 0.65rem !important;
    height: 1px !important;
    background: rgba(195, 148, 255, 0.65) !important;
    box-shadow: 0 0 6px rgba(195, 148, 255, 0.50) !important;
}

/* Línea ornamental debajo que se desvanece hacia la derecha */
#mainMenu .menu-subtitle::after {
    content: '' !important;
    display: block !important;
    margin-top: 0.45rem !important;
    height: 1px !important;
    width: clamp(12rem, 28vw, 22rem) !important;
    background: linear-gradient(
        to right,
        rgba(195, 148, 255, 0.50) 0%,
        rgba(175, 128, 245, 0.20) 50%,
        transparent 100%
    ) !important;
    box-shadow: 0 0 8px rgba(175, 128, 255, 0.25) !important;
}

[data-theme="dark"] #mainMenu .menu-subtitle {
    color: rgba(200, 168, 248, 0.78) !important;
}

/* ── COLUMNA DE NAVEGACIÓN (derecha) ───────────────────────── */
#mainMenu .menu-container {
    position: absolute !important;
    right: clamp(1.5rem, 4vw, 3.5rem) !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    width: clamp(240px, 26vw, 310px) !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 0.45rem !important;
    z-index: 10 !important;
    /* Sobreescribir cualquier estilo previo del menu-center-content */
    margin: 0 !important;
    padding: 0 !important;
    left: auto !important;
}

/* ── ÍTEMS DE MENÚ ─────────────────────────────────────────── */
#mainMenu .hub-menu-item {
    display: flex !important;
    align-items: center !important;
    gap: 0.85rem !important;
    width: 100% !important;
    padding: 0.78rem 1rem 0.78rem 0.82rem !important;
    background: linear-gradient(
        108deg,
        rgba(14, 7, 30, 0.82) 0%,
        rgba(10, 5, 22, 0.74) 100%
    ) !important;
    border: 1px solid var(--hub-btn-border) !important;
    /* Línea de acento izquierda — da profundidad visual */
    border-left: 3px solid rgba(145, 100, 230, 0.38) !important;
    border-radius: 10px !important;
    backdrop-filter: blur(18px) !important;
    -webkit-backdrop-filter: blur(18px) !important;
    cursor: pointer !important;
    transition: background 0.22s, border-color 0.22s, border-left-color 0.22s,
                transform 0.22s, box-shadow 0.22s !important;
    text-align: left !important;
    color: var(--hub-text) !important;
    position: relative !important;
    overflow: hidden !important;
    box-shadow: 0 2px 16px rgba(10, 4, 28, 0.40),
                inset 0 1px 0 rgba(200, 165, 255, 0.06) !important;
    animation: hubSlideLeft 0.45s both !important;
}

#mainMenu .hub-menu-item:nth-child(1) { animation-delay: 0.28s !important; }
#mainMenu .hub-menu-item:nth-child(2) { animation-delay: 0.38s !important; }
#mainMenu .hub-menu-item:nth-child(3) { animation-delay: 0.48s !important; }
#mainMenu .hub-menu-item:nth-child(4) { animation-delay: 0.58s !important; }

#mainMenu .hub-menu-item:hover {
    background: linear-gradient(
        108deg,
        rgba(24, 12, 46, 0.90) 0%,
        rgba(16, 8, 32, 0.82) 100%
    ) !important;
    border-color: rgba(178, 132, 255, 0.62) !important;
    border-left-color: rgba(195, 148, 255, 0.90) !important;
    transform: translateX(-4px) !important;
    box-shadow: 0 4px 28px rgba(10, 4, 28, 0.55),
                inset 0 1px 0 rgba(210, 178, 255, 0.09) !important;
}

/* Shimmer al hover */
#mainMenu .hub-menu-item::before {
    content: '' !important;
    position: absolute !important;
    top: 0; left: -110% !important;
    width: 55%; height: 100% !important;
    background: linear-gradient(
        108deg,
        transparent 20%,
        rgba(200, 162, 255, 0.08) 50%,
        transparent 80%
    ) !important;
    transition: left 0.55s ease !important;
    pointer-events: none !important;
    z-index: 1 !important;
}
#mainMenu .hub-menu-item:hover::before { left: 150% !important; }

/* Primario (Continuar) — borde izquierdo dorado, glow propio */
#mainMenu .hub-menu-item.primary {
    border-color: rgba(185, 140, 255, 0.55) !important;
    border-left-color: rgba(195, 148, 255, 0.85) !important;
    background: linear-gradient(
        108deg,
        rgba(18, 9, 36, 0.86) 0%,
        rgba(12, 6, 26, 0.78) 100%
    ) !important;
    box-shadow: 0 3px 22px rgba(10, 4, 28, 0.50),
                0 0 0 1px rgba(185, 140, 255, 0.08),
                inset 0 1px 0 rgba(210, 178, 255, 0.08) !important;
}

#mainMenu .hub-menu-item.primary .hub-item-icon {
    background: rgba(162, 115, 245, 0.28) !important;
    border-color: rgba(162, 115, 245, 0.50) !important;
    box-shadow: 0 0 10px rgba(162, 115, 245, 0.25) !important;
}

#mainMenu .hub-menu-item.primary:hover {
    border-left-color: var(--hub-gold) !important;
    box-shadow: 0 6px 32px rgba(10, 4, 28, 0.62),
                0 0 0 1px rgba(195, 148, 255, 0.15) !important;
}

/* Opciones — más sutil */
#mainMenu .hub-menu-item--minor {
    opacity: 0.68 !important;
    border-left-color: rgba(130, 92, 210, 0.28) !important;
}
#mainMenu .hub-menu-item--minor:hover {
    opacity: 1 !important;
}

/* ── ICONO dentro del ítem ─────────────────────────────────── */
#mainMenu .hub-item-icon {
    width: 34px !important;
    height: 34px !important;
    flex: 0 0 34px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    border-radius: 9px !important;
    background: radial-gradient(
        circle at 40% 35%,
        rgba(175, 130, 255, 0.22) 0%,
        rgba(125, 82, 210, 0.10) 100%
    ) !important;
    border: 1px solid rgba(152, 108, 240, 0.35) !important;
    color: rgba(200, 162, 255, 0.90) !important;
    transition: background 0.22s, color 0.22s, border-color 0.22s, box-shadow 0.22s !important;
    box-shadow: inset 0 1px 0 rgba(210, 178, 255, 0.10) !important;
}

#mainMenu .hub-menu-item:hover .hub-item-icon {
    background: radial-gradient(
        circle at 40% 35%,
        rgba(192, 148, 255, 0.32) 0%,
        rgba(145, 100, 232, 0.16) 100%
    ) !important;
    border-color: rgba(195, 150, 255, 0.55) !important;
    color: var(--hub-gold) !important;
    box-shadow: 0 0 10px rgba(175, 130, 255, 0.28),
                inset 0 1px 0 rgba(220, 188, 255, 0.14) !important;
}

/* ── CONTENIDO de texto del ítem ───────────────────────────── */
#mainMenu .hub-item-content {
    flex: 1 !important;
    display: flex !important;
    flex-direction: column !important;
    gap: 0.12rem !important;
    min-width: 0 !important; /* permite text-overflow */
}

#mainMenu .hub-menu-item .menu-label {
    font-family: 'Cinzel', serif !important;
    font-size: 0.80rem !important;
    font-weight: 600 !important;
    letter-spacing: 0.10em !important;
    text-transform: uppercase !important;
    color: var(--hub-text) !important;
    line-height: 1.2 !important;
}

#mainMenu .hub-item-sub {
    font-size: 0.67rem !important;
    color: rgba(190, 158, 248, 0.75) !important;
    letter-spacing: 0.02em !important;
    /* Georgia: elegante, soporta minúsculas, tono serif místico sin el problema
       de small-caps de Cinzel que forzaba todo a mayúsculas */
    font-family: Georgia, 'Times New Roman', serif !important;
    font-style: italic !important;
    text-transform: none !important;
    white-space: normal !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    line-height: 1.35 !important;
}

#mainMenu .hub-menu-item:hover .hub-item-sub {
    color: rgba(218, 190, 255, 0.94) !important;
}

/* ── FLECHA del ítem ───────────────────────────────────────── */
#mainMenu .hub-item-arrow {
    flex: 0 0 auto !important;
    color: rgba(155, 112, 240, 0.42) !important;
    transition: transform 0.22s ease, color 0.22s !important;
}

#mainMenu .hub-menu-item:hover .hub-item-arrow {
    transform: translateX(3px) !important;
    color: var(--hub-gold) !important;
}

/* ── BOTÓN SALIR ───────────────────────────────────────────── */
#mainMenu .menu-exit-btn {
    background: rgba(10, 5, 22, 0.58) !important;
    border-color: rgba(140, 100, 218, 0.22) !important;
    color: rgba(175, 138, 248, 0.58) !important;
}

#mainMenu .menu-exit-btn:hover {
    background: rgba(20, 10, 38, 0.72) !important;
    border-color: rgba(165, 120, 244, 0.50) !important;
    color: rgba(212, 175, 255, 0.96) !important;
}

/* ── ANIMACIONES DE ENTRADA ────────────────────────────────── */
@keyframes hubSlideDown {
    from { opacity: 0; transform: translateY(-10px); }
    to   { opacity: 1; transform: translateY(0); }
}

@keyframes hubSlideUp {
    from { opacity: 0; transform: translateY(20px); filter: blur(3px); }
    to   { opacity: 1; transform: translateY(0);    filter: blur(0); }
}

@keyframes hubSlideLeft {
    from { opacity: 0; transform: translateX(28px); filter: blur(2px); }
    to   { opacity: 1; transform: translateX(0);    filter: blur(0); }
}

/* ── ANIMACIONES DEL BRAND (título + subtítulo) ────────────── */

/* Glow que respira: el título pulsa entre suave e intenso */
@keyframes hubTitleBreath {
    0%, 100% {
        text-shadow:
            0 0 16px rgba(192, 145, 252, 0.60),
            0 0 44px rgba(148, 96, 236, 0.30),
            0 0 85px rgba(112, 65, 200, 0.16),
            0 3px 12px rgba(0, 0, 0, 0.88);
    }
    50% {
        text-shadow:
            0 0 28px rgba(215, 170, 255, 0.88),
            0 0 68px rgba(172, 118, 252, 0.52),
            0 0 120px rgba(145, 88, 228, 0.28),
            0 3px 12px rgba(0, 0, 0, 0.88);
    }
}

/* Flotación sutil: sube y baja 4px muy despacio */
@keyframes hubTitleFloat {
    0%, 100% { transform: translateY(0px); }
    50%       { transform: translateY(-4px); }
}

/* Shimmer periódico: luz que barre el brand de izq a dcha */
@keyframes hubBrandShimmer {
    0%,  30% { left: -80%;  opacity: 0; }
    33%       { opacity: 1; }
    65%       { left: 130%; opacity: 1; }
    68%, 100% { left: 130%; opacity: 0; }
}

/* Subtítulo aparece desde abajo con fade */
@keyframes hubSubtitleReveal {
    from { opacity: 0; transform: translateY(8px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ── RESPONSIVE: móvil ─────────────────────────────────────── */
@media (max-width: 680px) {
    #mainMenu .menu-top-bar {
        padding: 0.75rem 1rem !important;
    }

    /* En móvil: columna centrada */
    #mainMenu .menu-container {
        position: absolute !important;
        right: auto !important;
        left: 50% !important;
        top: auto !important;
        bottom: 5rem !important;
        transform: translateX(-50%) !important;
        width: min(92vw, 340px) !important;
    }

    /* Título: más pequeño, centrado */
    #mainMenu .menu-brand {
        left: 50% !important;
        bottom: auto !important;
        top: 50% !important;
        transform: translate(-50%, -50%) !important;
        text-align: center !important;
        display: none !important; /* ocultar en móvil con nav centrada */
    }

    #mainMenu .hub-menu-item:hover {
        transform: none !important;
    }
}


/* -- css/sections/hub-luna.css -- */
/* ============================================================
   ETHERIA · HUB "LUNA DE PLATA"  —  estancia aislada
   ------------------------------------------------------------
   Todo va bajo #mainMenu para ganar la cascada sin !important.
   En el repo: copiar como css/sections/hub-luna.css y añadir AL
   FINAL de NON_CRITICAL_CSS_ORDER en build.js.
   Path de imagen en repo: ./assets/backgrounds/hub-valley.png
   (build.js lo reescribe a ./assets/... en dist/)
   ============================================================ */

#mainMenu.cel-hub {
  --cel-void:        #0c0720;
  --cel-bg:          #1a0f33;
  --cel-violet:      #7c4dff;
  --cel-violet-glow: #9d6bff;
  --cel-violet-soft: #b794f6;
  --cel-lilac:       #cbb6ff;
  --cel-gold:        #e8c878;
  --cel-gold-glow:   #f4d98a;
  --cel-silver:      #e9e3fb;
  --cel-text-hi:     #f3eeff;
  --cel-text:        #d2c7ec;
  --cel-text-muted:  #9a8fc2;
  --cel-text-dim:    #6b6090;
  --cel-online:      #8fe0c2;
  /* ambiente Luna de Plata */
  --cel-sky-top:     #100a2c;
  --cel-sky-mid:     #211a4c;
  --cel-sky-low:     #2e2362;
  /* atmósfera — variables base (noche por defecto) */
  --cel-horizon-glow: rgba(176,178,255,0.45);
  --cel-land-filter:  brightness(0.50) saturate(0.78) contrast(1.0) hue-rotate(224deg);
  --cel-star-op:      1;

  position: fixed;
  inset: 0;
  overflow: hidden;
  background: var(--cel-void);
  font-family: 'Outfit', system-ui, sans-serif;
  color: var(--cel-text);
  --mx: 0;
  --my: 0;
}

/* Parallax helper — un elemento con [data-pd] se desplaza según su profundidad.
   Para capas con transform base (menú, marca) ese base va en su propia regla. */
#mainMenu.cel-hub [data-pd] {
  transform: translate3d(
    calc(var(--mx) * (var(--pd) * -1) * 1px),
    calc(var(--my) * (var(--pd) * -0.6) * 1px),
    0
  );
  transition: transform 140ms ease-out;
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  #mainMenu.cel-hub [data-pd] { transform: none !important; transition: none; }
}

/* ── Atmósferas · momento del día ───────────────────────────
   'noche' = la Luna de Plata original. Cada clase solo cambia
   matiz del cielo, brillo del horizonte, tinte del paisaje,
   densidad de estrellas y el astro (luna/sol). ───────────── */
#mainMenu.cel-hub.amb-amanecer {
  --cel-sky-top:#2a1e42; --cel-sky-mid:#6e4250; --cel-sky-low:#c47a4e;
  --cel-horizon-glow: rgba(250,180,120,0.60);
  --cel-land-filter:  brightness(0.60) saturate(1.0) contrast(1.0) sepia(0.18) hue-rotate(318deg);
  --cel-star-op: 0.42;
}
#mainMenu.cel-hub.amb-mediodia {
  --cel-sky-top:#3f5290; --cel-sky-mid:#5f7ab4; --cel-sky-low:#9fbcdc;
  --cel-horizon-glow: rgba(228,238,255,0.50);
  --cel-land-filter:  brightness(1.0) saturate(1.1) contrast(1.02) hue-rotate(0deg);
  --cel-star-op: 0.05;
}
#mainMenu.cel-hub.amb-atardecer {
  --cel-sky-top:#150d2e; --cel-sky-mid:#3e1638; --cel-sky-low:#7e2c34;
  --cel-horizon-glow: rgba(236,96,64,0.58);
  --cel-land-filter:  brightness(0.50) saturate(1.15) contrast(1.04) sepia(0.15) hue-rotate(330deg);
  --cel-star-op: 0.5;
}
#mainMenu.cel-hub.amb-noche {
  --cel-sky-top:#0c0726; --cel-sky-mid:#1a1442; --cel-sky-low:#241c54;
  --cel-horizon-glow: rgba(176,178,255,0.42);
  --cel-land-filter:  brightness(0.46) saturate(0.76) contrast(1.0) hue-rotate(224deg);
  --cel-star-op: 1;
}
/* nebulosa: detalle puntual por atmósfera (atenuada de día) */
#mainMenu.amb-amanecer .cel-nebula{ opacity:0.7; }
#mainMenu.amb-amanecer .cel-nebula i:nth-child(1){ background:radial-gradient(circle, rgba(250,170,120,0.34) 0%, transparent 68%); }
#mainMenu.amb-mediodia .cel-nebula{ opacity:0.32; }
#mainMenu.amb-mediodia .cel-nebula i:nth-child(1){ background:radial-gradient(circle, rgba(190,215,255,0.34) 0%, transparent 70%); }
#mainMenu.amb-atardecer .cel-nebula i:nth-child(2){ background:radial-gradient(circle, rgba(238,120,90,0.28) 0%, transparent 66%); }

/* ── Astro: sol (día) en lugar de luna (noche) ──────────── */
#mainMenu .cel-moon { display:none; }
#mainMenu.amb-noche .cel-moon { display:block; }
#mainMenu .cel-sun {
  position:absolute; top:var(--sun-top,10%); left:var(--sun-left,42%); display:none; pointer-events:none;
}
#mainMenu.amb-amanecer .cel-sun,
#mainMenu.amb-mediodia .cel-sun,
#mainMenu.amb-atardecer .cel-sun { display:block; }
#mainMenu .cel-sun .orb {
  position:relative; width:var(--sun-size,120px); height:var(--sun-size,120px); border-radius:50%;
  background:var(--sun-grad); box-shadow:var(--sun-shadow);
}
#mainMenu .cel-sun .glow {
  position:absolute; left:50%; top:50%; transform:translate(-50%,-50%);
  width:calc(var(--sun-size,120px) * 2.7); height:calc(var(--sun-size,120px) * 2.7); border-radius:50%;
  background:var(--sun-glow); animation:cel-moonglow 8s ease-in-out infinite;
}
#mainMenu.amb-amanecer {
  --sun-top:32%; --sun-left:42%; --sun-size:118px;
  --sun-grad:radial-gradient(circle at 42% 40%, #fff3e0 0%, #ffd9a8 40%, #f5b070 72%, #e0905e 100%);
  --sun-shadow:0 0 64px rgba(250,190,130,0.65), inset -8px -8px 30px rgba(170,100,70,0.35);
  --sun-glow:radial-gradient(circle, rgba(252,200,140,0.40) 0%, rgba(240,170,110,0.16) 42%, transparent 70%);
}
#mainMenu.amb-mediodia {
  --sun-top:6%; --sun-left:50%; --sun-size:104px;
  --sun-grad:radial-gradient(circle at 40% 36%, #ffffff 0%, #fff4d6 46%, #ffe49e 78%, #f5cd76 100%);
  --sun-shadow:0 0 70px rgba(255,236,160,0.7), inset -6px -6px 24px rgba(200,160,80,0.3);
  --sun-glow:radial-gradient(circle, rgba(255,240,190,0.40) 0%, rgba(255,220,150,0.16) 40%, transparent 66%);
}
#mainMenu.amb-atardecer {
  --sun-top:40%; --sun-left:55%; --sun-size:150px;
  --sun-grad:radial-gradient(circle at 44% 42%, #ffd9a0 0%, #ff9d5a 38%, #e85e3a 70%, #c43028 100%);
  --sun-shadow:0 0 84px rgba(236,94,58,0.62), inset -10px -10px 36px rgba(140,40,40,0.42);
  --sun-glow:radial-gradient(circle, rgba(238,110,70,0.42) 0%, rgba(210,70,60,0.16) 44%, transparent 72%);
}
/* mediodía: paisaje recupera color natural */
#mainMenu.amb-mediodia .cel-landscape .tint{ opacity:0.35; }
#mainMenu.amb-mediodia .cel-landscape .tint2{ opacity:0.12; }
#mainMenu.amb-amanecer .cel-landscape .tint2{ opacity:0.3; }

/* ── 1. Cielo ───────────────────────────────────────────── */
#mainMenu .cel-sky {
  position: absolute; inset: 0;
  background: linear-gradient(180deg,
    var(--cel-sky-top) 0%, var(--cel-sky-mid) 48%,
    var(--cel-sky-low) 78%, var(--cel-sky-top) 100%);
}

/* ── 2. Nebulosa ────────────────────────────────────────── */
#mainMenu .cel-nebula { position: absolute; inset: -8%; pointer-events: none; }
#mainMenu .cel-nebula i {
  position: absolute; border-radius: 50%; display: block;
  filter: blur(30px);
}
#mainMenu .cel-nebula i:nth-child(1) {
  top: 4%; left: 8%; width: 52%; height: 52%;
  background: radial-gradient(circle, rgba(111,107,255,0.34) 0%, transparent 68%);
  animation: cel-nebula 16s ease-in-out infinite;
}
#mainMenu .cel-nebula i:nth-child(2) {
  top: 0; right: 4%; width: 46%; height: 50%;
  background: radial-gradient(circle, rgba(157,107,255,0.26) 0%, transparent 66%);
  animation: cel-nebula 20s ease-in-out 2s infinite;
}
#mainMenu .cel-nebula i:nth-child(3) {
  top: 22%; left: 32%; width: 50%; height: 46%;
  background: radial-gradient(circle, rgba(74,74,158,0.38) 0%, transparent 70%);
  animation: cel-nebula 24s ease-in-out 1s infinite;
}
@keyframes cel-nebula {
  0%,100% { transform: translate(0,0) scale(1); opacity: 0.9; }
  50%     { transform: translate(14px,-10px) scale(1.06); opacity: 1; }
}

/* ── 3. Aurora ──────────────────────────────────────────── */
#mainMenu .cel-aurora {
  position: absolute; inset: 0; pointer-events: none;
  mix-blend-mode: screen; opacity: 0.32;
  background:
    conic-gradient(from 210deg at 30% 0%, transparent 0deg, rgba(157,155,255,0.33) 18deg, transparent 36deg),
    conic-gradient(from 160deg at 72% 0%, transparent 0deg, rgba(157,155,255,0.27) 14deg, transparent 30deg);
  animation: cel-aurora 18s ease-in-out infinite;
}
@keyframes cel-aurora { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }

/* ── 4. Estrellas (las puebla hub-luna.js) ──────────────── */
#mainMenu .cel-stars { position: absolute; inset: 0; pointer-events: none; opacity: var(--cel-star-op, 1); transition: opacity 700ms ease; }
#mainMenu .cel-stars .star {
  position: absolute; border-radius: 50%; background: #fff;
  animation: cel-twinkle var(--dur,6s) ease-in-out var(--del,0s) infinite;
}
#mainMenu .cel-stars .star-bright { position: absolute; }
#mainMenu .cel-stars .star-bright .dot {
  position: absolute; border-radius: 50%; background: #fff;
  box-shadow: 0 0 6px #fff, 0 0 12px var(--cel-violet-soft);
  transform: translate(-50%,-50%);
}
#mainMenu .cel-stars .star-bright .gx,
#mainMenu .cel-stars .star-bright .gy {
  position: absolute; transform: translate(-50%,-50%); opacity: 0.7;
  background: linear-gradient(90deg, transparent, var(--cel-lilac), transparent);
}
#mainMenu .cel-stars .star-bright .gy { background: linear-gradient(180deg, transparent, var(--cel-lilac), transparent); }
@keyframes cel-twinkle { 0%,100% { opacity: 0.25; } 50% { opacity: 1; } }

/* ── 5. Constelaciones (las dibuja hub-luna.js) ─────────── */
#mainMenu .cel-constellations { position: absolute; inset: 0; pointer-events: none; }
#mainMenu .cel-constellations svg { position: absolute; overflow: visible;
  filter: drop-shadow(0 0 5px rgba(203,182,255,0.53)); }
#mainMenu .cel-constellations .c-line {
  stroke: var(--cel-lilac); stroke-width: 0.5; opacity: 0.55; fill: none; stroke-linecap: round;
  stroke-dasharray: 240; stroke-dashoffset: 240;
  animation: cel-draw 2.4s ease-out forwards;
}
#mainMenu .cel-constellations .c-node-h { fill: var(--cel-lilac); opacity: 0.18; }
#mainMenu .cel-constellations .c-node { fill: #fff; }
@keyframes cel-draw { to { stroke-dashoffset: 0; } }
@keyframes cel-constShimmer { 0%,100% { opacity: 0.6; } 50% { opacity: 1; } }

/* ── 6. Luna ────────────────────────────────────────────── */
#mainMenu .cel-moon { position: absolute; top: 5%; right: 15%; pointer-events: none; }
#mainMenu .cel-moon .disc {
  position: relative; width: 170px; height: 170px; border-radius: 50%;
  background: radial-gradient(circle at 38% 34%, #f4f1ff 0%, #d9d4f5 45%, #a9a4d8 75%, #7d78b0 100%);
  box-shadow: 0 0 50px rgba(190,190,255,0.5), inset -14px -14px 36px rgba(70,60,120,0.5);
}
#mainMenu .cel-moon .halo {
  position: absolute; inset: -70px; border-radius: 50%;
  background: radial-gradient(circle, rgba(180,182,255,0.30) 0%, rgba(157,107,255,0.12) 40%, transparent 70%);
  animation: cel-moonglow 8s ease-in-out infinite;
}
#mainMenu .cel-moon .crater { position: absolute; border-radius: 50%; background: rgba(120,114,170,0.32); }
#mainMenu .cel-moon .crater.a { top: 30%; left: 34%; width: 22px; height: 22px; }
#mainMenu .cel-moon .crater.b { top: 54%; left: 56%; width: 16px; height: 16px; }
#mainMenu .cel-moon .crater.c { top: 62%; left: 30%; width: 11px; height: 11px; }
#mainMenu .cel-moon .veil {
  position: absolute; top: 40%; left: -30%; width: 170%; height: 30px; border-radius: 50%;
  background: linear-gradient(90deg, transparent, rgba(40,30,80,0.55), transparent);
  filter: blur(5px); animation: cel-veil 14s ease-in-out infinite;
}
@keyframes cel-moonglow { 0%,100% { opacity: 0.85; transform: scale(1); } 50% { opacity: 1; transform: scale(1.05); } }
@keyframes cel-veil { 0%,100% { transform: translateX(0); opacity: 0.6; } 50% { transform: translateX(18px); opacity: 0.9; } }

/* ── 7. Resplandor de horizonte ─────────────────────────── */
#mainMenu .cel-horizon {
  position: absolute; left: 0; right: 0; bottom: 30%; height: 24%; pointer-events: none;
  background: radial-gradient(ellipse 80% 100% at 50% 100%, var(--cel-horizon-glow) 0%, transparent 72%);
}

/* ── 8. Paisaje lejano ──────────────────────────────────── */
#mainMenu .cel-landscape { position: absolute; left: -3%; right: -3%; bottom: 0; height: 46%; }
#mainMenu .cel-landscape .img {
  position: absolute; inset: 0;
  background-image: url('./assets/backgrounds/hub-valley.png');   /* repo: ./assets/backgrounds/hub-valley.png */
  background-size: cover; background-position: center 72%;
  image-rendering: pixelated;
  filter: var(--cel-land-filter, brightness(0.50) saturate(0.78) contrast(1.0) hue-rotate(224deg));
  transition: filter 700ms ease;
  -webkit-mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.5) 26%, #000 58%);
          mask-image: linear-gradient(180deg, transparent 0%, rgba(0,0,0,0.5) 26%, #000 58%);
}
#mainMenu .cel-landscape .tint {
  position: absolute; inset: 0; mix-blend-mode: multiply;
  background: linear-gradient(180deg, transparent 0%, rgba(56,58,118,0.48) 60%, var(--cel-void) 100%);
}
#mainMenu .cel-landscape .tint2 {
  position: absolute; inset: 0; mix-blend-mode: color; opacity: 0.6;
  background: rgba(56,58,118,0.48);
}

/* ── 9. Motas (las puebla hub-luna.js) ──────────────────── */
#mainMenu .cel-motes { position: absolute; inset: 0; pointer-events: none; }
#mainMenu .cel-motes .mote {
  position: absolute; bottom: -20px; border-radius: 50%;
  background: var(--cel-violet-soft);
  box-shadow: 0 0 6px var(--cel-violet-soft), 0 0 12px rgba(183,148,246,0.53);
  animation: cel-mote var(--dur,20s) linear var(--del,0s) infinite;
}
@keyframes cel-mote {
  0%   { transform: translate(0,0); opacity: 0; }
  12%  { opacity: 0.9; }
  88%  { opacity: 0.8; }
  100% { transform: translate(var(--drift,0), -108vh); opacity: 0; }
}

/* Estrella fugaz */
#mainMenu .cel-shoot {
  position: absolute; top: 12%; left: 70%; width: 120px; height: 1px; pointer-events: none;
  background: linear-gradient(90deg, transparent, var(--cel-silver));
  opacity: 0; transform: rotate(20deg); border-radius: 2px;
  animation: cel-shoot 11s ease-in 4s infinite;
}
@keyframes cel-shoot {
  0% { opacity: 0; transform: translate(0,0) rotate(20deg); }
  2% { opacity: 1; }
  9% { opacity: 1; transform: translate(-340px,124px) rotate(20deg); }
  11%{ opacity: 0; transform: translate(-360px,130px) rotate(20deg); }
  100%{ opacity: 0; }
}

/* ── 10. Viñeta ─────────────────────────────────────────── */
#mainMenu .cel-vignette {
  position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(ellipse 116% 84% at 50% 46%, transparent 38%, rgba(6,3,18,0.72) 100%);
}

/* ── 11. Anillo-sigilo arcano ───────────────────────────── */
#mainMenu .cel-sigil {
  position: absolute; left: 60px; bottom: 30px; width: 560px; height: 560px;
  transform: translate(-22%, 24%); opacity: 0.16; pointer-events: none;
}
#mainMenu .cel-sigil svg { width: 100%; height: 100%; animation: cel-spin 90s linear infinite; }
@keyframes cel-spin { to { transform: rotate(360deg); } }

/* ============================================================
   UI — barra superior, marca, menú, Ethy, estado, salir
   ============================================================ */

/* Capas de UI con z y parallax inverso */
#mainMenu .cel-topbar,
#mainMenu .menu-brand,
#mainMenu .menu-container,
#mainMenu .cel-ethy,
#mainMenu .cel-status,
#mainMenu .menu-exit-btn { z-index: 6; }
#mainMenu .cel-sigil { z-index: 1; }

/* ── Barra superior ─────────────────────────────────────── */
#mainMenu .cel-topbar {
  position: absolute; top: 26px; left: 34px; right: 34px;
  display: flex; align-items: flex-start; justify-content: space-between;
}
#mainMenu .menu-profile-btn {
  display: flex; align-items: center; gap: 13px; cursor: pointer;
  padding: 7px 16px 7px 7px; border-radius: 999px; border: 1px solid rgba(124,77,255,0.28);
  background: rgba(16,10,38,0.42); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 6px 20px rgba(0,0,0,0.4); transition: all 280ms ease;
}
#mainMenu .menu-profile-btn:hover {
  background: rgba(124,77,255,0.16); border-color: rgba(124,77,255,0.53);
  box-shadow: 0 0 22px rgba(124,77,255,0.27);
}
#mainMenu .menu-profile-avatar {
  position: relative; width: 54px; height: 54px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; flex-shrink: 0;
  overflow: hidden;
  background: linear-gradient(135deg, #6b46c1, #3b2a6b);
  border: 1px solid rgba(203,182,255,0.5);
  font-family: 'Cormorant Garamond', serif; font-weight: 600; font-size: 22px; color: #fff;
}
#mainMenu .menu-profile-avatar::after {
  content: ''; position: absolute; right: 0px; bottom: 0px; width: 13px; height: 13px;
  border-radius: 50%; background: var(--cel-online); border: 2px solid #150c30;
  box-shadow: 0 0 8px var(--cel-online);
}
#mainMenu .menu-profile-avatar img {
  position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover;
}
#mainMenu .menu-profile-name {
  display: block; font-family: 'Cormorant Garamond', serif; font-weight: 600; font-size: 19px;
  color: var(--cel-text-hi); letter-spacing: 0.02em; line-height: 1;
}
#mainMenu .menu-profile-hint {
  display: block; font-size: 9.5px; color: var(--cel-violet-soft); margin-top: 5px;
  letter-spacing: 0.18em; text-transform: uppercase;
}
#mainMenu .cel-top-actions { display: flex; align-items: center; gap: 12px; }
#mainMenu .cel-round-btn {
  position: relative; width: 42px; height: 42px; border-radius: 50%; cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  background: rgba(16,10,38,0.46); border: 1px solid rgba(124,77,255,0.30);
  backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px);
  color: var(--cel-lilac); transition: all 240ms ease;
}
#mainMenu .cel-round-btn:hover {
  background: rgba(124,77,255,0.22); border-color: rgba(124,77,255,0.6);
  color: var(--cel-text-hi); box-shadow: 0 0 20px rgba(124,77,255,0.33);
}
#mainMenu .cel-round-btn .badge {
  position: absolute; top: 7px; right: 7px; width: 8px; height: 8px; border-radius: 50%;
  background: var(--cel-gold); box-shadow: 0 0 8px var(--cel-gold); border: 1px solid #1a0f33;
}

/* ── Marca "Etheria" ────────────────────────────────────── */
#mainMenu .menu-brand {
  position: absolute; left: 60px; bottom: 118px; max-width: 760px;
  transform: translate3d(calc(var(--mx) * 9px), calc(var(--my) * 5.4px), 0);
  transition: transform 140ms ease-out;
}
