}
body.theme-rpg #vnSection .vn-dialogue-box .vn-speaker-plate::after {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    inset: 3px !important;
    clip-path: polygon(12px 0%, calc(100% - 12px) 0%, 100% 50%, calc(100% - 12px) 100%, 12px 100%, 0% 50%) !important;
    border: 1px solid rgba(255,210,140,.45) !important;
