/* ══════════════════════════════════════════════════════════════════════
   SPINNER DE PAGINACIÓN — "Cargando mensajes anteriores"
   Aparece en la parte superior del historial mientras loadOlderMessages
   está en vuelo. Neutral — funciona en ambos modos.
   ══════════════════════════════════════════════════════════════════════ */

@keyframes history-spinner-bounce {
    0%, 80%, 100% { transform: translateY(0);    opacity: .35; }
    40%            { transform: translateY(-6px); opacity: 1;   }
}

#vnSection .history-older-spinner {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 14px 0 10px;
    width: 100%;
}

#vnSection .history-older-spinner.hidden { display: none; }

#vnSection .history-older-spinner-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: rgba(201, 168, 108, .6);
    animation: history-spinner-bounce 1.1s ease-in-out infinite;
}

#vnSection .history-older-spinner-dot:nth-child(2) { animation-delay: .18s; }
#vnSection .history-older-spinner-dot:nth-child(3) { animation-delay: .36s; }

/* Mensaje de fin de historial */
#vnSection .history-older-end {
    font-family: 'Cinzel', serif;
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .2em;
    text-transform: uppercase;
    color: rgba(201, 168, 108, .45);
    text-align: center;
    display: block;
    padding: 6px 0;
}

/* Modo Palabra → lavanda */
body.theme-classic #vnSection .history-older-spinner-dot {
    background: rgba(193, 168, 236, .6);
}
body.theme-classic #vnSection .history-older-end {
    color: rgba(193, 168, 236, .45);
}

/* Modo Azar → ámbar */
body.theme-rpg #vnSection .history-older-spinner-dot {
    background: rgba(227, 162, 79, .6);
}
body.theme-rpg #vnSection .history-older-end {
    color: rgba(227, 162, 79, .45);
}

/* Reducir movimiento */
@media (prefers-reduced-motion: reduce) {
    #vnSection .history-older-spinner-dot { animation: none; opacity: .6; }
}

/* ══════════════════════════════════════════════════════════════════════
   DROPDOWN DE EXPORTACIÓN
   Funciona en ambos modos — neutral visualmente.
   ══════════════════════════════════════════════════════════════════════ */

@keyframes export-menu-in {
    from { opacity: 0; transform: translateX(8px) scale(.97); }
    to   { opacity: 1; transform: translateX(0)   scale(1);   }
}

#vnSection .export-menu {
    position: absolute;
    right: 0;
    top: calc(100% + 6px);
    width: 190px;
    background: rgba(10, 8, 24, .97);
    border: 1px solid rgba(201, 168, 108, .3);
    border-radius: 11px;
    padding: 5px;
    z-index: var(--z-controls, 200);
    box-shadow: 0 12px 36px rgba(0, 0, 0, .5);
    backdrop-filter: blur(10px);
    animation: export-menu-in .18s ease;
}

#vnSection .export-menu.hidden { display: none; }

#vnSection .export-menu-item {
    display: flex;
    align-items: center;
    gap: 9px;
    width: 100%;
    padding: 9px 11px;
    background: none;
    border: none;
    border-radius: 7px;
    color: rgba(243, 236, 218, .8);
    font-family: 'Cinzel', serif;
    font-size: 10px;
    font-weight: 500;
    letter-spacing: .06em;
    cursor: pointer;
    text-align: left;
    transition: background .12s ease, color .12s ease;
}

#vnSection .export-menu-item:hover {
    background: rgba(201, 168, 108, .1);
    color: #c9a86c;
}

#vnSection .export-menu-item svg {
    flex-shrink: 0;
    opacity: .7;
}

/* Modo Palabra */
body.theme-classic #vnSection .export-menu {
    border-color: rgba(193, 168, 236, .3);
}
body.theme-classic #vnSection .export-menu-item:hover {
    background: rgba(193, 168, 236, .1);
    color: #c1a8ec;
}

/* Modo Azar */
body.theme-rpg #vnSection .export-menu {
    border-color: rgba(227, 162, 79, .3);
    border-radius: 8px;
}
body.theme-rpg #vnSection .export-menu-item:hover {
    background: rgba(227, 162, 79, .1);
    color: #e3a24f;
}
body.theme-rpg #vnSection .export-menu-item { border-radius: 5px; }

@media (prefers-reduced-motion: reduce) {
    #vnSection .export-menu { animation: none; }
}

/* ══════════════════════════════════════════════════════════════════════
   ELECCIONES DEL CICLO DENTRO DEL REPLY PANEL
   Sección que aparece encima del textarea cuando hay elecciones activas.
   Scope: body.theme-classic (las elecciones son exclusivas del modo Palabra)
   ══════════════════════════════════════════════════════════════════════ */

body.theme-classic .vrp-cycle-choices {
    padding: 14px 16px 10px;
    border-bottom: 1px solid rgba(193, 168, 236, .15);
    display: flex;
    flex-direction: column;
    gap: 10px;
    background: rgba(193, 168, 236, .03);
}

body.theme-classic .vrp-cycle-choices.hidden { display: none; }

/* Tarjeta de una elección */
body.theme-classic .vrp-cycle-card {
    border: 1px solid rgba(193, 168, 236, .2);
    border-radius: 10px;
    padding: 12px 13px 10px;
    background: rgba(10, 8, 28, .5);
    transition: opacity .2s ease;
}

body.theme-classic .vrp-cycle-card-done {
    opacity: .65;
}

body.theme-classic .vrp-cycle-card-header {
    display: flex;
    align-items: flex-start;
    gap: 7px;
    margin-bottom: 9px;
}

body.theme-classic .vrp-cycle-icon {
    color: #c1a8ec;
    font-size: 11px;
    flex-shrink: 0;
    margin-top: 2px;
}

body.theme-classic .vrp-cycle-question {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 15px;
    color: #f3ecda;
    line-height: 1.45;
    flex: 1;
}

body.theme-classic .vrp-cycle-responded {
    font-family: 'Cinzel', serif;
    font-size: 8px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: #6fae9c;
    white-space: nowrap;
    margin-top: 3px;
    flex-shrink: 0;
}

/* Opciones de respuesta */
body.theme-classic .vrp-cycle-opts {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

body.theme-classic .vrp-cycle-opt {
    display: flex;
    align-items: center;
    gap: 9px;
    width: 100%;
    padding: 8px 11px;
    background: rgba(255, 255, 255, .03);
    border: 1px solid rgba(255, 255, 255, .08);
    border-radius: 7px;
    cursor: pointer;
    text-align: left;
    transition: background .14s ease, border-color .14s ease, transform .14s ease;
    font-family: inherit;
}

body.theme-classic .vrp-cycle-opt:hover:not(:disabled) {
    background: rgba(193, 168, 236, .1);
    border-color: rgba(193, 168, 236, .35);
    transform: translateX(3px);
}

body.theme-classic .vrp-cycle-opt:disabled { cursor: default; }

body.theme-classic .vrp-cycle-opt-selected {
    background: rgba(111, 174, 156, .1) !important;
    border-color: rgba(111, 174, 156, .4) !important;
}

body.theme-classic .vrp-cycle-opt-spent {
    opacity: .5;
}

body.theme-classic .vrp-cycle-opt-label {
    font-family: 'Cinzel', serif;
    font-size: 10px;
    font-weight: 600;
    color: #c1a8ec;
    min-width: 16px;
    flex-shrink: 0;
}

body.theme-classic .vrp-cycle-opt-text {
    font-family: 'Crimson Text', serif;
    font-size: 14px;
    color: rgba(243, 236, 218, .85);
    line-height: 1.35;
}

@media (prefers-reduced-motion: reduce) {
    body.theme-classic .vrp-cycle-opt:hover:not(:disabled) { transform: none; }
}

/* ══════════════════════════════════════════════════════════════════════
   BANNER DE TURNO
   Aparece encima de la caja de diálogo cuando turn_mode está activo.
   Funciona en ambos modos (Palabra y Azar).
   ══════════════════════════════════════════════════════════════════════ */

@keyframes turn-banner-in {
    from { opacity: 0; transform: translateY(6px); }
    to   { opacity: 1; transform: translateY(0); }
}

#vnSection .vn-turn-banner {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    bottom: calc(var(--dialogue-box-height, 180px) + 10px);
    display: flex;
    align-items: center;
    gap: 7px;
    padding: 5px 14px 5px 10px;
    border-radius: 999px;
    font-family: 'Cinzel', serif;
    font-size: 10px;
    font-weight: 600;
    letter-spacing: .12em;
    white-space: nowrap;
    z-index: var(--z-dialogue, 150);
    pointer-events: none;
    animation: turn-banner-in .25s ease;
    backdrop-filter: blur(8px);
}

#vnSection .vn-turn-banner.hidden { display: none; }

/* Tu turno — invita a responder */
#vnSection .vn-turn-mine {
    background: rgba(111, 174, 156, .15);
    border: 1px solid rgba(111, 174, 156, .4);
    color: #6fae9c;
}

/* Turno de otro — espera */
#vnSection .vn-turn-other {
    background: rgba(10, 8, 28, .7);
    border: 1px solid rgba(255, 255, 255, .1);
    color: rgba(243, 236, 218, .55);
}

#vnSection .vn-turn-other strong {
    color: rgba(243, 236, 218, .8);
    font-weight: 600;
}

#vnSection .turn-banner-icon {
    font-size: 11px;
    flex-shrink: 0;
}

#vnSection .turn-banner-text {
    font-size: 10px;
}

/* Modo Palabra — ajuste de bottom por la caja de diálogo */
body.theme-classic #vnSection .vn-turn-banner {
    bottom: 210px;
}

/* Modo Azar — caja ligeramente más alta */
body.theme-rpg #vnSection .vn-turn-banner {
    bottom: 220px;
}

/* Móvil */
@media (max-width: 600px) {
    body.theme-classic #vnSection .vn-turn-banner,
    body.theme-rpg    #vnSection .vn-turn-banner {
        bottom: 170px;
        font-size: 9px;
    }
}

@media (prefers-reduced-motion: reduce) {
    #vnSection .vn-turn-banner { animation: none; }
}

/* ══════════════════════════════════════════════════════════════════════
   ESTADO DE TURNO EN EL PARTY PANEL
   Funciona en ambos modos: party clásico (cp-member) y RPG (vn-party-member)
   ══════════════════════════════════════════════════════════════════════ */

/* ── Party clásico — turno activo ────────────────────────────────── */
#vnSection .cp-member--active-turn,
.classic-party-panel .cp-member--active-turn {
    border-color: rgba(201, 168, 108, .5) !important;
    background: rgba(201, 168, 108, .08) !important;
    box-shadow: 0 0 10px rgba(201, 168, 108, .15);
}

/* Icono de estado en la tarjeta del party clásico */
.classic-party-panel .cp-status-icon {
    font-size: 10px;
    margin-left: auto;
    flex-shrink: 0;
}

/* ✦ Tu turno */
.classic-party-panel .cp-member--active-turn .cp-status-icon {
    color: #c9a86c;
}

/* ✓ Respondió */
.classic-party-panel .cp-member--responded .cp-status-icon {
    color: #6fae9c;
}

/* · Esperando */
.classic-party-panel .cp-member:not(.cp-member--responded):not(.cp-member--active-turn) .cp-status-icon {
    color: rgba(243, 236, 218, .3);
}

/* Modo Palabra — turno en lavanda */
body.theme-classic .classic-party-panel .cp-member--active-turn {
    border-color: rgba(193, 168, 236, .5) !important;
    background: rgba(193, 168, 236, .08) !important;
    box-shadow: 0 0 10px rgba(193, 168, 236, .15);
}
body.theme-classic .classic-party-panel .cp-member--active-turn .cp-status-icon {
    color: #c1a8ec;
}

/* ── Party RPG — turno activo ─────────────────────────────────────── */
#vnSection .vn-party-member--active-turn {
    border-left-color: #c9a86c !important;
    background: rgba(201, 168, 108, .06) !important;
}

/* Badge ✦ / ▶ en la esquina de la tarjeta RPG */
#vnSection .vn-party-turn-badge {
    position: absolute;
    top: 6px;
    right: 28px;   /* a la izquierda del número de slot */
    font-size: 10px;
    color: #c9a86c;
    line-height: 1;
    pointer-events: none;
    animation: cycle-pulse 2s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
    #vnSection .vn-party-turn-badge { animation: none; }
}


/* -- css/sections/charPopover.css -- */
/* ══════════════════════════════════════════════════════════════════════
   css/sections/charPopover.css
   Popover visual de personaje — party panel (clásico y RPG).
   Puramente visual: sin botones de acción ni editores.

   Cargado al final de NON_CRITICAL_CSS_ORDER.
   ══════════════════════════════════════════════════════════════════════ */

@keyframes cp-popover-in {
    from { opacity: 0; transform: translateY(6px) scale(.97); }
    to   { opacity: 1; transform: translateY(0)   scale(1);   }
}

/* ── Contenedor ──────────────────────────────────────────────────── */
#vnSection #charPopover {
    position: absolute;
    width: 260px;
    background: rgba(8, 6, 22, .97);
    border: 1px solid rgba(201, 168, 108, .28);
    border-radius: 14px;
    padding: 14px;
    z-index: var(--z-modals, 500);
    box-shadow: 0 16px 48px rgba(0, 0, 0, .55),
                inset 0 1px 0 rgba(255, 255, 255, .04);
    backdrop-filter: blur(12px);
    animation: cp-popover-in .2s cubic-bezier(.2, .8, .3, 1);
    pointer-events: auto;
}

#vnSection #charPopover.hidden { display: none; }

/* Modo Palabra → borde lavanda */
body.theme-classic #vnSection #charPopover {
    border-color: rgba(193, 168, 236, .28);
}

/* Modo Azar → borde ámbar, esquinas más rectas */
body.theme-rpg #vnSection #charPopover {
    border-color: rgba(227, 162, 79, .28);
    border-radius: 10px;
}

/* ── Cabecera: avatar + nombre ───────────────────────────────────── */
#vnSection .cp-popover-header {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
}

#vnSection .cp-popover-avatar-wrap {
    flex-shrink: 0;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, .1);
    background: rgba(255, 255, 255, .04);
    display: flex;
    align-items: center;
    justify-content: center;
}

#vnSection .cp-popover-avatar {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

#vnSection .cp-popover-initial {
    font-family: 'Cinzel', serif;
    font-size: 18px;
    font-weight: 600;
    color: var(--char-color, #9b59b6);
    line-height: 1;
    user-select: none;
}

#vnSection .cp-popover-meta {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
}

#vnSection .cp-popover-name {
    font-family: 'Cinzel', serif;
    font-size: 12px;
    font-weight: 600;
    color: #f3ecda;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

#vnSection .cp-popover-sub {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 11px;
    color: rgba(243, 236, 218, .45);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* ── Separador entre cabecera y cuerpo ───────────────────────────── */
#vnSection .cp-popover-body {
    border-top: 1px solid rgba(255, 255, 255, .07);
    padding-top: 11px;
}

/* ── Afinidad (modo clásico) ─────────────────────────────────────── */
#vnSection .cp-popover-affinity {
    display: flex;
    align-items: center;
    gap: 9px;
}

#vnSection .cp-popover-aff-icon {
    font-size: 18px;
    color: var(--aff-color, #9b59b6);
    flex-shrink: 0;
    line-height: 1;
}

#vnSection .cp-popover-aff-info {
    display: flex;
    flex-direction: column;
    gap: 2px;
}

#vnSection .cp-popover-aff-name {
    font-family: 'Cinzel', serif;
    font-size: 11px;
    font-weight: 600;
    color: var(--aff-color, #9b59b6);
}

/* Indicador sutil cuando se está en el techo unilateral */
#vnSection .cp-popover-aff-hint {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 10px;
    color: rgba(243, 236, 218, .35);
}

#vnSection .cp-popover-aff-unknown {
    opacity: .5;
}
#vnSection .cp-popover-aff-unknown .cp-popover-aff-icon,
#vnSection .cp-popover-aff-unknown .cp-popover-aff-name {
    color: rgba(243, 236, 218, .4);
}

/* "Tu personaje" */
#vnSection .cp-popover-me {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 12px;
    color: rgba(243, 236, 218, .4);
    text-align: center;
    padding: 2px 0;
}

/* ── Sección de vínculo ──────────────────────────────────────────── */
#vnSection .cp-popover-aff-section {
    display: flex;
    flex-direction: column;
    gap: 7px;
}

#vnSection .cp-popover-aff-label {
    font-family: 'Cinzel', serif;
    font-size: 8px;
    font-weight: 600;
    letter-spacing: .12em;
    text-transform: uppercase;
    color: rgba(243, 236, 218, .3);
}

/* Barra de intensidad de afinidad */
#vnSection .cp-popover-aff-bar-wrap {
    height: 4px;
    background: rgba(255, 255, 255, .08);
    border-radius: 999px;
    overflow: hidden;
}

#vnSection .cp-popover-aff-bar {
    height: 100%;
    border-radius: 999px;
    transition: width .4s cubic-bezier(.2, .8, .3, 1);
    min-width: 4px;
}

/* ── Badge "Tu personaje" ────────────────────────────────────────── */
#vnSection .cp-popover-badge-me {
    font-family: 'Cinzel', serif;
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: rgba(193, 168, 236, .6);
    text-align: center;
    padding: 5px 0 2px;
}

/* ── Stats RPG ───────────────────────────────────────────────────── */
#vnSection .cp-popover-stats {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 6px;
    margin-bottom: 10px;
}

#vnSection .cp-popover-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    background: rgba(255, 255, 255, .04);
    border: 1px solid rgba(255, 255, 255, .07);
    border-radius: 6px;
    padding: 5px 4px;
}

#vnSection .cp-popover-stat-label {
    font-family: 'Cinzel', serif;
    font-size: 8px;
    font-weight: 600;
    letter-spacing: .08em;
    color: rgba(227, 162, 79, .7);
    text-transform: uppercase;
}

#vnSection .cp-popover-stat-val {
    font-family: ui-monospace, monospace;
    font-size: 13px;
    font-weight: 700;
    color: #f3ecda;
    line-height: 1;
}

/* ── Minibarras HP / EXP ─────────────────────────────────────────── */
#vnSection .cp-popover-bars {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

#vnSection .cp-popover-bar-row {
    display: flex;
    align-items: center;
    gap: 6px;
}

#vnSection .cp-popover-bar-label {
    font-family: 'Cinzel', serif;
    font-size: 8px;
    font-weight: 600;
    letter-spacing: .08em;
    color: rgba(243, 236, 218, .45);
    width: 22px;
    flex-shrink: 0;
    text-transform: uppercase;
}

#vnSection .cp-popover-bar {
    flex: 1;
    height: 5px;
    background: rgba(255, 255, 255, .08);
    border-radius: 999px;
    overflow: hidden;
}

#vnSection .cp-popover-bar-fill {
    height: 100%;
    border-radius: 999px;
    transition: width .3s ease;
}

#vnSection .cp-popover-bar-hp  { background: #6fae9c; }
#vnSection .cp-popover-bar-exp { background: #c9a86c; }

#vnSection .cp-popover-bar-val {
    font-family: ui-monospace, monospace;
    font-size: 9px;
    color: rgba(243, 236, 218, .45);
    white-space: nowrap;
    min-width: 36px;
    text-align: right;
    flex-shrink: 0;
}

/* Sin datos */
#vnSection .cp-popover-empty {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 12px;
    color: rgba(243, 236, 218, .35);
    text-align: center;
}

/* Reducir movimiento */
@media (prefers-reduced-motion: reduce) {
    #vnSection #charPopover { animation: none; }
    #vnSection .cp-popover-bar-fill { transition: none; }
}


/* -- css/sections/activityDashboard.css -- */
/* ══════════════════════════════════════════════════════════════════════
   css/sections/activityDashboard.css
   Dashboard de actividad por historia — solo modo clásico (owner).
   ══════════════════════════════════════════════════════════════════════ */

@keyframes adb-in {
    from { opacity: 0; transform: scale(.96); }
    to   { opacity: 1; transform: scale(1); }
}

/* ── Modal overlay ───────────────────────────────────────────────── */
#activityDashboardModal {
    position: fixed;
    inset: 0;
    background: rgba(4, 3, 14, .75);
    z-index: 900;
    display: flex;
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(4px);
    padding: 16px;
}
#activityDashboardModal.hidden { display: none; }

#activityDashboardBody {
    width: min(560px, 100%);
    max-height: 85vh;
    overflow-y: auto;
    background: rgba(8, 6, 22, .97);
    border: 1px solid rgba(201, 168, 108, .3);
    border-radius: 18px;
    box-shadow: 0 24px 64px rgba(0, 0, 0, .6);
    animation: adb-in .25s ease;
    scrollbar-width: thin;
    scrollbar-color: rgba(201, 168, 108, .2) transparent;
}

/* ── Raíz del contenido ──────────────────────────────────────────── */
.adb-root { padding: 24px 22px 20px; }

/* ── Cabecera ────────────────────────────────────────────────────── */
.adb-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: 18px;
}

.adb-title {
    font-family: 'Cinzel', serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: .2em;
    color: #c9a86c;
}

.adb-period {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 11px;
    color: rgba(243, 236, 218, .4);
}

/* ── Métricas ────────────────────────────────────────────────────── */
.adb-metrics {
    display: flex;
    gap: 8px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}

.adb-metric {
    flex: 1;
    min-width: 72px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 3px;
    padding: 10px 8px;
    background: rgba(255, 255, 255, .04);
    border: 1px solid rgba(255, 255, 255, .07);
    border-radius: 10px;
}

.adb-metric-icon {
    font-size: 14px;
    color: rgba(201, 168, 108, .7);
}

.adb-metric-val {
    font-family: ui-monospace, monospace;
    font-size: 20px;
    font-weight: 700;
    color: #f3ecda;
    line-height: 1;
}

.adb-metric-label {
    font-family: 'Cinzel', serif;
    font-size: 8px;
    letter-spacing: .1em;
    text-transform: uppercase;
    color: rgba(243, 236, 218, .4);
}

/* ── Nota de vínculos bilaterales ────────────────────────────────── */
.adb-bilateral-note {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 12px;
    color: rgba(111, 174, 156, .8);
    text-align: center;
    margin-bottom: 16px;
    padding: 8px 12px;
    background: rgba(111, 174, 156, .06);
    border: 1px solid rgba(111, 174, 156, .2);
    border-radius: 8px;
}

/* ── Secciones ───────────────────────────────────────────────────── */
.adb-section { margin-bottom: 18px; }

.adb-section-label {
    display: block;
    font-family: 'Cinzel', serif;
    font-size: 9px;
    font-weight: 600;
    letter-spacing: .18em;
    text-transform: uppercase;
    color: rgba(201, 168, 108, .55);
    margin-bottom: 8px;
}

/* ── Gráfico de barras ───────────────────────────────────────────── */
.adb-bars {
    display: flex;
    align-items: flex-end;
    gap: 4px;
    height: 80px;
    padding-bottom: 20px;
    position: relative;
}

.adb-bar-col {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    height: 100%;
    justify-content: flex-end;
}

.adb-bar-wrap {
    width: 100%;
    flex: 1;
    display: flex;
    align-items: flex-end;
}

.adb-bar-fill {
    width: 100%;
    background: linear-gradient(to top, rgba(193, 168, 236, .7), rgba(193, 168, 236, .3));
    border-radius: 3px 3px 0 0;
    min-height: 2px;
    transition: height .3s ease;
}

.adb-bar-label {
    font-family: ui-monospace, monospace;
    font-size: 7px;
    color: rgba(243, 236, 218, .3);
    margin-top: 4px;
    white-space: nowrap;
}

/* ── Columnas dobles ─────────────────────────────────────────────── */
.adb-cols {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
}

.adb-col { display: flex; flex-direction: column; gap: 6px; }

/* ── Hitos de rango ──────────────────────────────────────────────── */
.adb-rank-row, .adb-branch-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 9px;
    background: rgba(255, 255, 255, .03);
    border: 1px solid rgba(255, 255, 255, .06);
    border-radius: 6px;
}

.adb-rank-name, .adb-branch-label {
    font-family: 'Cinzel', serif;
    font-size: 9px;
    color: rgba(243, 236, 218, .7);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.adb-rank-count, .adb-branch-count {
    font-family: ui-monospace, monospace;
    font-size: 10px;
    font-weight: 700;
    color: #c9a86c;
    flex-shrink: 0;
    margin-left: 6px;
}

/* ── Estados vacíos y loading ────────────────────────────────────── */
.adb-empty {
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 12px;
    color: rgba(243, 236, 218, .3);
    text-align: center;
    padding: 8px 0;
}

.adb-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 40px;
    font-family: 'EB Garamond', serif;
    font-style: italic;
    font-size: 14px;
    color: rgba(243, 236, 218, .5);
}

@keyframes adb-spin { to { transform: rotate(360deg); } }

.adb-spinner {
    width: 16px;
    height: 16px;
    border: 2px solid rgba(201, 168, 108, .2);
    border-top-color: #c9a86c;
    border-radius: 50%;
    animation: adb-spin .8s linear infinite;
}

/* Responsive */
@media (max-width: 480px) {
    .adb-cols { grid-template-columns: 1fr; }
    .adb-metrics { gap: 6px; }
    .adb-metric { min-width: 60px; padding: 8px 6px; }
}

@media (prefers-reduced-motion: reduce) {
    #activityDashboardBody { animation: none; }
    .adb-bar-fill          { transition: none; }
    .adb-spinner           { animation: none; border-top-color: #c9a86c; }
}

